  `IsTree` int(11) NULL DEFAULT NULL COMMENT '树形结构',
  `EnableCache` int(11) NULL DEFAULT NULL COMMENT 'EnableCache',
  `CacheParentKey` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `Column` int(11) NULL DEFAULT NULL COMMENT '电脑端布局',
  `TableInEdit` int(11) NULL DEFAULT NULL COMMENT 'TableInEdit',
  `RowAction` mediumtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `Tabs` mediumtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '表单分组',
  `TabsPosition` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '分组标签位置',
  `TableTabs` mediumtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '表单分组',
  `TableTabsPosition` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `TableArticle` mediumtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `FormArticle` mediumtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `FormOpenType` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '表单打开方式',
  `FormOpenWidth` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '弹窗/抽屉宽度',
  `FormLabelPosition` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '标签对齐方式',
  `FieldBorder` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `InFormV8` mediumtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '前端表单进入V8事件',
  `OutFormV8` mediumtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '前端表单提交后V8事件',
  `SubmitFormV8` mediumtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '前端表单提交前V8事件',
  `InputBorderStyle` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '输入框样式',
  `BindRole` mediumtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '访问权限',
  `AddCallbakApi` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `UptCallbakApi` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `DelCallbakApi` varchar(500) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `DataEncryptSave` int(11) NULL DEFAULT NULL COMMENT '数据加密存储',
  `DataEncryptTransfer` int(11) NULL DEFAULT NULL COMMENT 'DataEncryptTransfer',
  `ApiReplace` mediumtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `IsAnonymousRead` int(11) NULL DEFAULT NULL COMMENT '允许匿名读取',
  `IsAnonymousAdd` int(11) NULL DEFAULT NULL COMMENT '允许匿名新增',
  `ServerDataV8` mediumtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '数据处理事件（后端）',
  `TreeParentField` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `TreeParentFields` mediumtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `TreeLazy` int(11) NULL DEFAULT NULL COMMENT '树形结构',
  `TreeHasChildren` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `UserName` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '操作人',
  `SubmitBeforeServerV8` mediumtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '后端表单提交前V8事件',
  `SubmitAfterServerV8` mediumtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '表单提交后事件（后端）',
  `DataBaseId` varchar(36) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'DataBaseId',
  `DataBaseName` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '所属数据库',
  `EnableDataLog` int(11) NULL DEFAULT NULL COMMENT '启用数据日志',
  `ReportName` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '报表引擎',
  `ReportId` varchar(36) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '报表引擎Id',
  `DataSourceId` varchar(36) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'DataSourceId',
  `EnableDataComment` int(11) NULL DEFAULT NULL COMMENT '启用数据评论',
  `DisplayDefaultField` int(11) NULL DEFAULT NULL COMMENT '显示默认字段',
  `DataLogRole` mediumtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '数据日志权限',
  PRIMARY KEY (`Id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

