  `ApiRemark` mediumtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '接口说明',
  `TestParam` mediumtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '参数',
  `TestResult` mediumtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT 'null',
  `ApiAddress` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '自定义接口地址',
  `AllowAnonymous` bit(1) NULL DEFAULT NULL COMMENT '允许匿名调用',
  `Files` mediumtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '相关附件',
  `ResponseFile` int(11) NULL DEFAULT NULL COMMENT '响应文件',
  `Category` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '接口分类',
  `EnableLog` int(11) NULL DEFAULT NULL COMMENT '开启日志',
  `StopHttp` int(11) NULL DEFAULT NULL COMMENT '禁止外部调用',
  `AiCheckResult` mediumtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT 'AI检查结果',
  `ResponseType` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '响应类型',
  `Timeout` int(11) NULL DEFAULT NULL,
  `MaxStatements` int(11) NULL DEFAULT NULL COMMENT '最大语句数',
  `LimitMemory` int(11) NULL DEFAULT NULL COMMENT '内存限制',
  `LimitRecursion` int(11) NULL DEFAULT NULL COMMENT '递归深度限制',
  PRIMARY KEY (`Id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

