  `UserId` varchar(36) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '操作人Id',
  `UserName` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '操作人',
  `IsDeleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `NodeName` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '节点名称',
  `FlowDesignId` varchar(36) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '流程图Id',
  `StartV8` mediumtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '开始V8',
  `EndV8` mediumtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '结束V8',
  `Timeout` int(11) NULL DEFAULT NULL COMMENT 'null',
  `NodeType` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '节点类型',
  `Roles` mediumtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT 'null',
  `Depts` mediumtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT 'null',
  `Users` mediumtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '绑定账户',
  `Description` mediumtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT 'null',
  `Remark` mediumtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT 'null',
  `BackNodes` mediumtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '可退回节点',
  `PositionLeft` varchar(25) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '坐标X',
  `PositionTop` varchar(25) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '坐标Y',
  `Icon` varchar(25) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'null',
  `DisplayFields` mediumtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT 'null',
  `HideFields` mediumtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT 'null',
  `EditFields` mediumtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT 'null',
  `FieldsConfig` mediumtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '字段设置',
  `CopyUsers` mediumtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '抄送',
  `TableId` varchar(36) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'TableId',
  `AllowSelectUsers` int(11) NULL DEFAULT NULL COMMENT '手动指定下节点审批人',
  `AllowAddUsers` int(11) NULL DEFAULT NULL COMMENT '允许添加审批人',
  `LineValueV8` mediumtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '条件判断V8',
  `AllowRecall` int(11) NULL DEFAULT NULL COMMENT '允许撤回',
  `SameDeptApprove` int(11) NULL DEFAULT NULL COMMENT '同部门领导审批',
  `AllowHandOver` int(11) NULL DEFAULT NULL COMMENT '允许移交',
  `HideHandOverSelect` int(11) NULL DEFAULT NULL COMMENT '隐藏移交选择人',
  `StartV8Server` mediumtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `EndV8Server` mediumtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  PRIMARY KEY (`Id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

