INSERT INTO `diy_document` VALUES ('034f501d-b2a8-4ca5-b7a5-7f06b8584087', '2022-05-28 08:52:15', '2023-10-24 09:40:47', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', 'Microi.net使用说明', '<ul class=\" list-paddingleft-2\" style=\"list-style-type: disc;\"><li><p><strong>DiyLock.cs</strong>&nbsp;<br/><span style=\"box-sizing: border-box; color: #333333; font-family: &quot;Open Sans&quot;, &quot;Clear Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; orphans: 4; white-space: pre-wrap; background-color: #FFFFFF;\"><span style=\"box-sizing: border-box;\">高性能分布式锁</span></span><span style=\"background-color: #FFFFFF; color: #333333; font-family: &quot;Open Sans&quot;, &quot;Clear Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; orphans: 4; white-space: pre-wrap;\">可用于库存增减、生成唯一编号等场景。</span></p><pre>public&nbsp;async&nbsp;TaskStock()\n{\n&nbsp;&nbsp;&nbsp;&nbsp;//定义锁内代码执行结果\n&nbsp;&nbsp;&nbsp;&nbsp;var&nbsp;actionResult&nbsp;=&nbsp;new&nbsp;DosResult(1);\n&nbsp;&nbsp;&nbsp;&nbsp;//Key一般传入该方法操作的唯一值；value随意传；Expiry：锁的过期时间，也是获取锁的等待时间。\n&nbsp;&nbsp;&nbsp;&nbsp;var&nbsp;lockResult&nbsp;=&nbsp;await&nbsp;DiyLock.ActionLock(&quot;Key&quot;,&nbsp;&quot;&quot;,&nbsp;TimeSpan.FromSeconds(10),&nbsp;()&nbsp;=&gt;\n&nbsp;&nbsp;&nbsp;&nbsp;{\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//-------执行单线程代码、数据库操作等\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;if(库存足够){\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;actionResult&nbsp;=&nbsp;new&nbsp;DosResult(1);\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;return;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;}else{\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;actionResult&nbsp;=&nbsp;new&nbsp;DosResult(0,&nbsp;null,&nbsp;&quot;库存不足！&quot;);\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;return;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;}\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//-------END\n&nbsp;&nbsp;&nbsp;&nbsp;});\n&nbsp;&nbsp;&nbsp;&nbsp;//判断锁是否获取成功、锁内代码是否异常（必须）\n&nbsp;&nbsp;&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;//判断锁内代码执行是否执行成功\n&nbsp;&nbsp;&nbsp;&nbsp;if&nbsp;(actionResult.Code&nbsp;!=&nbsp;1)\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;return&nbsp;actionResult;\n&nbsp;&nbsp;//继续解锁之后的业务逻辑...\n}</pre><p><br/></p></li><li><p><strong>FormEngine<br/></strong>表单引擎对数据的CURD相关操作</p></li><li><pre class=\"brush:c#;toolbar:false\">public&nbsp;class&nbsp;TestClass\n{\n&nbsp;&nbsp;&nbsp;&nbsp;private&nbsp;static&nbsp;FormEngine&nbsp;_formEngine&nbsp;=&nbsp;new&nbsp;FormEngine();\n&nbsp;&nbsp;&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;public&nbsp;async&nbsp;Task&lt;DosResult&gt;&nbsp;TestMethod(Param&nbsp;param)\n&nbsp;&nbsp;&nbsp;&nbsp;{\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//获取一条数据\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;var&nbsp;result&nbsp;=&nbsp;await&nbsp;_formEngine.GetFormDataAsync(new\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;{\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;FormEngineKey&nbsp;=&nbsp;&quot;sys_user&quot;,\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//WHERE&nbsp;Id=&#39;1&#39;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Id&nbsp;:&nbsp;&quot;1&quot;,//Id与_Where必须至少有一个。\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//WHERE&nbsp;Account&nbsp;=&nbsp;&#39;admin&#39;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;_Where&nbsp;=&nbsp;new&nbsp;List&lt;DiyWhere&gt;()&nbsp;{&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;new&nbsp;DiyWhere()&nbsp;{\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Name&nbsp;=&nbsp;&quot;Account&quot;,\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Value&nbsp;=&nbsp;&quot;admin&quot;,\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Type&nbsp;=&nbsp;&quot;=&quot;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;}&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;},\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;OsClient&nbsp;=&nbsp;param.OsClient,//可选，不传则默认，当为数据库级别saas模式时，需要传入对应的值。\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;_CurrentUser&nbsp;=&nbsp;param._CurrentUser,//可选\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;});\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//注：以上返回的是result.Data为dynamic类型，可使用result.Data.Account&nbsp;或者&nbsp;(string)result.Data.Account&nbsp;获取到Account值。\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//也支持以下方式获取数据（定义一个SysUser实体类）：\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;var&nbsp;result&nbsp;=&nbsp;await&nbsp;_formEngine.GetFormDataAsync&lt;SysUser&gt;(new\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;{\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;FormEngineKey&nbsp;=&nbsp;&quot;sys_user&quot;,\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//WHERE&nbsp;Id=&#39;1&#39;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Id&nbsp;:&nbsp;&quot;1&quot;,//Id与_Where必须至少有一个。\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//WHERE&nbsp;Account&nbsp;=&nbsp;&#39;admin&#39;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;_Where&nbsp;=&nbsp;new&nbsp;List&lt;DiyWhere&gt;()&nbsp;{&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;new&nbsp;DiyWhere()&nbsp;{\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Name&nbsp;=&nbsp;&quot;Account&quot;,\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Value&nbsp;=&nbsp;&quot;admin&quot;,\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Type&nbsp;=&nbsp;&quot;=&quot;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;}&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;},\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;OsClient&nbsp;=&nbsp;param.OsClient,//可选，不传则默认，当为数据库级别saas模式时，需要传入对应的值。\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;_CurrentUser&nbsp;=&nbsp;param._CurrentUser,//可选\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;});\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;var&nbsp;account&nbsp;=&nbsp;result.Data.Account;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//获取列表数据\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;var&nbsp;result&nbsp;=&nbsp;await&nbsp;_formEngine.GetTableDataAsync(new\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;{\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;FormEngineKey&nbsp;=&nbsp;&quot;sys_user&quot;,\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//WHERE&nbsp;Account&nbsp;=&nbsp;&#39;admin&#39;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;_Where&nbsp;=&nbsp;new&nbsp;List&lt;DiyWhere&gt;()&nbsp;{&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;new&nbsp;DiyWhere()&nbsp;{\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Name&nbsp;=&nbsp;&quot;Account&quot;,\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Value&nbsp;=&nbsp;&quot;admin&quot;,\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Type&nbsp;=&nbsp;&quot;=&quot;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;}&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;},\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;OsClient&nbsp;=&nbsp;param.OsClient,//可选，不传则默认，当为数据库级别saas模式时，需要传入对应的值。\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;_CurrentUser&nbsp;=&nbsp;param._CurrentUser,//可选\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;});\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//新增一条数据\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;result&nbsp;=&nbsp;await&nbsp;_formEngine.AddFormDataAsync(new\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;{\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;FormEngineKey&nbsp;=&nbsp;&quot;sys_user&quot;,\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;_RowModel&nbsp;=&nbsp;new&nbsp;Dictionary&lt;string,&nbsp;string&gt;()&nbsp;{\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;{&nbsp;&quot;Account&quot;,&nbsp;&quot;test&quot;},\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;{&nbsp;&quot;Sex&quot;,&nbsp;&quot;1&quot;}\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;}\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;OsClient&nbsp;=&nbsp;param.OsClient,//可选，不传则默认，当为数据库级别saas模式时，需要传入对应的值。\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;_CurrentUser&nbsp;=&nbsp;param._CurrentUser,//可选，但如果不传会导致数据UserId（创建人Id）、UserName（创建人）无值。\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;});\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//修改一条数据\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;result&nbsp;=&nbsp;await&nbsp;_formEngine.UptFormDataAsync(new\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;{\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;FormEngineKey&nbsp;=&nbsp;&quot;sys_user&quot;,\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Id&nbsp;=&nbsp;&quot;1&quot;,//根据Id=1删除数据\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;_RowModel&nbsp;=&nbsp;new&nbsp;Dictionary&lt;string,&nbsp;string&gt;()&nbsp;{\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;{&nbsp;&quot;Account&quot;,&nbsp;&quot;test&quot;},\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;{&nbsp;&quot;Sex&quot;,&nbsp;&quot;1&quot;}\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;}\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;OsClient&nbsp;=&nbsp;param.OsClient,//可选，不传则默认，当为数据库级别saas模式时，需要传入对应的值。\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;_CurrentUser&nbsp;=&nbsp;param._CurrentUser,//可选，但如果不传会导致数据UserId（创建人Id）、UserName（创建人）无值。\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;});\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//根据条件批量修改数据\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;result&nbsp;=&nbsp;await&nbsp;_formEngine.UptFormDataByWhereAsync(new\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;{\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;FormEngineKey&nbsp;=&nbsp;&quot;sys_user&quot;,\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//WHERE&nbsp;Account&nbsp;LIKE&nbsp;&#39;%admin%&#39;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;_Where&nbsp;=&nbsp;new&nbsp;List&lt;DiyWhere&gt;()&nbsp;{&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;new&nbsp;DiyWhere()&nbsp;{\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Name&nbsp;=&nbsp;&quot;Account&quot;,\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Value&nbsp;=&nbsp;&quot;admin&quot;,\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Type&nbsp;=&nbsp;&quot;Like&quot;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;}&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;},\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;_RowModel&nbsp;=&nbsp;new&nbsp;Dictionary&lt;string,&nbsp;string&gt;()&nbsp;{\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;{&nbsp;&quot;Account&quot;,&nbsp;&quot;test&quot;},\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;{&nbsp;&quot;Sex&quot;,&nbsp;&quot;1&quot;}\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;}\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;OsClient&nbsp;=&nbsp;param.OsClient,//可选，不传则默认，当为数据库级别saas模式时，需要传入对应的值。\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;_CurrentUser&nbsp;=&nbsp;param._CurrentUser,//可选，但如果不传会导致数据UserId（创建人Id）、UserName（创建人）无值。\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;});\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//删除一条数据\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;result&nbsp;=&nbsp;await&nbsp;_formEngine.DelFormDataAsync(new\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;{\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;FormEngineKey&nbsp;=&nbsp;&quot;sys_user&quot;,\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Id&nbsp;=&nbsp;&quot;1&quot;,\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;OsClient&nbsp;=&nbsp;param.OsClient,//可选，不传则默认，当为数据库级别saas模式时，需要传入对应的值。\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;_CurrentUser&nbsp;=&nbsp;param._CurrentUser,//可选，但如果不传会导致数据UserId（创建人Id）、UserName（创建人）无值。\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;});\n&nbsp;&nbsp;&nbsp;&nbsp;}\n}</pre></li></ul><p><br/></p><ul class=\" list-paddingleft-2\" style=\"list-style-type: disc;\"><li><p><strong>ApiEngine</strong><br/></p></li><li><pre class=\"brush:js;toolbar:false\">public&nbsp;class&nbsp;TestClass\n{\n&nbsp;&nbsp;&nbsp;&nbsp;private&nbsp;static&nbsp;ApiEngine&nbsp;_apiEngine&nbsp;=&nbsp;new&nbsp;ApiEngine();\n&nbsp;&nbsp;&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;public&nbsp;async&nbsp;Task&lt;DosResult&gt;&nbsp;TestMethod([FromBody]JObject&nbsp;param)\n&nbsp;&nbsp;&nbsp;&nbsp;{\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;var&nbsp;result&nbsp;=&nbsp;await&nbsp;_apiEngine.RunAsync(param);\n&nbsp;&nbsp;&nbsp;&nbsp;}\n}</pre></li></ul><p><br/></p><p><br/></p><p><br/></p><p><br/></p><p><br/></p>', b'1', 'f1fab703-bf30-44e9-a538-0fde57dd7671', '', 10, NULL);
INSERT INTO `diy_document` VALUES ('0a240028-7f75-4f0c-b411-3a60327d2344', '2022-03-20 12:13:47', '2023-08-06 17:56:06', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '安装部署', '', b'1', NULL, '', 10, NULL);
INSERT INTO `diy_document` VALUES ('0ac68bf4-ab4a-4120-b3ca-a6a902311a29', '2022-07-21 08:39:25', '2024-07-15 18:10:31', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '接口引擎', '<p>通过接口引擎可在线实现逻辑比较复杂的动态接口，支持大部分ES6语法。</p><p>接口引擎的具体用法可见【服务器端V8】</p><ul class=\" list-paddingleft-2\" style=\"list-style-type: disc;\"><li><p><span style=\"color: #4F81BD;\"></span></p></li><li><p><span style=\"color: #4F81BD;\"><strong>V8.DbTrans<br/></strong></span>事务对象，需要在V8代码中执行V8.DbTrans.Commit()或V8.DbTrans.Rollback()<br/>可以不用考虑在V8代码中使用try catch捕捉异常去V8.DbTrans.Rollback()，外部会识别到异常并且执行V8.DbTrans.Rollback();<br/><br/></p></li><li><p><span style=\"color: #4F81BD;\"><strong>V8.Param<br/></strong></span>用于访问前端传入的参数<br/><br/></p></li><li><p><span style=\"color: #4F81BD;\"><strong>V8.Action<br/></strong></span>用于访问在全局服务器V8代码处自定义的方法<br/><br/></p></li><li><p><span style=\"color: #4F81BD;\"><strong>V8.Result<br/></strong></span>用于返回值<br/><br/></p></li><li><p><span style=\"color: #4F81BD;\"><strong>V8.FormSubmitAction<br/></strong></span>表单提交类型：Insert、Update、Delete<br/><br/></p></li><li><p><span style=\"color: #4F81BD;\"><strong>System<br/></strong></span>可访问.net内置System类，如：System.Guid.NewGuid();<br/>更多用法待挖掘。</p><p><br/></p></li></ul><p>代码示例：<br/></p><pre class=\"brush:js;toolbar:false\">//必传参数：Id（线索Id）,&nbsp;ApiEngineKey（linqu_xiansuo）\n//验证参数\nif(!V8.Param.Id){\n&nbsp;&nbsp;&nbsp;&nbsp;V8.Result&nbsp;=&nbsp;{&nbsp;Code&nbsp;:&nbsp;0,&nbsp;Msg&nbsp;:&nbsp;&#39;参数数错！&#39;};\n&nbsp;&nbsp;&nbsp;&nbsp;return;\n}\n//获取该线索。这里的GetFormData等同于/api/DiyTable/GetDiyTableRowModel\nvar&nbsp;xiansuoModelResult&nbsp;=&nbsp;V8.FormEngine.GetFormData({\n&nbsp;&nbsp;&nbsp;&nbsp;FormEngineKey&nbsp;:&nbsp;&#39;Diy_Xiansuo&#39;,&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;Id&nbsp;:&nbsp;V8.Param.Id\n});\n//判断是否可领取\nif(xiansuoModelResult.Code&nbsp;!=&nbsp;1){\n&nbsp;&nbsp;&nbsp;&nbsp;V8.Result&nbsp;=&nbsp;{&nbsp;Code&nbsp;:&nbsp;0,&nbsp;Msg&nbsp;:&nbsp;&#39;获取线索数据出现错误：&#39;&nbsp;+&nbsp;xiansuoModelResult.Msg};\n&nbsp;&nbsp;&nbsp;&nbsp;return;\n}\nif(!xiansuoModelResult.Data.FuzeR){\n&nbsp;&nbsp;&nbsp;&nbsp;V8.Result&nbsp;=&nbsp;{&nbsp;Code&nbsp;:&nbsp;0,&nbsp;Msg&nbsp;:&nbsp;&#39;该线索已被[&#39;&nbsp;+&nbsp;xiansuoModelResult.Data.FuzeR&nbsp;+&nbsp;&#39;]抢先领取！&#39;};\n&nbsp;&nbsp;&nbsp;&nbsp;return;\n}\n//执行领取。将负责人设置为当前用户。UptFormData支持第二个参数传入事务对象。\nvar&nbsp;xiansuoModelResult&nbsp;=&nbsp;V8.FormEngine.UptFormData({\n&nbsp;&nbsp;&nbsp;&nbsp;FormEngineKey&nbsp;:&nbsp;&#39;Diy_Xiansuo&#39;,&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;Id&nbsp;:&nbsp;V8.Param.Id,&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;_RowModel:{&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;FuzeR&nbsp;:&nbsp;V8.CurrentUser.Name,&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;FuzeRID&nbsp;:&nbsp;V8.CurrentUser.Id&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;}\n});\n//返回是否成功\nV8.Result&nbsp;=&nbsp;{&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;Code&nbsp;:&nbsp;xiansuoModelResult.Code,&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;Data&nbsp;:&nbsp;xiansuoModelResult.Data,&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;Msg&nbsp;:&nbsp;xiansuoModelResult.Msg&nbsp;\n};</pre><ul class=\" list-paddingleft-2\" style=\"list-style-type: disc;\"><li><p><strong>其它V8按钮调用以上接口引擎</strong>：<br/></p></li></ul><pre class=\"brush:js;toolbar:false\">V8.ConfirmTips(&#39;确认领取？&#39;,&nbsp;function(){\n&nbsp;&nbsp;&nbsp;&nbsp;//抢先领取线索，调用接口引擎。带分布式锁。\n&nbsp;&nbsp;&nbsp;&nbsp;V8.ApiEngine.Run({\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;ApiKey&nbsp;:&nbsp;&#39;linqu_xiansuo&#39;,\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Id&nbsp;:&nbsp;V8.Form.Id\n&nbsp;&nbsp;&nbsp;&nbsp;},&nbsp;function(result){\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;if(result.Code&nbsp;==&nbsp;1){\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;V8.Tips(&#39;领取成功！&#39;);\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//刷新表格\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;V8.RefreshTable();\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;}else{\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;V8.Tips(&#39;领取失败：&#39;&nbsp;+&nbsp;result.Msg);\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;}\n&nbsp;&nbsp;&nbsp;&nbsp;});\n});</pre><ul class=\" list-paddingleft-2\" style=\"width: 1302.92px; white-space: normal;\"><li><p><strong>接收文件、下载文件、上传文件<br/></strong></p></li><li><pre class=\"brush:js;toolbar:false\">//接口引擎自2024-07-15开始支持Payload=Form&nbsp;Data的方式调用，并且能接收文件\n//接收到的文件列表。值格式：{&nbsp;&#39;文件名1.png&#39;:&nbsp;&#39;base64字符串形式的文件byte[]&#39;,&nbsp;&#39;文件名2.xls&#39;:&nbsp;&#39;base64字符串形式的文件byte[]&#39;&nbsp;}\nvar&nbsp;filesByteBase64&nbsp;=&nbsp;V8.FilesByteBase64;\n\n//将接收到的文件上传到低代码平台（调用V8内置函数，也可以使用V8.Http上传到低代码平台或第三方平台。调用内置函数无需token且性能更高，而V8.Http需要token。）\n//至于是上传到阿里云OSS、还是MinIO或亚马逊S3，由系统设置和SaaS引擎配置决定。\nvar&nbsp;upResult&nbsp;=&nbsp;V8.Method.Upload({\n&nbsp;&nbsp;&nbsp;&nbsp;FilesByteBase64&nbsp;:&nbsp;filesByteBase64,//直接传入相同类型、格式的文件列表数据\n&nbsp;&nbsp;&nbsp;&nbsp;Limit&nbsp;:&nbsp;false,&nbsp;//是否上传到私有桶\n&nbsp;&nbsp;&nbsp;&nbsp;Preview&nbsp;:&nbsp;false,&nbsp;//如果是图片，是否压缩\n&nbsp;&nbsp;&nbsp;&nbsp;Path&nbsp;:&nbsp;&#39;/img&#39;//上传到的路径前缀\n});\nvar&nbsp;filePath&nbsp;=&nbsp;upResult.Path;\n\n//下载一个文件\nvar&nbsp;downResult&nbsp;=&nbsp;V8.Http.GetResponse({\n&nbsp;&nbsp;&nbsp;&nbsp;Url&nbsp;:&nbsp;&#39;https://static-ali-img.itdos.com/itdos/img/20230623/WechatIMG21753.png&#39;\n});\nvar&nbsp;imgByte&nbsp;=&nbsp;downResult.RawBytes;\n\n//将下载的文件上传到第三方平台（通过V8.Http发起请求）\nvar&nbsp;upResult2&nbsp;=&nbsp;V8.Http.Post({\n&nbsp;&nbsp;&nbsp;&nbsp;Url&nbsp;:&nbsp;V8.SysConfig.ApiBase&nbsp;+&nbsp;&#39;/api/HDFS/Upload&#39;,\n&nbsp;&nbsp;&nbsp;&nbsp;FilesByteBase64&nbsp;:&nbsp;{&nbsp;&#39;fileName1.png&#39;&nbsp;:&nbsp;System.Convert.ToBase64String(imgByte)&nbsp;},\n&nbsp;&nbsp;&nbsp;&nbsp;PostParam&nbsp;:&nbsp;{\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Limit&nbsp;:&nbsp;false,&nbsp;//是否上传到私有桶\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Preview&nbsp;:&nbsp;false,&nbsp;//如果是图片，是否压缩\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Path&nbsp;:&nbsp;&#39;/img&#39;//上传到的路径前缀\n&nbsp;&nbsp;&nbsp;&nbsp;},\n&nbsp;&nbsp;&nbsp;&nbsp;Headers&nbsp;:&nbsp;{\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;authorization&nbsp;:&nbsp;&#39;Bearer&nbsp;&#39;&nbsp;+&nbsp;V8.Method.GetCurrentToken().Token\n&nbsp;&nbsp;&nbsp;&nbsp;}\n});\nupResult2&nbsp;=&nbsp;JSON.parse(upResult2);\nvar&nbsp;filePath2&nbsp;=&nbsp;upResult2.Path;\n\nV8.Result&nbsp;=&nbsp;{&nbsp;Code&nbsp;:&nbsp;1,&nbsp;Data&nbsp;:&nbsp;{\n&nbsp;&nbsp;&nbsp;&nbsp;upResult&nbsp;:&nbsp;upResult,\n&nbsp;&nbsp;&nbsp;&nbsp;upResult2&nbsp;:&nbsp;upResult2\n}&nbsp;};</pre></li><li><p><strong>响应文件<br/></strong></p></li><li><pre class=\"brush:js;toolbar:false\">//先下载一个文件\nvar&nbsp;downResult&nbsp;=&nbsp;V8.Http.GetResponse({\n&nbsp;&nbsp;&nbsp;&nbsp;Url&nbsp;:&nbsp;&#39;https://static-ali-img.itdos.com/itdos/img/20230623/WechatIMG21753.png&#39;\n});\nvar&nbsp;imgByte&nbsp;=&nbsp;downResult.RawBytes;\n//Sys_ApiEngine表需要有一个开关组件：响应文件，字段名[ResponseFile]\n//返回文件\nV8.Result&nbsp;=&nbsp;{\n&nbsp;&nbsp;&nbsp;&nbsp;Code&nbsp;:&nbsp;1,\n&nbsp;&nbsp;&nbsp;&nbsp;Data&nbsp;:&nbsp;{\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;FileName&nbsp;:&nbsp;&#39;测试响应文件.png&#39;,//必须\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;ContentType&nbsp;:&nbsp;&#39;image/png&#39;,//必须\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;FileByteBase64&nbsp;:&nbsp;System.Convert.ToBase64String(imgByte)//必须\n&nbsp;&nbsp;&nbsp;&nbsp;}\n};</pre></li></ul>', b'1', '808f0a05-6587-4439-ab96-8403f9349b4f', '', 50, NULL);
INSERT INTO `diy_document` VALUES ('148abc5d-8685-490f-95f7-a40be84f5cf3', '2022-03-24 00:11:42', NULL, 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '统一身份认证 OAuth2.0、JWT', '<p style=\"box-sizing: border-box;line-height: inherit;orphans: 4;margin-top: 0px;margin-bottom: 0.5rem;white-space: pre-wrap;width: inherit;position: relative;color: rgb(51, 51, 51);font-family: &#39;Open Sans&#39;, &#39;Clear Sans&#39;, &#39;Helvetica Neue&#39;, Helvetica, Arial, sans-serif;background-color: rgb(255, 255, 255)\"><span style=\"box-sizing: border-box\">下载iTdos.DIY统一身份认证系统源代码</span></p><pre class=\"md-fences md-end-block ty-contain-cm modeLoaded\" style=\"box-sizing: border-box;font-family: var(--monospace);font-size: 0.9em;break-inside: avoid;overflow: visible;white-space: normal;background-image: inherit;background-position: inherit;background-size: inherit;background-repeat: inherit;background-attachment: inherit;background-origin: inherit;background-clip: inherit;border: 1px solid rgb(231, 234, 237);border-radius: 3px;padding: 8px 4px 6px;margin-bottom: 15px;margin-top: 15px;width: inherit;color: rgb(51, 51, 51);position: relative !important\">#git&nbsp;clone&nbsp;https://git.itdos.net:99/itdos/itdos-diy-framework-auth.git帐号密码为iTdos官方注册帐号密码，拉取权限由商业授权获得</pre><p style=\"box-sizing: border-box;line-height: inherit;orphans: 4;margin-top: 0.5rem;margin-bottom: 0.5rem;white-space: pre-wrap;width: inherit;position: relative;color: rgb(51, 51, 51);font-family: &#39;Open Sans&#39;, &#39;Clear Sans&#39;, &#39;Helvetica Neue&#39;, Helvetica, Arial, sans-serif;background-color: rgb(255, 255, 255)\"><span style=\"box-sizing: border-box\">本系统由.net 5.0开发，支持.net core 2.x/3.x，支持分布式部署</span></p><p><br/></p>', b'1', 'f1fab703-bf30-44e9-a538-0fde57dd7671', '', 0, NULL);
INSERT INTO `diy_document` VALUES ('1a54b9d8-e268-45bd-821e-79685a4a48be', '2024-02-18 12:49:44', NULL, 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '平台部署', '', b'1', '8da6fe30-dda4-47b0-99c9-ef283195a2ae', '', 5, NULL);
INSERT INTO `diy_document` VALUES ('1d774243-01df-4d21-8ea1-b8c06f99e903', '2023-08-07 10:27:00', '2023-08-07 10:33:46', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '移动端V8对照表', '<p><br/></p><p>服务器端V8引擎代码不区分移动端，但PC的前端V8代码并没有在移动端完全实现，移动端也有一些独立的V8函数，以下为对照表：</p><p><br/></p><table class=\"table table-border\"><tbody><tr class=\"firstRow\"><td width=\"436\" valign=\"top\" style=\"word-break: break-all;\"><strong>V8对象、函数</strong></td><td width=\"436\" valign=\"top\" style=\"word-break: break-all;\"><strong>移动端</strong></td><td width=\"436\" valign=\"top\" style=\"word-break: break-all;\"><strong>PC端</strong></td></tr><tr><td width=\"436\" valign=\"top\" style=\"word-break: break-all;\">V8.Form</td><td width=\"436\" valign=\"top\" style=\"word-break: break-all;\">√</td><td width=\"436\" valign=\"top\" style=\"word-break: break-all;\">√</td></tr><tr><td width=\"436\" valign=\"top\" style=\"word-break: break-all;\">V8.OldForm</td><td width=\"436\" valign=\"top\"><br/></td><td width=\"436\" valign=\"top\" style=\"word-break: break-all;\">√</td></tr><tr><td width=\"436\" valign=\"top\" style=\"word-break: break-all;\">V8.FormSet</td><td width=\"436\" valign=\"top\" style=\"word-break: break-all;\">√</td><td width=\"436\" valign=\"top\" style=\"word-break: break-all;\">√</td></tr><tr><td width=\"436\" valign=\"top\" style=\"word-break: break-all;\">V8.Field</td><td width=\"436\" valign=\"top\" style=\"word-break: break-all;\">√</td><td width=\"436\" valign=\"top\" style=\"word-break: break-all;\">√</td></tr><tr><td width=\"436\" valign=\"top\" style=\"word-break: break-all;\">V8.FieldSet</td><td width=\"436\" valign=\"top\"><br/></td><td width=\"436\" valign=\"top\" style=\"word-break: break-all;\">√</td></tr><tr><td width=\"436\" valign=\"top\" style=\"word-break: break-all;\">V8.ScanCode</td><td width=\"436\" valign=\"top\">√</td><td width=\"436\" valign=\"top\"><br/></td></tr><tr><td width=\"436\" valign=\"top\"><br/></td><td width=\"436\" valign=\"top\"><br/></td><td width=\"436\" valign=\"top\"><br/></td></tr><tr><td width=\"436\" valign=\"top\"><br/></td><td width=\"436\" valign=\"top\"><br/></td><td width=\"436\" valign=\"top\"><br/></td></tr></tbody></table><p><br/></p>', b'1', '81b5d8fd-d93e-46ad-9363-568aeac82ab9', '', 9999999, NULL);
INSERT INTO `diy_document` VALUES ('26f2a98b-3a16-4312-9f2e-b1137846824d', '2022-03-21 02:06:10', '2022-03-21 02:06:44', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', 'CentOS 7.x', '', b'1', '847cf98b-5746-4087-bd9f-3c7e80084b4f', '', 0, NULL);
INSERT INTO `diy_document` VALUES ('37cd12e5-2459-47d0-bbac-b8a9b4da763e', '2022-03-20 12:24:54', '2022-03-20 12:30:12', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '环境', '<ul style=\"box-sizing: border-box; margin-top: 0.8em; margin-bottom: 0.8em; padding-left: 30px; position: relative; color: rgb(51, 51, 51); font-family: &quot;Open Sans&quot;, &quot;Clear Sans&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; white-space: normal; background-color: rgb(255, 255, 255);\"><li><p style=\"box-sizing: border-box; line-height: inherit; orphans: 4; margin-top: 0px; margin-bottom: 0.5rem; width: inherit; position: relative;\"><span style=\"box-sizing: border-box;\">iTdos官方开发工具合集地址：</span><a href=\"https://nas.itdos.net:88/s/CN9RcE5Gnq2gs4X\" target=\"_blank\" class=\"url\" style=\"box-sizing: border-box; cursor: pointer; color: rgb(65, 131, 196); word-break: break-all;\">https://nas.itdos.net:88/s/CN9RcE5Gnq2gs4X</a><span style=\"box-sizing: border-box;\"> &nbsp; &nbsp;密码：itdos</span></p></li><li><p style=\"box-sizing: border-box; line-height: inherit; orphans: 4; margin-top: 0px; margin-bottom: 0.5rem; width: inherit; position: relative;\"><span style=\"box-sizing: border-box;\">安装Git</span></p><p style=\"box-sizing: border-box; line-height: inherit; orphans: 4; margin-top: 0.5rem; margin-bottom: 0.5rem; width: inherit; position: relative;\"><span style=\"box-sizing: border-box;\">访问</span><a href=\"https://git-scm.com/downloads\" target=\"_blank\" class=\"url\" style=\"box-sizing: border-box; cursor: pointer; color: rgb(65, 131, 196); word-break: break-all;\">https://git-scm.com/downloads</a><span style=\"box-sizing: border-box;\"> 下载[Git-2.29.2.3-64-bit.exe]，或访问iTdos官方开发工具合集地址下载，默认安装即可。</span></p></li><li><p style=\"box-sizing: border-box; line-height: inherit; orphans: 4; margin-top: 0px; margin-bottom: 0.5rem; width: inherit; position: relative;\"><span style=\"box-sizing: border-box;\">安装Git工具</span></p><p style=\"box-sizing: border-box; line-height: inherit; orphans: 4; margin-top: 0.5rem; margin-bottom: 0.5rem; width: inherit; position: relative;\"><span style=\"box-sizing: border-box;\">访问</span><a href=\"https://tortoisegit.org/download/\" target=\"_blank\" class=\"url\" style=\"box-sizing: border-box; cursor: pointer; color: rgb(65, 131, 196); word-break: break-all;\">https://tortoisegit.org/download/</a><span style=\"box-sizing: border-box;\"> 下载[TortoiseGit-2.11.0.0-64bit.msi]，或访问iTdos官方开发工具合集地址下载，默认安装即可。</span></p></li></ul><p><br/></p>', b'1', 'f1fab703-bf30-44e9-a538-0fde57dd7671', '', 0, NULL);
INSERT INTO `diy_document` VALUES ('382d7c44-3ee5-4e0d-bc18-ac238820963b', '2023-09-28 16:39:36', '2023-09-28 16:42:13', '864d7d70-dc08-4d65-a570-52985f62958a', '虞翰霖', b'0', '私有镜像仓库部署', '<p>Harbor</p><ol class=\" list-paddingleft-2\" style=\"list-style-type: decimal;\"><li><p>官网下载离线安装包</p></li><li><p>上传至服务器并解压</p></li><li><p>修改harbor.yml文件，修改hostname，http port，https port证书路径，若不使用https则先注释https</p></li><li><p>执行 ./install.sh脚本</p></li><li><p>运行docker-compose up -d</p></li><li><p>WEB访问&nbsp; hostname(ip) + port ，账号密码存于harbor.yml文件中<br/></p></li></ol>', b'1', '0a240028-7f75-4f0c-b411-3a60327d2344', '', 0, NULL);
INSERT INTO `diy_document` VALUES ('4044fa0f-ac71-4ed0-8ab4-015eb5ddbb89', '2022-03-20 12:22:18', '2023-08-06 17:55:37', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '阿里云部署', '<ul class=\" list-paddingleft-2\" style=\"list-style-type: disc;\"><li><p><strong>购买服务器</strong></p></li><li><p><strong>oss创建</strong></p></li><li><p><strong>域名解析</strong></p></li><li><p><strong><b>负载均衡</b></strong></p></li></ul>', b'1', '0a240028-7f75-4f0c-b411-3a60327d2344', '', 20, NULL);
INSERT INTO `diy_document` VALUES ('446634d8-6084-4039-aaad-d2ef5dc31f05', '2022-05-20 09:36:05', '2022-05-20 09:51:40', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '微服务搭建', '<p class=\"ne-p\" style=\"margin-top: 0px; margin-bottom: 0px; padding: 0px; min-height: 24px;\"><span class=\"ne-text\">Docker环境安装<br/>● 下载并安装 Docker DeskTop<br/>● 启用或关闭Windows功能中开启HyperV功能<br/>● 重启电脑至BIOS检查并开启电脑虚拟化CPU Intel-VT</span></p><p class=\"ne-p\" style=\"margin-top: 0px; margin-bottom: 0px; padding: 0px; min-height: 24px;\"><br/></p><ol class=\"ne-ol list-paddingleft-2\" style=\"padding-left: 23px;\"><li><p><span class=\"ne-text\"> 全局配置<br/></span><span class=\"ne-text\">npm install nrm -g<br/></span><span class=\"ne-text\">nrm add microi </span><a href=\"https://nexus.itdos.com/repository/npm/\" target=\"_blank\" class=\"ne-link\"><span class=\"ne-text\">https://repository.microi.net/repository/npm/</span></a><span class=\"ne-text\"><br/></span><span class=\"ne-text\">nrm use microi<br/></span><span class=\"ne-text\">npm adduser --registry </span><a href=\"https://nexus.itdos.com/repository/npm/\" target=\"_blank\" class=\"ne-link\"><span class=\"ne-text\"><a href=\"https://nexus.itdos.com/repository/npm/\" target=\"_blank\" class=\"ne-link\" style=\"white-space: normal;\"><span class=\"ne-text\">https://repository.microi.net</span></a>/repository/npm/</span></a><span class=\"ne-text\"> </span></p></li><li><p><span class=\"ne-text\"> 克隆项目：git clone </span><a href=\"https://git.itdos.net:99/Anderson/microi.service.framework\" target=\"_blank\" class=\"ne-link\"><span class=\"ne-text\">https://git.itdos.net:99/Anderson/microi.service.framework</span></a><span class=\"ne-text\"> </span></p></li><li><p><span class=\"ne-text\"> 进入克隆好的项目，安装依赖并运行：<br/></span><span class=\"ne-text\">● npm install （python包容易超时，多尝试几次或者想办法）<br/></span><span class=\"ne-text\">● 修改main.js中的DiyCommon.SetApiBase、DiyCommon.SetOsClient为指定的客户配置。<br/></span><span class=\"ne-text\">● 修改package.json中的servicename为OsClient的全小写，如：aijuhome<br/></span><span class=\"ne-text\">● 登录的账号密码对应OS的，使用admin登录<br/></span><span class=\"ne-text\">● npm run dev (运行后可以看到侧边栏已经变成了线上的了) </span></p></li><li><p><span class=\"ne-text\"> 将原来的项目的views文件夹下对应的比如jinhaiou文件夹复制到微服务克隆下来的项目中的views中去<br/></span><span class=\"ne-text\">● 运行项目，如果提示缺包就装包（原本项目的依赖）<br/></span><span class=\"ne-text\">● 修改src\\router\\index.js中servicename（同package.json）<br/></span><span class=\"ne-text\">● 修改/src/views/login/index.vue中的【Microi.Service微服务】为【服务名称+微服务】，例：Haiou微服务<br/></span><span class=\"ne-text\">● 复制原有的所有自定义路由到src\\router\\index.js的asyncRouter方法中（规定所有的微服务路由以OsClient名为开头,例如/haiou，剩下的所有路由path作为haiou的子路由） </span></p></li><li><p><span class=\"ne-text\"> docker推送<br/></span><span class=\"ne-text\">● 打包项目 npm run build<br/></span><span class=\"ne-text\">● 打包后进入打包文件夹 dist/<br/></span><span class=\"ne-text\">● 运行publish.bat（第一次需要先修改bat，配置对应的账号密码等再运行）<br/></span><span class=\"ne-text\">● docker推送后效果可以在对应的os-microi域名上查看 </span></p></li><li><p><span class=\"ne-text\"> 修改OS系统的模块配置中的地址（不用动组件路径）<br/></span><span class=\"ne-text\">● 所有的微服务路由以OsClient名为开头,例如/haiou，剩下的所有路由path作为haiou的子路由，如果不想显示可以加hidden属性<br/></span><span class=\"ne-text\">● 可以直接在os-microi域名上展示效果并直接复制上去 </span></p></li><li><p><span class=\"ne-text\"> 重新创建一个新的git仓库，并且以后以该仓库作为开发（例：Microi.Service.Aijuhome）<br/></span><span class=\"ne-text\">rm -rf .git<br/></span><span class=\"ne-text\">git init<br/></span><span class=\"ne-text\">git remote add origin 地址<br/></span><span class=\"ne-text\">git add .<br/></span><span class=\"ne-text\">git commit -m &#39;微服务初始化&#39;<br/></span><span class=\"ne-text\">git push origin master&nbsp;</span></p></li></ol><p><br/></p>', b'1', 'a35e6604-e290-46d6-8769-94a680758637', '', 0, NULL);
INSERT INTO `diy_document` VALUES ('4d28198c-c3e8-4d6f-9a6e-4be9317874cb', '2024-02-18 12:51:55', '2024-02-18 13:51:04', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '工作流引擎', '', b'1', '8da6fe30-dda4-47b0-99c9-ef283195a2ae', '', 40, NULL);
INSERT INTO `diy_document` VALUES ('5742ce77-b9f6-4972-bf69-d3b4d68e49c7', '2022-07-05 10:31:26', '2022-07-05 10:32:07', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '单行文本', '<ul class=\" list-paddingleft-2\" style=\"list-style-type: disc;\"><li><p>支持配置<br/>占位文字（placeholder）<br/>密码输入Icon图标及位置<br/>复合文字及位置<br/>值变更事件<br/>失去焦点事件<br/>键盘事件<br/></p></li></ul>', b'1', 'bdd79162-325c-419c-958b-90360ac789cc', '', 10, NULL);
INSERT INTO `diy_document` VALUES ('603c6375-03ed-4222-b100-a3e229280454', '2022-11-15 16:39:47', '2023-10-09 10:57:11', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '程序部署', '<ol class=\" list-paddingleft-2\" style=\"list-style-type: decimal;\"><li><p><strong>下载并解压3件套</strong><br/>压缩包商业授权获取。<br/>Microi.net.Api（后端接口系统）、Microi.net.Auth（后端身份认证系统）、Microi.net.Vue（前端访问系统）<br/><br/></p></li><li><p><span style=\"text-decoration: line-through;\"><strong>IIS创建应用程序池</strong></span><br/><span style=\"text-decoration: line-through;\">创建两个应用程序池，分别用于auth身份认证系统和api后端接口系统，如取名为.NET6Auth、.NET6Api，选择[无托管代码]、[集成]</span><br/><br/></p></li><li><p><strong>部署auth.itdos.com身份认证系统&nbsp;</strong></p><p><strong>方案1（推荐）：<br/></strong>a ) 将三件套中的auth包解压开，进入目录找到appsettings.json文件，编辑修改<span style=\"text-wrap: wrap;\">[</span><span style=\"text-wrap: wrap; color: #212529; font-family: &quot;Helvetica Neue&quot;, Helvetica, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, Arial, sans-serif; font-size: 14px; background-color: #FFFFFF;\"><span style=\"color: #4F81BD;\">OsClient</span>、<span style=\"color: #4F81BD;\">OsClientType、OsClientNetwork、OsClientDbConn</span></span><span style=\"text-wrap: wrap;\">]四个参数，改成本地对应的</span></p><p><span style=\"text-wrap: wrap;\"><img src=\"https://static-ali-img.itdos.com//itdos/itdos/upload/editor/image/202309/6383124995671143943939168_origin.png/20230925/auth.png\" alt=\"auth.png\"/></span></p><p>b ) 修改完成后，在同级目录下运行cmd或者powershell，执行命令 ```dotnet Microi.net.Auth.dll --urls=http://0.0.0.0:1051```,成功运行程序，若提示lisence问题，则提供对应的HID（注意HID会在报错信息中输出，可直接获取HID），反馈给系统管理员，来获取商业授权获取证书，获取后，放到同级目录下覆盖后，再次运行命令即可。</p><p><span style=\"text-wrap: wrap;\">c) 部署完成后，分别访问是否正常（假设端口为1051）：</span><br/><a href=\"http://localhost:1051/\" target=\"_blank\" style=\"text-wrap: wrap;\">http://localhost:1051/</a><br/><a href=\"http://localhost:1051/.well-known/openid-configuration\" target=\"_blank\" style=\"text-wrap: wrap;\">http://localhost:1051/.well-known/openid-configuration</a><span style=\"text-wrap: wrap;\">（会返回json数据）</span><br/></p><p>d ) 最后可将改服务程序制作成windows server服务进行管理，命令参考如下：``` sc create microi-auth binPath=&quot;C:\\Microi\\Microi.net.Auth\\net6.0 \\Microi.net.Auth.exe&quot; ```</p><p><br/></p></li></ol><p><strong>&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;&nbsp;&nbsp;方案2（不推荐）：<br/></strong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;新建网站，选择.NET6Auth应用程序池。创建成功后，需要添加环境变量[<span style=\"color: #212529; font-family: &quot;Helvetica Neue&quot;, Helvetica, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, Arial, sans-serif; font-size: 14px; background-color: #FFFFFF;\"><span style=\"color: #4F81BD; font-family: &quot;Helvetica Neue&quot;, Helvetica, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, Arial, sans-serif; font-size: 14px; background-color: #FFFFFF;\">OsClient</span>、<span style=\"color: #4F81BD; font-family: &quot;Helvetica Neue&quot;, Helvetica, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, Arial, sans-serif; font-size: 14px; background-color: #FFFFFF;\">OsClientType、<span style=\"color: #4F81BD; font-family: &quot;Helvetica Neue&quot;, Helvetica, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, Arial, sans-serif; font-size: 14px; background-color: #FFFFFF;\">OsClientNetwork、<span style=\"color: #4F81BD; font-family: &quot;Helvetica Neue&quot;, Helvetica, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, Arial, sans-serif; font-size: 14px; background-color: #FFFFFF;\">OsClientDbConn</span></span></span></span>]（也可以在appsettings.json中配置），并且需要与api.itdos.com镜像保持一致。<br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;选中网站，在右侧[管理]--[配置编辑器]，选择节[system.webServer/aspNetCore]，编辑[environmentVariables]：<br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;添加完环境变量后，需要重启网站。<br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;web.config中建议修改配置stdoutLogEnabled=&quot;true&quot;，可在程序根目录/logs/stdout_***.log中查看运行日志、错误日志。<br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<img src=\"https://static-ali-img.itdos.com/upload/editor/image/202211/6380477407893740586127381.png\" alt=\"win3.png\" style=\"white-space: normal; width: 1024px;\"/><br/>&nbsp;&nbsp;&nbsp;&nbsp;部署完成后，分别访问是否正常（假设端口为1051）：<br/><a href=\"http://localhost:1051/\" target=\"_blank\">http://localhost:1051/</a><br/><a href=\"http://localhost:1051/.well-known/openid-configuration\" target=\"_blank\">http://localhost:1051/.well-known/openid-configuration</a>（会返回json数据）</p><p><br/></p><p><br/> <br/><strong><br/></strong></p><p><strong>&nbsp; 4. 部署api.itdos.com后端接口系统</strong><br/></p><p><br/></p><p><strong>方案1（推荐）：</strong></p><p>和auth部署几乎一样！<strong><br/></strong>a ) 将三件套中的api包解压开，将之前auth目录下的appsettings.json直接复制过来，覆盖即可</p><p><br/></p><p>b ) json文件覆盖完成后，在同级目录下运行cmd或者powershell，执行命令 ```dotnet Microi.net.Api.dll --urls=http://0.0.0.0:1061```,成功运行程序，若提示lisence问题，则提供对应的HID（注意HID会在报错信息中输出，可直接获取HID），反馈给系统管理员，来获取商业授权获取证书，获取后，放到同级目录下覆盖后，再次运行命令即可。</p><p>c ) 部署完成后，分别访问是否正常（假设端口为1061）：<br/><a href=\"http://localhost:1051/\" target=\"_blank\">http://localhost:1061/</a><br/><br/></p><p>d ) 最后可将改服务程序制作成windows server服务进行管理，命令参考如下：``` sc create microi-api binPath=&quot;C:\\Microi\\Microi.net.Api\\net6.0 \\Microi.net.Api.exe&quot; ```</p><p><br/></p><p><br/></p><p><br/></p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<strong style=\"text-wrap: wrap;\">方案2（不推荐）</strong><br/><span style=\"text-wrap: wrap;\">步骤同身份认证系统一模一样，只是要选择.NET6Api应用程序池，额外添加4个环境变量[</span><span style=\"text-wrap: wrap; color: #212529; font-family: &quot;Helvetica Neue&quot;, Helvetica, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, Arial, sans-serif; font-size: 14px; background-color: #FFFFFF;\">OsClientRedisHost、OsClientRedisPort、OsClientRedisPwd、AuthServer</span><span style=\"text-wrap: wrap;\">]（注意若数据库Sys_OsClient表中已经存在此4个环境变量正确的值，可不用在此添加）。</span><br/><span style=\"text-wrap: wrap;\">web.config中建议修改配置stdoutLogEnabled=&quot;true&quot;，可在程序根目录/logs/stdout_***.log中查看运行日志、错误日志。</span><br/><img src=\"https://static-ali-img.itdos.com/upload/editor/image/202211/6380485444078778701691847.png\" alt=\"win5.png\" style=\"text-wrap: wrap;\"/></p><p><br/></p><p><br/></p><p><strong>&nbsp; 5.部署os.itdos.com前端访问系统<br/></strong>a ) 直接创建网站即可，使用任意程序池均可，不用配置环境变量，<br/>b ) 但需要修改根目录/index.html中的OsClient、ApiBase对应的变量值。这里图中只是参考，<strong>要按真实的client名字和api地址接口来填写</strong></p><p><img src=\"https://static-ali-img.itdos.com//itdos/itdos/upload/editor/image/202309/6383124964739859058076187_origin.png/20230925/os-html.png\" alt=\"os-html.png\"/><br/>注意：<br/>部署微服务时，需要在http标头添加允许跨域：<br/>Access-Control-Allow-Origin&nbsp; &nbsp; &nbsp; &nbsp; *<br/>c ) 添加后重启网站和应用程序池。<br/><br/><br/><br/><br/><br/></p>', b'1', 'd216e012-8872-4944-a9d9-207d39cba61f', '', 2, NULL);
INSERT INTO `diy_document` VALUES ('61756b73-5347-4fb4-aac7-b136e9bc4e3e', '2022-11-10 17:44:16', NULL, 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '', '<ol class=\" list-paddingleft-2\" style=\"list-style-type: decimal;\">\n    <li>\n        <p>\n            安装IIS<br/>此步骤为基操，可百度。<br/><br/>\n        </p>\n    </li>\n    <li>\n        <p>\n            安装MySql数据库<br/>官方5.7下载地址：<a href=\"https://dev.mysql.com/downloads/file/?id=514047\" target=\"_blank\">https://dev.mysql.com/downloads/file/?id=514047</a><br/>点击【No thanks, just start my download.】<br/>安装步骤截图：<br/><br/><br/>\n        </p>\n    </li>\n    <li>\n        <p>\n            <img src=\"https://static-ali-img.itdos.com/upload/editor/image/202211/6380369903514717805320923.png\" style=\"\"/>\n        </p>\n    </li>\n    <li>\n        <p>\n            <img src=\"https://static-ali-img.itdos.com/upload/editor/image/202211/6380369903553471386628081.png\" style=\"\"/>\n        </p>\n    </li>\n    <li>\n        <p>\n            <img src=\"https://static-ali-img.itdos.com/upload/editor/image/202211/6380369903578114162396094.png\" style=\"\"/>\n        </p>\n    </li>\n    <li>\n        <p>\n            <img src=\"https://static-ali-img.itdos.com/upload/editor/image/202211/6380369903608305376252952.png\" style=\"\"/>\n        </p>\n    </li>\n    <li>\n        <p>\n            <img src=\"https://static-ali-img.itdos.com/upload/editor/image/202211/6380369903728321578376962.png\" style=\"\"/>\n        </p>\n    </li>\n    <li>\n        <p>\n            <img src=\"https://static-ali-img.itdos.com/upload/editor/image/202211/6380369903727997722580803.png\" style=\"\"/>\n        </p>\n    </li>\n    <li>\n        <p>\n            <img src=\"https://static-ali-img.itdos.com/upload/editor/image/202211/6380369903749410369636717.png\" style=\"\"/>\n        </p>\n    </li>\n    <li>\n        <p>\n            安装Redis缓存<br/><br/><br/>\n        </p>\n    </li>\n    <li>\n        <p>\n            安装MongoDB数据库<br/><br/><br/>\n        </p>\n    </li>\n    <li>\n        <p>\n            安装MinIO分布式存储<br/><br/><br/>\n        </p>\n    </li>\n</ol>', b'0', NULL, '', 0, NULL);
INSERT INTO `diy_document` VALUES ('65cd77d4-a979-433d-bd71-324ecbd27ccd', '2024-04-01 16:33:24', '2024-05-09 15:28:57', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '表结构说明及同步方案', '<p>同步方案：<br/></p><p style=\"white-space: normal;\">&nbsp; &nbsp; 1、首次测试环境向正式环境全量迁移：<br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;可直接将测试环境数据库覆盖至正式环境，然后去正式环境修改：</p><ul class=\" list-paddingleft-2\" style=\"list-style-type: disc;\"><ul class=\" list-paddingleft-2\" style=\"list-style-type: square;\"><li><p style=\"white-space: normal;\">sys_config：系统设置。如：系统标题/Logo等、FileServer、ApiBase、<span style=\"font-family: &quot;Helvetica Neue&quot;, Helvetica, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, Arial, sans-serif; font-size: 14px; background-color: #FFFFFF;\">全局V8引擎代码里面可能需要改掉的常量</span></p></li><li><p>sys_osclients：SaaS引擎。如：Redis配置、MinIO配置等</p></li></ul></ul><p>&nbsp;&nbsp;&nbsp;&nbsp;2、测试环境向正式环境差量迁移模块（或系统A向系统B差量迁移模块）：<br/></p><ul class=\" list-paddingleft-2\" style=\"list-style-type: disc;\"><ul class=\" list-paddingleft-2\" style=\"list-style-type: square;\"><li><p>针对完全新增的表模块（如diy_test1、diy_test2），在测试环境sql管理器中分别执行<br/>【select * from diy_table where `Name` in (&#39;diy_test1&#39;, &#39;diy_test2&#39;)】<br/>【select * from diy_field where TableId in (select Id from diy_table where `Name` in (&#39;diy_test1&#39;, &#39;diy_test2&#39;))】<br/>【select * from sys_menu where `Name` In (&#39;test1&#39;, &#39;test2&#39;)】<br/>将数据结果复制为Insert语句到正式环境数据库中执行，并且在测试环境数据库中复制diy_test1、diy_test2的物理表结构sql到正式环境数据库中执行。</p></li><li><p>针对已有表的模块新增的一些字段，建议手动再加一下</p></li><li><p>以上操作后期可通过【应用商城】的数据库包功能进行全量或差量同步。</p></li></ul></ul><p>&nbsp;&nbsp;&nbsp;&nbsp;3、测试环境向正式环境全量同步所有模块：</p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;可直接全量同步的表：<br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;diy_table、diy_field、diy_component、microi_print_template、sys_apiengine、sys_datasource、sys_basedata、<br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;sys_dept、sys_role、sys_rolelimit、<br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;wf_flowdesign、wf_node、wf_line、<br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;可能需要差量同步的表：<br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;sys_menu（测试环境可能包含一些测试模块）、<br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;不可直接同步的表：<br/>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;sys_osclients、sys_config<br/></p><p><br/></p><p><strong>表结构说明：</strong><br/></p><p>diy_table<br/></p><p>&nbsp; &nbsp; DIY表，如在表单设计列表处新增一张表【diy_test】，diy_table就会新增一条记录，大致包含：物理表名、表说明、表单属性配置。<br/></p><p>diy_field</p><p>&nbsp; &nbsp; DIY表字段，包含表单设计器里的字段属性<br/></p><p>diy_component<br/>&nbsp; &nbsp; 系统表单组件<br/></p><p>diy_tenant<br/>&nbsp;&nbsp;&nbsp;&nbsp;系统租户<br/></p><p>microi_database<br/>&nbsp;&nbsp;&nbsp;&nbsp;扩展数据库<br/></p><p>microi_datalog<br/>&nbsp;&nbsp;&nbsp;&nbsp;数据日志<br/></p><p>microi_print_template<br/>&nbsp;&nbsp;&nbsp;&nbsp;自定义导出打印word模板<br/></p><p>sys_apiengine<br/>&nbsp;&nbsp;&nbsp;&nbsp;接口引擎<br/></p><p>sys_basedata<br/>&nbsp;&nbsp;&nbsp;&nbsp;基础数据<br/></p><p>sys_config<br/>&nbsp;&nbsp;&nbsp;&nbsp;系统设置<br/></p><p>sys_configtenant<br/>&nbsp;&nbsp;&nbsp;&nbsp;租户独立系统设置<br/></p><p>sys_datasource<br/>&nbsp;&nbsp;&nbsp;&nbsp;数据源引擎<br/></p><p>sys_dept<br/>&nbsp;&nbsp;&nbsp;&nbsp;部门机构<br/></p><p>sys_menu<br/>&nbsp;&nbsp;&nbsp;&nbsp;菜单、模块引擎<br/></p><p>sys_role<br/>&nbsp;&nbsp;&nbsp;&nbsp;角色<br/></p><p>sys_rolelimit<br/>&nbsp;&nbsp;&nbsp;&nbsp;角色权限<br/></p><p>sys_user<br/>&nbsp;&nbsp;&nbsp;&nbsp;系统用户<br/></p><p>wf_flow<br/>&nbsp;&nbsp;&nbsp;&nbsp;流程实例。每发起一个流程，会新增一条数据，不管流程怎么流转，发起的流程对应此表只有一条数据，显示流程当前状态、发起人等信息。<br/></p><p>wf_flowdesign<br/>&nbsp;&nbsp;&nbsp;&nbsp;流程设计图。包含流程属性。<br/></p><p>wf_history<br/>&nbsp;&nbsp;&nbsp;&nbsp;工作流转历史记录<br/></p><p>wf_line<br/>&nbsp;&nbsp;&nbsp;&nbsp;流程设计的线，包含线属性<br/></p><p>wf_node<br/>&nbsp;&nbsp;&nbsp;&nbsp;流程设计的节点，包含节点属性<br/></p><p>wf_work<br/>&nbsp;&nbsp;&nbsp;&nbsp;工作表，流程每运行到一个节点均会新增数据，如果有N个人接收到待办任务此表会生产N条数据，包括打回、移交均会产生新的数据。<br/></p><p><br/></p><p><br/></p><p>迁移数据库时，不可直接删除全部数据的平台基础表：</p><p>diy_component（所有控件）</p><p>diy_field（所有字段）</p><p>diy_table（所有表）<br/></p><p>diy_sso（删除里面的token那条数据会导致无法通过url token参数自动登录）</p><p>sys_apiengine（接口引擎）</p><p>sys_basedata（里面有一些系统原厂基础数据不能删除）<br/></p><p>sys_config（系统设置不能删除）<br/></p><p>sys_datasource（数据源引擎）<br/></p><p>sys_dept（部门机构不能全删一条不留）<br/></p><p>sys_menu（菜单模块）<br/></p><p>sys_microiservice（微服务）<br/></p><p>sys_osclients（saas引擎）<br/></p><p>sys_role（角色）</p><p>sys_rolelimit（角色权限）</p><p>sys_user（admin帐号不能删）<br/></p><p>sys_userfk（admin帐号相关的不能删）</p><p><br/></p><p><br/></p><p><br/></p><p><br/></p><p><br/></p><p><br/></p><p><br/></p><p><br/></p><p><br/></p>', b'1', '808f0a05-6587-4439-ab96-8403f9349b4f', '', 999, NULL);
INSERT INTO `diy_document` VALUES ('73eb2ede-7779-4bc8-93bd-a0d5d6eec537', '2022-03-20 18:37:50', '2023-08-06 17:44:07', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '成功案例', '<ul class=\" list-paddingleft-2\" style=\"list-style-type: disc;\"><li><p style=\"margin-bottom: 10px;\">目前已有成功案例客户50家以上。</p></li><li><p style=\"margin-bottom: 10px;\">由于我们的客户很多是开发者、企业开发团队，他们基于Microi吾码低代码平台开发的软件产品已应用到数百家企业。<br/></p></li><li><p style=\"box-sizing: border-box; padding: 0px; margin-top: 0px; margin-bottom: 10px;\"><span style=\"box-sizing: border-box; padding: 0px; margin: 0px;\">房地产互联网平台（类似贝壳）（大量的前端<span style=\"box-sizing: border-box; padding: 0px; margin: 0px;\">微服务定制</span>）</span></p></li><li><p style=\"box-sizing: border-box; padding: 0px; margin-top: 0px; margin-bottom: 10px;\"><span style=\"box-sizing: border-box; padding: 0px; margin: 0px;\">大型电器ERP（300+表，100+模块）（大量的后端二次开发定制）</span></p></li><li><p style=\"box-sizing: border-box; padding: 0px; margin-top: 0px; margin-bottom: 10px;\"><span style=\"box-sizing: border-box; padding: 0px; margin: 0px;\">多个服装ERP（100+表，1个人1个月完成）（纯低代码平台实现的服装ERP系统）</span></p></li><li><p style=\"box-sizing: border-box; padding: 0px; margin-top: 0px; margin-bottom: 10px;\"><span style=\"box-sizing: border-box; padding: 0px; margin: 0px;\">物联网智能家居（亿级数据量处理）、植物工厂智能硬件控制</span></p></li><li><p style=\"box-sizing: border-box; padding: 0px; margin-top: 0px; margin-bottom: 10px;\"><span style=\"box-sizing: border-box; padding: 0px; margin: 0px;\"><span style=\"box-sizing: border-box; padding: 0px; margin: 0px; white-space: pre;\"></span>集团、国企OA系统</span></p></li><li><p style=\"box-sizing: border-box; padding: 0px; margin-top: 0px; margin-bottom: 10px;\"><span style=\"box-sizing: border-box; padding: 0px; margin: 0px;\">停车场、潮汐检测、固定资产、CRM 等等平台</span></p></li></ul>', b'1', NULL, '', 9999, NULL);
INSERT INTO `diy_document` VALUES ('7a059752-f849-4715-98de-7beb5d0991a3', '2022-03-20 12:32:02', '2023-08-06 17:39:05', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '下载框架源码', '<p style=\"box-sizing: border-box;line-height: inherit;orphans: 4;margin-top: 0px;margin-bottom: 0.5rem;white-space: pre-wrap;width: inherit;position: relative;color: rgb(51, 51, 51);font-family: &#39;Open Sans&#39;, &#39;Clear Sans&#39;, &#39;Helvetica Neue&#39;, Helvetica, Arial, sans-serif;background-color: rgb(255, 255, 255)\"><span style=\"box-sizing: border-box\">拉取源码</span></p><pre class=\"md-fences md-end-block ty-contain-cm modeLoaded\" style=\"box-sizing: border-box;font-family: var(--monospace);font-size: 0.9em;break-inside: avoid;overflow: visible;white-space: normal;background-image: inherit;background-position: inherit;background-size: inherit;background-repeat: inherit;background-attachment: inherit;background-origin: inherit;background-clip: inherit;border: 1px solid rgb(231, 234, 237);border-radius: 3px;padding: 8px 4px 6px;margin-bottom: 15px;margin-top: 15px;width: inherit;color: rgb(51, 51, 51);position: relative !important\">#git&nbsp;clone&nbsp;&nbsp;\n帐号密码为iTdos官方注册帐号密码，拉取权限由商业授权获得</pre><p style=\"box-sizing: border-box;line-height: inherit;orphans: 4;margin-top: 0.5rem;margin-bottom: 0.5rem;white-space: pre-wrap;width: inherit;position: relative;color: rgb(51, 51, 51);font-family: &#39;Open Sans&#39;, &#39;Clear Sans&#39;, &#39;Helvetica Neue&#39;, Helvetica, Arial, sans-serif;background-color: rgb(255, 255, 255)\"><span style=\"box-sizing: border-box\">本系统由.net 6.0开发，支持.net core 2.x/3.x/5.0/6.0</span></p><p><br/></p>', b'1', 'f1fab703-bf30-44e9-a538-0fde57dd7671', '', 0, NULL);
INSERT INTO `diy_document` VALUES ('7afc4dae-d5b1-486c-8796-3c30625fa5c8', '2023-08-09 02:51:29', '2024-04-02 16:49:12', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', 'DosResult说明', '<p>服务器端几乎所有接口返回的类型均为DosResult，因此建议接口引擎、服务器端二次开发也这样返回给到前端。</p><p>格式为：<br/></p><pre class=\"brush:js;toolbar:false\">{&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;Code&nbsp;:&nbsp;1,//值说明见下面INSERT INTO `diy_document` VALUES ('7c965880-acdb-4091-adc6-b14e276a4da8', '2024-02-18 12:00:39', '2024-02-18 13:51:31', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '创建表单模块', '<p>本节视频讲述如何快速创建一个带<span style=\"text-wrap: wrap;\">增删改查的表单</span>模块。</p><p><br/></p><p>目前吾码平台的每个模块（菜单）需要对应一张数据库表，因此：</p><p>1、创建数据库表，并设计</p><p>2、创建模块引擎</p><p><br/></p>', b'1', '8da6fe30-dda4-47b0-99c9-ef283195a2ae', '', 10, NULL);
INSERT INTO `diy_document` VALUES ('7ee94ecb-4d8d-46df-a9fd-530832c56ed4', '2022-07-26 18:20:10', '2023-08-09 00:06:40', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '模块引擎', '<ul class=\" list-paddingleft-2\" style=\"list-style-type: disc;\"><li><p>数据列表页支持的Url参数<br/>用法：this.$router.push(&#39;/microi-upt-log?Keyword=v3.5.27&amp;Tab=测试Tab3&amp;_SearchDateTime=CreateTime|2022-07-01|2022-07-26&#39;)<br/><span style=\"color: #4F81BD;\"><strong>Keyword</strong></span>：模糊搜索<br/><strong><span style=\"color: #4F81BD;\">Tab</span></strong>：选中某个Tab页签<br/><strong><span style=\"color: #4F81BD;\">_SearchDateTime</span></strong>：时间区间搜索，分为3段：字段名称、开始时间、结束时间<br/><br/></p></li></ul>', b'1', '808f0a05-6587-4439-ab96-8403f9349b4f', '', 50, NULL);
INSERT INTO `diy_document` VALUES ('808f0a05-6587-4439-ab96-8403f9349b4f', '2022-03-20 12:20:02', NULL, 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '使用文档', '', b'1', NULL, '', 30, NULL);
INSERT INTO `diy_document` VALUES ('80d5a5a5-60c6-4369-8e3f-3d520da20ec5', '2022-07-05 10:47:58', NULL, 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '接口说明', '<ul class=\" list-paddingleft-2\" style=\"list-style-type: disc;\"><li><p>Swagger地址<br/><a href=\"https://api-china.itdos.com/swagger/index.html\" target=\"_blank\">https://api-china.itdos.com/swagger/index.html</a></p></li><li><p>获取数据列表<br/>接口地址：/api/DiyTable/GetDiyTableRow<br/>参数：{<br/>&nbsp;&nbsp;&nbsp;&nbsp;<br/>}<br/><br/></p></li></ul>', b'1', 'a35e6604-e290-46d6-8769-94a680758637', '', 20, NULL);
INSERT INTO `diy_document` VALUES ('8197669f-e2b5-4716-8531-5378462383ea', '2024-02-18 12:48:15', '2024-02-18 13:07:34', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '平台介绍', '<p><br/></p><p>详见平台PPT：<a href=\"https://file.microios.com/microios-public/microios/file/upload/microi.net.ppt.20231227.pdf\">https://file.microios.com/microios-public/microios/file/upload/microi.net.ppt.20231227.pdf</a></p>', b'1', '8da6fe30-dda4-47b0-99c9-ef283195a2ae', '', 1, NULL);
INSERT INTO `diy_document` VALUES ('81b5d8fd-d93e-46ad-9363-568aeac82ab9', '2023-07-28 14:36:58', '2023-08-06 17:10:54', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', 'V8引擎代码', '<ul class=\" list-paddingleft-2\" style=\"list-style-type: disc;\"><li><p>V8引擎代码分为前端和服务器端两种。</p><p>如【表单提交前V8事件】属于前端V8，【服务器端表单提交前V8事件】属于后端V8。</p></li><li><p>前端与服务器端V8均为javascript语法，集成了有很多不同的函数名称、变量名称，但只要前后端函数名称相同的情况下，用法几乎一致。</p></li></ul>', b'1', '808f0a05-6587-4439-ab96-8403f9349b4f', '', -20, NULL);
INSERT INTO `diy_document` VALUES ('820eb166-abaf-4fac-9bbb-73933c926e21', '2022-03-20 12:21:31', '2024-12-04 03:36:39', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '环境安装', '<p><span style=\"color: rgb(225, 60, 57); font-size: 24px;\"><strong>最新线上文档： </strong></span><a href=\"https://microi.blog.csdn.net/article/details/143576299\" target=\"_blank\"><span style=\"color: rgb(225, 60, 57); font-size: 24px;\"><strong>https://microi.blog.csdn.net/article/details/143576299</strong></span></a><span style=\"color: rgb(225, 60, 57); font-size: 24px;\"><strong> </strong></span></p><ol><li>安装Docker环境 #curl -fsSL https://get.docker.com | bash -s docker --mirror Aliyun#systemctl start docker#systemctl enable docker.service</li><li>安装MySql数据库</li><ol><li>通过docker安装#docker pull mysql:5.6 说明：支持MySql5.5、5.6、5.7、8任意版本，可自由选择，参考https://hub.docker.com/_/mysql?tab=tags #docker run -itd --name mysql56 --restart=always --log-opt max-size=10m --log-opt max-file=10 -v /home/mysql56/data:/var/lib/mysql -p 3307:3306 -e MYSQL_ROOT_PASSWORD=iTdos.pwd.mySql -e TZ=Asia/Shanghai mysql:5.6 --lower-case-table-names=1 --character-set-server=utf8mb4 --collation-server=utf8mb4_unicode_ci 说明： a、取名mysql56（自定义） b、将MySql数据文件映射至容器外部的/home/mysql56/data（自定义） c、将3306端口映射至3307（自定义），预防外部机器撞库 d、iTdos.pwd.mySql为root密码（自定义） e、TZ=Asia/Shanghai，指定时区， f、lower-case-table-names=1，不区分大小写。</li><li>通过原生安装 需要修改配置文件，在[mysqld]下增加配置：lower_case_table_names=1 注意创建数据时，字符集使用utf8mb4，排序规则使用utf8mb4_general_ci</li></ol></ol><p><br><br></p><ol><li>安装Redis缓存</li><ol><li>通过docker安装#docker pull redis:6.2.7 说明： 版本随意（目前我们是6.x），自由选择，参考https://hub.docker.com/_/redis?tab=tags #docker run -itd --name redis6 --restart=always --log-opt max-size=10m --log-opt max-file=10 -p 6380:6379 redis:6.2.7 --requirepass Microi.redis 说明： 取名redis（自定义），6379映射至6380（自定义），密码：Microi.redis（自定义）</li><li>通过原生安装</li><li>也可以安装redis哨兵模式</li></ol><li>安装MongoDB数据库（注意需要映射数据目录）</li><ol><li>通过docker安装#docker pull mongo:4.4.17 或者 #docker pull registry.cn-beijing.aliyuncs.com/itdos/mongo4:4.4.17 说明： 目前我们是4.x，6.x版本好像命令有变，参考https://hub.docker.com/_/mongo?tab=tags&page=1 #docker run -itd --name mongo4 --restart=always --log-opt max-size=10m --log-opt max-file=10 -p 27018:27017 mongo:4.4.17 --auth 或者 #docker run -itd --name mongo4 --restart=always --log-opt max-size=10m --log-opt max-file=10 -p 27018:27017 registry.cn-beijing.aliyuncs.com/itdos/mongo4:4.4.17 --auth #docker exec -it mongo4 mongo root #use admin #db.createUser({user: \'root\', pwd: \'iTdos.mongo\', roles: [\'root\']}) 说明：创建root用户，密码iTdos.mongo（自定义） #db.auth(\'root\', \'iTdos.mongo\') 说明：测试连接，返回1表示正确</li><li>通过原生安装mong --port 27018</li></ol><li>安装MinIO分布式存储（使用阿里云OSS等云存储不需要安装MinIO）</li><ol><li>通过docker安装#docker run -p 9010:9000 -p 9011:9001 --name minio \\ --restart=always \\ --log-opt max-size=10m --log-opt max-file=10 \\ -e \"MINIO_ROOT_USER=root\" \\ -e \"MINIO_ROOT_PASSWORD=iTdos.minio\" \\ -v /data/minio/data:/data \\ -v /data/minio/config:/root/.minio \\ -d minio/minio server /data --console-address \":9001\" 说明： 9011为MinIO后台管理系统地址端口，9010为文件访问地址以及接口调用端口。 MINIO_ROOT_USER、MINIO_ROOT_PASSWORD为帐号密码，自定义， 通过ip:9011登陆进去，创建2个Bucket，一个私有，一个公有，可分别取名（名称自定义）：itdos-public（需界面中配置权限为public）、itdos-private 注意服务器9010端口一定要开放外网访问，前端上传的图片若允许公网访问，则是通过MinIO的公有Bucket域名访问。</li></ol></ol>', b'1', '26f2a98b-3a16-4312-9f2e-b1137846824d', '', 0, '');
INSERT INTO `diy_document` VALUES ('831d0023-0896-43b5-a01a-0ce17adc17de', '2023-08-04 11:43:49', '2024-11-27 02:32:04', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', 'V8.FormEngine用法', '<p><span style=\"color: rgb(225, 60, 57); font-size: 22px;\"><strong>最新线上文档： </strong></span><a href=\"https://microi.blog.csdn.net/article/details/143623519\" target=\"_blank\"><span style=\"color: rgb(225, 60, 57); font-size: 22px;\"><strong>https://microi.blog.csdn.net/article/details/143623519</strong></span></a><span style=\"color: rgb(225, 60, 57); font-size: 22px;\"><strong> </strong></span></p><p><br></p><p>此文档为服务器端V8、前端V8共享文档，两者均为javascript语法。</p><p>前后端V8均支持V8.FormEngine对象，用法基本一致，但略有差别。</p><p>服务器端[V8.FormEngine.函数]对表的所有操作，均支持第二个参数传入V8.DbTrans对象，而前端V8多次调用FormEngine的函数无法带事务，因为是多次请求http接口。</p><p>注意在接口引擎中需要执行V8.DbTrans.Commit()或V8.DbTrans.Rollback()，</p><p>而在服务器端V8事件中无需执行V8.DbTrans.Commit()【外部会执行】，只需要视情况执行V8.DbTrans.Rollback()</p><p>V8.FormEngine下所有函数为单表操作（除Batch批量操作），如需多表关联查询，请查看V8.ModuleEngine用法。</p><p><br></p><ul><li>若是前端V8，则用法有两种：</li><li>第一种，同步执行： var result = await V8.FormEngine.GetTableData({//注意有个await FormEngineKey : \'\',//表名或表Id，不区分大小写 _Where : [] }); 第二种，异步执行： V8.FormEngine.GetTableData({ FormEngineKey : \'\',//表名或表Id _Where : [] }, function(result){ //在回调函数中获取result结果 //值得注意的是：如果要在回调函数中使用await，那么需要将上面的function(result)定义为 async function(result) });</li></ul><p><br></p><ul><li>若是服务器端V8，用法暂时只有一种，同步执行：</li><li>var result = V8.FormEngine.GetTableData({ FormEngineKey : \'\',//表名、表Id _Where : [], }, V8.DbTrans);//服务器端第二个参数支持传入V8.DbTrans对象，注意需要执行V8.DbTrans.Commit()或V8.DbTrans.Rollback(); //也可写 await V8.FormEngine.GetTableData()，目前写或不写await均为同步返回结果。 //异步写法为：V8.FormEngine.GetTableDataAsync()，但暂不支持回调函数</li></ul><p><br></p><ul><li>若是服务器端.net二次开发，则c#写法（非V8 javascript语法）为：</li><li>var _formEngine = new FormEngine(); var result = await _formEngine.GetTableDataAsync(new { FormEngineKey = \"\", _Where = new List&lt;DiyWhere&gt;(){ ... } });</li><li>GetFormData</li><li>//获取一条数据，这里列举了服务器端V8、前端V8两种写法，其它函数均同理。 //服务器端V8写法（同步）： var modelResult = V8.FormEngine.GetFormData({ FormEngineKey : \'\',//必传。可以是TableName的值，也可以是TableId的值, Id : \'\',//Id与_Where两者必传其一 _Where : []//Id与_Where两者必传其一 }); //前端V8写法一（同步）： var modelResult = await V8.FormEngine.GetFormData({ FormEngineKey : \'\' Id : \'\' }); //前端V8写法二（异步）： V8.FormEngine.GetFormData({ FormEngineKey : \'\' Id : \'\' }, function(modelResult){ //在回调函数中获取modelResult结果 //值得注意的是：如果要在回调函数中使用await，那么需要将上面的function(modelResult)定义为 async function(modelResult) }); //返回 { Code : 1/0, Data : {}, Msg : \'错误信息\' } //值得注意的是： //当表单属性中开启了【允许匿名新增数据】，那么则可以不传入token使用V8.FormEngine.GetFormDataAnonymous()获取数据 //参数与上面一致，但需要新增一个OsClient的参数</li><li>UptFormData</li><li>//修改一条数据 V8.FormEngine.UptFormData({ FormEngineKey : \'\', Id : \'\',//必传 _RowModel : { FieldName : \'\'//要修改的字段，注意字段值不能是{}或[]，需要序列化 } });</li><li>UptFormDataBatch</li><li>//批量修改，自带事务，也可第二个参数传入V8.DbTrans事务对象。 //每条数据支持不同的表FormEngineKey var uptList = []; uptList.push({ FormEngineKey : \'\', Id : \'\',//必传 _RowModel: { } }); var uptResult = V8.FormEngine.UptFormDataBatch(uptList);</li><li>UptFormDataByWhere</li><li>//根据where条件进行批量修改，谨慎操作。如果未传入条件，则返回错误 //对应sql：update diy_content set Name=\'xxx\' where ContentKey like \'%test%\' var result = V8.FormEngine.UptFormDataByWhere({ FormEngineKey : \'diy_content\', _Where : [{ Name : \'ContentKey\', Value : \'test\', Type : \'Like\' }], _RowModel : { Name : \'xxx\' } });</li><li>DelFormData</li><li>//删除一条数据 V8.FormEngine.DelFormData({ FormEngineKey : \'\',//必传 Id : \'\',//必传 });</li><li>DelFormDataBatch</li><li>//批量删除，自带事务，也可第二个参数传入V8.DbTrans事务对象。 //每条数据支持不同的表FormEngineKey var delList = []; delList.push({ FormEngineKey : \'\', Id : \'\',//必传 }); var delResult = V8.FormEngine.DelFormDataBatch(delList);</li><li>DelFormDataByWhere</li><li>//根据where条件进行批量删除，谨慎操作。如果未传入条件，则返回错误 //对应sql：DELETE FROM diy_content WHERE ContentKey LIKE \'%test%\' var result = V8.FormEngine.DelFormDataByWhere({ FormEngineKey : \'diy_content\', _Where : [{ Name : \'ContentKey\', Value : \'test\', Type : \'Like\' }], });</li><li>AddFormData</li><li>//新增一条数据 V8.FormEngine.AddFormData({ FormEngineKey : \'\',//必传 Id : \'\',//可选，若不传则由服务器端自动生成guid值 _RowModel : { } }); //返回 { Code : 1/0, Data : {新增后的数据对象，包含Id、CreateTime、UserId等默认字段}, Msg : \'错误信息！\' } //值得注意的是：当表单属性中开启了【允许匿名新增数据】，那么则可以不传入token使用V8.FormEngine.AddFormDataAnonymous()新增数据 //参数与上面一致，但需要新增一个OsClient的参数。</li><li>AddFormDataBatch</li><li>//批量新增，自带事务，也可第二个参数传入V8.DbTrans事务对象。 //每条数据支持不同的表FormEngineKey var addList = []; addList.push({ FormEngineKey : \'\', Id : \'\',//可选 _RowModel: { } }); var addResult = V8.FormEngine.AddFormDataBatch(addList);</li><li>GetTableData</li><li>//获取数据列表 V8.FormEngine.GetTableData({ FormEngineKey : \'\',//必传 //对应Sql条件：where Age = \'10\' AND Account &lt;&gt; \'admin\' _Where : [{ Name : \'Age\', Value : \'10\', Type : \'=\' }, { Name : \'Account\', Value : \'admin\', Type : \'!=\' }], _OrderBy : \'Name\',//可选。传入排序字段名称，暂不支持多字段排序。 _OrderByType : \'ASC\',//可选。值：DESC、ASC（大小写无所谓） }); //返回 { Code : 1/0, Data : [], DataCount : 数量总数用于计算分页, Msg : \'错误信息\' } //值得注意的是：当表单属性中开启了【允许匿名读取数据】，那么则可以不传入token使用V8.FormEngine.GetTableDataAnonymous()获取数据 //参数与上面一致，但需要新增一个OsClient的参数。</li><li>GetTableDataCount</li><li>//仅获取数据条数</li><li>GetTableDataTree</li><li>//获取一个树形数据，前提是表单设计中必须开启【树形结构】配置 //值得注意的是：当表单属性中开启了【允许匿名读取数据】，那么则可以不传入token使用V8.FormEngine.GetTableDataTreeAnonymous()获取数据 //参数与上面一致，但需要新增一个OsClient的参数。</li><li>GetFieldData</li><li>//获取某个字段配置的数据源</li><li>AddField</li><li>//暂时仅支持服务器端V8。新增一个字段 var addField = V8.FormEngine.AddField({ TableName : \'Diy_Test\',//表名 Name : \'Age\',//字段名 Type : \'int\',//字段类型 Label : \'年龄\',//字段显示名称, Component : \'NumberText\',//控件类型 TableWidth : \'100\',//表格宽度 Visible : 1 //是否显示 });</li><li>AddTable</li><li>//暂时仅支持服务器端V8。新增一张表</li></ul><p><br></p><p><br></p>', b'1', '81b5d8fd-d93e-46ad-9363-568aeac82ab9', '', 40, '');
INSERT INTO `diy_document` VALUES ('840a052a-c10a-47bd-b01f-2c70d32ad207', '2022-06-22 13:57:13', '2022-06-25 14:23:26', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '定制组件', '<p><br/></p><p>定制组件实际上是最强大的表单引擎组件，它可以实现任何功能，由开发者定制开发，具体开发流程如下：<br/><br/></p><ul class=\" list-paddingleft-2\" style=\"list-style-type: disc;\"><li><p>创建一个/views/test/loudong.vue的定制组件（源码在主框架源码）<br/>定制组件中可以通过监听DataAppend来实现数据的变化<br/><br/></p></li><li><p>在表单中添加一个定制组件，自定义填写组件名称，填写组件路径/test/loudong.vue<br/><br/></p></li><li><p>可以在任意地方的V8事件中给定制组件赋值：<br/></p><pre class=\"brush:js;toolbar:false\">V8.FieldSet(&#39;定制组件字段名&#39;,&nbsp;&#39;DataAppend&#39;,&nbsp;值);\n例子：\nV8.FieldSet(&#39;DevComponent98&#39;,&nbsp;&#39;DataAppend&#39;,&nbsp;{HourseDirId&nbsp;:&nbsp;V8.Form.Biaoti,&nbsp;Name&nbsp;:&nbsp;&#39;Test&#39;});\n\n说明：\nDataAppend为定制组件的Props，建议固定此名称。</pre><p><br/></p></li><li><p>在main.js或需要的地方中注册定制组件<br/>注意：目前基于前端microi.net组件进行二次开发，需要以下手动注册组件，后面会解决此问题不需要手动注册。目前基于microi.net源码开发不需要手动注册。</p><pre class=\"brush:js;toolbar:false\">var&nbsp;LoudongTestComponent&nbsp;=&nbsp;(resolve)&nbsp;=&gt;&nbsp;require([&#39;@/views/test/loudong&#39;],&nbsp;resolve)\nVue.component(&#39;LoudongTestComponent&#39;,&nbsp;LoudongTestComponent);</pre><p><br/></p></li><li><p>效果如下：<br/><img src=\"https://static-ali-img.itdos.com/upload/editor/image/202206/6379150390025498609095096.png\" alt=\"WX20220622-141124@2x.png\"/><br/></p></li></ul><p><br/></p>', b'1', 'bdd79162-325c-419c-958b-90360ac789cc', '', 0, NULL);
INSERT INTO `diy_document` VALUES ('847cf98b-5746-4087-bd9f-3c7e80084b4f', '2022-03-20 12:55:11', NULL, 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '本地部署', '', b'1', '0a240028-7f75-4f0c-b411-3a60327d2344', '', 0, NULL);
INSERT INTO `diy_document` VALUES ('84cf94ae-ec1e-4628-ae7d-bbbf2d05c217', '2024-02-18 12:50:29', '2024-02-18 13:51:19', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '表单控件及V8引擎', '', b'1', '8da6fe30-dda4-47b0-99c9-ef283195a2ae', '', 30, NULL);
INSERT INTO `diy_document` VALUES ('8637ebc4-b92b-4cfb-bed5-156cf9274d69', '2023-08-09 00:07:46', '2024-04-02 16:49:03', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '验证码', '<p>低代码平台若要使用验证码组件（目前主要应用于登陆接口、接口引擎），服务器端需要通过nuget引用Microi.Captcha组件，</p><p>在Program.cs中注入依赖组件services.AddMicroiCaptcha();</p><p>在系统设置中（Sys_Config）需要存在EnableCaptcha字段（开关组件、int），并且值为1。</p><p><br/></p><ul class=\" list-paddingleft-2\" style=\"list-style-type: disc;\"><li><p><strong>获取验证码图片</strong><br/></p></li><li><pre class=\"brush:js;toolbar:false\">通过浏览器测试：\nhttps://api.microios.com/api/Captcha/getCaptcha?OsClient=micrios\n通过查看元素，可在Response&nbsp;Headers中看到返回了captchaid，在提交验证码时，此值必须传入到后端。\n\n在PC前端或Uni-App移动端的处理方式大致为：\n&lt;img&nbsp;id=&quot;CaptchaImg&quot;&nbsp;src=&quot;&quot;&nbsp;@click=&quot;GetCaptcha()&quot;&nbsp;/&gt;\nGetCaptcha(){\n&nbsp;&nbsp;&nbsp;&nbsp;$axios.get(self.DiyCommon.GetApiBase()&nbsp;+&nbsp;&#39;/api/Captcha/getCaptcha&#39;,&nbsp;{\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;params:&nbsp;{\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;OsClient&nbsp;:&nbsp;self.OsClient//一定要传入OsClient值\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;},\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;responseType:&nbsp;&#39;arraybuffer&#39;\n&nbsp;&nbsp;&nbsp;&nbsp;})\n&nbsp;&nbsp;&nbsp;&nbsp;.then(response&nbsp;=&gt;&nbsp;{\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;if(response&nbsp;&amp;&amp;&nbsp;response.headers&nbsp;&amp;&amp;&nbsp;response.headers.captchaid){\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;self.CaptchaId&nbsp;=&nbsp;response.headers.captchaid;//一定要将返回的captchaid存储起来\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;}\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;return&nbsp;&#39;data:image/png;base64,&#39;&nbsp;+&nbsp;btoa(\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;new&nbsp;Uint8Array(response.data)\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;.reduce((data,&nbsp;byte)&nbsp;=&gt;&nbsp;data&nbsp;+&nbsp;String.fromCharCode(byte),&nbsp;&#39;&#39;)\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;);\n&nbsp;&nbsp;&nbsp;&nbsp;}).then(data&nbsp;=&gt;&nbsp;{\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;$(&#39;#CaptchaImg&#39;).attr(&#39;src&#39;,&nbsp;data);//显示验证码图片\n&nbsp;&nbsp;&nbsp;&nbsp;});\n}</pre><p>&nbsp; &nbsp; &nbsp; &nbsp;</p></li><li><p><strong>提交验证码</strong><br/></p></li><li><pre class=\"brush:js;toolbar:false\">//参数传入_CaptchaId、_CaptchaValue</pre><p>&nbsp; &nbsp; &nbsp; &nbsp;</p></li><li><p><strong>验证码配置<br/></strong>可在系统设置中配置验证码规则<br/></p></li><li><table class=\"table table-border\"><tbody><tr class=\"firstRow\"><td width=\"304\" valign=\"top\" style=\"word-break: break-all;\"><span style=\"color: #40485B; font-family: -apple-system, system-ui, &quot;Segoe UI&quot;, Helvetica, Arial, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Liberation Sans&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Hiragino Sans GB&quot;, &quot;Wenquanyi Micro Hei&quot;, &quot;WenQuanYi Zen Hei&quot;, &quot;ST Heiti&quot;, SimHei, SimSun, &quot;WenQuanYi Zen Hei Sharp&quot;, sans-serif; font-weight: 600; background-color: #FFFFFF;\">CaptchaType</span><br/>\n &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</td><td width=\"304\" valign=\"top\" style=\"word-break: break-all;\"><span style=\"color: #40485B; font-family: -apple-system, system-ui, &quot;Segoe UI&quot;, Helvetica, Arial, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Liberation Sans&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Hiragino Sans GB&quot;, &quot;Wenquanyi Micro Hei&quot;, &quot;WenQuanYi Zen Hei&quot;, &quot;ST Heiti&quot;, SimHei, SimSun, &quot;WenQuanYi Zen Hei Sharp&quot;, sans-serif; font-weight: 600; background-color: #FFFFFF;\">字体</span><br/>\n &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</td><td width=\"304\" valign=\"top\" style=\"word-break: break-all;\"><span style=\"color: #40485B; font-family: -apple-system, system-ui, &quot;Segoe UI&quot;, Helvetica, Arial, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Liberation Sans&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Hiragino Sans GB&quot;, &quot;Wenquanyi Micro Hei&quot;, &quot;WenQuanYi Zen Hei&quot;, &quot;ST Heiti&quot;, SimHei, SimSun, &quot;WenQuanYi Zen Hei Sharp&quot;, sans-serif; font-weight: 600; background-color: #FFFFFF;\">静态图</span><br/>\n &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</td><td width=\"304\" valign=\"top\" style=\"word-break: break-all;\"><span style=\"color: #40485B; font-family: -apple-system, system-ui, &quot;Segoe UI&quot;, Helvetica, Arial, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Liberation Sans&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Hiragino Sans GB&quot;, &quot;Wenquanyi Micro Hei&quot;, &quot;WenQuanYi Zen Hei&quot;, &quot;ST Heiti&quot;, SimHei, SimSun, &quot;WenQuanYi Zen Hei Sharp&quot;, sans-serif; font-weight: 600; background-color: #FFFFFF;\">动图</span><br/>\n &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</td></tr><tr><td width=\"304\" valign=\"top\" style=\"word-break: break-all;\"><span style=\"color: #40485B; font-family: -apple-system, system-ui, &quot;Segoe UI&quot;, Helvetica, Arial, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Liberation Sans&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Hiragino Sans GB&quot;, &quot;Wenquanyi Micro Hei&quot;, &quot;WenQuanYi Zen Hei&quot;, &quot;ST Heiti&quot;, SimHei, SimSun, &quot;WenQuanYi Zen Hei Sharp&quot;, sans-serif; background-color: #FFFFFF;\">DEFAULT (0)</span><br/>\n &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</td><td width=\"304\" valign=\"top\"><br/></td><td width=\"304\" valign=\"top\"><img src=\"https://static-ali-img.itdos.com//itdos/itdos/upload/editor/image/202309/6382987335545209958389942.gif/20230909/1.gif\" alt=\"1.gif\"/><br/></td><td width=\"304\" valign=\"top\"><img src=\"https://static-ali-img.itdos.com//itdos/itdos/upload/editor/image/202309/6382987336384782028080986.gif/20230909/2.gif\" alt=\"2.gif\"/><br/></td></tr><tr><td width=\"304\" valign=\"top\" style=\"word-break: break-all;\"><span style=\"color: #40485B; font-family: -apple-system, system-ui, &quot;Segoe UI&quot;, Helvetica, Arial, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Liberation Sans&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Hiragino Sans GB&quot;, &quot;Wenquanyi Micro Hei&quot;, &quot;WenQuanYi Zen Hei&quot;, &quot;ST Heiti&quot;, SimHei, SimSun, &quot;WenQuanYi Zen Hei Sharp&quot;, sans-serif; background-color: #F6F8FA;\">CHINESE (1)</span><br/>\n &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</td><td width=\"304\" valign=\"top\"><br/></td><td width=\"304\" valign=\"top\"><img src=\"https://static-ali-img.itdos.com//itdos/itdos/upload/editor/image/202309/6382987348140208461391418.gif/20230909/2-1.gif\" alt=\"2-1.gif\"/><br/></td><td width=\"304\" valign=\"top\"><img src=\"https://static-ali-img.itdos.com//itdos/itdos/upload/editor/image/202309/6382987348878749178882619.gif/20230909/2-2.gif\" alt=\"2-2.gif\"/><br/></td></tr><tr><td width=\"304\" valign=\"top\" style=\"word-break: break-all;\"><span style=\"color: #40485B; font-family: -apple-system, system-ui, &quot;Segoe UI&quot;, Helvetica, Arial, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Liberation Sans&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Hiragino Sans GB&quot;, &quot;Wenquanyi Micro Hei&quot;, &quot;WenQuanYi Zen Hei&quot;, &quot;ST Heiti&quot;, SimHei, SimSun, &quot;WenQuanYi Zen Hei Sharp&quot;, sans-serif; background-color: #FFFFFF;\">NUMBER (2)</span><br/>\n &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</td><td width=\"304\" valign=\"top\"><br/></td><td width=\"304\" valign=\"top\"><img src=\"https://static-ali-img.itdos.com//itdos/itdos/upload/editor/image/202309/6382987351081492956070489.gif/20230909/3-1.gif\" alt=\"3-1.gif\"/><br/></td><td width=\"304\" valign=\"top\"><img src=\"https://static-ali-img.itdos.com//itdos/itdos/upload/editor/image/202309/6382987351833418265739934.gif/20230909/3-2.gif\" alt=\"3-2.gif\"/><br/></td></tr><tr><td width=\"304\" valign=\"top\" style=\"word-break: break-all;\"><span style=\"color: #40485B; font-family: -apple-system, system-ui, &quot;Segoe UI&quot;, Helvetica, Arial, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Liberation Sans&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Hiragino Sans GB&quot;, &quot;Wenquanyi Micro Hei&quot;, &quot;WenQuanYi Zen Hei&quot;, &quot;ST Heiti&quot;, SimHei, SimSun, &quot;WenQuanYi Zen Hei Sharp&quot;, sans-serif; background-color: #F6F8FA;\">NUMBER_ZH_CN (3)</span><br/>\n &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</td><td width=\"304\" valign=\"top\"><br/></td><td width=\"304\" valign=\"top\"><img src=\"https://static-ali-img.itdos.com//itdos/itdos/upload/editor/image/202309/6382987352637251001802115.gif/20230909/4-1.gif\" alt=\"4-1.gif\"/><br/></td><td width=\"304\" valign=\"top\"><img src=\"https://static-ali-img.itdos.com//itdos/itdos/upload/editor/image/202309/6382987353340272558580529.gif/20230909/4-2.gif\" alt=\"4-2.gif\"/><br/></td></tr><tr><td width=\"304\" valign=\"top\" style=\"word-break: break-all;\"><span style=\"color: #40485B; font-family: -apple-system, system-ui, &quot;Segoe UI&quot;, Helvetica, Arial, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Liberation Sans&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Hiragino Sans GB&quot;, &quot;Wenquanyi Micro Hei&quot;, &quot;WenQuanYi Zen Hei&quot;, &quot;ST Heiti&quot;, SimHei, SimSun, &quot;WenQuanYi Zen Hei Sharp&quot;, sans-serif; background-color: #FFFFFF;\">NUMBER_ZH_HK (4)</span><br/>\n &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</td><td width=\"304\" valign=\"top\"><br/></td><td width=\"304\" valign=\"top\"><img src=\"https://static-ali-img.itdos.com//itdos/itdos/upload/editor/image/202309/6382987354240120153944859.gif/20230909/5-1.gif\" alt=\"5-1.gif\"/><br/></td><td width=\"304\" valign=\"top\"><img src=\"https://static-ali-img.itdos.com//itdos/itdos/upload/editor/image/202309/6382987355024308308067930.gif/20230909/5-2.gif\" alt=\"5-2.gif\"/><br/></td></tr><tr><td width=\"304\" valign=\"top\" style=\"word-break: break-all;\"><span style=\"color: #40485B; font-family: -apple-system, system-ui, &quot;Segoe UI&quot;, Helvetica, Arial, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Liberation Sans&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Hiragino Sans GB&quot;, &quot;Wenquanyi Micro Hei&quot;, &quot;WenQuanYi Zen Hei&quot;, &quot;ST Heiti&quot;, SimHei, SimSun, &quot;WenQuanYi Zen Hei Sharp&quot;, sans-serif; background-color: #F6F8FA;\">WORD (5)</span><br/>\n &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</td><td width=\"304\" valign=\"top\"><br/></td><td width=\"304\" valign=\"top\"><img src=\"https://static-ali-img.itdos.com//itdos/itdos/upload/editor/image/202309/6382987356231940556741541.gif/20230909/6-1.gif\" alt=\"6-1.gif\"/><br/></td><td width=\"304\" valign=\"top\"><img src=\"https://static-ali-img.itdos.com//itdos/itdos/upload/editor/image/202309/6382987356971159357182120.gif/20230909/6-2.gif\" alt=\"6-2.gif\"/><br/></td></tr><tr><td width=\"304\" valign=\"top\" style=\"word-break: break-all;\"><span style=\"color: #40485B; font-family: -apple-system, system-ui, &quot;Segoe UI&quot;, Helvetica, Arial, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Liberation Sans&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Hiragino Sans GB&quot;, &quot;Wenquanyi Micro Hei&quot;, &quot;WenQuanYi Zen Hei&quot;, &quot;ST Heiti&quot;, SimHei, SimSun, &quot;WenQuanYi Zen Hei Sharp&quot;, sans-serif; background-color: #FFFFFF;\">WORD_LOWER (6)</span><br/>\n &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</td><td width=\"304\" valign=\"top\"><br/></td><td width=\"304\" valign=\"top\"><img src=\"https://static-ali-img.itdos.com//itdos/itdos/upload/editor/image/202309/6382987357903149398401416.gif/20230909/7-1.gif\" alt=\"7-1.gif\"/><br/></td><td width=\"304\" valign=\"top\"><img src=\"https://static-ali-img.itdos.com//itdos/itdos/upload/editor/image/202309/6382987358559208156725035.gif/20230909/7-2.gif\" alt=\"7-2.gif\"/><br/></td></tr><tr><td width=\"304\" valign=\"top\" style=\"word-break: break-all;\"><span style=\"color: #40485B; font-family: -apple-system, system-ui, &quot;Segoe UI&quot;, Helvetica, Arial, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Liberation Sans&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Hiragino Sans GB&quot;, &quot;Wenquanyi Micro Hei&quot;, &quot;WenQuanYi Zen Hei&quot;, &quot;ST Heiti&quot;, SimHei, SimSun, &quot;WenQuanYi Zen Hei Sharp&quot;, sans-serif; background-color: #F6F8FA;\">WORD_UPPER (7)</span><br/>\n &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</td><td width=\"304\" valign=\"top\"><br/></td><td width=\"304\" valign=\"top\"><img src=\"https://static-ali-img.itdos.com//itdos/itdos/upload/editor/image/202309/6382987359347923562585116.gif/20230909/8-1.gif\" alt=\"8-1.gif\"/><br/></td><td width=\"304\" valign=\"top\"><img src=\"https://static-ali-img.itdos.com//itdos/itdos/upload/editor/image/202309/6382987368351564882713778.gif/20230909/8-2.gif\" alt=\"8-2.gif\"/><br/></td></tr><tr><td width=\"304\" valign=\"top\" style=\"word-break: break-all;\"><span style=\"color: #40485B; font-family: -apple-system, system-ui, &quot;Segoe UI&quot;, Helvetica, Arial, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Liberation Sans&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Hiragino Sans GB&quot;, &quot;Wenquanyi Micro Hei&quot;, &quot;WenQuanYi Zen Hei&quot;, &quot;ST Heiti&quot;, SimHei, SimSun, &quot;WenQuanYi Zen Hei Sharp&quot;, sans-serif; background-color: #FFFFFF;\">WORD_NUMBER_LOWER (8)</span><br/>\n &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</td><td width=\"304\" valign=\"top\"><br/></td><td width=\"304\" valign=\"top\"><img src=\"https://static-ali-img.itdos.com//itdos/itdos/upload/editor/image/202309/6382987369066747495961267.gif/20230909/9-1.gif\" alt=\"9-1.gif\"/><br/></td><td width=\"304\" valign=\"top\"><img src=\"https://static-ali-img.itdos.com//itdos/itdos/upload/editor/image/202309/6382987369777462003187163.gif/20230909/9-2.gif\" alt=\"9-2.gif\"/><br/></td></tr><tr><td valign=\"top\" colspan=\"1\" rowspan=\"1\" style=\"word-break: break-all;\"><span style=\"color: #40485B; font-family: -apple-system, system-ui, &quot;Segoe UI&quot;, Helvetica, Arial, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Liberation Sans&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Hiragino Sans GB&quot;, &quot;Wenquanyi Micro Hei&quot;, &quot;WenQuanYi Zen Hei&quot;, &quot;ST Heiti&quot;, SimHei, SimSun, &quot;WenQuanYi Zen Hei Sharp&quot;, sans-serif; background-color: #F6F8FA;\">WORD_NUMBER_UPPER (9)</span><br/>\n &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</td><td valign=\"top\" colspan=\"1\" rowspan=\"1\"><br/></td><td valign=\"top\" colspan=\"1\" rowspan=\"1\" style=\"word-break: break-all;\"><img src=\"https://static-ali-img.itdos.com//itdos/itdos/upload/editor/image/202309/6382987375136845773128473.gif/20230909/10-1.gif\" alt=\"10-1.gif\"/><br/></td><td valign=\"top\" colspan=\"1\" rowspan=\"1\"><img src=\"https://static-ali-img.itdos.com//itdos/itdos/upload/editor/image/202309/6382987375867861808167519.gif/20230909/10-2.gif\" alt=\"10-2.gif\"/><br/></td></tr><tr><td valign=\"top\" colspan=\"1\" rowspan=\"1\" style=\"word-break: break-all;\"><span style=\"color: #40485B; font-family: -apple-system, system-ui, &quot;Segoe UI&quot;, Helvetica, Arial, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Liberation Sans&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Hiragino Sans GB&quot;, &quot;Wenquanyi Micro Hei&quot;, &quot;WenQuanYi Zen Hei&quot;, &quot;ST Heiti&quot;, SimHei, SimSun, &quot;WenQuanYi Zen Hei Sharp&quot;, sans-serif; background-color: #FFFFFF;\">ARITHMETIC (10)</span><br/>\n &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</td><td valign=\"top\" colspan=\"1\" rowspan=\"1\"><br/></td><td valign=\"top\" colspan=\"1\" rowspan=\"1\"><img src=\"https://static-ali-img.itdos.com//itdos/itdos/upload/editor/image/202309/6382987376677516548099905.gif/20230909/11-1.gif\" alt=\"11-1.gif\"/><br/></td><td valign=\"top\" colspan=\"1\" rowspan=\"1\"><img src=\"https://static-ali-img.itdos.com//itdos/itdos/upload/editor/image/202309/6382987377367742808615156.gif/20230909/11-2.gif\" alt=\"11-2.gif\"/><br/></td></tr><tr><td valign=\"top\" colspan=\"1\" rowspan=\"1\" style=\"word-break: break-all;\"><span style=\"color: #40485B; font-family: -apple-system, system-ui, &quot;Segoe UI&quot;, Helvetica, Arial, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Liberation Sans&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Hiragino Sans GB&quot;, &quot;Wenquanyi Micro Hei&quot;, &quot;WenQuanYi Zen Hei&quot;, &quot;ST Heiti&quot;, SimHei, SimSun, &quot;WenQuanYi Zen Hei Sharp&quot;, sans-serif; background-color: #F6F8FA;\">ARITHMETIC_ZH (11)</span><br/>\n &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;</td><td valign=\"top\" colspan=\"1\" rowspan=\"1\"><br/></td><td valign=\"top\" colspan=\"1\" rowspan=\"1\"><img src=\"https://static-ali-img.itdos.com//itdos/itdos/upload/editor/image/202309/6382987378101506678680095.gif/20230909/12-1.gif\" alt=\"12-1.gif\"/><br/></td><td valign=\"top\" colspan=\"1\" rowspan=\"1\"><img src=\"https://static-ali-img.itdos.com//itdos/itdos/upload/editor/image/202309/6382987378730926385837508.gif/20230909/12-2.gif\" alt=\"12-2.gif\"/><br/></td></tr></tbody></table></li></ul><pre class=\"brush:js;toolbar:false\">{\n&nbsp;&nbsp;&nbsp;&nbsp;&quot;CaptchaType&quot;:&nbsp;11,&nbsp;//&nbsp;验证码类型，值为0-11，具体效果见平台文档\n&nbsp;&nbsp;&nbsp;&nbsp;&quot;CodeLength&quot;:&nbsp;1,&nbsp;//&nbsp;验证码长度,&nbsp;要放在CaptchaType设置后。当类型为算术表达式时（CaptchaType=10-11），长度代表操作的个数,&nbsp;建议1。当CaptchaType=0-9时建议填4。\n&nbsp;&nbsp;&nbsp;&nbsp;&quot;ExpirySeconds&quot;:&nbsp;300,&nbsp;//&nbsp;验证码过期秒数\n&nbsp;&nbsp;&nbsp;&nbsp;&quot;IgnoreCase&quot;:&nbsp;true,&nbsp;//&nbsp;比较时是否忽略大小写\n&nbsp;&nbsp;&nbsp;&nbsp;//&quot;StoreageKeyPrefix&quot;:&nbsp;&quot;&quot;,&nbsp;//&nbsp;存储键前缀\n&nbsp;&nbsp;&nbsp;&nbsp;&quot;ImageOption&quot;:&nbsp;{\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&quot;Animation&quot;:&nbsp;true,&nbsp;//&nbsp;是否启用动画\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&quot;FontSize&quot;:&nbsp;32,&nbsp;//&nbsp;字体大小\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&quot;Width&quot;:&nbsp;150,&nbsp;//&nbsp;验证码宽度\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&quot;Height&quot;:&nbsp;50,&nbsp;//&nbsp;验证码高度\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&quot;BubbleMinRadius&quot;:&nbsp;5,&nbsp;//&nbsp;气泡最小半径\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&quot;BubbleMaxRadius&quot;:&nbsp;10,&nbsp;//&nbsp;气泡最大半径\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&quot;BubbleCount&quot;:&nbsp;3,&nbsp;//&nbsp;气泡数量\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&quot;BubbleThickness&quot;:&nbsp;1.0,&nbsp;//&nbsp;气泡边沿厚度\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&quot;InterferenceLineCount&quot;:&nbsp;2,&nbsp;//&nbsp;干扰线数量\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//&quot;FontFamily&quot;:&nbsp;&quot;kaiti&quot;,&nbsp;//【暂不支持】&nbsp;包含actionj,epilog,fresnel,headache,lexo,prefix,progbot,ransom,robot,scandal,kaiti\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&quot;FrameDelay&quot;:&nbsp;300,&nbsp;//&nbsp;每帧延迟,Animation=true时有效,&nbsp;默认30，建议300左右\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//&quot;BackgroundColor&quot;:&nbsp;&quot;#ffffff&quot;,&nbsp;//【暂不支持】&nbsp;&nbsp;格式:&nbsp;rgb,&nbsp;rgba,&nbsp;rrggbb,&nbsp;or&nbsp;rrggbbaa&nbsp;format&nbsp;to&nbsp;match&nbsp;web&nbsp;syntax,&nbsp;默认#fff\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&quot;ForegroundColors&quot;:&nbsp;&quot;&quot;,&nbsp;//&nbsp;&nbsp;颜色格式同BackgroundColor,多个颜色逗号分割，随机选取。不填，空值，则使用默认颜色集\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&quot;Quality&quot;:&nbsp;100,&nbsp;//&nbsp;图片质量（质量越高图片越大，gif调整无效可能会更大）\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&quot;TextBold&quot;:&nbsp;false&nbsp;//&nbsp;粗体\n&nbsp;&nbsp;&nbsp;&nbsp;}\n}</pre><p><br/></p>', b'1', '808f0a05-6587-4439-ab96-8403f9349b4f', '', 200, NULL);
INSERT INTO `diy_document` VALUES ('8da6fe30-dda4-47b0-99c9-ef283195a2ae', '2024-02-18 11:59:28', NULL, 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '视频文档', '', b'1', NULL, '', 40, NULL);
INSERT INTO `diy_document` VALUES ('8daccbf6-3b4a-44ff-a5a1-81017a439150', '2022-07-27 15:14:13', '2022-07-27 15:17:04', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '模板引擎', '<p>模板引擎目前在表单引擎中的表格V8模板引擎、表单V8模板引擎，用于处理最终渲染后的数据。</p><p>例子：</p><pre class=\"brush:js;toolbar:false\">if(V8.IsNull(V8.Form.Zhuangtai)){\n&nbsp;&nbsp;&nbsp;&nbsp;V8.Result&nbsp;=&nbsp;&#39;&#39;;\n}else{\n&nbsp;&nbsp;&nbsp;&nbsp;var&nbsp;classStr&nbsp;=&nbsp;&#39;badge-primary&#39;;\n&nbsp;&nbsp;&nbsp;&nbsp;if(V8.Form.Zhuangtai&nbsp;==&nbsp;&#39;禁用&#39;){\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;classStr&nbsp;=&nbsp;`badge-danger`;\n&nbsp;&nbsp;&nbsp;&nbsp;}\n&nbsp;&nbsp;&nbsp;&nbsp;else&nbsp;if(V8.Form.Zhuangtai&nbsp;==&nbsp;&#39;未通过&#39;){\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;classStr&nbsp;=&nbsp;`badge-warning`;\n&nbsp;&nbsp;&nbsp;&nbsp;}\n&nbsp;&nbsp;&nbsp;&nbsp;else&nbsp;if(V8.Form.Zhuangtai&nbsp;==&nbsp;&#39;待审核&#39;){\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;classStr&nbsp;=&nbsp;`badge-info`;\n&nbsp;&nbsp;&nbsp;&nbsp;}\n&nbsp;&nbsp;&nbsp;&nbsp;var&nbsp;html&nbsp;=&nbsp;`&lt;span&nbsp;class=&quot;badge&nbsp;badge-pill&nbsp;${classStr}&quot;&gt;${V8.Form.Zhuangtai}&lt;/span&gt;`;\n&nbsp;&nbsp;&nbsp;&nbsp;V8.Result&nbsp;=&nbsp;html;\n}</pre><p>模板引擎支持bootstrap、element-ui的样式。</p><p>常用bootstrap样式：</p><p><span class=\"badge badge-primary\">Primary</span><span class=\"badge badge-secondary\">Secondary</span><span class=\"badge badge-success\">Success</span><span class=\"badge badge-danger\">Danger</span><span class=\"badge badge-warning\">Warning</span><span class=\"badge badge-info\">Info</span><span class=\"badge badge-light\">Light</span><span class=\"badge badge-dark\">Dark</span></p><pre class=\"brush:js;toolbar:false\">&lt;span&nbsp;class=&quot;badge&nbsp;badge-primary&quot;&gt;Primary&lt;/span&gt;\n&lt;span&nbsp;class=&quot;badge&nbsp;badge-secondary&quot;&gt;Secondary&lt;/span&gt;\n&lt;span&nbsp;class=&quot;badge&nbsp;badge-success&quot;&gt;Success&lt;/span&gt;\n&lt;span&nbsp;class=&quot;badge&nbsp;badge-danger&quot;&gt;Danger&lt;/span&gt;\n&lt;span&nbsp;class=&quot;badge&nbsp;badge-warning&quot;&gt;Warning&lt;/span&gt;\n&lt;span&nbsp;class=&quot;badge&nbsp;badge-info&quot;&gt;Info&lt;/span&gt;\n&lt;span&nbsp;class=&quot;badge&nbsp;badge-light&quot;&gt;Light&lt;/span&gt;\n&lt;span&nbsp;class=&quot;badge&nbsp;badge-dark&quot;&gt;Dark&lt;/span&gt;</pre><p><br/></p>', b'1', '808f0a05-6587-4439-ab96-8403f9349b4f', '', 10, NULL);
INSERT INTO `diy_document` VALUES ('96fc2aea-f888-4286-9011-daa5192e88d9', '2022-03-23 01:54:25', '2024-11-27 02:27:33', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '前端V8', '<p><span style=\"color: rgb(225, 60, 57); font-size: 22px;\"><strong>最新线上文档： </strong></span><a href=\"https://microi.blog.csdn.net/article/details/143623205\" target=\"_blank\"><span style=\"color: rgb(225, 60, 57); font-size: 22px;\"><strong>https://microi.blog.csdn.net/article/details/143623205</strong></span></a><span style=\"color: rgb(225, 60, 57); font-size: 22px;\"><strong> </strong></span></p><p><br></p><p><span style=\"font-size: 14px;\">前端V8引擎代码与服务器端V8的编程语言均为Javascript语法。</span></p><p><span style=\"font-size: 14px;\">前端V8引擎支持完整ES6语法。</span></p><p><span style=\"font-size: 14px;\">前端V8引擎集成了很多函数直接通过http调用后端接口，与V8.Post()写对应的接口地址效果一样。</span></p><p><span style=\"font-size: 14px;\">前端V8引擎代码在前端执行，若是通过直接调用服务器端的低代码平台通用接口，前端V8代码不会执行（服务器端V8引擎代码会执行）。</span></p><p><br></p><p><br><span style=\"font-size: 14px;\"><strong>常用内置对象、函数：</strong></span></p><ul><li>V8.Form 访问当前表单字段值 例：var name = V8.Form.UserName; 如果是下拉框组件，设定了绑定显示字段，则可以是：V8.Form.字段名称.显示字段</li><li>V8.OldForm 访问当前表单修改前字段值 例：var oldName = V8.OldForm.UserName;</li><li>V8.FormSet 给当前表单字段赋值 例：V8.FormSet(\'UserName\', \'张三\'); 也可以使用常规js写法（只不过在某些特殊情况下可能会不生效）：V8.Form.UserName = \'张三\';</li><li>V8.Field 访问当前表单字段属性 例：var isReadonly = V8.Form.UserName.Readonly;//UserName字段当前是否是只读 包含属性：Name、Label、Config、Data(绑定数据源)、Readonly、Visible、Placeholder等等</li><li>V8.FieldSet 给当前表单字段属性赋值 例：V8.FieldSet(\'UserName\', \'Readonly\', false);//设置UserName字段为只读</li></ul><p><span style=\"font-size: 14px;\"><strong>一些常量（均为string类型）：</strong></span></p><ul><li>V8.FormOutAction 获取离开表单的类型，可用于离开表单、提交表单后V8引擎代码中做为判断，可能的值：Update/Insert/Close/Delete</li><li>V8.FormOutAfterAction 获取离开表单后的类型，可用于离开表单/提交表单后V8引擎代码，可能的值：Insert/Update/View/Close</li><li>V8.FormSubmitAction 表单提交类型（Insert/Update/Delete），可在“表单提交前V8引擎代码”中赋值V8.Result = false;以阻止表单提交。</li><li>V8.FormMode 获取当前Form打开的模式，可能的值：Add（新增）、Edit（编辑）、View（预览）</li><li>V8.LoadMode 当前Form的加载模式，要么为空，要么值为Design（string，设计模式），特别注意一些事件中如果使用了V8.FieldSet更改了字段属性，需要判断V8.LoadMode == \'Design\'时不执行，否则保存表单设计后会持久化保存字段属性。</li><li>V8.TableRowId 获取当前Form的Id，也可以使用V8.Form.Id</li><li>V8.KeyCode 键盘事件V8可获取键盘的code值，如Enter键对应13 例：if(V8.KeyCode == 13){ V8.Tips(\'您已经按了Enter键！\'); }</li><li>V8.TableId、V8.TableName 获取当前DIY表的Id、Name</li><li>V8.EventName 前端V8事件名称，在全局V8引擎代码中比较好用，可能的值： FormTemplateEngine：表单模板引擎 TableTemplateEngine：表格模板引擎 OpenTableBefore：弹出表格前事件 OpenTableSubmit：弹出表格提交事件 FieldOnKeyup：文本框键盘事件 FormOut：离开表单事件（指表单提交后） FormSubmitBefore：表单提交前事件 FormIn：进入表单事件 FieldValueChange：字段值变更事件 BtnFormDetailRun：详情按钮V8按钮 V8BtnLimit：V8按钮是否显示事件 V8BtnRun：V8按钮执行事件 TableRowClick：表格行点击V8事件 PageTab：多Tab页签V8事件 WFNodeEnd：流程节点结束V8事件 WFNodeStart：流程节点开始V8事件</li><li>V8.CurrentToken 当前登陆身份token</li><li>V8.TableModel 获取当前表的对象，里面包含了Id、Name等表信息。</li><li>V8.ThisValue 访问下拉框选择后的值对象，如V8.ThisValue.Id</li><li>V8.Tips 右下角弹出消息提示，用法：V8.Tips(msgContent, true/false, time) msgContent为消息内容 true为成功消息（1秒后消失），false为错误消息（5秒后消失） time可传入提示框多少秒后消失</li><li>V8.CurrentUser 访问当前登陆用户信息 例：V8.CurrentUser.Id/Name/Role/Dept等等</li><li>V8.Post</li><li>//发起ajax请求，常规用法，自带token，默认Form Data参数格式（非Request Payload） V8.Post(\'api url\', { Id : 1 }, function(result){ if(result.Code == 1){ ... } }) //完整用法 V8.Post({ url : \'\',//接口地址，必传。 data : {}, //接口参数 dataType : \'json\', //默认空（Form Data），可选json（Request Payload） header : {}, //可选参数 success : function(result){ }, //请求成功的回调函数，常用参数。 fail : function(result){ }, //请求失败的回调函数，如接口报错404、500，可选参数，也可传入error，与fail一致。 });</li><li>V8.PostAsync：发起同步请求，var result = await V8.PostAsync(\'接口地址\', {参数});</li></ul><p><span style=\"font-size: 14px;\">如同步获取一个服务器端的GUID：var newGuid = await V8.PostAsync(\'/api/DiyTable/NewGuid\');</span></p><ul><li>V8.Get：发起ajax请求，V8.Get(\'api url\', {}, function(result){})</li><li>V8.GetAsync：发起同步请求，var result = V8.GetAsync(\'api url\', {});</li></ul><p><br></p><ul><li>V8.ChineseToPinyin(chinese, fullPyLen, type)：中文转拼音 fullPyLen: 2(默认)，前几个字全拼音；type : 1 驼峰（默认），2全大写，3全小写</li><li>V8.RefreshTable({ _PageIndex : -1 }) 刷新表格数据列表，_PageIndex传入-1表示跳转到最后一页。 一般用于页面更多按钮、行更多按钮等刷新当前表格。 注意与【V8.TableRefresh】不同的是它是刷新当前主表单里面的子表格（将来会优化函数命名）。</li><li>V8.Router.Push(url)：页面跳转</li><li>V8.Window.Open(url)：打开新页面</li><li>V8.OpenForm(formModel, type) 打开表单，type：\'View\'/\'Edit\'/\'Add\'，如在[行更多V8按钮]事件中：V8.OpenForm(V8.Form, \'Edit\')</li><li>V8.OpenFormWF(formModel, type) 打开带流程信息的表单。（目前是获取此数据对应的最后一个流程）</li><li>V8.TableRowSelected 获取已选择的行数组，每行包含了所有数据</li><li>V8.SearchSet/SearchAppend({FieldName : value, FieldName2 : value})：表格Tabs设置搜索条件</li><li>V8.IsNull(value)：判断某个值是否为空 当值为null、undefined、\'\'（空字符串）、\'null\'（null字符串）、\'undefined\'（undefined字符串），均返回true</li><li>父表中对子表操作：</li><ul><li>V8.TableSearchAppend(V8.Field.子表Name, {FiedlName : value, FieldName2 : value})</li><li>V8.TableSearchSet(V8.Field.子表Name, {FiedlName : value, FieldName2 : value})</li><li>V8.TableRefresh(V8.Field.子表Name, { _PageIndex : -1 }) _PageIndex传入-1表示跳转到最后一页。（注意与【V8.RefreshTable】不同的是它一般是用于模块引擎中行更多按钮、页面更多按钮刷新当前表格，将来会优化函数命名）。</li></ul><li>V8.FormSubmit({CloseForm:true, SavedType:\'Insert\', Callback : function}) 提交表单。 CloseForm：是否关闭Form表单； SavedType：保存表单后的操作Insert/Update/View Callback：回调函数</li><li>子表中对父级操作：</li><ul><li>V8.ParentForm：访问父级表单所有字段 支持在子表的子表中，使用V8.ParentForm.ParentForm对父表赋值。</li><li>[已废除]V8.ParentFormSet(\'字段名\', \'值\')：给父表单某个字段赋值 请使用V8.ParentForm.FormSet(\'字段名\', \'值\')</li></ul><li>V8.AddSysLog：新增日志 例：V8.AddSysLog({Title : \'库存同步\', Type:\'SyncStock\', Content:\'张三调用了库存同步接口，同步后库存为100。\') 参数值均为自定义。</li><li></li><li>V8.ReloadForm：重新加载当前表单 例：V8.ReloadForm({Id : \'xxxx-xxxx-xxxx\'}, \'Edit/View\');//以编辑或预览模式重新加载当前表单</li><li>V8.HideFormBtn(\'Update/Delete\')：隐藏编辑/删除按钮</li><li>V8.HideFormTab(tabName) 隐藏某个表单Tab标签页，用法：V8.HideFormTab(\'tabName（在表单属性中配置的Tab名称）\')</li><li>V8.ShowFormTab(tabName) 显示某个表单Tab标签页，用法：V8.HideFormTab(\'tabName（在表单属性中配置的Tab名称）\')</li><li>V8.ClickFormTab(tabName) 选中某个表单Tab标签页</li><li>V8.GetFormTabs 获取表单所有Tab标签页。</li><li>V8.ConfirmTips 确认提示框 例：V8.ConfirmTips(\'确认审批？\', okCallback, cancelCallback, option)。 option为可选参数，可配置：{Title:\'\',OkText:\'\',CancelText:\'\',Icon:\'\'}</li></ul><p><br></p><ul><li>V8.ShowTableChildHideField 将子表已隐藏的字段强制显示出来，并且刷新子表。</li><li>V8.ShowTableChildHideField(\'子表fieldName\',[\'fieldName\',\'fieldName\']);</li><li>V8.RefreshChildTable(fieldModel, V8.Row)：刷新子表 例：V8.RefreshChildTable(V8.Field.子表列名, V8.Row)，第二个参数可传入parentFormModel。</li><li>V8.GetChildTableData(\'子表字段名称\');</li><li>V8.CurrentTableData;</li><li>V8.WF.StartWork：发起流程： V8.WF.StartWork({ FlowDesignId:\'\',//流程图Id，必传 FormData:JSON.stringify({}),//可选，也可以传入{} object类型，内部会自动序列化 TableRowId:\'\',//关联的数据Id，必传 NoticeFields:JSON.stringify([]),//通知数据，可选，格式：[{Id:\'字段Id\',Name:\'字段名\',Label:\'字段名称\',Value:\'值\'}]，如果是数组类型，内部会自动序列化 //还可以传入选择的下一步审批人、添加的审批人、审批意见 等等 }, function(result){ //这是回调函数处理，result返回了Receivers、ToNodeName等});</li><li>V8.SendSystemMessage：发送系统消息//消息内容var msgContent = \'测试v8发送系统消息！\' + new Date().toString();//内容增加路由跳转msgContent += \'&lt;a href=\"/#/diy-xmxx?Keyword=海鸥\"&gt;测试页面跳转&lt;/a&gt;\';//发送系统消息V8.SendSystemMessage({ Content: msgContent, ToUserId: \'c19e70d1-b7b3-4eaa-933d-e8f59c85562f\'}, function(result){ V8.Tips(JSON.stringify(result));});</li><li>V8.FormWF：访问当前是否打开了带流程界面的表单，返回值： { IsWF:true/false, //是否打开了带流程界面的表单 WorkType:\'\',//StartWork、ViewWork FlowDesignId:\'流程图Id\' }</li><li>V8.Base64：base64加解密 V8.Base64.endcode(\'待加密字符串\');//加密 V8.Base64.dedcode(\'待解密字符串\');//解密 V8.Base64.isValid(\'已加密字符串\');//判断是否是已加密的base64格式</li><li>V8.OpenDialog(param)：打开一个定制组件对话框 例子；</li><li>V8.OpenDialog({ ComponentName:\'NodeColConfig\',//必传，其余参数可选。组件名称，二次开发必须提前预注册。 Title: \'测试定制组件标题\', OpenType:\'\',//可传：Drawer TitleIcon: \'fas fa-plus\',//标题左侧的图标 Width: \'70%\', DataAppend:{//传入自定义附加数据，DataAppend为固定参数名称 Abc:123, Name:\'张三\' }});//在定制组件内props接收V8对象：props: { DataAppend:{ type: Object, default: () =&gt; {} }}mounted() { //this.DataAppend.V8包含了绝大部分可使用的V8内置函数，可以使用V8事件一样的写法。 //获取已打开的表单中（或已选中的一条表格数据）的Title字段值。 var title = this.DataAppend.V8.Form.Title; //访问传过来的自定义数据 var name = this.DataAppend.Name;//张三 //刷新diy表格 this.DataAppend.V8.RefreshTable(); //关闭当前对话框 this.DataAppend.V8.CloseThisDialog();},</li><li>V8.NewGuid() 生成一个前端Guid值</li><li>await V8.NewServerGuid() 生成一个服务器端Guid值</li><li>V8._：访问underscore对象，常用的js实用库，如：V8._.where(...)。underscore用法见：https://underscorejs.org/ https://underscorejs.net/</li><li>V8.ModuleEngine： 模块引擎相关</li><li>V8.ApiEngine： 接口引擎</li><li>V8.DataSourceEngine： 数据源引擎</li><li>V8.OpenAnyForm： 打开一个任意表单</li><li>V8.OpenAnyForm({ TableName: \"Diy_ShouhouDD\", //必传。打开哪张表。 FormMode: \"Edit\", //必传。打开的模式：Add、Edit、View Id: V8.Form.Id, //当FormMode为Edit、View时，必传Id。 DialogType: \"Dialog\", //可选。打开的方式，不传则默认为表单属性设置的打开方式。 SelectFields: [\"ZhipaiXX\", \"ShouhouRY\"], //可选。只查询、显示哪些字段。不传则默认显示。 Width: \"765px\", //可选。弹出层的宽度。不传则默认为表单属性设置的弹出宽度。 DataAppend: { //传入自定义附加数据，DataAppend为固定参数名称。可在指定的打开表单V8事件中使用V8.DataAppend访问。 Abc: 123, Name: \"张三\", }, //替换掉提交事件。可选。 EventReplace: { //这3个参数一定会接收到，必须执行callback(DosResult) Submit: async function (v8, param, callback) { //调用指派接口 var result = await V8.ApiEngine.Run({ ApiEngineKey: \"shouhoudd_zhipai\", Id: v8.Form.Id, ShouhouRY: V8.Form.ShouhouRY, ShouhouRYID: V8.Form.ShouhouRYID, ShouhouRYDH: V8.Form.ShouhouRYDH, }); callback(result); }, }, });</li></ul><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p>', b'1', '81b5d8fd-d93e-46ad-9363-568aeac82ab9', '', -10, '');
INSERT INTO `diy_document` VALUES ('99140d12-4943-493d-aa5e-af6c5f0da479', '2022-03-20 12:25:06', '2023-08-06 17:41:04', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '环境', '<ul style=\"box-sizing: border-box;margin-top: 0.8em;margin-bottom: 0.8em;padding-left: 30px;position: relative;color: rgb(51, 51, 51);font-family: &#39;Open Sans&#39;, &#39;Clear Sans&#39;, &#39;Helvetica Neue&#39;, Helvetica, Arial, sans-serif;white-space: normal;background-color: rgb(255, 255, 255)\" class=\" list-paddingleft-2\"><li><p style=\"box-sizing: border-box;line-height: inherit;orphans: 4;margin-top: 0px;margin-bottom: 0.5rem;width: inherit;position: relative\"><span style=\"box-sizing: border-box\">安装Node.js</span></p><p style=\"box-sizing: border-box;line-height: inherit;orphans: 4;margin-top: 0.5rem;margin-bottom: 0.5rem;width: inherit;position: relative\"><span style=\"box-sizing: border-box\">访问Node.js官网</span><a href=\"https://nodejs.org/en/\" target=\"_blank\" style=\"box-sizing: border-box;cursor: pointer;color: rgb(65, 131, 196)\">https://nodejs.org/en/</a><span style=\"box-sizing: border-box\"> ，下载LTS版本[node-v14.15.3-x64.msi]，或访问iTdos官方开发工具合集地址下载，默认安装即可，安装完成后，cmd窗口中分别运行以下命令查看版本，注意node版本不同，可能会存在一些问题，下面列出目前我们测试过没问题的node版本：<br/></span></p></li><li><pre class=\"brush:js;toolbar:false\">#node&nbsp;-v\nv14.15.3、v14.17.2\n#npm&nbsp;-v\n6.14.9</pre></li><li><p style=\"box-sizing: border-box;line-height: inherit;orphans: 4;margin-top: 0px;margin-bottom: 0.5rem;width: inherit;position: relative\"><span style=\"box-sizing: border-box\">设置淘宝镜像，参考资料：</span><a href=\"https://developer.aliyun.com/mirror/NPM?from=tnpm\" target=\"_blank\" style=\"box-sizing: border-box;cursor: pointer;color: rgb(65, 131, 196)\">https://developer.aliyun.com/mirror/NPM?from=tnpm</a><br/></p></li><li><pre class=\"brush:js;toolbar:false\">#npm&nbsp;install&nbsp;-g&nbsp;cnpm&nbsp;--registry=https://registry.npm.taobao.org\n如果安装失败，可以使用&nbsp;npm&nbsp;cache&nbsp;clean&nbsp;清理缓存，然后再重新安装</pre></li><li><p style=\"box-sizing: border-box;line-height: inherit;orphans: 4;margin-top: 0px;margin-bottom: 0.5rem;width: inherit;position: relative\"><span style=\"box-sizing: border-box\">安装npm源管理器nrm<br/></span></p></li><li><pre class=\"brush:js;toolbar:false\">#cnpm&nbsp;install&nbsp;nrm&nbsp;-g\n#nrm&nbsp;ls</pre></li><li><p style=\"box-sizing: border-box;line-height: inherit;orphans: 4;margin-top: 0px;margin-bottom: 0.5rem;width: inherit;position: relative\"><span style=\"box-sizing: border-box\">添加microi官方私有npm源<br/></span></p></li><li><pre class=\"brush:js;toolbar:false\">#nrm&nbsp;add&nbsp;itdos&nbsp;http://repository.microi.net/\n#nrm&nbsp;use&nbsp;itdos\n#nrm&nbsp;ls</pre></li></ul><p><br/></p>', b'1', 'a35e6604-e290-46d6-8769-94a680758637', '', 0, NULL);
INSERT INTO `diy_document` VALUES ('9ad29d36-0cab-44d8-be02-08461fecf1dd', '2023-08-07 10:36:52', NULL, 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '扩展V8引擎', '<p>服务器端、前端V8引擎代码均支持自由扩展。</p><p><strong>前端V8引擎代码扩展方法：</strong></p><pre class=\"brush:js;toolbar:false\">//待补充</pre><p><strong>服务器端V8引擎代码扩展方法：</strong></p><pre class=\"brush:js;toolbar:false\">//待补充</pre><p><br/></p>', b'1', '81b5d8fd-d93e-46ad-9363-568aeac82ab9', '', 200, NULL);
INSERT INTO `diy_document` VALUES ('9be9db29-cb3f-49f5-9a52-9576a7efdc8b', '2022-06-25 17:54:48', '2022-07-26 15:51:45', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '弹出表格', '<ul class=\" list-paddingleft-2\" style=\"list-style-type: disc;\"><li><p>弹出前V8事件：<br/>//添加搜索条件<br/>V8.AppendSearchChildTable(V8.Field.弹出表格控件的字段Name, { Name: &#39;张三&#39;, Sex: 1});<br/></p></li><li><p>提交V8事件<br/>//获取已选择的数据<br/>var selectData = V8.TableRowSelected;<br/>//调用接口将数据插入到某个地方<br/>//刷新子表<br/>V8.RefreshChildTable(V8.Field.子表字段Name);<br/></p></li></ul><p><br/></p>', b'1', 'bdd79162-325c-419c-958b-90360ac789cc', '', 0, NULL);
