INSERT INTO `diy_field` VALUES ('01KGDZNERAPT3DHG5QQHBQH8KG', '1d28e502-70ea-4a2b-9793-699b3f42234e', '固定列', 'FixedFields', 1, 'mediumtext', '', 'MultipleSelect', '', 0, 1, 0, '2026-02-02 09:32:22', '2026-04-07 01:10:29', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', 1200, '01KGA478B1JWN8QQWKMCGTMQD9', 'iTdos', b'0', '[]', '{\"ParamData\":{},\"KeysAddVisible\":false,\"KeysAddVModel\":\"\",\"Sql\":\"select A.Id,A.Name,A.Label,A.TableId,B.Name TableName,B.Description TableDescription,\nCONCAT(A.Name, \' - \', A.Label, \'(\', B.Name, \' - \', B.Description, \')\') _Name\nfrom diy_field A\nleft join diy_table B ON A.TableId=B.Id\nwhere A.IsDeleted<>1 and B.IsDeleted<>1\nand (\'$V8.Form.DiyTableId$\' like CONCAT(\'%\', A.TableId, \'%\') OR \'$V8.Form.JoinTables$\' like CONCAT(\'%\', A.TableId, \'%\'))\norder by B.Name asc,A.Name asc\",\"EnableSearch\":true,\"V8Code\":\"\",\"V8CodeBlur\":\"\",\"DataSource\":\"Sql\",\"DataSourceSqlRemote\":false,\"DataSourceId\":\"\",\"DataSourceApiEngineKey\":\"\",\"SelectLabel\":\"_Name\",\"SelectSaveField\":\"\",\"SelectSaveFormat\":\"Text\",\"NumberTextStep\":1,\"NumberTextPrecision\":0,\"NumberText\":0,\"NumberTextMath\":\"\",\"NumberTextBtn\":true,\"NumberTextBtnPosition\":\"right\",\"DividerPosition\":\"left\",\"DataSourceSqlRemoteLoading\":false,\"TextShowPassword\":false,\"TextIcon\":\"\",\"TextIconPosition\":\"\",\"TextApend\":\"\",\"TextApendPosition\":\"\",\"DateTimeType\":\"date\",\"TextAutocomplete\":false,\"AutoNumberFixed\":\"\",\"AutoNumberLength\":1,\"AutoNumberFields\":[],\"DevComponentName\":\"\",\"DevComponentPath\":\"\",\"TableChildTableId\":\"\",\"TableChildSysMenuId\":\"\",\"TableChildSysMenuName\":\"\",\"TableChildFkFieldName\":\"\",\"TableChildCallbackField\":\"\",\"TableChildRowClickV8\":\"\",\"MapCompany\":\"Baidu\"}', 24, 120, '', 0, '[]', '', '', NULL, '', '', 0, '', 0, 0, '管理员', 1, '', NULL, '', 'sys_menu', '', NULL);
