INSERT INTO `diy_field` VALUES ('01KGFEN9RA5VBGWNNAF9PYXW2V', '6cf254f1-edd0-4f04-96bc-c9ad08b5a2c1', '选择接口引擎', 'SelectApiEngine', 1, 'mediumtext', '', 'MultipleSelect', '', 0, 1, 0, '2026-02-02 23:13:40', '2026-04-07 01:10:30', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', 1900, '01KGFEETNK3KVYXEF3BNH6WXFX', 'iTdos', b'0', '[]', '{\"ParamData\":{},\"KeysAddVisible\":false,\"KeysAddVModel\":\"\",\"Sql\":\"select Id,CONCAT(ApiName,\' - \', ApiEngineKey) ApiName,ApiEngineKey from sys_apiengine where IsDeleted<>1\",\"EnableSearch\":true,\"V8Code\":\"\",\"V8CodeBlur\":\"\",\"DataSource\":\"Sql\",\"DataSourceSqlRemote\":false,\"DataSourceId\":\"\",\"DataSourceApiEngineKey\":\"\",\"SelectLabel\":\"ApiName\",\"SelectSaveField\":\"\",\"SelectSaveFormat\":\"Text\",\"NumberTextStep\":1,\"NumberTextPrecision\":0,\"NumberText\":0,\"NumberTextMath\":\"\",\"NumberTextBtn\":true,\"NumberTextBtnPosition\":\"right\",\"DividerPosition\":\"left\",\"DataSourceSqlRemoteLoading\":false,\"TextShowPassword\":false,\"TextIcon\":\"\",\"TextIconPosition\":\"\",\"TextApend\":\"\",\"TextApendPosition\":\"\",\"DateTimeType\":\"date\",\"TextAutocomplete\":false,\"AutoNumberFixed\":\"\",\"AutoNumberLength\":1,\"AutoNumberFields\":[],\"DevComponentName\":\"\",\"DevComponentPath\":\"\",\"TableChildTableId\":\"\",\"TableChildSysMenuId\":\"\",\"TableChildSysMenuName\":\"\",\"TableChildFkFieldName\":\"\",\"TableChildCallbackField\":\"\",\"TableChildRowClickV8\":\"\",\"MapCompany\":\"Baidu\"}', 12, 120, '', 0, '[]', '', '', '', '', '', 0, '', 0, 0, '管理员', 1, '', NULL, '', 'sys_microistore', '', NULL);
INSERT INTO `diy_field` VALUES ('01KGFEPBXFNNCAN2WAAHRHW553', '6cf254f1-edd0-4f04-96bc-c9ad08b5a2c1', '开始制作', 'BtnMakeApp', 1, '', '', 'Button', '', 0, 1, 0, '2026-02-02 23:14:15', '2026-04-07 01:10:30', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', 2000, '01KGFEETNK3KVYXEF3BNH6WXFX', 'iTdos', b'0', '[]', '{\"ParamData\":{},\"KeysAddVisible\":false,\"KeysAddVModel\":\"\",\"V8Code\":\"//获取相关数据\\ndebugger;\\nvar MenuIds = [];\\nvar FlowIds = [];\\nvar ApiEngineKeys = [];\\nif (V8.Form.SelectMenu && V8.Form.SelectMenu.length > 0) {\\n  MenuIds = V8.Form.SelectMenu.map(item => { return item.Id });\\n}\\nif (V8.Form.SelectWF && V8.Form.SelectWF.length > 0) {\\n  FlowIds = V8.Form.SelectWF.map(item => { return item.Id });\\n}\\nif (V8.Form.SelectApiEngine && V8.Form.SelectApiEngine.length > 0) {\\n  ApiEngineKeys = V8.Form.SelectApiEngine.map(item => { return item.ApiEngineKey });\\n}\\nif (MenuIds.length == 0 && FlowIds.length == 0 && ApiEngineKeys.length == 0) {\\n  V8.Tips(\'菜单、流程、接口模块至少选择1个！\', false);\\n  return;\\n}\\n//执行导出数据包\\nvar packageResult = await V8.ApiEngine.Run(\\\"export-microi-store-package\\\", {\\n  MenuIds, FlowIds, ApiEngineKeys\\n});\\nif (packageResult.Code != 1) {\\n  V8.Tips(\'制作失败：\' + packageResult.Msg, false);\\n  return;\\n}\\nV8.FormSet(\'AppPakcet\', JSON.stringify(packageResult.Data));\\nV8.Tips(\'制作成功！，请查看数据包！\');\\n\\n\\n\\n\",\"V8CodeBlur\":\"\",\"Button\":{\"Type\":\"primary\",\"Loading\":false,\"Icon\":\"\",\"Size\":\"small\",\"PreviewCanClick\":true},\"Sql\":\"\",\"EnableSearch\":true,\"NumberTextStep\":1,\"NumberTextPrecision\":0,\"NumberText\":0,\"NumberTextMath\":\"\",\"NumberTextBtn\":true,\"NumberTextBtnPosition\":\"right\",\"DividerPosition\":\"left\",\"DataSource\":\"\",\"DataSourceSqlRemote\":false,\"DataSourceSqlRemoteLoading\":false,\"DataSourceId\":\"\",\"DataSourceApiEngineKey\":\"\",\"TextShowPassword\":false,\"TextIcon\":\"\",\"TextIconPosition\":\"\",\"TextApend\":\"\",\"TextApendPosition\":\"\",\"SelectLabel\":\"\",\"SelectSaveField\":\"\",\"SelectSaveFormat\":\"Text\",\"DateTimeType\":\"date\",\"TextAutocomplete\":false,\"AutoNumberFixed\":\"\",\"AutoNumberLength\":1,\"AutoNumberFields\":[],\"DevComponentName\":\"\",\"DevComponentPath\":\"\",\"TableChildTableId\":\"\",\"TableChildSysMenuId\":\"\",\"TableChildSysMenuName\":\"\",\"TableChildFkFieldName\":\"\",\"TableChildCallbackField\":\"\",\"TableChildRowClickV8\":\"\",\"MapCompany\":\"Baidu\"}', NULL, 120, '', 0, '[]', '', '', '', '', '', 0, '', 0, 0, '管理员', 1, '', NULL, '', 'sys_microistore', '//获取相关数据\ndebugger;\nvar MenuIds = [];\nvar FlowIds = [];\nvar ApiEngineKeys = [];\nvar TableIds = [];\nif (V8.Form.SelectMenu && V8.Form.SelectMenu.length > 0) {\n  MenuIds = V8.Form.SelectMenu.map(item => { return item.Id });\n}\nif (V8.Form.SelectTable && V8.Form.SelectTable.length > 0) {\n  TableIds = V8.Form.SelectTable.map(item => { return item.Id });\n}\nif (V8.Form.SelectWF && V8.Form.SelectWF.length > 0) {\n  FlowIds = V8.Form.SelectWF.map(item => { return item.Id });\n}\nif (V8.Form.SelectApiEngine && V8.Form.SelectApiEngine.length > 0) {\n  ApiEngineKeys = V8.Form.SelectApiEngine.map(item => { return item.ApiEngineKey });\n}\nif (MenuIds.length == 0 && TableIds.length == 0 && FlowIds.length == 0 && ApiEngineKeys.length == 0) {\n  V8.Tips(\'【菜单、流程、接口引擎、表单】至少选择1个！\', false);\n  return;\n}\n//执行导出数据包\nvar packageResult = await V8.ApiEngine.Run(\"export-microi-store-package\", {\n  MenuIds, FlowIds, ApiEngineKeys, TableIds\n});\nif (packageResult.Code != 1) {\n  V8.Tips(\'制作失败：\' + packageResult.Msg, false);\n  return;\n}\nV8.FormSet(\'AppPakcet\', JSON.stringify(packageResult.Data));\nV8.Tips(\'制作成功！，请查看数据包！\');\n\n\n\n', NULL);
