INSERT INTO `diy_field` VALUES ('42c6f660-bb10-4a9c-ab94-134b5d951879', '1d28e502-70ea-4a2b-9793-699b3f42234e', '查询列', 'SelectFields', 1, 'mediumtext', '', 'JsonTable', '指定select哪些列，不指定则是select *', 0, 1, 0, '2022-08-16 15:54:11', '2026-04-07 01:10:30', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', 400, '01KGA478B1JWN8QQWKMCGTMQD9', 'iTdos', b'0', '[]', '{\"ParamData\":{},\"KeysAddVisible\":false,\"KeysAddVModel\":\"\",\"V8Code\":\"\",\"V8CodeBlur\":\"\",\"Sql\":\"select A.Id,A.Name,A.Label,A.TableId,B.Name TableName,B.Description TableDescription,\nCONCAT(A.Name, \' - \', A.Label, \'(\', B.Name, \' - \', B.Description, \')\') _Name\nfrom diy_field A\nleft join diy_table B ON A.TableId=B.Id\nwhere A.IsDeleted<>1 and B.IsDeleted<>1\nand (\'$V8.Form.DiyTableId$\' like CONCAT(\'%\', A.TableId, \'%\') OR \'$V8.Form.JoinTables$\' like CONCAT(\'%\', A.TableId, \'%\'))\norder by B.Name asc,A.Name asc\",\"EnableSearch\":true,\"NumberTextStep\":1,\"NumberTextPrecision\":0,\"NumberText\":0,\"NumberTextMath\":\"\",\"NumberTextBtn\":true,\"NumberTextBtnPosition\":\"right\",\"DividerPosition\":\"left\",\"DataSource\":\"Sql\",\"DataSourceSqlRemote\":false,\"DataSourceSqlRemoteLoading\":false,\"DataSourceId\":\"\",\"DataSourceApiEngineKey\":\"\",\"TextShowPassword\":false,\"TextIcon\":\"\",\"TextIconPosition\":\"\",\"TextApend\":\"\",\"TextApendPosition\":\"\",\"SelectLabel\":\"_Name\",\"SelectSaveField\":\"\",\"SelectSaveFormat\":\"Text\",\"DateTimeType\":\"date\",\"TextAutocomplete\":false,\"AutoNumberFixed\":\"\",\"AutoNumberLength\":1,\"AutoNumberFields\":[],\"DevComponentName\":\"\",\"DevComponentPath\":\"\",\"TableChildTableId\":\"\",\"TableChildSysMenuId\":\"\",\"TableChildSysMenuName\":\"\",\"TableChildFkFieldName\":\"\",\"TableChildCallbackField\":\"\",\"TableChildRowClickV8\":\"\",\"MapCompany\":\"Baidu\",\"JsonTable\":{\"Columns\":[{\"Id\":\"01KGFVT7B0EX04NN5FWB5SS7CS\",\"Sort\":1,\"Label\":\"Id\",\"Key\":\"Id\",\"Component\":\"Text\",\"Width\":\"\",\"MinWidth\":120,\"Required