INSERT INTO `diy_field` VALUES ('476cf7b1-d3ac-4228-ac8c-38881f3bc016', '3c55fc03-e9d6-4b3e-953d-494e6e5ffcf3', '添加选择的字段', 'JiazaiXZZD', 1, '', '', 'Button', '', 0, 0, 0, '2024-04-03 15:26:47', '2026-03-25 16:57:02', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', 1400, '字段配置', '', b'0', '[]', '{\"ParamData\":{},\"KeysAddVisible\":false,\"KeysAddVModel\":\"\",\"Sql\":\"\",\"EnableSearch\":false,\"NumberTextStep\":1,\"NumberTextPrecision\":0,\"NumberText\":0,\"NumberTextMath\":\"\",\"NumberTextBtn\":true,\"NumberTextBtnPosition\":\"right\",\"V8Code\":\"if(!V8.Form.RptSelectFieldList || V8.Form.RptSelectFieldList.length == 0){\\n  V8.Tips(\'请选择要添加的字段\', false); return;\\n}\\n//直接插入到数据库，不管重复\\nvar newFiledList = [];\\nV8.Form.RptSelectFieldList.forEach(item => {\\n  var newItem = {...item};\\n  newItem.TableId = V8.Form.FkTableId;\\n  newItem.Id = \'\';\\n  newItem.Label = newItem.Label.replace(`（${newItem.Name}）`, \'\');\\n  newFiledList.push({\\n    FormEngineKey : \'diy_field\',\\n    _RowModel : newItem\\n  });\\n})\\n//插入数据库\\nvar addResult = await V8.FormEngine.AddFormDataBatch(newFiledList);\\nif(addResult.Code == 1){\\n  V8.Tips(\'加载成功！\');\\n  V8.TableRefresh(V8.Field.RptFieldList, { _PageIndex : -1 })\\n}else{\\n  V8.Tips(\'加载失败：\' + addResult.Msg, false);\\n}\",\"V8CodeBlur\":\"\",\"DividerPosition\":\"left\",\"DataSource\":\"\",\"DataSourceSqlRemote\":false,\"DataSourceSqlRemoteLoading\":false,\"DataSourceId\":\"\",\"TextShowPassword\":false,\"TextIcon\":\"\",\"TextIconPosition\":\"\",\"TextApend\":\"\",\"TextApendPosition\":\"\",\"SelectLabel\":\"\",\"SelectSaveField\":\"\",\"SelectSaveFormat\":\"Text\",\"DateTimeType\":\"date\",\"TextAutocomplete\":false,\"AutoNumberFixed\":\"\",\"AutoNumberLength\":1,\"AutoNumberFields\":[],\"DevComponentName\":\"\",\"DevComponentPath\":\"\",\"TableChildTableId\":\"\",\"TableChildSysMenuId\":\"\",\"TableChildSysMenuName\":\"\",\"TableChildFkFieldName\":\"\",\"TableChildCallbackField\":\"\",\"TableChildRowClickV8\":\"\",\"MapCompany\":\"Baidu\",\"Button\":{\"Type\":\"primary\",\"Loading\":false,\"Icon\":\"fas fa-cloud-download-alt\",\"Size\":\"mini\",\"PreviewCanClick\":true},\"DataSourceApiEngineKey\":\"\"}', NULL, 120, '', 0, '[]', '', '', '', '', '', 0, '', 0, 0, NULL, 1, '', NULL, '', 'Rpt_Report', '', NULL);
