INSERT INTO `diy_field` VALUES ('5ed4bc53-c5f5-4417-9c7f-cfa0a5c4613b', '5608c807-7178-4fdb-a765-c1b7ac4ad5c0', '名称', 'Mingcheng', 1, 'varchar(255)', '', 'Select', '', 1, 1, 0, '2020-08-18 09:37:37', '2022-05-19 04:34:19', '00000000-0000-0000-0000-000000000000', 100, '', '', b'0', '[]', '{\"KeysAddVisible\":false,\"KeysAddVModel\":\"\",\"Sql\":\"SELECT * from  (select A.ID,A.Zd_ZJM,A.Zd_PrtNo,A.Zd_Name,A.Zd_GuiGe ,A.Zd_DanWei,A.Zd_Price,A.Zd_CKNM,B.CangkuLB,Zd_Del,CONCAT(A.Zd_PrtNo, \', \', A.Zd_Name, \', \', A.Zd_GuiGe) AS pinjie,substring_index(\'$Keyword$\',\',\',1) AS name, substring_index(\'$Keyword$\',\',\',-1) AS guige  from C_WuZiBianMa A INNER JOIN Diy_CangkuXX B ON A.Zd_CKNM=B.CangkuMC ) AS C where Zd_Del=0  and (CangkuLB=\'总装及预装\'  or CangkuLB=\'组件\')  and (zd_Prtno like \'%$Keyword$%\'  or Zd_Name like \'%$Keyword$%\'  or Zd_GuiGe  like \'%$Keyword$%\' or Zd_ZJM LIKE \'%$Keyword$%\' OR (Zd_ZJM like concat(\'%\',name,\'%\') AND Zd_ZJM  like concat(\'%\',guige,\'%\')) )  group by Zd_PrtNo  limit 0,90 \",\"EnableSearch\":true,\"NumberTextStep\":1,\"NumberTextPrecision\":0,\"NumberText\":0,\"NumberTextMath\":\"\",\"NumberTextBtn\":true,\"NumberTextBtnPosition\":\"\",\"V8Code\":\"V8.FormSet(\'ShuxingY\',\'\');\\nV8.FormSet(\'ShuxingE\',\'\');\\nV8.FormSet(\'ShuxingYZ\',\'\');\\nV8.FormSet(\'MingchengZ\',V8.ThisValue.Zd_Name);\\nV8.FormSet(\'Guige\',V8.ThisValue.Zd_GuiGe);\\nV8.FormSet(\'WuziBMCK\',V8.ThisValue.Zd_CKNM);\\nV8.FormSet(\'Danjia\',V8.ThisValue.Zd_Price);\\nV8.FormSet(\'Bianma\',V8.ThisValue.Zd_PrtNo);\\nV8.FormSet(\'Mingcheng\',V8.ThisValue.Zd_Name);\\nV8.FormSet(\'ChanpinID\',V8.ThisValue.ID);\\nV8.FormSet(\'Danwei\',V8.ThisValue.Zd_DanWei);\\n\\n \\nlet sql=\\\"SELECT attribute1,attribute2,ShuxingYZ,ShuxingEZ,CONCAT(ShuxingYZ, \',\',ShuxingEZ)AS pinjie FROM `diy_materialpropertylist` WHERE BianmaF=\'\\\"+V8.Form.Bianma+\\\"\'\\\";\\nV8.RunSqlGetList(sql, function(data){ \\n   V8.FieldSet(\'ShuxingY\', \'Data\', data); \\n})\",\"DividerPosition\":\"left\",\"DataSource\":\"Sql\",\"DataSourceSqlRemote\":true,\"DataSourceSqlRemoteLoading\":false,\"TextShowPassword\":false,\"TextIcon\":\"\",\"TextIconPosition\":\"\",\"TextApend\":\"\",\"TextApendPosition\":\"\",\"SelectLabel\":\"pinjie\",\"DateTimeType\":\"date\",\"TextAutocomplete\":false,\"AutoNumberFixed\":\"\",\"AutoNumberLength\":1,\"AutoNumberFields\":[],\"ImgUploadLimit\":false,\"ImgUploadMultiple\":false,\"ImgUploadTips\":\"只能上传图片文件\",\"UploadMaxCount\":10,\"FileUploadLimit\":true,\"FileUploadMultiple\":true,\"FileUploadTips\":\"附件最大500M\",\"DevComponentName\":\"\",\"DevComponentPath\":\"\",\"TableChildTableId\":\"\",\"TableChildSysMenuId\":\"\",\"TableChildSysMenuName\":\"\",\"TableChildFkFieldName\":\"\",\"TableChildCallbackField\":\"\",\"MapCompany\":\"Baidu\",\"ParamData\":{},\"SelectSaveField\":\"\",\"SelectSaveFormat\":\"Json\",\"AutoNumber\":{\"DataRule\":\"\",\"CreateRule\":\"\"},\"ImgUpload\":{\"Limit\":false,\"Multiple\":false,\"Tips\":\"\",\"MaxCount\":10,\"ShowFileList\":false},\"FileUpload\":{\"Limit\":true,\"Multiple\":true,\"Tips\":\"\",\"MaxCount\":10,\"ShowFileList\":false},\"TableChild\":{\"Data\":[],\"SearchAppend\":{}},\"Button\":{\"Type\":\"primary\",\"Loading\":false,\"Icon\":\"\",\"Size\":\"mini\",\"PreviewCanClick\":true},\"Autocomplete\":{},\"V8CodeBlur\":\"\",\"TableChildRowClickV8\":\"\",\"Unique\":{\"Type\":\"Alone\"},\"OpenTable\":{\"BtnText\":\"\",\"ShowDialog\":false,\"MultipleSelect\":false,\"SubmitV8\":\"\",\"BeforeOpenV8\":\"\",\"SearchAppend\":{}},\"Department\":{\"Multiple\":false},\"Cascader\":{\"Lazy\":false,\"Filterable\":false},\"JoinForm\":{\"TableId\":\"\",\"TableName\":\"\",\"Id\":\"\",\"FormMode\":\"\",\"_SearchEqual\":{}}}', NULL, 100, '', 0, '[]', '', '', NULL, '', '', 0, '', 0, NULL, NULL, 1, NULL, NULL, NULL, 'diy_chukoucpbjqd_plasticdetails', NULL, NULL);
