INSERT INTO `diy_field` VALUES ('6ce10c1b-96c5-44d4-b16b-db0152f7c28a', '3c55fc03-e9d6-4b3e-953d-494e6e5ffcf3', '添加表的所有字段', 'RptLoadTableField', 1, '', '', 'Button', '', 0, 0, 0, '2024-04-03 15:07:24', '2026-03-25 16:57:02', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', 1200, '字段配置', '', b'0', '[]', '{\"ParamData\":{},\"KeysAddVisible\":false,\"KeysAddVModel\":\"\",\"Sql\":\"\",\"EnableSearch\":false,\"NumberTextStep\":1,\"NumberTextPrecision\":0,\"NumberText\":0,\"NumberTextMath\":\"\",\"NumberTextBtn\":true,\"NumberTextBtnPosition\":\"right\",\"V8Code\":\"if(!V8.Form.RptSelectTable.Id){\\n  V8.Tips(\'请选择表！\', false); return;\\n}\\n\\n//获取该表的所有字段\\nvar fieldListResult = await V8.FormEngine.GetTableData({\\n  FormEngineKey : \'diy_field\',\\n  _Where:[{ Name : \'TableId\', Value : V8.Form.RptSelectTable.Id, Type : \'=\' }]\\n});\\nif(fieldListResult.Code != 1){\\n  V8.Tips(fieldListResult.Msg, false); return;\\n}\\nvar fieldList = fieldListResult.Data;\\n//获取已有的所有字段\\nvar oldFiledList = await V8.FormEngine.GetTableData({\\n  FormEngineKey : \'diy_field\',\\n  _Where:[{ Name : \'TableId\', Value : V8.Form.FkTableId, Type : \'=\' }]\\n});\\nif(oldFiledList.Code != 1){\\n  V8.Tips(oldFiledList.Msg, false); return;\\n}\\n//有重复的不插入到数据库\\nvar newFiledList = [];\\nfieldList.forEach(item => {\\n  if(!oldFiledList.Data.find(filed => field.Name == item.Name)){\\n    item.TableId = V8.Form.FkTableId;\\n    item.Id = \'\';\\n    newFiledList.push({\\n      FormEngineKey : \'diy_field\',\\n      _RowModel : item\\n    });\\n  }\\n})\\n//插入数据库\\nvar addResult = await V8.FormEngine.AddFormDataBatch(newFiledList);\\nif(addResult.Code == 1){\\n  V8.Tips(\'加载成功！\');\\n  V8.TableRefresh(V8.Field.RptFieldList, { _PageIndex : -1 })\\n}else{\\n  V8.Tips(\'加载失败：\' + addResult.Msg, false);\\n}\",\"V8CodeBlur\":\"\",\"DividerPosition\":\"left\",\"DataSource\":\"\",\"DataSourceSqlRemote\":false,\"DataSourceSqlRemoteLoading\":false,\"DataSourceId\":\"\",\"TextShowPassword\":false,\"TextIcon\":\"\",\"TextIconPosition\":\"\",\"TextApend\":\"\",\"TextApendPosition\":\"\",\"SelectLabel\":\"\",\"SelectSaveField\":\"\",\"SelectSaveFormat\":\"Text\",\"DateTimeType\":\"date\",\"TextAutocomplete\":false,\"AutoNumberFixed\":\"\",\"AutoNumberLength\":1,\"AutoNumberFields\":[],\"DevComponentName\":\"\",\"DevComponentPath\":\"\",\"TableChildTableId\":\"\",\"TableChildSysMenuId\":\"\",\"TableChildSysMenuName\":\"\",\"TableChildFkFieldName\":\"\",\"TableChildCallbackField\":\"\",\"TableChildRowClickV8\":\"\",\"MapCompany\":\"Baidu\",\"Button\":{\"Type\":\"danger\",\"Loading\":false,\"Icon\":\"fas fa-cloud-download-alt\",\"Size\":\"mini\",\"PreviewCanClick\":true},\"DataSourceApiEngineKey\":\"\"}', NULL, 120, '', 0, '[]', '', '', '', '', '', 0, '', 0, 0, NULL, 1, '', NULL, '', 'Rpt_Report', 'if(!V8.Form.RptSelectTable.Id){\n  V8.Tips(\'请选择表！\', false); return;\n}\n\n//获取该表的所有字段\nvar fieldListResult = await V8.FormEngine.GetTableData({\n  FormEngineKey : \'diy_field\',\n  _Where:[{ Name : \'TableId\', Value : V8.Form.RptSelectTable.Id, Type : \'=\' }]\n});\nif(fieldListResult.Code != 1){\n  V8.Tips(fieldListResult.Msg, false); return;\n}\nvar fieldList = fieldListResult.Data;\n//获取已有的所有字段\nvar oldFiledList = await V8.FormEngine.GetTableData({\n  FormEngineKey : \'diy_field\',\n  _Where:[{ Name : \'TableId\', Value : V8.Form.FkTableId, Type : \'=\' }]\n});\nif(oldFiledList.Code != 1){\n  V8.Tips(oldFiledList.Msg, false); return;\n}\n//有重复的不插入到数据库\nvar newFiledList = [];\nfieldList.forEach(item => {\n  if(!oldFiledList.Data.find(filed => field.Name == item.Name)){\n    item.TableId = V8.Form.FkTableId;\n    item.Id = \'\';\n    item.IsVirtual = 1;\n    newFiledList.push({\n      FormEngineKey : \'diy_field\',\n      _RowModel : item\n    });\n  }\n})\n//插入数据库\nvar addResult = await V8.FormEngine.AddFormDataBatch(newFiledList);\nif(addResult.Code == 1){\n  V8.Tips(\'加载成功！\');\n  V8.TableRefresh(V8.Field.RptFieldList, { _PageIndex : -1 })\n}else{\n  V8.Tips(\'加载失败：\' + addResult.Msg, false);\n}', NULL);
