INSERT INTO `diy_field` VALUES ('ad6fd302-3149-47cf-8b3a-675a0017ec7a', 'cf389aef-72cc-4980-9c5b-143123561ac0', '测试自定义接口地址', 'TestBtnApiAddress', 1, '', '', 'Button', '', 0, 1, 0, '2025-12-15 03:17:30', '2026-03-08 00:48:32', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', 2000, 'e4c00d48-6af1-42e8-b2c6-603672295f19', '', b'0', '[]', '{\"ParamData\":{},\"KeysAddVisible\":false,\"KeysAddVModel\":\"\",\"Sql\":\"\",\"EnableSearch\":true,\"NumberTextStep\":1,\"NumberTextPrecision\":0,\"NumberText\":0,\"NumberTextMath\":\"\",\"NumberTextBtn\":true,\"NumberTextBtnPosition\":\"right\",\"V8Code\":\"if(!V8.Form.ApiAddress){\\n  V8.Tips(\'ApiAddress不能为空！\', false);\\n  return;\\n}\\nvar data = {\\n  OsClient : V8.OsClient\\n};\\n\\nif(V8.Form.TestParam){\\n  //---拼接参数 普通写法\\n  //var testParam = JSON.parse(V8.Form.TestParam);\\n  //for(let key in testParam){\\n  //  param[key] = testParam[key];\\n  //}\\n  //---拼接参数 ES6写法\\n  data = {\\n    ...JSON.parse(V8.Form.TestParam),\\n    ...data\\n  }\\n}\\nvar option = {\\n  url : V8.Form.ApiAddress,\\n  data : data,\\n  dataType : V8.Form.DataType || \'json\',\\n  header : {},\\n  success : function(result){\\n    if(typeof(result) == \'object\'){\\n      result = JSON.stringify(result);\\n    }\\n    V8.FormSet(\'TestResult\', \'[\' \\n      + new Date().Format(\'yyyy-MM-dd HH:mm:ss\') \\n      + \']执行结果：\' + result);\\n    V8.Tips(\'测试完毕，请查看结果！\');\\n  }\\n};\\nif(V8.Form.AllowAnonymous){\\n  option.header.osclient = V8.OsClient;\\n  option.header.apiengine = 1;\\n}\\nV8.Post(option);\",\"V8CodeBlur\":\"\",\"DividerPosition\":\"left\",\"DataSource\":\"\",\"DataSourceSqlRemote\":false,\"DataSourceSqlRemoteLoading\":false,\"DataSourceId\":\"\",\"DataSourceApiEngineKey\":\"\",\"TextShowPassword\":false,\"TextIcon\":\"\",\"TextIconPosition\":\"\",\"TextApend\":\"\",\"TextApendPosition\":\"\",\"SelectLabel\":\"\",\"SelectSaveField\":\"\",\"SelectSaveFormat\":\"Text\",\"DateTimeType\":\"date\",\"TextAutocomplete\":false,\"AutoNumberFixed\":\"\",\"AutoNumberLength\":1,\"AutoNumberFields\":[],\"DevComponentName\":\"\",\"DevComponentPath\":\"\",\"TableChildTableId\":\"\",\"TableChildSysMenuId\":\"\",\"TableChildSysMenuName\":\"\",\"TableChildFkFieldName\":\"\",\"TableChildCallbackField\":\"\",\"TableChildRowClickV8\":\"\",\"MapCompany\":\"Baidu\",\"Button\":{\"Type\":\"primary\",\"Loading\":false,\"Icon\":\"fab fa-angellist\",\"Size\":\"mini\",\"PreviewCanClick\":true}}', 8, 120, '', 0, '[]', '', '', '', '', '', 0, '', 0, 0, NULL, 1, '', NULL, '', 'sys_apiengine', '', NULL);
