JA5Q\",\"Sort\":8,\"Label\":\"统计方式\",\"Key\":\"Type\",\"Component\":\"Text\",\"Width\":\"\",\"MinWidth\":120,\"Required\":false,\"Visible\":true,\"DefaultValue\":\"\",\"Placeholder\":\"Sum\",\"Readonly\":false,\"Config\":{},\"Data\":[],\"KeyValueList\":[],\"DataString\":\"\"}],\"DataSource\":\"Sql\",\"Sql\":\"select A.Id,A.Name,A.Label,A.TableId,B.Name TableName,B.Description TableDescription,\nCONCAT(A.Name, \' - \', A.Label, \'(\', B.Name, \' - \', B.Description, \')\') _Name\nfrom diy_field A\nleft join diy_table B ON A.TableId=B.Id\nwhere A.IsDeleted<>1 and B.IsDeleted<>1\nand (\'$V8.Form.DiyTableId$\' like CONCAT(\'%\', A.TableId, \'%\') OR \'$V8.Form.JoinTables$\' like CONCAT(\'%\', A.TableId, \'%\'))\norder by B.Name asc,A.Name asc\",\"DataSourceId\":\"\",\"ApiEngineKey\":\"\",\"SelectLabel\":\"_Name\",\"KeyValueList\":[],\"DataSourceSqlRemote\":false}}', 24, 50, '', 0, '[]', '', '', NULL, '', '', 0, '', 1, 0, NULL, 1, '', NULL, '', 'sys_menu', '', NULL);
