INSERT INTO `diy_table` VALUES ('0234e89e-2e80-4ae0-b86a-f53635e29460', 'diy_schedule_job', '定时任务表', '2023-10-10 13:42:22', '2026-03-21 03:20:17', '84ed01b8-ca38-4916-9673-fa869b3817ab', b'0', 'iTdos', 0, 0, '', 2, 0, '[]', '[{\"Name\":\"none\",\"EnName\":\"none\",\"Display\":true,\"Sort\":1,\"Id\":\"c511a3e0-3c53-446b-ae0b-6cfce6652f51\"}]', '', '[]', '', '', '', 'Drawer', '70%', '', '', '\r\nif(V8.FormMode == \'Add\'){\r\n  V8.FormSet(\'JobType\', \'1\');\r\n  V8.FieldSet(\'Status\', \'Visible\', false);\r\n  V8.FieldSet(\'LastTime\', \'Visible\', false);\r\n  V8.FieldSet(\'NextTime\', \'Visible\', false);\r\n  V8.FieldSet(\'DllName\', \'Visible\', false);\r\n  V8.FieldSet(\'JobPath\', \'Visible\', false);\r\n  V8.FieldSet(\'CronExpression\', \'Visible\', false);\r\n  V8.FieldSet(\'RenwuZHRZ\', \'Visible\', false);\r\n  V8.FieldSet(\'RizhiLB\', \'Visible\', false);\r\n  V8.FormSet(\'ZhiXingZQLB\', \'简单模式\');\r\n}\r\nif(V8.FormMode == \'Edit\'){\r\n  V8.FieldSet(\'Status\', \'Visible\', false);\r\n  V8.FieldSet(\'LastTime\', \'Visible\', false);\r\n  V8.FieldSet(\'NextTime\', \'Visible\', false);\r\n  V8.FieldSet(\'JobName\', \'Readonly\', true);\r\n  V8.FieldSet(\'DllName\', \'Readonly\', true);\r\n  V8.FieldSet(\'JobPath\', \'Readonly\', true);\r\n  V8.FieldSet(\'JobParam\', \'Readonly\', true);\r\n  V8.FieldSet(\'ApiEngineKey\', \'Readonly\', true);\r\n  V8.FieldSet(\'JobType\', \'Readonly\', true);\r\n  V8.FieldSet(\'CronExpression\', \'Visible\', false);\r\n  V8.FieldSet(\'RenwuZHRZ\', \'Visible\', false);\r\n  V8.FieldSet(\'RizhiLB\', \'Visible\', false);\r\n  if(V8.Form.JobType == \"1\"){\r\n    V8.FieldSet(\'DllName\', \'Visible\', false);\r\n    V8.FieldSet(\'JobPath\', \'Visible\', false);\r\n  }\r\n  else {\r\n    V8.FieldSet(\'DllName\', \'Visible\', true);\r\n    V8.FieldSet(\'JobPath\', \'Visible\', true);\r\n    V8.FieldSet(\'ApiEngineKey\', \'Visible\', false);\r\n  }\r\n  if(V8.Form.ZhiXingZQLB == \'简单模式\'){\r\n  if(V8.Form.ZhiXingZQ == \"每天\"){\r\n  V8.FieldSet(\'xiaoShi\', \'Visible\', true);\r\n  V8.FieldSet(\'FenZhong\', \'Visible\', true);\r\n  V8.FieldSet(\'Tian\', \'Visible\', false);\r\n  V8.FieldSet(\'Week\', \'Visible\', false);\r\n  V8.FieldSet(\'Miao\', \'Visible\', false);\r\n}\r\nelse if(V8.Form.ZhiXingZQ == \"N天\"){\r\n   V8.FieldSet(\'XiaoShi\', \'Visible\', true);\r\n   V8.FieldSet(\'FenZhong\', \'Visible\', true);\r\n   V8.FieldSet(\'Tian\', \'Visible\', true);\r\n   V8.FieldSet(\'Week\', \'Visible\', false);\r\n   V8.FieldSet(\'Miao\', \'Visible\', false);\r\n}\r\nelse if(V8.Form.ZhiXingZQ == \"每小时\"){\r\n   V8.FieldSet(\'XiaoShi\', \'Visible\', false);\r\n   V8.FieldSet(\'FenZhong\', \'Visible\', true);\r\n   V8.FieldSet(\'Tian\', \'Visible\', false);\r\n   V8.FieldSet(\'Week\', \'Visible\', false);\r\n   V8.FieldSet(\'Miao\', \'Visible\', false);\r\n}\r\nelse if(V8.Form.ZhiXingZQ == \"N小时\"){\r\n   V8.FieldSet(\'XiaoShi\', \'Visible\', true);\r\n   V8.FieldSet(\'FenZhong\', \'Visible\', true);\r\n   V8.FieldSet(\'Tian\', \'Visible\', false);\r\n   V8.FieldSet(\'Week\', \'Visible\', false);\r\n   V8.FieldSet(\'Miao\', \'Visible\', false);\r\n}\r\nelse if(V8.Form.ZhiXingZQ == \"N分钟\"){\r\n   V8.FieldSet(\'XiaoShi\', \'Visible\', false);\r\n   V8.FieldSet(\'FenZhong\', \'Visible\', true);\r\n   V8.FieldSet(\'Tian\', \'Visible\', false);\r\n   V8.FieldSet(\'Week\', \'Visible\', false);\r\n   V8.FieldSet(\'Miao\', \'Visible\', false);\r\n}\r\nelse if(V8.Form.ZhiXingZQ == \"每星期\"){\r\n   V8.FieldSet(\'XiaoShi\', \'Visible\', true);\r\n   V8.FieldSet(\'FenZhong\', \'Visible\', true);\r\n   V8.FieldSet(\'Tian\', \'Visible\', false);\r\n   V8.FieldSet(\'Week\', \'Visible\', true);\r\n   V8.FieldSet(\'Miao\', \'Visible\', false);\r\n}\r\nelse if(V8.Form.ZhiXingZQ == \"每月\"){\r\n   V8.FieldSet(\'XiaoShi\', \'Visible\', true);\r\n   V8.FieldSet(\'FenZhong\', \'Visible\', true);\r\n   V8.FieldSet(\'Tian\', \'Visible\', true);\r\n   V8.FieldSet(\'Week\', \'Visible\', false);\r\n   V8.FieldSet(\'Miao\', \'Visible\', false);\r\n}\r\nelse if(V8.Form.ZhiXingZQ == \"N秒\"){\r\n   V8.FieldSet(\'XiaoShi\', \'Visible\', false);\r\n   V8.FieldSet(\'FenZhong\', \'Visible\', false);\r\n   V8.FieldSet(\'Tian\', \'Visible\', false);\r\n   V8.FieldSet(\'Week\', \'Visible\', false);\r\n   V8.FieldSet(\'Miao\', \'Visible\', true);\r\n}\r\n}\r\nelse{\r\n  V8.FieldSet(\'ZhiXingZQ\', \'Visible\', false);\r\n  V8.FieldSet(\'Tian\', \'Visible\', false);\r\n  V8.FieldSet(\'Week\', \'Visible\', false);\r\n  V8.FieldSet(\'XiaoShi\', \'Visible\', false);\r\n  V8.FieldSet(\'FenZhong\', \'Visible\', false);\r\n  V8.FieldSet(\'Miao\', \'Visible\', false);\r\n  V8.FieldSet(\'CronExpression\', \'Visible\', true);\r\n}\r\n\r\n}\r\nif(V8.FormMode == \'View\'){\r\n  //V8.FieldSet(\'CronExpression\', \'Visible\', false);\r\n   if(V8.Form.JobType == \"1\"){\r\n    V8.FieldSet(\'DllName\', \'Visible\', false);\r\n    V8.FieldSet(\'JobPath\', \'Visible\', false);\r\n  }\r\n  else {\r\n    V8.FieldSet(\'DllName\', \'Visible\', true);\r\n    V8.FieldSet(\'JobPath\', \'Visible\', true);\r\n    V8.FieldSet(\'ApiEngineKey\', \'Visible\', false);\r\n  }\r\n}\r\n', '//已迁移至【服务器端表单提交前V8事件】--2025-12-15 --by anderson\n// 前端离开表单后事件\n// var para = {\n//   Id : V8.Form.Id,\n//   JobName : V8.Form.JobName,\n//   DllName : V8.Form.DllName,\n//   JobPath : V8.Form.JobPath,\n//   JobDesc : V8.Form.JobDesc,\n//   JobParam : V8.Form.JobParam,\n//   CronDesc : V8.Form.CronDesc,\n//   CronExpression : V8.Form.CronExpression,\n//   JobType : V8.Form.JobType,\n//   ApiEngineKey : V8.Form.ApiEngineKey\n// }\n// if(V8.FormOutAction == \'Insert\'){\n//     var result = await V8.Post(\'/api/Job/AddJob\', para, null, { DataType : \'form\' });\n//     if(result.Code != 1){ \n//       V8.Tips(\'新增job失败\', false);         \n//     }\n//     V8.RefreshTable({ _PageIndex : 1 })\n// }\n// else if(V8.FormOutAction == \'Update\'){\n//     var result = await V8.Post(\'/api/Job/UpdateJob\', para, null, { DataType : \'form\' });\n//     if(result.Code != 1){ \n//       V8.Tips(\'修改失败\', false);         \n//     }\n//     V8.RefreshTable({ _PageIndex : 1 })\n// }\n// else if(V8.FormOutAction == \'Delete\'){\n//  V8.Post(\'/api/Job/DeleteJob\', para, function(result){\n//     if(result.Code != 1){ \n//       V8.Tips(\'删除失败\', result.Msg);\n//       V8.Result = false;\n//       return;\n//     }\n//   }, {\n//     DataType : \'form\'\n//   })\n// }\n', 'if(V8.FormSubmitAction == \'Insert\'){\r\n  if(!V8.Form.JobType || !V8.Form.JobName){\r\n    V8.Tips(\"任务类别、任务key不能为空\", false);\r\n    V8.Result = false;\r\n    return;\r\n  }\r\n  if(V8.Form.JobType == \"1\"){\r\n    if(!V8.Form.ApiEngineKey){\r\n      V8.Tips(\"ApiEngineKey不能为空\", false);\r\n      V8.Result = false;\r\n      return;\r\n    }\r\n  }\r\n  else {\r\n    if(!V8.Form.DllName || !V8.Form.JobPath){\r\n      V8.Tips(\"Dll名称、任务路径不能为空\", false);\r\n      V8.Result = false;\r\n      return;\r\n    }\r\n    if(V8.Form.DllName.indexOf(\".dll\") == -1){\r\n      V8.Tips(\"Dll名称不对，需要包含.dll\", false);\r\n      V8.Result = false;\r\n      return;\r\n    }\r\n  }\r\n  var regStr = /^[a-zA-Z]+$/;\r\n  if(!regStr.test(V8.Form.JobName)){\r\n    V8.Tips(\"任务key只能输入英文\", false);\r\n    V8.Result = false;\r\n    return;\r\n  }\r\n}\r\nif(V8.FormSubmitAction == \'Insert\' || V8.FormSubmitAction == \'Update\'){\r\n  // 校验执行周期\r\n  if(!V8.Form.ZhiXingZQLB){\r\n    V8.Tips(\"请选择执行周期类别\", false);\r\n    V8.Result = false;\r\n    return;\r\n  }\r\n   var cron = \'\';\r\n  if(V8.Form.ZhiXingZQLB == \'简单模式\'){\r\n    // 校验执行周期\r\n  if(!V8.Form.ZhiXingZQ){\r\n    V8.Tips(\"请选择执行周期\", false);\r\n    V8.Result = false;\r\n    return;\r\n  }\r\n  // 依据执行周期生成cron表达式\r\n  if(V8.Form.ZhiXingZQ == \"每天\"){\r\n    if(!V8.Form.XiaoShi && String(V8.Form.XiaoShi) !== \'0\'){\r\n      V8.Tips(\"请输入小时\", false);\r\n      V8.Result = false;\r\n      return;\r\n    } \r\n    if(!V8.Form.FenZhong && String(V8.Form.FenZhong) !== \'0\'){\r\n      V8.Tips(\"请输入分钟\", false);\r\n      V8.Result = false;\r\n      return;\r\n    } \r\n    if(V8.Form.FenZhong > 59 || V8.Form.FenZhong < 0){\r\n      V8.Tips(\"分钟需要在0-59之间\", false);\r\n      V8.Result = false;\r\n      return;\r\n    }\r\n    if(V8.Form.XiaoShi > 23 || V8.Form.XiaoShi < 0){\r\n      V8.Tips(\"小时需要在0-23之间\", false);\r\n      V8.Result = false;\r\n      return;\r\n    }\r\n    cron = `0 ${V8.Form.FenZhong} ${V8.Form.XiaoShi} * * ?`;\r\n  }\r\n  else if(V8.Form.ZhiXingZQ == \"N天\"){\r\n    if(!V8.Form.XiaoShi && String(V8.Form.XiaoShi) !== \'0\'){\r\n      V8.Tips(\"请输入小时\", false);\r\n      V8.Result = false;\r\n      return;\r\n    } \r\n    if(!V8.Form.FenZhong && String(V8.Form.FenZhong) !== \'0\'){\r\n      V8.Tips(\"请输入分钟\", false);\r\n      V8.Result = false;\r\n      return;\r\n    } \r\n    if(!V8.Form.Tian && String(V8.Form.Tian) !== \'0\'){\r\n      V8.Tips(\"请输入日\", false);\r\n      V8.Result = false;\r\n      return;\r\n    } \r\n    if(V8.Form.FenZhong > 59 || V8.Form.FenZhong < 0){\r\n      V8.Tips(\"分钟需要在0-59之间\", false);\r\n      V8.Result = false;\r\n      return;\r\n    }\r\n    if(V8.Form.XiaoShi > 23 || V8.Form.XiaoShi < 0){\r\n      V8.Tips(\"小时需要在0-23之间\", false);\r\n      V8.Result = false;\r\n      return;\r\n    }\r\n    if(V8.Form.Tian <= 0){\r\n      V8.Tips(\"日需要大于等于1\", false);\r\n      V8.Result = false;\r\n      return;\r\n    }\r\n    cron = `0 ${V8.Form.FenZhong} ${V8.Form.XiaoShi} 1/${V8.Form.Tian} * ?`;\r\n  }\r\n  else if(V8.Form.ZhiXingZQ == \"每小时\"){\r\n    if(!V8.Form.FenZhong && String(V8.Form.FenZhong) !== \'0\'){\r\n      V8.Tips(\"请输入分钟\", false);\r\n      V8.Result = false;\r\n      return;\r\n    } \r\n    if(V8.Form.FenZhong > 59 || V8.Form.FenZhong < 0){\r\n      V8.Tips(\"分钟需要在0-59之间\", false);\r\n      V8.Result = false;\r\n      return;\r\n    }\r\n    cron = `0 ${V8.Form.FenZhong} * * * ?`;\r\n  }\r\n  else if(V8.Form.ZhiXingZQ == \"N小时\"){\r\n    if(!V8.Form.XiaoShi && String(V8.Form.XiaoShi) !== \'0\'){\r\n      V8.Tips(\"请输入小时\", false);\r\n      V8.Result = false;\r\n      return;\r\n    } \r\n    if(!V8.Form.FenZhong && String(V8.Form.FenZhong) !== \'0\'){\r\n      V8.Tips(\"请输入分钟\", false);\r\n      V8.Result = false;\r\n      return;\r\n    } \r\n    if(V8.Form.FenZhong > 59 || V8.Form.FenZhong < 0){\r\n      V8.Tips(\"分钟需要在0-59之间\", false);\r\n      V8.Result = false;\r\n      return;\r\n    }\r\n    if(V8.Form.XiaoShi > 23 || V8.Form.XiaoShi <= 0){\r\n      V8.Tips(\"小时需要在1-23之间\", false);\r\n      V8.Result = false;\r\n      return;\r\n    }\r\n    cron = `0 ${V8.Form.FenZhong} 0/${V8.Form.XiaoShi} * * ?`;\r\n  }\r\n  else if(V8.Form.ZhiXingZQ == \"N分钟\"){\r\n    if(!V8.Form.FenZhong && String(V8.Form.FenZhong) !== \'0\'){\r\n      V8.Tips(\"请输入分钟\", false);\r\n      V8.Result = false;\r\n      return;\r\n    } \r\n    if(V8.Form.FenZhong > 59 || V8.Form.FenZhong < 0){\r\n      V8.Tips(\"分钟需要在0-59之间\", false);\r\n      V8.Result = false;\r\n      return;\r\n    }\r\n    cron = `0 0/${V8.Form.FenZhong} * * * ?`;\r\n  }\r\n  else if(V8.Form.ZhiXingZQ == \"每星期\"){\r\n    if(!V8.Form.XiaoShi && String(V8.Form.XiaoShi) !== \'0\'){\r\n      V8.Tips(\"请输入小时\", false);\r\n      V8.Result = false;\r\n      return;\r\n    } \r\n    if(!V8.Form.FenZhong && String(V8.Form.FenZhong) !== \'0\'){\r\n      V8.Tips(\"请输入分钟\", false);\r\n      V8.Result = false;\r\n      return;\r\n    } \r\n    if(!V8.Form.Week && String(V8.Form.Week) !== \'0\'){\r\n      V8.Tips(\"请输入星期\", false);\r\n      V8.Result = false;\r\n      return;\r\n    } \r\n    if(V8.Form.FenZhong > 59 || V8.Form.FenZhong < 0){\r\n      V8.Tips(\"分钟需要在0-59之间\", false);\r\n      V8.Result = false;\r\n      return;\r\n    }\r\n    if(V8.Form.XiaoShi > 23 || V8.Form.XiaoShi < 0){\r\n      V8.Tips(\"小时需要在0-23之间\", false);\r\n      V8.Result = false;\r\n      return;\r\n    }\r\n    cron = `0 ${V8.Form.FenZhong} ${V8.Form.XiaoShi} ? * ${V8.Form.Week}`;\r\n  }\r\n  else if(V8.Form.ZhiXingZQ == \"每月\"){\r\n    if(!V8.Form.XiaoShi && String(V8.Form.XiaoShi) !== \'0\'){\r\n      V8.Tips(\"请输入小时\", false);\r\n      V8.Result = false;\r\n      return;\r\n    } \r\n    if(!V8.Form.FenZhong && String(V8.Form.FenZhong) !== \'0\'){\r\n      V8.Tips(\"请输入分钟\", false);\r\n      V8.Result = false;\r\n      return;\r\n    } \r\n    if(!V8.Form.Tian && String(V8.Form.Tian) !== \'0\'){\r\n      V8.Tips(\"请输入日\", false);\r\n      V8.Result = false;\r\n      return;\r\n    } \r\n    if(V8.Form.FenZhong > 59 || V8.Form.FenZhong < 0){\r\n      V8.Tips(\"分钟需要在0-59之间\", false);\r\n      V8.Result = false;\r\n      return;\r\n    }\r\n    if(V8.Form.XiaoShi > 23 || V8.Form.XiaoShi < 0){\r\n      V8.Tips(\"小时需要在0-23之间\", false);\r\n      V8.Result = false;\r\n      return;\r\n    }\r\n    if(V8.Form.Tian > 30 || V8.Form.Tian < 1){\r\n      V8.Tips(\"日需要在1-30之间\", false);\r\n      V8.Result = false;\r\n      return;\r\n    }\r\n    cron = `0 ${V8.Form.FenZhong} ${V8.Form.XiaoShi} ${V8.Form.Tian} * ?`;\r\n  }\r\n  else if(V8.Form.ZhiXingZQ == \"N秒\"){\r\n    if(!V8.Form.Miao && String(V8.Form.Miao) !== \'0\'){\r\n      V8.Tips(\"请输入秒\", false);\r\n      V8.Result = false;\r\n      return;\r\n    } \r\n    if(V8.Form.Miao > 59 || V8.Form.Miao <= 0){\r\n      V8.Tips(\"秒需要在1-59之间\", false);\r\n      V8.Result = false;\r\n      return;\r\n    }\r\n    cron = `0/${V8.Form.Miao} * * * * ?`;\r\n  }\r\n  V8.FormSet(\'CronExpression\', cron);\r\n  }\r\n  else{\r\n    cron = V8.Form.CronExpression;\r\n  }\r\n  \r\n  if(!cron){\r\n    V8.Tips(\"请选择执行周期\", false);\r\n    V8.Result = false;\r\n    return;\r\n  }\r\n}\r\nif(V8.FormSubmitAction == \'Insert\'){\r\n  V8.FormSet(\'Status\',\'创建中\');\r\n}', '', '[]', '', '', '', 0, 0, '{\"Insert\":\"\",\"Update\":\"\",\"Delete\":\"\",\"Select\":\"\"}', 0, 0, '', '', '', 0, '', NULL, 'if(V8.Form.JobType == \'1\' && !V8.Form.ApiEngineKey){\n  return { Code : 0, Msg : \'ApiEngineKey不能为空！\' };\n}\nvar currentTokenObj = V8.Method.GetCurrentToken() || {};\nvar apiBase = V8.SysConfig.ApiBase;//\'https://localhost:7266\';//\nvar para = {\n  Id : V8.Form.Id,\n  JobName : V8.Form.JobName,\n  DllName : V8.Form.DllName,\n  JobPath : V8.Form.JobPath,\n  JobDesc : V8.Form.JobDesc,\n  JobParam : V8.Form.JobParam,\n  CronDesc : V8.Form.CronDesc,\n  CronExpression : V8.Form.CronExpression,\n  JobType : V8.Form.JobType,\n  ApiEngineKey : V8.Form.ApiEngineKey\n}\nif(V8.FormSubmitAction == \'Insert\'){\n    var result = V8.Http.Post({ \n      Url : apiBase + \'/api/Job/AddJob\',\n      PostParam : para, \n      ParamType : \'form\',\n      Headers:{\n        authorization : \'Bearer \' + currentTokenObj.Token\n      }\n    });\n    result = JSON.parse(result);\n    if(result.DataAppend){\n      if(result.DataAppend.Status){\n        V8.Form.Status = result.DataAppend.Status;\n      }\n      if(result.DataAppend.LastTime){\n        V8.Form.LastTime = result.DataAppend.LastTime;\n      }\n      if(result.DataAppend.NextTime){\n        V8.Form.NextTime = result.DataAppend.NextTime;\n      }\n    }\n    if(result.Code != 1){ \n      return result;\n    }\n}\n \nelse if(V8.FormSubmitAction == \'Update\'){\n  var result = V8.Http.Post({ \n    Url : apiBase + \'/api/Job/UpdateJob\',\n    PostParam, para, \n    ParamType : \'form\',\n    Headers:{\n      authorization : \'Bearer \' + currentTokenObj.Token\n    }\n  });\n  result = JSON.parse(result);\n  if(result.Code != 1){ \n    return result;\n  }\n}\nelse if(V8.FormSubmitAction == \'Delete\'){\n  var result = V8.Http.Post({\n    Url : apiBase + \'/api/Job/DeleteJob\',\n    PostParam : para, \n    ParamType : \'form\',\n    Headers:{\n      authorization : \'Bearer \' + currentTokenObj.Token\n    }\n  });\n  result = JSON.parse(result);\n  if(result.Code != 1){ \n    return result;\n  }\n}\n', '', '', '', NULL, '', '', '', NULL, NULL, NULL);
INSERT INTO `diy_table` VALUES ('026be7b3-0634-416c-b462-789f0e8931b5', 'sys_user', '员工信息', '2021-09-06 12:45:24', '2026-04-07 17:11:58', '00000000-0000-0000-0000-000000000000', b'0', 'iTdos', 0, 0, '', 4, 0, '[]', '[{\"Name\":\"账号信息\",\"EnName\":\"none\",\"Display\":true,\"Sort\":1,\"Id\":\"01KGFAYTX0QP1F5Q1Z88X5RMVF\",\"Icon\":\"ChatLineSquare\"},{\"Name\":\"更多信息\",\"Display\":true,\"Id\":\"01KGFAYTX1S0KNYX09JGX71TWH\",\"Icon\":\"Burger\"},{\"Name\":\"个人设置\",\"Display\":true,\"Id\":\"01KGFAYTX109WCP98XJZP395VY\",\"Icon\":\"Setting\"}]', 'top', '[]', '', '', '', 'Drawer', '70%', 'top', '', '//角色存储格式：[id1,id2,id3]。 --2026-03-30 Anderson：格式应该是[{Id:\'\',Name:\'\',Level:0}]\nif(V8.Form.RoleIds){\n  //正常在下拉复选框中显示\n  try{\n    var roleIdsValue = [];\n    for(var i = 0 ; i < V8.Form.RoleIds.length; i++){\n      if(typeof(V8.Form.RoleIds[i]) == \'string\'){\n        roleIdsValue.push({ Id : V8.Form.RoleIds[i] });\n      }else{\n        roleIdsValue.push(V8.Form.RoleIds[i]);\n      }\n    }\n    V8.FormSet(\'RoleIds\', roleIdsValue);\n  }catch(e){\n    V8.FormSet(\'RoleIds\', []);\n  }\n}\n\nwindow.ZZMMChange = function(zzmm){\n  V8.FieldSet(\'ZZMMJiaruSJ\', \'Visible\', false);\n  V8.FieldSet(\'ZZMMJiaruDD\', \'Visible\', false);\n  V8.FieldSet(\'ZZMMJieshaoR\', \'Visible\', false);\n  V8.FieldSet(\'ZZMMDanrenGZW\', \'Visible\', false);\n  if(zzmm && zzmm != \'群众\'){\n    V8.FieldSet(\'ZZMMJiaruSJ\', \'Visible\', true);\n    V8.FieldSet(\'ZZMMJiaruDD\', \'Visible\', true);\n    V8.FieldSet(\'ZZMMJieshaoR\', \'Visible\', true);\n    V8.FieldSet(\'ZZMMDanrenGZW\', \'Visible\', true);\n  }\n}\nwindow.ZZMMChange(V8.Form.ZhengzhiMM);', '// //更新用户信息缓存\n// debugger;\n// if(V8.FormOutAction == \'Update\'){\n//   V8.Post(\'/api/SysUser/RefreshLoginUser\', {\n//     userId : V8.Form.Id,\n//     osClient : V8.OsClient\n//   }, function(result){\n//     if(result.Code == 1){\n//       V8.Tips(\'更新用户缓存信息成功！\');\n//     }else{\n//       V8.Tips(\'更新用户缓存信息失败：\' + result.Msg, false);\n//     }\n//   })\n// }\n', '/*\nif(V8.Form.RoleIds){\n  var saveRoleIds = [];\n  for(var i = 0; i < V8.Form.RoleIds.length; i++){\n    saveRoleIds.push(V8.Form.RoleIds[i].Id);\n  }\n  V8.FormSet(\'RoleIds\', saveRoleIds);\n}\n*/', '', '[]', '', '', '', 0, 0, '{\"Insert\":\"\",\"Update\":\"\",\"Delete\":\"\",\"Select\":\"\"}', 0, 0, '', '', '', 0, '//密码加密\nvar decodePwd = \'\';\ntry{\n  //尝试解密\n  decodeP', NULL, 'if(V8.Form.Pwd){\n  //密码加密\n  var decodePwd = \'\';\n  try{\n    //尝试解密\n    decodePwd = V8.EncryptHelper.DESDecode(V8.Form.Pwd);\n  }catch(e){\n    //如果解密失败，就是明文\n    decodePwd = V8.Form.Pwd;\n  }\n  //DES加密\n  V8.Form.Pwd = V8.EncryptHelper.DESEncode(decodePwd);\n}', '//实际这里更新用户信息缓存是没有用的，因为事务还未提交 ，用户信息并未更改成功！\n//V8.Method.RefreshLoginUser(V8.Form.Id, V8.OsClient)', '', '', 0, '', '', '', 0, 0, '[]');
