INSERT INTO `diy_table` VALUES ('1d28e502-70ea-4a2b-9793-699b3f42234e', 'sys_menu', '模块引擎', '2021-09-05 19:14:16', '2026-04-07 01:10:29', '00000000-0000-0000-0000-000000000000', b'0', 'iTdos', 1, 0, '', 3, 0, '[]', '[{\"Name\":\"模块信息\",\"EnName\":\"none\",\"Display\":true,\"Sort\":1,\"Icon\":\"fas fa-align-right\",\"Id\":\"01KGA478B0NB99YQN5ZMY6S85W\"},{\"Sort\":2,\"Name\":\"数据源\",\"Icon\":\"fas fa-database\",\"Display\":true,\"Id\":\"01KGA478B1JWN8QQWKMCGTMQD9\"},{\"Sort\":3,\"Name\":\"替换\",\"Icon\":\"fab fa-accessible-icon\",\"Display\":true,\"Id\":\"01KGA478B1CH5KJKZKWMGGPH4C\"},{\"Sort\":4,\"Name\":\"按钮\",\"Icon\":\"fab fa-btc\",\"Display\":true,\"Id\":\"01KGA478B18MCNQRBDWGX548DE\"},{\"Sort\":5,\"Name\":\"更多配置\",\"Id\":\"01KGA4C04FACS3PHGCD679KT86\",\"Icon\":\"Basketball\",\"Display\":true},{\"Id\":\"01KM3RY888PNG4PR12AAS2R5AP\",\"Name\":\"卡片数据\",\"Icon\":\"Iphone\",\"Display\":true}]', '', '[]', '', '', '', 'Drawer', '80%', 'top', '', 'if (V8.FormMode == \'Add\') {\n  V8.FormSet(\'Display\', true);\n}\nwindow.OpenTypeChange = function (v8) {\n  v8.FieldSet(\'DiyTableId\', \'Visible\', v8.Form.OpenType.Key == \'Diy\');//选择表单\n  v8.FieldSet(\'ComponentName\', \'Visible\', v8.Form.OpenType.Key == \'Diy\' || v8.Form.OpenType.Key == \'Report\');//界面模板\n\n  if (v8.Form.OpenType.Key == \'Diy\') {\n    v8.FieldSet(\'ComponentPath\', \'Visible\', true);\n    v8.FieldSet(\'ReportName\', \'Visible\', false);\n  } else if (v8.Form.OpenType.Key == \'Component\') {//定制\n    v8.FieldSet(\'ComponentPath\', \'Visible\', true);\n    v8.FieldSet(\'ReportName\', \'Visible\', false);\n  } else if (v8.Form.OpenType.Key == \'Report\') {\n    v8.FieldSet(\'ComponentPath\', \'Visible\', true);\n    v8.FieldSet(\'ReportName\', \'Visible\', true);\n  } else if (v8.Form.OpenType.Key == \'Iframe\' || v8.Form.OpenType.Key == \'SecondMenu\') {\n    v8.FieldSet(\'ComponentPath\', \'Visible\', false);\n    v8.FieldSet(\'ReportName\', \'Visible\', false);\n  } else if (v8.Form.OpenType.Key == \'PageEngine\') {\n    v8.FieldSet(\'ComponentPath\', \'Visible\', true);\n    v8.FormSet(\'ComponentPath\', \'/page-engine/renderer\');\n  } else {\n    v8.FieldSet(\'ComponentPath\', \'Visible\', false);\n    v8.FieldSet(\'ReportName\', \'Visible\', false);\n  }\n\n  v8.FieldSet(\'SecondMenuWidth\', \'Visible\', v8.Form.OpenType.Key == \'SecondMenu\');\n  v8.FieldSet(\'SecondMenuHeight\', \'Visible\', v8.Form.OpenType.Key == \'SecondMenu\');\n  v8.FieldSet(\'SecondMenuLineCount\', \'Visible\', v8.Form.OpenType.Key == \'SecondMenu\');\n  v8.FieldSet(\'SecondMenuColumn\', \'Visible\', v8.Form.OpenType.Key == \'SecondMenu\');\n  v8.FieldSet(\'SecondMenuRow\', \'Visible\', v8.Form.OpenType.Key == \'SecondMenu\');\n\n}\nwindow.OpenTypeChange(V8)\n\nwindow.DisplayChange = function (v8) {\n  if (v8.Form.DisplayMac) {\n    v8.FieldSet(\'SizeWidthMac\', \'Visible\', true);\n    v8.FieldSet(\'SizeHeightMac\', \'Visible\', true);\n    v8.FieldSet(\'MacScreenIndex\', \'Visible\', true);\n  } else {\n    v8.FieldSet(\'SizeWidthMac\', \'Visible\', false);\n    v8.FieldSet(\'SizeHeightMac\', \'Visible\', false);\n    v8.FieldSet(\'MacScreenIndex\', \'Visible\', false);\n  }\n}\nwindow.DisplayChange(V8);\nV8.FieldSet(\"InTableEditFields\", \"Visible\", V8.Form.InTableEdit ? 1 : 0)\n', '', '', '', '[]', '', '', '', 0, 0, '{\"Insert\":\"\",\"Update\":\"\",\"Delete\":\"\",\"Select\":\"\"}', 0, 0, 'var base64ToStringArr = [\"SqlWhere\", \"SqlJoin\", \"MoreBtns\", \"FormBtns\", \"ExportMoreBtns\", \"BatchSelectMoreBtns\", \"PageBtns\", \"PageTabs\"];\nbase64ToStringArr.forEach(item => {\n  if(V8.Form[item]){\n    V8.Form[item] = V8.Base64.Base64ToString(V8.Form[item]);\n  }\n})', 'ParentId', 'ParentIds', 1, 'HasChild', NULL, 'var base64ToStringArr = [\"SqlWhere\", \"SqlJoin\", \"MoreBtns\", \"FormBtns\", \"ExportMoreBtns\", \"BatchSelectMoreBtns\", \"PageBtns\", \"PageTabs\"];\nbase64ToStringArr.forEach(item => {\n  if(V8.Form[item]){\n    V8.Form[item] = V8.Base64.Base64ToString(V8.Form[item]);\n  }\n})\n//写当前数据、上级数据是否有子集\nvar currentHasChild = V8.FormEngine.GetTableData(\"sys_menu\", {\n  _SelectFields: [\'Id\'],\n  _Where: [[\"ParentId\", \"=\", V8.Form.Id]]\n});\nV8.Form.HasChild = (currentHasChild.Code == 1 && currentHasChild.Data.length > 0) ? 1 : 0;\n\nif (V8.Form.ParentId && V8.Form.ParentId != \'00000000-0000-0000-0000-000000000000\' && V8.Form.ParentId != \'00000000000000000000000000\') { \n  V8.FormEngine.UptFormData(\"sys_menu\", {\n    Id: V8.Form.ParentId,\n    HasChild : 1\n  });\n}\n', '//如果是新增，给admin管理员默认权限\nif(V8.FormSubmitAction == \'Insert\'){\n  var addResult = V8.FormEngine.AddFormData({\n    FormEngineKey : \'sys_rolelimit\',\n    _RowModel:{\n      RoleId : \'5db47859-35a3-411a-a1f7-99482e057d24\',\n      FkId : V8.Form.Id,\n      Type : \'Menu\',\n      CreateTime : V8.Action.GetDateTimeNow(),\n      Permission : \'[\\\"Add\\\",\\\"Edit\\\",\\\"Del\\\",\\\"Export\\\",\\\"Import\\\"]\'\n    }\n  });\n  if(addResult.Code == 1){\n    V8.Method.RefreshLoginUser(\'c74d669c-a3d4-11e5-b60d-b870f43edd03\', V8.OsClient)\n  }else{\n    //V8.Result = addResult;\n  }\n}\n//判断上下级HasChild\n//20245-01-08发现加了以下代码会导致sys_menu表的SearchFieldIds字段里面的等值Equal保存不上，暂时未找到原因，可能是因为不能在sys——menu事件中再去修改sys_menu\n/*\nif(V8.Form.ParentId){\n  V8.FormEngine.UptFormData(\'sys_menu\', {\n    HasChild : 1,\n    Id : V8.Form.ParentId\n  });\n}\n*/\nV8.Cache.Remove(`Microi:${V8.OsClient}:FormData:sys_menu:${V8.Form.Id.toLowerCase()}`);\nif(V8.Form.ModuleEngineKey){\n  V8.Cache.Remove(`Microi:${V8.OsClient}:FormData:sys_menu:${V8.Form.ModuleEngineKey.toLowerCase()}`);\n}', '', '', 0, '', '', '', 0, 0, '[]');
