INSERT INTO `diy_table` VALUES ('39bc4abe-98ee-46a7-b9d1-a7d649691193', 'diy_table', 'Diy_Table', '2022-08-08 21:32:48', '2026-04-17 03:58:53', '', b'0', 'iTdos', 0, 0, '', 2, 0, '[]', '[{\"Name\":\"表单信息\",\"EnName\":\"none\",\"Display\":true,\"Sort\":1,\"Id\":\"06399e92-a775-4ae8-9a55-9a755c1fe8fb\",\"Icon\":\"fas fa-align-right\"},{\"Sort\":2,\"Name\":\"事件\",\"Id\":\"84fb2e1e-111a-4e44-b76b-65a2adf8a0d5\",\"Icon\":\"fas fa-code\",\"Display\":true}]', '', '[]', '', '', '', 'Drawer', '', 'top', '', 'V8.FieldSet(\"TreeParentField\", \"Visible\", V8.Form.IsTree ? true : false);\r\nV8.FieldSet(\"TreeParentFields\", \"Visible\", V8.Form.IsTree ? true : false);\r\nV8.FieldSet(\"TreeHasChildren\", \"Visible\", V8.Form.IsTree ? true : false);\r\nV8.FieldSet(\"TreeLazy\", \"Visible\", V8.Form.IsTree ? true : false);', '', '', '', '[]', '', '', '', 0, 0, '{\"Insert\":\"\",\"Update\":\"\",\"Delete\":\"\",\"Select\":\"\"}', 0, 0, '', 'ParentId', 'ParentIds', 0, '', NULL, '', 'if(V8.FormSubmitAction == \'Insert\' && !V8.Form.ReportId){\n  var addTableResult = V8.FormEngine.AddTable({\n    Name : V8.Form.Name,\n    Description: V8.Form.Description,\n    DataBaseId: V8.Form.DataBaseId,\n    DataBaseName: V8.Form.DataBaseName,\n    _OnlyCreateTable : true,\n  });\n  if(addTableResult.Code != 1){\n    V8.Result = addTableResult;\n  }\n}\nV8.Cache.Remove(`Microi:${V8.OsClient}:FormData:diy_table:${V8.Form.Id.toLowerCase()}`);\nif(V8.Form.Name){\n  V8.Cache.Remove(`Microi:${V8.OsClient}:FormData:diy_table:${V8.Form.Name.toLowerCase()}`);\n}', '', '', NULL, '', '', '', NULL, NULL, '[]');
INSERT INTO `diy_table` VALUES ('3c55fc03-e9d6-4b3e-953d-494e6e5ffcf3', 'Rpt_Report', '报表引擎', '2022-07-10 20:18:54', '2026-03-25 16:57:02', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', b'0', '', 0, 0, '', 2, 0, '[]', '[{\"Name\":\"报表配置\",\"EnName\":\"none\",\"Display\":true,\"Sort\":1,\"Icon\":\"fas fa-align-right\",\"Id\":\"01KKPKB16X2JXY1B1P7JT6TAZ1\"},{\"Sort\":\"2\",\"Name\":\"字段配置\",\"Icon\":\"fab fa-amilia\",\"Display\":true,\"Id\":\"01KKPKB16YNZMSPFSWNWR88YS0\"}]', '', '[]', '', '', '', 'Drawer', '70%', 'top', '', 'window.LoadDataSourceTable = async function(dataSourceId){\n  if(V8.Form.DataSourceId || dataSourceId){\n    V8.Extend.LoadJoinForm(\'Sys_DataSource\', \'DataSourceForm\', V8.Form.DataSourceId || dataSourceId, V8.FormMode == \'View\' ? \'View\' : \'Edit\', V8);//V8.FormMode\n    //V8.FieldSet(\'DataSourceForm\', \'Visible\', true);\n  }else{\n    var newDataSourceId = await V8.NewServerGuid();\n    V8.Extend.LoadJoinForm(\'Sys_DataSource\', \'DataSourceForm\', newDataSourceId, \'Add\', V8);\n    //V8.FieldSet(\'DataSourceForm\', \'Visible\', false);\n  }\n}\nwindow.LoadDataSourceTable();\nif(!V8.Form.FkTableId){\n  V8.FieldSet(\'RptSelectTable\', \'Visible\', false);\n  V8.FieldSet(\'RptLoadTableField\', \'Visible\', false);\n  V8.FieldSet(\'RptSelectFieldList\', \'Visible\', false);\n  V8.FieldSet(\'JiazaiXZZD\', \'Visible\', false);\n  V8.FieldSet(\'RptFieldList\', \'Visible\', false);\n}else{\n  V8.FieldSet(\'RptSelectTable\', \'Visible\', true);\n  V8.FieldSet(\'RptLoadTableField\', \'Visible\', true);\n  V8.FieldSet(\'RptSelectFieldList\', \'Visible\', true);\n  V8.FieldSet(\'JiazaiXZZD\', \'Visible\', true);\n  V8.FieldSet(\'RptFieldList\', \'Visible\', true);\n}', '', '', '', '[]', '', '', '', 0, 0, '{\"Insert\":\"\",\"Update\":\"\",\"Delete\":\"\",\"Select\":\"\"}', 0, 0, '', '', '', 0, '', NULL, '//判断diy_table是否存在ReportId这条数据\nvar diyTableResult = V8.FormEngine.GetFormData({\n  FormEngineKey : \'diy_table\',\n  _Where:[{ Name : \'ReportId\', Value : V8.Form.Id, Type : \'=\' }]\n});\nvar _rowModel = {\n  Name : V8.Form.RptKey,\n  Description : V8.Form.RptName,\n  ReportId : V8.Form.Id,\n  ReportName : V8.Form.RptName,\n  DataSourceId : V8.Form.DataSourceId\n};\nif(diyTableResult.Code == 2){//新增\n  var addDiyTableResult = V8.FormEngine.AddFormData({\n    FormEngineKey : \'diy_table\',\n    _RowModel : _rowModel\n  });\n  if(addDiyTableResult.Code == 1){\n    V8.Form.FkTableId = addDiyTableResult.Data.Id;\n  }\n}else if(diyTableResult.Code == 1){//修改\n  var uptDiyTableResult = V8.FormEngine.UptFormData({\n    FormEngineKey : \'diy_table\',\n    Id : diyTableResult.Data.Id,\n    _RowModel : _rowModel\n  });\n}\nif(diyTableResult.Code == 1 && !V8.Form.FkTableId){\n  V8.Form.FkTableId = diyTableResult.Data.Id;\n}', '', '', '', NULL, '', '', '', NULL, NULL, '[]');
