INSERT INTO `diy_table` VALUES ('411ecfa3-67a7-47ee-a9dd-087aad2ff84c', 'diy_queue_receive', '消息队列管理', '2023-10-13 13:18:01', '2026-03-21 03:20:17', '84ed01b8-ca38-4916-9673-fa869b3817ab', b'0', 'iTdos', 0, 0, '', 2, 0, '[]', '[{\"Name\":\"none\",\"EnName\":\"none\",\"Display\":true,\"Sort\":1,\"Id\":\"ee43f090-e7c9-4cf7-ade6-4596dfce6c0c\"}]', '', '[]', '', '', '', 'Drawer', '70%', '', '', '\r\nif(V8.FormMode == \'Add\'){\r\n  V8.FormSet(\'Type\', \'1\');\r\n  V8.FieldSet(\'MethodName\', \'Visible\', false);\r\n  V8.FieldSet(\'DllName\', \'Visible\', false);\r\n  V8.FieldSet(\'ClassName\', \'Visible\', false);\r\n  V8.FieldSet(\'DuilieRZ\', \'Visible\', false);\r\n  V8.FieldSet(\'RizhiXX\', \'Visible\', false);\r\n  V8.FieldSet(\'Count\', \'Visible\', false);\r\n}\r\nif(V8.FormMode == \'Edit\'){\r\n  V8.FieldSet(\'QueueName\', \'Readonly\', true);\r\n  V8.FieldSet(\'DllName\', \'Readonly\', true);\r\n  V8.FieldSet(\'ClassName\', \'Readonly\', true);\r\n  V8.FieldSet(\'MethodName\', \'Readonly\', true);\r\n  V8.FieldSet(\'Type\', \'Readonly\', true);\r\n  V8.FieldSet(\'FailToReject\', \'Readonly\', true);\r\n  // V8.FieldSet(\'ApiEngineKey\', \'Readonly\', true);\r\n  V8.FieldSet(\'Count\', \'Readonly\', true);\r\n  V8.FieldSet(\'DuilieRZ\', \'Visible\', false);\r\n  V8.FieldSet(\'RizhiXX\', \'Visible\', false);\r\n  if(V8.Form.Type == \"1\"){\r\n    V8.FieldSet(\'MethodName\', \'Visible\', false);\r\n    V8.FieldSet(\'DllName\', \'Visible\', false);\r\n    V8.FieldSet(\'ClassName\', \'Visible\', false);\r\n  }\r\n  else {\r\n    V8.FieldSet(\'ApiEngineKey\', \'Visible\', false);\r\n  }\r\n  if(V8.Form.FailToReject == \'是\'){\r\n    V8.FieldSet(\'Count\', \'Visible\', true);\r\n  }\r\n  else{\r\n    V8.FieldSet(\'Count\', \'Visible\', false);\r\n  }\r\n}\r\nif(V8.FormMode == \'View\'){\r\n  if(V8.Form.Type == \"1\"){\r\n    V8.FieldSet(\'MethodName\', \'Visible\', false);\r\n    V8.FieldSet(\'DllName\', \'Visible\', false);\r\n    V8.FieldSet(\'ClassName\', \'Visible\', false);\r\n  }\r\n  else {\r\n    V8.FieldSet(\'ApiEngineKey\', \'Visible\', false);\r\n  }\r\n  if(V8.Form.FailToReject == \'是\'){\r\n    V8.FieldSet(\'Count\', \'Visible\', true);\r\n  }\r\n  else{\r\n    V8.FieldSet(\'Count\', \'Visible\', false);\r\n  }\r\n}', '', 'if(V8.FormSubmitAction == \'Insert\'){\r\n  if(!V8.Form.Type || !V8.Form.QueueName || !V8.Form.FailToReject){\r\n    V8.Tips(\"接口类型、队列名称、消息重回队列不能为空\", false);\r\n    V8.Result = false;\r\n    return;\r\n  }\r\n  if(V8.Form.Type == \"1\"){\r\n    if(!V8.Form.ApiEngineKey){\r\n      V8.Tips(\"ApiEngineKey不能为空\", false);\r\n      V8.Result = false;\r\n      return;\r\n    }\r\n  }\r\n  else {\r\n    if(!V8.Form.DllName || !V8.Form.ClassName || !V8.Form.MethodName){\r\n      V8.Tips(\"程序集名称、类名称、方法名称不能为空\", false);\r\n      V8.Result = false;\r\n      return;\r\n    }\r\n  }\r\n  var regStr = /[a-zA-Z]/g;\r\n  if(!regStr.test(V8.Form.QueueName)){\r\n    V8.Tips(\"队列名称只能输入英文\", false);\r\n    V8.Result = false;\r\n    return;\r\n  }\r\n  if(V8.Form.FailToReject == \'是\'){\r\n    if(!V8.Form.Count || V8.Form.Count > 10 || V8.Form.Count <= 0 ){\r\n      V8.Tips(\"重回队列次数不能为空且次数必须大于0小于10\", false);\r\n      V8.Result = false;\r\n      return;\r\n    }\r\n  }\r\n}\r\n\r\n', '', '[]', '', '', '', 0, 0, '{\"Insert\":\"\",\"Update\":\"\",\"Delete\":\"\",\"Select\":\"\"}', 0, 0, '', '', '', 0, '', NULL, '', '', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
