INSERT INTO `diy_table` VALUES ('c8570fa6-c10f-4014-8cb4-4b046e7ba69c', 'Sys_Config', '系统设置', '2021-08-23 15:19:04', '2026-04-19 23:43:18', '00000000-0000-0000-0000-000000000000', b'0', 'iTdos', 0, 0, '', 4, 0, '[]', '[{\"Name\":\"系统信息\",\"EnName\":\"none\",\"Sort\":1,\"Display\":true,\"Icon\":\"fas fa-info-circle\",\"Id\":\"39cde544-7a39-483d-8502-d167be5699ec\"},{\"Sort\":2,\"Name\":\"界面风格\",\"Display\":true,\"Icon\":\"fas fa-border-style\",\"Id\":\"f7e10da1-0b96-4624-90ea-07c7e6991b74\"},{\"Sort\":3,\"Name\":\"开发配置\",\"Display\":true,\"Icon\":\"fab fa-dev\",\"Id\":\"cfa27918-6245-4893-a77b-887c1a1e37f6\"},{\"Sort\":4,\"Name\":\"密码强度\",\"Icon\":\"fas fa-user-secret\",\"Display\":true,\"Id\":\"2c3dbe05-c684-4c99-9cf1-bf6c2f080904\"},{\"Sort\":5,\"Name\":\"移动端配置\",\"Icon\":\"fas fa-mobile-alt\",\"Display\":true,\"Id\":\"4409605d-86ff-4202-bb47-7f7f0e3be773\"}]', '', '[]', '', '', '', 'Drawer', '70%', 'top', '', '//PwdShortestLength\n//PwdContainNumber\n//PwdContainSpecial\n//PwdContainUpperLower\n//PwdAllowErrorCount\n//PwdErrorLockTime\n//PwdAllowMultiLogin\n\nif(V8.IsNull(V8.Form.PwdShortestLength) \n   || V8.Form.PwdShortestLength.length  == 0){\n	V8.FormSet(\'PwdShortestLength\', 6);\n}\nif(V8.IsNull(V8.Form.PwdAllowMultiLogin)){\n	V8.FormSet(\'PwdAllowMultiLogin\', true);\n}\n\nif(V8.IsNull(V8.Form.PwdEncode)){\n	V8.FormSet(\'PwdEncode\', \'DES\');\n}\n\nV8.FieldSet(\'PwdV8\', \'Visible\', V8.Form.PwdEncode == \'V8\');', '', '', '', '[]', '', '', '', 0, 0, '{\"Insert\":\"\",\"Update\":\"\",\"Delete\":\"\",\"Select\":\"\"}', 1, 0, '', 'ParentId', 'ParentIds', 0, '', NULL, '//检查如果是不启用当前设置、或是删除当前设置，则要判断若不存在其它设置项，中断提交\nif (!V8.Form.IsEnable || V8.FormSubmitAction == \'Delete\') { \n  //判断是否还存在其它系统设置\n  var list = V8.FormEngine.GetTableData(\'sys_config\', {\n    _Where: [\n      [\'IsEnable\', \'=\', 1],\n      [\'Id\', \'!=\', V8.Form.Id],\n    ]\n  });\n  if (list.Code != 1 || list.Data.length == 0) { \n    return { Code : 0, Msg : \'提交失败，系统设置至少保留 1 条已启用数据！\' };\n  }\n}', 'V8.Cache.Remove(`Microi:${V8.OsClient}:SysConfig`);', '', '', NULL, '', '', '', NULL, NULL, '[]');
