INSERT INTO `diy_table` VALUES ('cf389aef-72cc-4980-9c5b-143123561ac0', 'sys_apiengine', '接口引擎', '2022-07-19 20:39:12', '2026-03-21 03:20:17', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', b'0', 'iTdos', 0, 0, '', 3, 0, '[]', '[{\"Name\":\"引擎配置\",\"EnName\":\"none\",\"Display\":true,\"Sort\":1,\"Id\":\"1d7b8c6e-6c1b-47b8-bf6f-168831b83f28\",\"Icon\":\"fas fa-fire\"},{\"Sort\":3,\"Name\":\"详细配置\",\"Id\":\"01KFFN4HBY49TNPBX3K0KKHHG3\",\"Icon\":\"fas fa-cogs\",\"Display\":true},{\"Name\":\"运行测试\",\"Display\":true,\"Id\":\"e4c00d48-6af1-42e8-b2c6-603672295f19\",\"Sort\":5,\"Icon\":\"fab fa-dev\"}]', '', '[]', '', '', '', 'Drawer', '70%', 'top', '', 'if(V8.Form.Lock){\n  V8.FieldSet(\'LockKey\', \'Visible\', true);\n}else{\n  V8.FieldSet(\'LockKey\', \'Visible\', false);\n}\nvar default0 = {\n  \'Timeout\' : 600, \n  \'MaxStatements\' : 100000000, \n  \'LimitMemory\' : 2048, //2GB\n  \'LimitRecursion\' : 10000\n};\nfor(let key in default0){\n  if(V8.Form[key] <= 0){\n    V8.FormSet(key, default0[key]);\n  }\n}', '', '', '', '[]', '', '', '', 0, 0, '{\"Insert\":\"\",\"Update\":\"\",\"Delete\":\"\",\"Select\":\"\"}', 0, 0, '', '', '', 0, '', NULL, 'if(V8.Form.TestResult && V8.Form.TestResult.length > 2000){\n  V8.Form.TestResult = \'由于执行[接口测试]后得到的结果太大，系统已默认将[测试结果(TestResult)]字段重置为此说明！\'\n  // return { Code : 0, Msg : \'执行[接口测试]后得到的结果太大，请清空[测试结果]后再保存！\' };\n}\n\nif(V8.Form.TestParam && V8.Form.TestParam.length > 2000){\n  V8.Form.TestParam = \'\'\n}', 'var cacheKey = `Microi:${V8.OsClient}:FormData:sys_apiengine:${V8.Form.ApiEngineKey.toLowerCase()}`;\nvar cacheKeyId = `Microi:${V8.OsClient}:FormData:sys_apiengine:${V8.Form.Id.toLowerCase()}`;\nvar formModel = V8.Form;\nV8.Cache.Set(cacheKey, formModel);\nV8.Cache.Set(cacheKeyId, formModel);\n\nif(V8.OldForm && V8.OldForm.ApiEngineKey && V8.OldForm.ApiEngineKey != V8.Form.ApiEngineKey){\n  V8.Cache.Remove(`Microi:${V8.OsClient}:FormData:sys_apiengine:${V8.OldForm.ApiEngineKey.toLowerCase()}`);\n}\n\nif(V8.Form.ApiAddress){\n  var apiPath = V8.Form.ApiAddress.toLowerCase();\n  var cacheKey2 = `Microi:${V8.OsClient}:FormData:sys_apiengine:${apiPath}`;\n  V8.Cache.Set(cacheKey2, formModel);\n  if(V8.OldForm && V8.OldForm.ApiAddress && V8.OldForm.ApiAddress != V8.Form.ApiAddress){\n    V8.Cache.Remove(`Microi:${V8.OsClient}:FormData:sys_apiengine:${V8.OldForm.ApiAddress.toLowerCase()}`);\n  }\n}\n', '', '', NULL, '', '', '', NULL, NULL, '[]');
