INSERT INTO `diy_table` VALUES ('f4716ef1-59ab-4aa3-9a53-12bb402dd0d4', 'sys_datasource', '数据源引擎', '2022-05-30 15:30:34', '2026-03-21 03:20:17', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', b'0', '', 0, 0, '', 2, 0, '[]', '[{\"Name\":\"数据源配置\",\"EnName\":\"none\",\"Display\":true,\"Sort\":1},{\"Sort\":\"2\",\"Name\":\"运行测试\",\"Display\":true}]', 'top', '[]', '', '', '', 'Drawer', '70%', 'top', '', 'window.DataSourceVisible = function(dsType){\n  V8.FieldSet(\'JsonDataSource\', \'Visible\', false);\n  V8.FieldSet(\'V8DataSource\', \'Visible\', false);\n  V8.FieldSet(\'SqlDataSource\', \'Visible\', false);\n  if(dsType == \'JSON\'){\n    V8.FieldSet(\'JsonDataSource\', \'Visible\', true);\n  }\n  else if(dsType == \'V8\'){\n    V8.FieldSet(\'V8DataSource\', \'Visible\', true);\n  }\n  else if(dsType == \'SQL\'){\n    V8.FieldSet(\'SqlDataSource\', \'Visible\', true);\n  }\n}\nwindow.DataSourceVisible(V8.Form.DataSourceType);', '', '', '', '[]', '', '', '', 0, 0, '{\"Insert\":\"\",\"Update\":\"\",\"Delete\":\"\",\"Select\":\"\"}', 0, 0, '', '', '', 0, '', NULL, '', '', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
