INSERT INTO `diy_table` VALUES ('f96f00b8-8ced-4100-a398-a6254b518794', 'microi_database', '数据库管理', '2023-07-20 17:43:52', '2026-03-21 03:20:17', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', b'0', '', 0, 0, '', 2, 0, '[]', '[{\"Name\":\"none\",\"EnName\":\"none\",\"Display\":true,\"Sort\":1}]', '', '[]', '', '', '', 'Drawer', '60%', 'top', '', 'window.GetNotDiyTable = function(){\n  //获取所有非DIY表\n  V8.Post(\'/api/diytable/getNotDiyTable\', {\n    DataBaseId : V8.Form.Id\n  }, function(result){\n    if(result.Code != 1){\n      V8.Tips(\'获取所有非DIY表失败：\' + result.Msg, false);\n      return;\n    }\n    var data = [];\n    result.Data.forEach(item => {\n      data.push({ TableName : item, Id : item });\n    });\n    \n    V8.FieldSet(\'NotDiyTable\', \'Data\', data);\n  });\n}\nif(V8.FormMode == \'Edit\'){\n  V8.FieldSet(\'NotDiyTable\', \'Visible\', true);\n  V8.FieldSet(\'BtnLoadNotDiyTable\', \'Visible\', true);\n  window.GetNotDiyTable();\n}', '', '', '', '[]', '', '', '', 0, 0, '{\"Insert\":\"\",\"Update\":\"\",\"Delete\":\"\",\"Select\":\"\"}', 0, 0, '', '', '', 0, '', NULL, '', '', '', '', NULL, NULL, NULL, NULL, NULL, NULL, NULL);
