INSERT INTO `rpt_type` VALUES ('95b4eb9a-1799-453e-85a9-62e2fcc51c9a', '2022-07-10 23:00:55', NULL, 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '饼图', 'Pie');
INSERT INTO `sys_apiengine` VALUES ('005713be-69a1-4a0d-8663-601cd1e4c04a', '2024-11-25 11:32:55', '2026-04-19 05:01:08', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '[系统]复制表', 'copy_table', b'1', '[]', 'if (!V8.Param.TableId) {\n  return { Code: 0, Msg: \'参数错误！\' };\n}\n//判断新表名是否已存在\nif (V8.Param.TableName) {\n  var newTableModelResult = V8.FormEngine.GetFormData(\'Diy_Table\', {\n    _Where: [\n      [\'Name\', \'=\', V8.Param.TableName]\n    ]\n  });\n  if (newTableModelResult.Code == 1 && newTableModelResult.Data) {\n    return { Code: 0, Msg: `新的表名【${V8.Param.TableName}】已存在！` };\n  }\n}\n//取原表\nvar oldTableModelResult = V8.FormEngine.GetFormData(\'Diy_Table\', {\n  Id: V8.Param.TableId\n});\nif (oldTableModelResult.Code != 1) {\n  return oldTableModelResult;\n}\nvar oldTableModel = oldTableModelResult.Data;\n//取原表大概存在多少个复制体\nvar oldTableListResult = V8.FormEngine.GetTableData(\'Diy_Table\', {\n  _Where: [\n    [\'Name\', \'StartLike\', oldTableModel.Name]\n  ]\n});\nif (oldTableListResult.Code != 1) {\n  return oldTableListResult;\n}\nvar oldTableNewCount = oldTableListResult.Data.length + 1;\n\n//取原表所有字段\nvar oldTableFieldListResult = V8.FormEngine.GetTableData(\'Diy_Field\', {\n  _Where: [\n    [\'TableId\', \'=\', V8.Param.TableId]\n  ],\n});\nif (oldTableFieldListResult.Code != 1) {\n  return oldTableFieldListResult;\n}\nvar oldTableFieldList = oldTableFieldListResult.Data;\n//插入新表\nvar newTableModel = { ...oldTableModel };\n//定义新的TableId，后面插入字段需要用到\nvar newTableId = V8.Method.NewUlid();\nnewTableModel.Id = newTableId;\nnewTableModel.Name = V8.Param.TableName || (newTableModel.Name + oldTableNewCount);\nnewTableModel.Description = V8.Param.Description || newTableModel.Name;\nvar addTableResult = V8.FormEngine.AddTable(newTableModel, V8.DbTrans);//带事务\nif (addTableResult.Code != 1) {\n  return { Code: 0, Msg: \'插入新表失败：\' + addTableResult.Msg }//addTableResult;\n}\n\n//插入新表字段（跳过审计字段，AddTable已自动创建）\nvar fixedFieldNames = [\'Id\', \'CreateTime\', \'UpdateTime\', \'UserId\', \'UserName\', \'IsDeleted\'];\nfor (var i = 0; i < oldTableFieldList.length; i++) {\n  var oldField = oldTableFieldList[i];\n  //跳过审计字段（IsLockField==1 或 字段名在固定字段列表中），AddTable已自动创建\n  if (oldField.IsLockField == 1 || fixedFieldNames.indexOf(oldField.Name) > -1) {\n    continue;\n  }\n  var newFieldModel = { ...oldField };\n  //删除Id，防止重复\n  delete newFieldModel.Id;\n  newFieldModel.TableId = newTableId;\n  newFieldModel.TableName = newTableModel.Name;\n  var addFieldResult = V8.FormEngine.AddField(newFieldModel, V8.DbTrans);//带事务\n  if (addFieldResult.Code != 1) {\n    return { Code: 0, Msg: `插入字段[${newFieldModel.Name}]失败：` + addFieldResult.Msg }; //addFieldResult;\n  }\n}\nV8.Result = { Code: 1 };\n\n', b'1', 'TableName', '传入TableId（原表Id）、TableName（新表名）、Description（新表描述，可选）', '', '', '/api/FormEngine/copy-table', b'0', '[]', 0, '', 0, 0, '', '', 600, 100000000, 2048, 10000);
INSERT INTO `sys_apiengine` VALUES ('0094dd1f-33d6-48d9-8f66-1840ff22c737', '2026-01-06 04:07:15', '2026-03-21 03:20:16', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '[微信]微信v3支付JSAPI下单', 'v3_pay_transactions_jsapi', b'1', '[]', 'if(!V8.Param.OrderAmount || !V8.Param.OrderNo){\n	return { Code : 0, Msg : \'参数错误！\' }\n}\n//参数\nvar appid = V8.OsClientModel.MiniProgramAppId;//小程序 appid\nvar mchid = V8.OsClientModel.WeChatMchId;//商户Id\nvar serialNo = V8.OsClientModel.CertSerialNo;//商户API证书序列号serial_no，用于声明所使用的证书\nvar privateKey = V8.OsClientModel.WxPayPrivateKey;//私书私有key\nvar oepnId = V8.CurrentUser.MiniProgramOpenId;//V8.CurrentUser.MiniProgramOpenId;//\'ouVQI46Ckf_WzhYnjGIvtvzC2nwo\';//\nvar notify_url = V8.SysConfig.ApiBase + `/apiengine/wxpay-notify--OsClient--${V8.OsClient}--`;//用户支付成功后回调地址，由接口引擎实现\nvar jsapiUrl = \'https://api.mch.weixin.qq.com/v3/pay/transactions/jsapi\';//腾讯官方下单地址，固定url\nvar jsapiUrlSimple = \'/v3/pay/transactions/jsapi\';//腾讯官方下单地址，固定url\nvar currentUser = V8.CurrentUser;\n//参数校验\nif(!appid || !mchid || !serialNo || !privateKey){\n  V8.Result = { Code : 0, Msg : \'支付配置有误！\' }; return;\n}\nif(!oepnId){\n  V8.Result = { Code : 0, Msg : \'未找到当前登录用户小程序oepnid，无法发起支付！\' }; return;\n}\n//获取商品信息，根据商品Id查询出 商品名称、商品价格\nvar productName = V8.Param.ProductName || \'极芝客灵芝原液\';\nvar productPrice = parseInt(V8.Param.OrderAmount * 100);//商品价格，单位为分，必须整数int类型\n//新增订单信息，拿到订单编号（订单编号一般为【自动编号】控件，平台内置分布式锁保证唯一性）\n//订单编号。6-32位。需要是字符串。\nvar orderNo = V8.Param.OrderNo;//new Date().getTime().toString();\nvar payParam = {\n	\"mchid\": mchid,//支付商户Id\n	\"out_trade_no\": orderNo,//商户订单号\n	\"appid\": appid,//小程序 appid\n	\"description\": productName,//商品描述\n	\"notify_url\": notify_url,//回调地址，由接口引擎实现\n	\"amount\": {\n		\"total\": productPrice,//订单总金额，单位为分。\n		\"currency\": \"CNY\"//固定值\n	},\n	\"payer\": {\n		\"openid\": oepnId//用户的openid\n	}\n};\n//生成微信需要的加密请求头\nvar headers = {\n	Authorization : V8.Method.GetWeChatAuthorization(mchid, serialNo, privateKey, jsapiUrlSimple, JSON.stringify(payParam))\n};\n//向微信发起请求\nvar httpResult = V8.Http.Post({\n  Url : jsapiUrl,\n	//注意：接口引擎目前有个暂未解决的bug：\n	//参数传入int类型的值，接口引擎会序列化成浮点类型，这将导致微信参数验证不通过\n	//所以使用PostParamString参数，提前序列化好。\n  //PostParam: payParam,\n	PostParamString : JSON.stringify(payParam),\n	ParamType : \'JSON\',//这里的\'json\'不区分大小写\n	Headers : headers\n});\nvar httpResultObj = JSON.parse(httpResult);\n//如果不存在prepay_id，以DosResult标准格式返回错误结果到前端\nif(!httpResultObj.prepay_id){\n  return { Code : 0, Data : httpResultObj, Msg : httpResultObj.message };\n}else{\n	//返回一些前端发起支付需要的值\n	//签名，使用字段appId、timeStamp、nonceStr、package计算得出的签名值\n	httpResultObj.appid = appid;//小程序appid\n	httpResultObj.timeStamp = V8.Method.GetTimestamp().toString();//秒时间戳\n	httpResultObj.nonceStr = System.IO.Path.GetRandomFileName();//随机字符串\n	httpResultObj.package = \'prepay_id=\' + httpResultObj.prepay_id;//prepay_id\n	//微信签名\n	httpResultObj.paySign = V8.Method.GetWeChatSign(privateKey, [appid, httpResultObj.timeStamp, httpResultObj.nonceStr, httpResultObj.package]);\n  return { Code : 1, Data :  httpResultObj};//这里不用返回Data\n}', b'0', '', '必传：ProductId（商品Id，用于根据商品Id查询出 商品名称、商品价格）\nhttps://pay.weixin.qq.com/wiki/doc/apiv3/apis/chapter3_5_1.shtml', '', '[2026-01-15 04:00:30]执行结果：{\"Code\":0,\"Msg\":\"参数错误！\"}', '/apiengine/v3-pay-transactions-jsapi', b'0', '[]', 0, '', 0, 0, '', '', NULL, NULL, NULL, NULL);
INSERT INTO `sys_apiengine` VALUES ('01d220ee-6a30-4ba9-adaf-3d251a6e246f', '2026-01-06 04:01:27', '2026-03-21 03:20:16', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '[微信]微信支付申请退款', 'wxpay_v3_refund', b'1', '[]', 'if(!V8.Param.OrderId){\n  V8.Result = { Code : 0, Msg : \'参数错误！\' }; return;\n}\n//参数\nvar appid = V8.SysConfig.MiniProgramAppId;//小程序 appid\nvar mchid = V8.SysConfig.WeChatMchId;//商户Id\nvar serialNo = V8.SysConfig.CertSerialNo;//商户API证书序列号serial_no，用于声明所使用的证书\nvar privateKey = V8.SysConfig.WxPayPrivateKey;//私书私有key\nvar oepnId = V8.CurrentUser.MiniProgramOpenId;//\'ouVQI46Ckf_WzhYnjGIvtvzC2nwo\';//\nvar notify_url = \'https://api.microios.com/apiengine/wxpay-refund-notify\';//用户退款后回调地址，由接口引擎实现\nvar apiUrl = \'https://api.mch.weixin.qq.com/v3/refund/domestic/refunds\';\nvar apiUrlSimple = \'/v3/refund/domestic/refunds\';//腾讯官方下单地址，固定url\nvar currentUser = V8.CurrentUser;\n//参数校验\nif(!appid || !mchid || !serialNo || !privateKey){\n  V8.Result = { Code : 0, Msg : \'支付配置有误！\' }; return;\n}\nvar orderResult = V8.FormEngine.GetFormData({\n  FormEngineKey : \'diy_vip_order\',\n  Id : V8.Param.OrderId\n});\nif(orderResult.Code != 1){\n  V8.Result = orderResult; return;\n}\nvar orderModel = orderResult.Data;\nvar tongyiXDHTJG_Obj = JSON.parse(orderModel.TongyiXDHTJG);\nvar wxParam = {\n  \"transaction_id\": tongyiXDHTJG_Obj.transaction_id,//与out_trade_no二选一\n  //out_trade_no : orderModel.DingdanBH,//与transaction_id二选1\n  \"out_refund_no\": new Date().getTime().toString(),//商户系统内部的退款单号。应该是一张子表，可能会退款多次\n  \"reason\": \"用户自主退款\",\n  \"notify_url\": notify_url,\n  \"funds_account\": \"AVAILABLE\",\n  \"amount\": {\n    \"refund\": parseInt(orderModel.ShijiZFJE * 100),//退款金额，单位为分，只能为整数，不能超过原订单支付金额。\n    \"total\": parseInt(orderModel.DingdanJE * 100),//原支付交易的订单总金额，单位为分，只能为整数。\n    \"currency\": \"CNY\"\n  }\n};\n//生成微信需要的加密请求头\nvar headers = {\n	Authorization : V8.Method.GetWeChatAuthorization(mchid, serialNo, privateKey, apiUrlSimple, JSON.stringify(wxParam));\n};\n//向微信发起请求\nvar httpResult = V8.http.Post({\n  Url : apiUrl,\n	//注意：接口引擎目前有个暂未解决的bug：\n	//参数传入int类型的值，接口引擎会序列化成浮点类型，这将导致微信参数验证不通过\n	//所以使用PostParamString参数，提前序列化好。\n  //PostParam: payParam,\n	PostParamString : JSON.stringify(wxParam),\n	ParamType : \'JSON\',//这里的\'json\'不区分大小写\n	Headers : headers\n});\nV8.Result = httpResult;', b'0', '', '必传：OrderId（订单Id）\nhttps://pay.weixin.qq.com/wiki/doc/apiv3/apis/chapter3_5_9.shtml', '', '', '/apiengine/wxpay-v3-refund', b'0', '[]', 0, '', 0, 0, '', '', NULL, NULL, NULL, NULL);
INSERT INTO `sys_apiengine` VALUES ('01KGF6XR0HBDHKS6VFHA7DSSQ7', '2026-02-02 20:59:22', '2026-03-21 03:20:17', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '[系统]获取应用商城列表', 'get-microi-store', b'1', '[]', 'var pageIndex = V8.Param._PageIndex || 1;\nvar pageSize = V8.Param._PageSize || 15;\nvar keyword = V8.Param._Keyword || \'\';\nvar _where = [];\nif (keyword) {\n  _where.push([\'AppName\', \'Like\', keyword]);\n  _where.push([\'OR\', \'AppId\', \'Like\', keyword]);\n  _where.push([\'OR\', \'AppVersion\', \'Like\', keyword]);\n  _where.push([\'OR\', \'AppAuthor\', \'Like\', keyword]);\n  _where.push([\'OR\', \'AppDetail\', \'Like\', keyword]);\n}\nvar result = V8.FormEngine.GetTableData(\"sys_microistore\", {\n  _SelectNotFields : [\'AppPakcet\'],//不查询数据包，防止列表数据过大\n  _Where: _where,\n  _PageSize: pageSize,\n  _PageIndex: pageIndex,\n  OsClient: V8.OsClient//这里一定要传，否则B租户调用A租户的公开接口时，这个GetTableData又去取了B租户的token了\n});\nreturn result;', b'0', '', '', '', '', '/apiengine/get-microi-store-list', b'1', '[]', 0, '', 0, 0, '', '', 600, 100000000, 2048, 10000);
INSERT INTO `sys_apiengine` VALUES ('01KGF7P4KHSYRY8ZB3BG2VD6C2', '2026-02-02 21:12:51', '2026-03-21 03:20:16', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '[系统]获取应用商城单条数据', 'get-microi-store-model', b'1', '[]', 'var result = V8.FormEngine.GetFormData(\"sys_microistore\", {\n  Id: V8.Param.Id,\n  OsClient: V8.OsClient//这里一定要传，否则B租户调用A租户的公开接口时，这个GetTableData又去取了B租户的token了\n});\nreturn result;', b'0', '', '', '', '', '/apiengine/get-microi-store-model', b'1', '[]', 0, '', 0, 0, '', '', 600, 100000000, 2048, 10000);
INSERT INTO `sys_apiengine` VALUES ('01KGFFEK8P10P1S9SYH9PJNJ77', '2026-02-02 23:28:20', '2026-04-07 01:10:31', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '[系统]应用商城导出数据包', 'export-microi-store-package', b'1', '[]', '/**\n * 导出应用数据包接口引擎（A系统）！！\n * v2026-03-28 14:20\n * 功能：导出菜单、表定义、字段定义、工作流、接口引擎等元数据，形成应用数据包\n * \n * 业务逻辑：\n * 1. 接收一个或多个sys_menu的Id，获取它们及所有子菜单数据\n * 2. 获取每个菜单对应的diy_table数据\n * 3. 获取每个diy_table对应的diy_field数据\n * 3.5 自动发现子表控件：检查字段中Component=\'TableChild\'的控件，从Config中提取TableChildSysMenuId，\n *     将子表对应的菜单及其子菜单也加入导出范围\n * 3.6 可选：接收额外的TableIds参数，合并到已收集的表Id中（自动去重）\n * 4. 可选：接收一个或多个wf_flowdesign的Id，获取它们及对应的wf_node数据\n * 5. 可选：接收一个或多个sys_apiengine的ApiEngineKey，获取对应的接口引擎数据\n * 6. 将所有数据打包成一个JSON数据包返回\n * \n * 接口配置：\n * - ApiEngineKey: export-microi-store-package\n * - ApiAddress: /apiengine/export-microi-store-package\n * - 允许匿名调用: 否\n * - 分布式锁: 否\n * \n * 前端调用示例：\n * V8.ApiEngine.Run(\'export-microi-store-package\', {\n *   MenuIds: [\'menu-id-1\', \'menu-id-2\'],  // 可选\n *   FlowIds: [\'flow-id-1\', \'flow-id-2\'],  // 可选\n *   ApiEngineKeys: [\'api-key-1\', \'api-key-2\'],  // 可选，传\'*\'表示导出所有\n *   TableIds: [\'table-id-1\', \'table-id-2\']  // 可选，额外需要导出的表Id（与MenuIds中的表自动去重）\n * })\n * \n * 注意：MenuIds、FlowIds、ApiEngineKeys、TableIds 至少要传入一个非空数组\n * \n * 子表控件自动发现：\n * 导出时会自动检查所有表的字段，如果存在Component=\'TableChild\'的子表控件，\n * 会从其Config中提取TableChildSysMenuId，将对应的菜单及其子菜单也加入导出范围\n * \n * 返回格式：\n * {\n *   Code: 1,\n *   Data: {\n *     PackageInfo: { name: \'\', version: \'\', createTime: \'\' },\n *     SysMenus: [...],\n *     DiyTables: [...],\n *     DiyFields: [...],\n *     WfFlowDesigns: [...],  // 可选\n *     WfNodes: [...],  // 可选\n *     WfLines: [...],  // 可选\n *     SysApiEngines: [...]  // 可选\n *   },\n *   Msg: \'导出成功\'\n * }\n */\n\n// ==================== 参数接收与校验 ====================\n\nvar MenuIds = V8.Param.MenuIds;  // 菜单Id数组\nvar FlowIds = V8.Param.FlowIds;  // 工作流Id数组（可选）\nvar ApiEngineKeys = V8.Param.ApiEngineKeys;  // 接口引擎Key数组（可选）\nvar TableIds = V8.Param.TableIds;  // 表Id数组（可选，额外需要导出的表，与MenuIds中的表自动去重）\nvar PackageName = V8.Param.PackageName || \'未命名应用包\';  // 应用包名称\nvar PackageVersion = V8.Param.PackageVersion || \'1.0.0\';  // 应用包版本\n\n// 定义调试模式\nvar isDebug = true;\nvar debugLog = {};\n\n// 参数校验：MenuIds、FlowIds、ApiEngineKeys、TableIds 至少要有一个非空\nvar hasMenuIds = MenuIds && MenuIds.length > 0;\nvar hasFlowIds = FlowIds && FlowIds.length > 0;\nvar hasApiEngineKeys = ApiEngineKeys && ApiEngineKeys.length > 0;\nvar hasTableIds = TableIds && TableIds.length > 0;\n\nif (!hasMenuIds && !hasFlowIds && !hasApiEngineKeys && !hasTableIds) {\n    return {\n        Code: 0,\n        Msg: \'参数错误：MenuIds、FlowIds、ApiEngineKeys、TableIds 至少要传入一个非空数组\'\n    };\n}\n\ntry {\n    debugLog.startTime = new Date().toISOString();\n    debugLog.inputMenuIds = MenuIds;\n    debugLog.inputFlowIds = FlowIds;\n    debugLog.inputApiEngineKeys = ApiEngineKeys;\n    debugLog.inputTableIds = TableIds;\n\n    var fixedDiyField = [\n        { Name: \"Id\", Label: \"Id\", Type: \"varchar(36)\", Component: \"Guid\", Sort: 1, Visible: 0, TableWidth: 150 },\n        { Name: \"CreateTime\", Label: \"创建时间\", Type: \"datetime\", Component: \"DateTime\", Sort: 2, Visible: 1, TableWidth: 150 },\n        { Name: \"UpdateTime\", Label: \"修改时间\", Type: \"datetime\", Component: \"DateTime\", Sort: 3, Visible: 1, TableWidth: 150 },\n        { Name: \"UserId\", Label: \"创建人Id\", Type: \"varchar(36)\", Component: \"Guid\", Sort: 4, Visible: 0, TableWidth: 150 },\n        { Name: \"UserName\", Label: \"创建人\", Type: \"varchar(255)\", Component: \"Text\", Sort: 5, Visible: 1, TableWidth: 150 },\n        { Name: \"IsDeleted\", Label: \"是否已删除\", Type: \"int\", Component: \"Switch\", Sort: 6, Visible: 0, TableWidth: 50 }\n    ];\n\n\n    var someTableList = V8.FormEngine.GetTableData(\'diy_table\', {\n        _Where: [\n            [\'Name\', \'In\', [\'sys_menu\', \'diy_table\', \'diy_field\', \'wf_flowdesign\', \'wf_node\', \'wf_line\', \'sys_apiengine\']]\n        ]\n    });\n    if (someTableList.Code != 1) {\n        return someTableList;\n    }\n    someTableList = someTableList.Data;\n    var someTableIds = someTableList.map(item => item.Id);\n\n    var someFieldList = V8.FormEngine.GetTableData(\'diy_field\', {\n        _Where: [\n            [\'TableId\', \'In\', someTableIds]\n        ]\n    });\n    if (someFieldList.Code != 1) {\n        return someFieldList;\n    }\n    someFieldList = someFieldList.Data;\n\n    // 清理函数：移除对象中值为 null 或空字符串的属性，并移除跨租户字段\n    var cleanObject = function (obj) {\n        var cleaned = {};\n        // 需要移除的字段列表（跨租户数据）\n        var excludeFields = {\n            \'OsClient\': true,\n            \'CreateUserId\': true,\n            \'UpdateUserId\': true,\n            \'CreateUser\': true,\n            \'UpdateUser\': true\n        };\n\n        for (var key in obj) {\n            var value = obj[key];\n            // 跳过需要排除的字段\n            if (excludeFields[key]) {\n                continue;\n            }\n            // 只保留有值的字段（排除 null、undefined、空字符串）\n            if (value !== null && value !== undefined && value !== \'\') {\n                cleaned[key] = value;\n            }\n        }\n        return cleaned;\n    };\n\n    // ==================== 步骤1：查询所有菜单数据 ====================\n\n    var exportMenus = [];\n    var tableIds = [];\n    var tableIdMap = {};\n\n    if (hasMenuIds) {\n        // 获取菜单单所有字段 START\n        var sysMenuTableModel = someTableList.find(item => item.Name && item.Name.toLowerCase() == \'sys_menu\');\n        var sysMenuTableId = sysMenuTableModel.Id;\n        var sysMenuFields = someFieldList.filter(item => item.TableId == sysMenuTableId);\n        var sysMenuFieldNames = sysMenuFields.map(item => {\n            return item.Name;\n        });\n\n        // 去重：使用对象键值特性去除重复字段\n        var fieldMap = {};\n        for (var i = 0; i < sysMenuFieldNames.length; i++) {\n            fieldMap[sysMenuFieldNames[i]] = true;\n        }\n        sysMenuFieldNames = [];\n        for (var fieldName in fieldMap) {\n            sysMenuFieldNames.push(fieldName);\n        }\n\n        // 确保必要字段存在\n        if (sysMenuFieldNames.indexOf(\'Id\') <= -1) {\n            sysMenuFieldNames.push(\'Id\');\n        }\n        if (sysMenuFieldNames.indexOf(\'ParentId\') <= -1) {\n            sysMenuFieldNames.push(\'ParentId\');\n        }\n        if (sysMenuFieldNames.indexOf(\'DiyTableId\') <= -1) {\n            sysMenuFieldNames.push(\'DiyTableId\');\n        }\n        if (sysMenuFieldNames.indexOf(\'CreateTime\') <= -1) {\n            sysMenuFieldNames.push(\'CreateTime\');\n        }\n        // 获取菜单单所有字段 END\n\n        debugLog.sysMenuFieldNames = sysMenuFieldNames;\n        debugLog.sysMenuFieldNamesCount = sysMenuFieldNames.length;\n\n        var allMenusResult = V8.FormEngine.GetTableData(\'sys_menu\', {\n            _SelectFields: sysMenuFieldNames,\n        });\n\n        if (allMenusResult.Code !== 1) {\n            return {\n                Code: 0,\n                Msg: \'查询sys_menu表失败：\' + allMenusResult.Msg\n            };\n        }\n\n        var allMenus = allMenusResult.Data || [];\n        debugLog.totalMenusInDb = allMenus.length;\n\n        // 检查传入的MenuId是否在查询结果中\n        var targetMenu = allMenus.find(m => m.Id == MenuIds[0]);\n        debugLog.targetMenuFound = !!targetMenu;\n        debugLog.targetMenuData = targetMenu;\n\n        // ==================== 步骤2：递归获取所有子菜单 ====================\n\n        // 递归获取所有子菜单ID（带循环引用检测）\n        var getAllChildMenuIds = function (parentId, allMenus, visited) {\n            // 初始化访问记录\n            if (!visited) {\n                visited = {};\n            }\n\n            // parentId 必须有值，防止用 null 去匹配导致查询到所有根菜单\n            // 注意：用户传入的 MenuId 永远不会是 null，只有在递归过程中数据异常时才可能出现\n            if (!parentId) {\n                return [];\n            }\n\n            // 防止循环引用导致死循环\n            if (visited[parentId]) {\n                return [];\n            }\n\n            visited[parentId] = true;\n            var childIds = [parentId]; // 包含自己\n\n            for (var i = 0; i < allMenus.length; i++) {\n                // 查找子菜单：ParentId 等于当前 parentId\n                // 必须确保子菜单的 Id 有值，防止递归时传入 null\n                if (allMenus[i].ParentId == parentId && allMenus[i].Id && allMenus[i].Id != parentId) {\n                    var subChildIds = getAllChildMenuIds(allMenus[i].Id, allMenus, visited);\n                    childIds = childIds.concat(subChildIds);\n                }\n            }\n            return childIds;\n        };\n\n        // 收集所有相关菜单ID\n        var allRelatedMenuIds = [];\n        var menuIdMap = {};\n\n        for (var i = 0; i < MenuIds.length; i++) {\n            var menuId = MenuIds[i];\n            var childIds = getAllChildMenuIds(menuId, allMenus);\n            for (var j = 0; j < childIds.length; j++) {\n                if (!menuIdMap[childIds[j]]) {\n                    allRelatedMenuIds.push(childIds[j]);\n                    menuIdMap[childIds[j]] = true;\n                }\n            }\n        }\n\n        debugLog.relatedMenuIdsCount = allRelatedMenuIds.length;\n        debugLog.relatedMenuIds = allRelatedMenuIds;\n\n        // 过滤出所有相关菜单数据并清理空字段\n        var exportMenus = [];\n        for (var i = 0; i < allMenus.length; i++) {\n            if (menuIdMap[allMenus[i].Id]) {\n                exportMenus.push(cleanObject(allMenus[i]));\n            }\n        }\n\n        debugLog.exportMenusCount = exportMenus.length;\n        debugLog.exportMenusSample = exportMenus.slice(0, 3);  // 返回前3条菜单数据样本\n\n        // ==================== 步骤3：获取所有菜单关联的表ID ====================\n\n        for (var i = 0; i < exportMenus.length; i++) {\n            if (exportMenus[i].DiyTableId) {\n                if (!tableIdMap[exportMenus[i].DiyTableId]) {\n                    tableIds.push(exportMenus[i].DiyTableId);\n                    tableIdMap[exportMenus[i].DiyTableId] = true;\n                }\n            }\n        }\n\n        debugLog.relatedTableIds = tableIds;\n\n        // ==================== 步骤3.5：发现子表控件（TableChild）关联的菜单 ====================\n        // 查询当前已收集的tableIds对应的字段，找到Component=\'TableChild\'的字段\n        // 从其Config中提取TableChildSysMenuId，将对应的菜单及其子菜单也加入导出范围\n\n        if (tableIds.length > 0) {\n            var tableChildFieldsResult = V8.FormEngine.GetTableData(\'diy_field\', {\n                _Where: [\n                    [\'TableId\', \'In\', JSON.stringify(tableIds)],\n                    [\'Component\', \'=\', \'TableChild\']\n                ],\n                _SelectFields: [\'Id\', \'TableId\', \'Config\', \'Name\']\n            });\n\n            if (tableChildFieldsResult.Code == 1 && tableChildFieldsResult.Data && tableChildFieldsResult.Data.length > 0) {\n                var tableChildMenuIds = [];\n                debugLog.tableChildFieldsCount = tableChildFieldsResult.Data.length;\n\n                for (var tc = 0; tc < tableChildFieldsResult.Data.length; tc++) {\n                    var tcField = tableChildFieldsResult.Data[tc];\n                    if (tcField.Config) {\n                        try {\n                            var tcConfig = typeof tcField.Config === \'string\' ? JSON.parse(tcField.Config) : tcField.Config;\n                            if (tcConfig.TableChildSysMenuId && !menuIdMap[tcConfig.TableChildSysMenuId]) {\n                                tableChildMenuIds.push(tcConfig.TableChildSysMenuId);\n                                debugLog[\'tableChild_found_\' + tcField.Name] = \'TableChildSysMenuId=\' + tcConfig.TableChildSysMenuId;\n                            }\n                        } catch (tcParseError) {\n                            debugLog[\'tableChild_config_parse_error_\' + tcField.Id] = tcParseError.message;\n                        }\n                    }\n                }\n\n                // 对发现的子表菜单ID进行递归展开（获取其所有子菜单）\n                if (tableChildMenuIds.length > 0) {\n                    debugLog.tableChildMenuIds = tableChildMenuIds;\n\n                    for (var tci = 0; tci < tableChildMenuIds.length; tci++) {\n                        var tcMenuId = tableChildMenuIds[tci];\n                        var tcChildIds = getAllChildMenuIds(tcMenuId, allMenus);\n                        for (var tcj = 0; tcj < tcChildIds.length; tcj++) {\n                            if (!menuIdMap[tcChildIds[tcj]]) {\n                                allRelatedMenuIds.push(tcChildIds[tcj]);\n                                menuIdMap[tcChildIds[tcj]] = true;\n                            }\n                        }\n                    }\n\n                    // 将新发现的菜单加入exportMenus，并收集其关联的表ID\n                    for (var tci = 0; tci < allMenus.length; tci++) {\n                        if (menuIdMap[allMenus[tci].Id]) {\n                            var tcAlreadyExported = false;\n                            for (var tce = 0; tce < exportMenus.length; tce++) {\n                                if (exportMenus[tce].Id == allMenus[tci].Id) {\n                                    tcAlreadyExported = true;\n                                    break;\n                                }\n                            }\n                            if (!tcAlreadyExported) {\n                                exportMenus.push(cleanObject(allMenus[tci]));\n                                // 收集新菜单关联的表ID\n                                if (allMenus[tci].DiyTableId && !tableIdMap[allMenus[tci].DiyTableId]) {\n                                    tableIds.push(allMenus[tci].DiyTableId);\n                                    tableIdMap[allMenus[tci].DiyTableId] = true;\n                                }\n                            }\n                        }\n                    }\n\n                    debugLog.afterTableChildMenuCount = exportMenus.length;\n                    debugLog.afterTableChildTableIds = tableIds.slice();\n                }\n            }\n        }\n\n    } else {\n        debugLog.step1Skip = \'未传入MenuIds，跳过菜单数据查询\';\n    }\n\n    // ==================== 步骤3.6：合并额外传入的TableIds（去重） ====================\n\n    if (hasTableIds) {\n        for (var eti = 0; eti < TableIds.length; eti++) {\n            if (TableIds[eti] && !tableIdMap[TableIds[eti]]) {\n                tableIds.push(TableIds[eti]);\n                tableIdMap[TableIds[eti]] = true;\n            }\n        }\n        debugLog.afterMergeExtraTableIds = tableIds.slice();\n        debugLog.extraTableIdsCount = TableIds.length;\n    }\n\n    // ==================== 步骤4：查询所有相关的diy_table数据 ====================\n    // 获取 diy_table 所有字段 START\n    var diyTableTableModel = someTableList.find(item => item.Name && item.Name.toLowerCase() == \'diy_table\');\n    var diyTableTableId = diyTableTableModel.Id;\n    var diyTableFields = someFieldList.filter(item => item.TableId == diyTableTableId);\n    var diyTableFieldNames = diyTableFields.map(item => {\n        return item.Name;\n    });\n    if (diyTableFieldNames.indexOf(\'Id\') <= -1) {\n        diyTableFieldNames.push(\'Id\');\n    }\n    if (diyTableFieldNames.indexOf(\'CreateTime\') <= -1) {\n        diyTableFieldNames.push(\'CreateTime\');\n    }\n    // 获取 diy_table 所有字段 END\n\n    var exportTables = [];\n\n    if (tableIds.length > 0) {\n        var tablesResult = V8.FormEngine.GetTableData(\'diy_table\', {\n            _SelectFields: diyTableFieldNames,\n            _Where: [\n                [\'Id\', \'In\', JSON.stringify(tableIds)]\n            ]\n        });\n\n        if (tablesResult.Code !== 1) {\n            return {\n                Code: 0,\n                Msg: \'查询diy_table表失败：\' + tablesResult.Msg\n            };\n        }\n\n        exportTables = tablesResult.Data || [];\n    }\n\n    // 清理 diy_table 数据\n    exportTables = exportTables.map(cleanObject);\n\n    debugLog.exportTablesCount = exportTables.length;\n\n    // ==================== 步骤5：查询所有相关的diy_field数据 ====================\n    // 获取 diy_field 所有字段 START\n    var diyFieldTableModel = someTableList.find(item => item.Name && item.Name.toLowerCase() == \'diy_field\');\n    var diyFieldTableId = diyFieldTableModel.Id;\n    var diyFieldFields = someFieldList.filter(item => item.TableId == diyFieldTableId);\n    var diyFieldFieldNames = diyFieldFields.map(item => {\n        return item.Name;\n    });\n    if (diyFieldFieldNames.indexOf(\'Id\') <= -1) {\n        diyFieldFieldNames.push(\'Id\');\n    }\n    if (diyFieldFieldNames.indexOf(\'CreateTime\') <= -1) {\n        diyFieldFieldNames.push(\'CreateTime\');\n    }\n    // 获取 diy_field 所有字段 END\n    var exportFields = [];\n\n    if (tableIds.length > 0) {\n        var fieldsResult = V8.FormEngine.GetTableData(\'diy_field\', {\n            _SelectFields: diyFieldFieldNames,\n            _Where: [\n                [\'TableId\', \'In\', JSON.stringify(tableIds)]\n            ],\n        });\n\n        if (fieldsResult.Code !== 1) {\n            return {\n                Code: 0,\n                Msg: \'查询diy_field表失败：\' + fieldsResult.Msg\n            };\n        }\n\n        exportFields = fieldsResult.Data || [];\n    }\n\n    // 清理 diy_field 数据\n    exportFields = exportFields.map(cleanObject);\n\n    debugLog.exportFieldsCount = exportFields.length;\n\n    // ==================== 步骤5.5：生成DDL语句 ====================\n\n    // MySQL类型映射函数\n    var mapToMySQLType = function (diyType) {\n        if (!diyType) return \'varchar(255)\';\n\n        var typeStr = diyType.toLowerCase();\n\n        // 已经是标准MySQL类型，直接返回\n        if (typeStr.match(/^(varchar|int|bigint|datetime|text|longtext|decimal|double|float|tinyint|date|time|timestamp|json)\\(/)) {\n            return diyType;\n        }\n        if (typeStr == \'int\' || typeStr == \'bigint\' || typeStr == \'text\' || typeStr == \'mediumtext\' || typeStr == \'longtext\' ||\n            typeStr == \'datetime\' || typeStr == \'date\' || typeStr == \'time\' || typeStr == \'timestamp\' ||\n            typeStr == \'json\' || typeStr == \'tinyint\' || typeStr == \'double\' || typeStr == \'float\') {\n            return diyType;\n        }\n\n        // 类型映射\n        if (typeStr.indexOf(\'varchar\') == 0) return diyType;\n        if (typeStr.indexOf(\'decimal\') == 0) return diyType;\n        if (typeStr.indexOf(\'mediumtext\') == 0) return diyType;\n\n        // 默认映射规则\n        return \'varchar(255)\';\n    };\n\n    // 为每个表生成DDL\n    var ddlStatements = [];\n    for (var i = 0; i < exportTables.length; i++) {\n        var table = exportTables[i];\n        var tableName = table.Name;\n        var tableFields = exportFields.filter(f => f.TableId == table.Id);\n\n        if (!tableName) continue;\n\n        // 合并审计字段：先添加fixedDiyField，再添加表的自定义字段\n        var allFields = [];\n\n        // 1. 添加审计字段\n        for (var k = 0; k < fixedDiyField.length; k++) {\n            allFields.push({\n                Name: fixedDiyField[k].Name,\n                Type: fixedDiyField[k].Type,\n                Label: fixedDiyField[k].Label,\n                IsFixed: true\n            });\n        }\n\n        // 2. 添加表的自定义字段（排除已在fixedDiyField中的字段）\n        var fixedFieldNames = {};\n        for (var k = 0; k < fixedDiyField.length; k++) {\n            fixedFieldNames[fixedDiyField[k].Name] = true;\n        }\n\n        for (var j = 0; j < tableFields.length; j++) {\n            if (!fixedFieldNames[tableFields[j].Name]) {\n                allFields.push({\n                    Name: tableFields[j].Name,\n                    Type: tableFields[j].Type,\n                    Label: tableFields[j].Label || tableFields[j].Name,\n                    IsFixed: false\n                });\n            }\n        }\n\n        if (allFields.length == 0) continue;\n\n        var fieldDefs = [];\n        var fieldNameMap = {};  // 用于字段去重\n\n        for (var j = 0; j < allFields.length; j++) {\n            var field = allFields[j];\n            var fieldName = field.Name;\n\n            if (!fieldName) continue;\n\n            // MySQL字段名长度限制为64字符，超过则截断并记录\n            if (fieldName.length > 64) {\n                debugLog[\'field_name_too_long_\' + table.Name + \'_\' + fieldName] = \'字段名过长，已截断：\' + fieldName.length + \'字符\';\n                fieldName = fieldName.substring(0, 64);\n            }\n\n            // 字段去重：如果字段名已存在，跳过\n            if (fieldNameMap[fieldName]) {\n                debugLog[\'field_duplicate_\' + table.Name + \'_\' + fieldName] = \'字段重复，已跳过\';\n                continue;\n            }\n            fieldNameMap[fieldName] = true;\n\n            var fieldType = mapToMySQLType(field.Type);\n            var fieldDef = \'`\' + fieldName + \'` \' + fieldType;\n\n            // 主键不允许NULL\n            if (fieldName == \'Id\') {\n                fieldDef += \' NOT NULL PRIMARY KEY\';\n            } else {\n                // 其他字段允许NULL\n                fieldDef += \' NULL\';\n            }\n\n            // 添加字段说明（COMMENT）\n            if (field.Label && field.Label !== fieldName) {\n                // 转义单引号\n                var comment = field.Label.replace(/\'/g, \"\'\'\");\n                fieldDef += \" COMMENT \'\" + comment + \"\'\";\n            }\n\n            fieldDefs.push(fieldDef);\n        }\n\n        if (fieldDefs.length > 0) {\n            var ddl = \'CREATE TABLE IF NOT EXISTS `\' + tableName + \'` (\\n  \' +\n                fieldDefs.join(\',\\n  \') +\n                \'\\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;\';\n            ddlStatements.push({\n                TableName: tableName,\n                TableId: table.Id,\n                DDL: ddl\n            });\n        }\n    }\n\n    debugLog.ddlStatementsCount = ddlStatements.length;\n\n    // ==================== 步骤6：查询工作流数据（可选） ====================\n\n    var exportFlows = [];\n    var exportNodes = [];\n    var exportLines = [];\n\n    // 检查是否要导出所有工作流\n    var exportAllFlows = FlowIds && FlowIds.length == 1 && FlowIds[0] == \'*\';\n\n    if (exportAllFlows || (FlowIds && FlowIds.length > 0)) {\n        // 获取 wf_flowdesign 所有字段 START\n        var wfFlowdesignTableModel = someTableList.find(item => item.Name && item.Name.toLowerCase() == \'wf_flowdesign\');\n        var wfFlowdesignTableId = wfFlowdesignTableModel.Id;\n        var wfFlowdesignFields = someFieldList.filter(item => item.TableId == wfFlowdesignTableId);\n        var wfFlowdesignFieldNames = wfFlowdesignFields.map(item => {\n            return item.Name;\n        });\n        if (wfFlowdesignFieldNames.indexOf(\'Id\') <= -1) {\n            wfFlowdesignFieldNames.push(\'Id\');\n        }\n        if (wfFlowdesignFieldNames.indexOf(\'CreateTime\') <= -1) {\n            wfFlowdesignFieldNames.push(\'CreateTime\');\n        }\n        // 获取 wf_flowdesign 所有字段 END\n\n        // 查询工作流设计数据\n        var flowsWhere = [];\n        if (!exportAllFlows) {\n            // 只导出指定的工作流\n            flowsWhere.push([\'Id\', \'In\', JSON.stringify(FlowIds)]);\n        }\n        // 如果是导出所有工作流，不添加Where条件\n\n        var flowsResult = V8.FormEngine.GetTableData(\'wf_flowdesign\', {\n            _SelectFields: wfFlowdesignFieldNames,\n            _Where: flowsWhere.length > 0 ? flowsWhere : undefined,\n        });\n\n        if (flowsResult.Code == 1) {\n            exportFlows = flowsResult.Data || [];\n            exportFlows = exportFlows.map(cleanObject);\n            debugLog.exportFlowsCount = exportFlows.length;\n            debugLog.exportAllFlows = exportAllFlows;\n\n            // 查询工作流节点数据\n            if (exportFlows.length > 0) {\n                // 收集实际导出的工作流Id列表\n                var actualFlowIds = exportFlows.map(function (flow) { return flow.Id; });\n                debugLog.actualFlowIds = actualFlowIds;\n                // 获取 wf_node 所有字段 START\n                var wfNodeTableModel = someTableList.find(item => item.Name && item.Name.toLowerCase() == \'wf_node\');\n                var wfNodeTableId = wfNodeTableModel.Id;\n                var wfNodeFields = someFieldList.filter(item => item.TableId == wfNodeTableId);\n                var wfNodeFieldNames = wfNodeFields.map(item => {\n                    return item.Name;\n                });\n                if (wfNodeFieldNames.indexOf(\'Id\') <= -1) {\n                    wfNodeFieldNames.push(\'Id\');\n                }\n                if (wfNodeFieldNames.indexOf(\'CreateTime\') <= -1) {\n                    wfNodeFieldNames.push(\'CreateTime\');\n                }\n                // 获取 wf_node 所有字段 END\n\n                var nodesResult = V8.FormEngine.GetTableData(\'wf_node\', {\n                    _SelectFields: wfNodeFieldNames,\n                    _Where: [\n                        [\'FlowDesignId\', \'In\', JSON.stringify(actualFlowIds)]\n                    ],\n                });\n\n                if (nodesResult.Code == 1) {\n                    exportNodes = nodesResult.Data || [];\n                    exportNodes = exportNodes.map(cleanObject);\n                    debugLog.exportNodesCount = exportNodes.length;\n                }\n\n                // 获取 wf_line 所有字段 START\n                var wfLineTableModel = someTableList.find(item => item.Name && item.Name.toLowerCase() == \'wf_line\');\n                var wfLineTableId = wfLineTableModel.Id;\n                var wfLineFields = someFieldList.filter(item => item.TableId == wfLineTableId);\n                var wfLineFieldNames = wfLineFields.map(item => {\n                    return item.Name;\n                });\n                if (wfLineFieldNames.indexOf(\'Id\') <= -1) {\n                    wfLineFieldNames.push(\'Id\');\n                }\n                if (wfLineFieldNames.indexOf(\'CreateTime\') <= -1) {\n                    wfLineFieldNames.push(\'CreateTime\');\n                }\n                // 获取 wf_line 所有字段 END\n\n                // 查询工作流连线数据\n                var linesResult = V8.FormEngine.GetTableData(\'wf_line\', {\n                    _SelectFields: wfLineFieldNames,\n                    _Where: [\n                        [\'FlowDesignId\', \'In\', JSON.stringify(actualFlowIds)]\n                    ],\n                });\n\n                if (linesResult.Code == 1) {\n                    exportLines = linesResult.Data || [];\n                    exportLines = exportLines.map(cleanObject);\n                    debugLog.exportLinesCount = exportLines.length;\n                }\n            }\n        }\n    }\n\n    // ==================== 步骤7：查询接口引擎数据（可选） ====================\n\n    var exportApiEngines = [];\n\n    if (hasApiEngineKeys) {\n        // 获取 sys_apiengine 所有字段 START\n        var sysApiEngineTableModel = someTableList.find(item => item.Name && item.Name.toLowerCase() == \'sys_apiengine\');\n        if (sysApiEngineTableModel) {\n            var sysApiEngineTableId = sysApiEngineTableModel.Id;\n            var sysApiEngineFields = someFieldList.filter(item => item.TableId == sysApiEngineTableId);\n            var sysApiEngineFieldNames = sysApiEngineFields.map(item => {\n                return item.Name;\n            });\n            if (sysApiEngineFieldNames.indexOf(\'Id\') <= -1) {\n                sysApiEngineFieldNames.push(\'Id\');\n            }\n            if (sysApiEngineFieldNames.indexOf(\'ApiEngineKey\') <= -1) {\n                sysApiEngineFieldNames.push(\'ApiEngineKey\');\n            }\n            if (sysApiEngineFieldNames.indexOf(\'CreateTime\') <= -1) {\n                sysApiEngineFieldNames.push(\'CreateTime\');\n            }\n            // 获取 sys_apiengine 所有字段 END\n\n            // 检查是否要导出所有接口引擎\n            var exportAllApiEngines = ApiEngineKeys.length == 1 && ApiEngineKeys[0] == \'*\';\n\n            // 查询接口引擎数据\n            var apiEnginesWhere = [];\n            if (!exportAllApiEngines) {\n                // 只导出指定的接口引擎\n                apiEnginesWhere.push([\'ApiEngineKey\', \'In\', JSON.stringify(ApiEngineKeys)]);\n            }\n            // 如果是导出所有接口引擎，不添加Where条件\n\n            var apiEnginesResult = V8.FormEngine.GetTableData(\'sys_apiengine\', {\n                _SelectFields: sysApiEngineFieldNames,\n                _Where: apiEnginesWhere.length > 0 ? apiEnginesWhere : undefined,\n            });\n\n            if (apiEnginesResult.Code == 1) {\n                exportApiEngines = apiEnginesResult.Data || [];\n                exportApiEngines = exportApiEngines.map(cleanObject);\n                debugLog.exportApiEnginesCount = exportApiEngines.length;\n                debugLog.exportAllApiEngines = exportAllApiEngines;\n            }\n        } else {\n            debugLog.apiEngineTableNotFound = \'sys_apiengine表定义未找到\';\n        }\n    }\n\n    // ==================== 步骤8：组装数据包 ====================\n\n    var packageData = {\n        PackageInfo: {\n            Name: PackageName,\n            Version: PackageVersion,\n            CreateTime: new Date().toISOString(),\n            CreateUser: V8.CurrentUser.Name || \'未知\',\n            OsClient: V8.OsClient,\n            MenuCount: exportMenus.length,\n            TableCount: exportTables.length,\n            FieldCount: exportFields.length,\n            FlowCount: exportFlows.length,\n            NodeCount: exportNodes.length,\n            LineCount: exportLines.length,\n            DDLCount: ddlStatements.length,\n            ApiEngineCount: exportApiEngines.length\n        },\n        DDLStatements: ddlStatements,  // DDL语句数组\n        SysMenus: exportMenus,\n        DiyTables: exportTables,\n        DiyFields: exportFields\n    };\n\n    // 只有在有工作流数据时才添加\n    if (exportFlows.length > 0) {\n        packageData.WfFlowDesigns = exportFlows;\n        packageData.WfNodes = exportNodes;\n        packageData.WfLines = exportLines;\n    }\n\n    // 只有在有接口引擎数据时才添加\n    if (exportApiEngines.length > 0) {\n        packageData.SysApiEngines = exportApiEngines;\n    }\n\n    debugLog.endTime = new Date().toISOString();\n    debugLog.packageSize = JSON.stringify(packageData).length;\n\n    // ==================== 返回结果 ====================\n\n    return {\n        Code: 1,\n        Data: packageData,\n        Msg: \'导出成功\',\n        Debug: isDebug ? debugLog : undefined\n    };\n\n} catch (error) {\n    // ==================== 异常处理 ====================\n\n    debugLog.error = {\n        message: error.message,\n        stack: error.stack,\n        endTime: new Date().toISOString()\n    };\n\n    return {\n        Code: 0,\n        Msg: \'导出失败：\' + error.message,\n        Debug: isDebug ? debugLog : undefined\n    };\n}\n', b'0', '', '', '', '', '/apiengine/export-microi-store-package', b'0', '[]', 0, '系统', 0, 0, '', '', 600, 100000000, 2048, 10000);
INSERT INTO `sys_apiengine` VALUES ('01KGFFG74EZAS9VQTXZKD59X89', '2026-02-02 23:29:18', '2026-04-07 01:10:31', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '[系统]应用商城导入数据包', 'import-microi-store-package', b'1', '[]', '/**\n * 导入应用数据包接口引擎（B系统）\n * v2026-04-05 16:00\n * 功能：导入应用数据包，根据Id判断新增或修改\n * \n * 业务逻辑：\n * 1. 接收应用数据包\n * 2. 解析数据包中的各类数据\n * 3. 依次处理：diy_table -> diy_field -> sys_menu -> wf_flowdesign -> wf_node -> sys_apiengine\n * 4. 每条数据根据判断规则决定新增或修改：\n *    - diy_table: 根据 Id 和 Name 判断（不修改 Id 和 Name）\n *    - sys_apiengine: 根据 Id 或 ApiEngineKey 判断（不修改 Id 和 ApiEngineKey）\n *    - 其他表: 根据 Id 判断\n * 5. 使用事务保证数据一致性\n * \n * 说明：\n * - 支持导出接口通过 TableIds 额外传入的表（与MenuIds中的表合并去重后一起导出）\n * - 支持导出接口自动发现的子表控件（TableChild）关联的菜单和表\n * - 上述额外的表数据已包含在 DiyTables、DiyFields、DDLStatements 中，导入时统一处理\n * \n * 接口配置：\n * - ApiEngineKey: import-microi-store-package\n * - ApiAddress: /apiengine/import-microi-store-package\n * - 允许匿名调用: 否\n * - 分布式锁: 是（防止并发导入）\n * \n * 前端调用示例：\n * V8.ApiEngine.Run(\'import-microi-store-package\', {\n *   Package: packageData  // 从export-microi-store-package接口导出的数据包\n * })\n * \n * 返回格式：\n * {\n *   Code: 1,\n *   Data: {\n *     MenuInserted: 5,\n *     MenuUpdated: 3,\n *     TableInserted: 2,\n *     TableUpdated: 1,\n *     FieldInserted: 50,\n *     FieldUpdated: 20,\n *     FlowInserted: 1,\n *     FlowUpdated: 0,\n *     NodeInserted: 10,\n *     NodeUpdated: 5,\n *     LineInserted: 8,\n *     LineUpdated: 3,\n *     ApiEngineInserted: 3,\n *     ApiEngineUpdated: 2\n *   },\n *   Msg: \'导入成功\'\n * }\n */\n\n// ==================== 参数接收与校验 ====================\n\nvar Package = V8.Param.Package;  // 应用数据包\nvar InstallParentSysMenuId = V8.Param.InstallParentSysMenuId;  // 安装在哪个父级系统菜单Id下\n\n// 执行日志收集（用于最终构建中文报告）\nvar debugLog = {};\n\n// 参数校验\nif (!Package) {\n    return {\n        Code: 0,\n        Msg: \'参数错误：Package不能为空\'\n    };\n}\nif (typeof (Package) == \'string\') {\n    Package = JSON.parse(Package);\n}\n\nif (!Package.PackageInfo) {\n    return {\n        Code: 0,\n        Msg: \'参数错误：Package.PackageInfo不能为空\'\n    };\n}\n\ntry {\n    debugLog.startTime = new Date().toISOString();\n    debugLog.packageInfo = Package.PackageInfo;\n\n    // ==================== 辅助函数：判断数据是否存在 ====================\n\n    var checkExists = function (tableName, id) {\n        var result = V8.FormEngine.GetFormData(tableName, {\n            OsClient: V8.OsClient,\n            Id: id\n        });\n        return result.Code == 1 && result.Data;\n    };\n\n    // ==================== 统计变量 ====================\n\n    var stats = {\n        TableInserted: 0,\n        TableUpdated: 0,\n        FieldInserted: 0,\n        FieldUpdated: 0,\n        MenuInserted: 0,\n        MenuUpdated: 0,\n        FlowInserted: 0,\n        FlowUpdated: 0,\n        NodeInserted: 0,\n        NodeUpdated: 0,\n        LineInserted: 0,\n        LineUpdated: 0,\n        ApiEngineInserted: 0,\n        ApiEngineUpdated: 0\n    };\n\n    // ==================== 步骤0：执行DDL创建表和字段 ====================\n\n    debugLog.step0 = \'开始执行DDL创建表\';\n\n    var ddlStatements = Package.DDLStatements || [];\n    var ddlExecuted = 0;\n    var ddlSkipped = 0;\n    var fieldsAdded = 0;\n\n    // 定义审计字段（与export-package.js保持一致）\n    var fixedDiyField = [\n        { Name: \"Id\", Label: \"Id\", Type: \"varchar(36)\", Component: \"Guid\", Sort: 1, Visible: 0, TableWidth: 150 },\n        { Name: \"CreateTime\", Label: \"创建时间\", Type: \"datetime\", Component: \"DateTime\", Sort: 2, Visible: 1, TableWidth: 150 },\n        { Name: \"UpdateTime\", Label: \"修改时间\", Type: \"datetime\", Component: \"DateTime\", Sort: 3, Visible: 1, TableWidth: 150 },\n        { Name: \"UserId\", Label: \"创建人Id\", Type: \"varchar(36)\", Component: \"Guid\", Sort: 4, Visible: 0, TableWidth: 150 },\n        { Name: \"UserName\", Label: \"创建人\", Type: \"varchar(255)\", Component: \"Text\", Sort: 5, Visible: 1, TableWidth: 150 },\n        { Name: \"IsDeleted\", Label: \"是否已删除\", Type: \"int\", Component: \"Switch\", Sort: 6, Visible: 0, TableWidth: 50 }\n    ];\n\n    // MySQL类型映射函数（与导出保持一致）\n    var mapToMySQLType = function (diyType) {\n        if (!diyType) return \'varchar(255)\';\n\n        // 安全转换为字符串并小写\n        var typeStr = \'\';\n        try {\n            typeStr = String.prototype.toLowerCase.call(String(diyType));\n        } catch (e) {\n            return \'varchar(255)\';\n        }\n\n        if (typeStr.match(/^(varchar|int|bigint|datetime|text|longtext|decimal|double|float|tinyint|date|time|timestamp|json)\\(/)) {\n            return String(diyType);\n        }\n        if (typeStr == \'int\' || typeStr == \'bigint\' || typeStr == \'text\' || typeStr == \'mediumtext\' || typeStr == \'longtext\' ||\n            typeStr == \'datetime\' || typeStr == \'date\' || typeStr == \'time\' || typeStr == \'timestamp\' ||\n            typeStr == \'json\' || typeStr == \'tinyint\' || typeStr == \'double\' || typeStr == \'float\') {\n            return String(diyType);\n        }\n\n        if (typeStr.indexOf(\'mediumtext\') == 0) return String(diyType);\n        if (typeStr.indexOf(\'varchar\') == 0) return String(diyType);\n        if (typeStr.indexOf(\'decimal\') == 0) return String(diyType);\n\n        return \'varchar(255)\';\n    };\n\n    for (var i = 0; i < ddlStatements.length; i++) {\n        var ddlItem = ddlStatements[i];\n        if (!ddlItem.DDL || !ddlItem.TableName) continue;\n\n        var tableCreated = false;\n\n        try {\n            // 先尝试创建表（CREATE TABLE IF NOT EXISTS）\n            V8.Db.FromSql(ddlItem.DDL).ExecuteNonQuery();\n            tableCreated = true;\n            ddlExecuted++;\n            debugLog[\'ddl_create_\' + ddlItem.TableName] = \'表创建成功\';\n        } catch (ddlError) {\n            // 创建失败（表可能已存在）\n            debugLog[\'ddl_create_error_\' + ddlItem.TableName] = ddlError.message;\n            ddlSkipped++;\n        }\n\n        // 无论表是新创建还是已存在，都检查并补充缺失的字段\n        try {\n            // 查询表的所有字段\n            var checkColumnsSQL = \"SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = \'\" + ddlItem.TableName + \"\'\";\n            var columnsData = V8.Db.FromSql(checkColumnsSQL).ToArray();\n\n            if (!columnsData || columnsData.length == 0) {\n                debugLog[\'ddl_check_columns_\' + ddlItem.TableName] = \'表不存在或查询字段失败\';\n                continue;\n            }\n\n            var existingColumns = {};\n            for (var c = 0; c < columnsData.length; c++) {\n                try {\n                    var colName = columnsData[c].COLUMN_NAME;\n                    if (colName != null && colName !== undefined) {\n                        // 使用String.prototype确保安全\n                        var colNameStr = String.prototype.toLowerCase.call(String(colName));\n                        existingColumns[colNameStr] = true;\n                    }\n                } catch (e) {\n                    debugLog[\'field_parse_error_\' + ddlItem.TableName + \'_\' + c] = \'Column: \' + JSON.stringify(columnsData[c]) + \', Error: \' + e.message;\n                }\n            }\n\n            // 获取该表应有的所有字段：合并审计字段和自定义字段\n            var diyFields = Package.DiyFields || [];\n            var tableFields = [];\n\n            // 1. 先添加审计字段（fixedDiyField）\n            for (var ff = 0; ff < fixedDiyField.length; ff++) {\n                tableFields.push(fixedDiyField[ff]);\n            }\n\n            // 2. 再添加该表的自定义字段（从Package.DiyFields中筛选）\n            // 排除已在fixedDiyField中的字段名（比较时忽略大小写，但保持原始大小写）\n            var fixedFieldNames = {};\n            for (var ff = 0; ff < fixedDiyField.length; ff++) {\n                if (fixedDiyField[ff].Name) {\n                    // 用小写作为key来判断重复，但不改变原始字段名\n                    var fixedNameKey = (\'\' + fixedDiyField[ff].Name).toLowerCase();\n                    fixedFieldNames[fixedNameKey] = true;\n                }\n            }\n\n            for (var f = 0; f < diyFields.length; f++) {\n                if (diyFields[f].TableId == ddlItem.TableId && diyFields[f].Name) {\n                    // 用小写key判断是否重复，但添加的是原始对象（保持大驼峰）\n                    var diyNameKey = (\'\' + diyFields[f].Name).toLowerCase();\n                    if (!fixedFieldNames[diyNameKey]) {\n                        tableFields.push(diyFields[f]);  // 保持原始大小写\n                    }\n                }\n            }\n\n            // 检查缺失的字段并添加\n            var fieldsAddedForTable = 0;\n            for (var f = 0; f < tableFields.length; f++) {\n                var field = tableFields[f];\n                var fieldName = field.Name;\n\n                if (!fieldName) continue;\n\n                // Type为空、null或\"1\"表示虚拟字段，不应存在于物理表\n                var fieldType = field.Type;\n                if (!fieldType || fieldType === \'\' || fieldType === \'1\' || fieldType === 1) {\n                    debugLog[\'field_virtual_\' + ddlItem.TableName + \'_\' + fieldName] = \'虚拟字段(Type=\' + fieldType + \')，跳过物理表同步\';\n                    continue;\n                }\n\n                // 转换为字符串确保安全 - 使用最安全的转换方式\n                var fieldNameStr = (\'\' + fieldName);\n\n                // MySQL字段名长度限制为64字符\n                if (fieldNameStr.length > 64) {\n                    debugLog[\'field_name_too_long_\' + ddlItem.TableName + \'_\' + fieldNameStr.substring(0, 30)] = \'字段名过长，已跳过：\' + fieldNameStr.length + \'字符\';\n                    continue;\n                }\n\n                // 字段已存在，跳过（忽略大小写）\n                try {\n                    if (existingColumns[fieldNameStr.toLowerCase()]) {\n                        continue;\n                    }\n                } catch (e) {\n                    debugLog[\'field_check_error_\' + ddlItem.TableName + \'_\' + fieldNameStr] = \'Error checking field: \' + e.message;\n                    continue;\n                }\n\n                var fieldType = mapToMySQLType(field.Type);\n                var alterSQL = \'ALTER TABLE `\' + ddlItem.TableName + \'` ADD COLUMN `\' + fieldName + \'` \' + fieldType;\n\n                // Id字段不允许NULL，其他字段允许NULL\n                if (fieldName == \'Id\') {\n                    alterSQL += \' NOT NULL PRIMARY KEY\';\n                } else {\n                    alterSQL += \' NULL\';\n                }\n\n                // 添加字段说明（COMMENT）\n                if (field.Label && field.Label !== fieldName) {\n                    // 转义单引号\n                    var comment = field.Label.replace(/\'/g, \"\'\'\");\n                    alterSQL += \" COMMENT \'\" + comment + \"\'\";\n                }\n\n                try {\n                    V8.Db.FromSql(alterSQL).ExecuteNonQuery();\n                    fieldsAdded++;\n                    fieldsAddedForTable++;\n                    debugLog[\'field_added_\' + ddlItem.TableName + \'_\' + fieldName] = \'字段已添加\';\n                } catch (alterError) {\n                    debugLog[\'field_add_error_\' + ddlItem.TableName + \'_\' + fieldName] = alterError.message;\n                }\n            }\n\n            if (fieldsAddedForTable > 0) {\n                debugLog[\'ddl_alter_\' + ddlItem.TableName] = \'添加了\' + fieldsAddedForTable + \'个字段\';\n            }\n\n        } catch (checkError) {\n            debugLog[\'ddl_check_error_\' + ddlItem.TableName] = checkError.message;\n        }\n    }\n\n    stats.DDLExecuted = ddlExecuted;\n    stats.DDLSkipped = ddlSkipped;\n    stats.FieldsAdded = fieldsAdded;\n    debugLog.step0Result = \'DDL执行完成：创建表\' + ddlExecuted + \'，跳过\' + ddlSkipped + \'，添加字段\' + fieldsAdded;\n\n    // ==================== 步骤1：处理diy_table数据 ====================\n\n    debugLog.step1 = \'开始处理diy_table数据\';\n\n    var diyTables = Package.DiyTables || [];\n\n    for (var i = 0; i < diyTables.length; i++) {\n        var table = diyTables[i];\n\n        if (!table.Id) {\n            debugLog[\'table_no_id_\' + i] = \'跳过无Id的表数据\';\n            continue;\n        }\n\n        // 根据Id和Name判断是否存在\n        var existsById = checkExists(\'diy_table\', table.Id);\n        var existsByName = false;\n\n        if (table.Name) {\n            var checkByNameResult = V8.FormEngine.GetFormData(\'diy_table\', {\n                OsClient: V8.OsClient,\n                _Where: [[\'Name\', \'=\', table.Name]],\n                _PageSize: 1\n            });\n            existsByName = checkByNameResult.Code == 1 && checkByNameResult.Data;\n            //如果存在此tableName，但又不存在taleId，将此tableName的Id修改为应用商城的diy_table的Id\n            if (existsByName && !existsById) {\n                try {\n                    V8.Db.FromSql(\"UPDATE diy_table SET Id = \'\" + table.Id + \"\' WHERE Name = \'\" + table.Name + \"\' and IsDeleted<>1\")\n                        .ExecuteNonQuery();\n                } catch (error) {\n\n                }\n                try {\n                    V8.Db.FromSql(\"UPDATE diy_field SET TableId = \'\" + table.Id + \"\' WHERE TableId = \'\" + checkByNameResult.Data.Id + \"\' and IsDeleted<>1\")\n                        .ExecuteNonQuery();\n                } catch (error) {\n\n                }\n                try {\n                    V8.Db.FromSql(\"UPDATE sys_menu SET DiyTableId = \'\" + table.Id + \"\' WHERE DiyTableId = \'\" + checkByNameResult.Data.Id + \"\' and IsDeleted<>1\")\n                        .ExecuteNonQuery();\n                } catch (error) {\n\n                }\n\n                V8.Cache.Remove(`Microi:${V8.OsClient}:FormData:diy_table:${checkByNameResult.Data.Id.toLowerCase()}`);\n                V8.Cache.Remove(`Microi:${V8.OsClient}:FormData:diy_table:${checkByNameResult.Data.Name.toLowerCase()}`);\n                V8.Cache.Remove(`Microi:${V8.OsClient}:FormData:diy_table_field_list:${checkByNameResult.Data.Id}`);\n                V8.Cache.Remove(`Microi:${V8.OsClient}:FormData:diy_table_field_list:${checkByNameResult.Data.Name.toLowerCase()}`);\n            }\n        }\n\n        var exists = existsById || existsByName;\n        var modelCopy = {};\n        for (var key in table) {\n            modelCopy[key] = table[key];\n        }\n        modelCopy.OsClient = V8.OsClient;\n        modelCopy.Id = table.Id;\n        if (exists) {\n            var uptResult = V8.FormEngine.UptFormData(\'diy_table\', modelCopy);\n            if (uptResult.Code == 1) {\n                stats.TableUpdated++;\n            } else {\n                debugLog[\'table_upt_error_\' + table.Id] = uptResult.Msg;\n            }\n        } else {\n            // 不存在则新增\n            var addResult = V8.FormEngine.AddFormData(\'diy_table\', modelCopy);\n            if (addResult.Code == 1) {\n                stats.TableInserted++;\n            } else {\n                debugLog[\'table_add_error_\' + table.Id] = addResult.Msg;\n            }\n        }\n\n        //清除缓存\n        var delCaheResult1 = V8.Cache.Remove(`Microi:${V8.OsClient}:FormData:diy_table:${table.Id.toLowerCase()}`);\n        debugLog[\'delCaheResult1_\' + table.Id] = delCaheResult1;\n\n        var delCaheResult2 = V8.Cache.Remove(`Microi:${V8.OsClient}:FormData:diy_table:${table.Name.toLowerCase()}`);\n        debugLog[\'delCaheResult2_\' + table.Name] = delCaheResult2;\n\n        V8.Cache.Remove(`Microi:${V8.OsClient}:FormData:diy_table_field_list:${table.Id}`);\n        V8.Cache.Remove(`Microi:${V8.OsClient}:FormData:diy_table_field_list:${table.Name.toLowerCase()}`);\n    }\n\n    debugLog.step1Result = \'表数据处理完成：新增\' + stats.TableInserted + \'，修改\' + stats.TableUpdated;\n\n    // ==================== 步骤2：处理diy_field数据 ====================\n\n    debugLog.step2 = \'开始处理diy_field数据\';\n\n    var diyFields = Package.DiyFields || [];\n    debugLog.step2_totalFields = diyFields.length;\n    var fieldChanges = []; // 记录字段的变化（Name、Type、Label）\n\n    for (var i = 0; i < diyFields.length; i++) {\n        var field = diyFields[i];\n\n        // SelectApi 专项追踪\n        var isSelectApi = (field.Name === \'SelectApi\');\n        if (isSelectApi) {\n            debugLog[\'★SelectApi_found_at_index\'] = i;\n            debugLog[\'★SelectApi_Id\'] = field.Id;\n            debugLog[\'★SelectApi_TableId\'] = field.TableId;\n        }\n\n        if (!field.Id) {\n            debugLog[\'field_no_id_\' + i] = \'跳过无Id的字段数据\';\n            continue;\n        }\n\n        var exists = checkExists(\'diy_field\', field.Id);\n        if (isSelectApi) {\n            debugLog[\'★SelectApi_existsById\'] = exists;\n        }\n\n        if (!exists) {\n            //判断根据Name和TableId是否存在，如果存在，则需要将Id改到以应用商城的为准\n            var checkByNameResult = V8.FormEngine.GetFormData(\'diy_field\', {\n                OsClient: V8.OsClient,\n                _Where: [\n                    [\'TableId\', \'=\', field.TableId],\n                    [\'Name\', \'=\', field.Name]\n                ]\n            });\n            if (isSelectApi) {\n                debugLog[\'★SelectApi_checkByName_Code\'] = checkByNameResult.Code;\n                debugLog[\'★SelectApi_checkByName_HasData\'] = !!(checkByNameResult.Data);\n            }\n            if (checkByNameResult.Code == 1) {\n                try {\n                    V8.Db.FromSql(\"UPDATE diy_field SET Id = \'\" + field.Id + \"\' WHERE TableId = \'\" + field.TableId + \"\' AND Name = \'\" + field.Name + \"\' and IsDeleted<>1\").ExecuteNonQuery();\n                } catch (error) {\n                    if (isSelectApi) {\n                        debugLog[\'★SelectApi_updateId_error\'] = error.message;\n                    }\n                }\n                V8.Cache.Remove(`Microi:${V8.OsClient}:FormData:diy_table_field_list:${field.TableId.toLowerCase()}`);\n                exists = true;\n            }\n        }\n\n        if (exists) {\n            // 存在则修改 - 先查询旧数据，记录变化\n            var oldFieldResult = V8.FormEngine.GetFormData(\'diy_field\', {\n                OsClient: V8.OsClient,\n                Id: field.Id\n            });\n            if (oldFieldResult.Code == 1 && oldFieldResult.Data) {\n                var oldField = oldFieldResult.Data;\n                var hasChange = false;\n                var changeInfo = {\n                    Id: field.Id,\n                    TableName: oldField.TableName, // 使用旧的TableName\n                    OldName: oldField.Name,\n                    NewName: field.Name,\n                    OldType: oldField.Type,\n                    NewType: field.Type,\n                    OldLabel: oldField.Label,\n                    NewLabel: field.Label\n                };\n\n                // 检测是否有变化\n                if (oldField.Name != field.Name) {\n                    hasChange = true;\n                    debugLog[\'field_name_changed_\' + field.Id] = oldField.Name + \' → \' + field.Name;\n                }\n                if (oldField.Type != field.Type) {\n                    hasChange = true;\n                    debugLog[\'field_type_changed_\' + field.Id] = oldField.Type + \' → \' + field.Type;\n                }\n                if (oldField.Label != field.Label) {\n                    hasChange = true;\n                }\n\n                if (hasChange) {\n                    fieldChanges.push(changeInfo);\n                }\n            }\n\n            // 创建副本，避免污染原始数据（步骤2.5需要用到TableId）\n            var fieldCopy = {};\n            for (var key in field) {\n                fieldCopy[key] = field[key];\n            }\n            fieldCopy.OsClient = V8.OsClient;\n            fieldCopy.Id = field.Id;\n            fieldCopy.NameConfirm = 1;\n\n            // 检测僵尸记录：由旧版 _FormData wrapper bug 创建，Name/TableId/OsClient 均为 null\n            // FormEngine.UptFormData 内部走 UptDiyField → ChangeColumn(from=null, to=Name)，\n            // 这条路径对 null→非null 的字段名变更有副作用，改为直接 SQL 全量覆盖\n            var isZombieRecord = (oldFieldResult.Code == 1 && oldFieldResult.Data &&\n                (!oldFieldResult.Data.OsClient || !oldFieldResult.Data.Name || !oldFieldResult.Data.TableId));\n\n            if (isSelectApi) {\n                debugLog[\'★SelectApi_isZombieRecord\'] = isZombieRecord;\n                debugLog[\'★SelectApi_fieldCopy_Name\'] = fieldCopy.Name;\n                debugLog[\'★SelectApi_fieldCopy_OsClient\'] = fieldCopy.OsClient;\n                debugLog[\'★SelectApi_oldData_Name\'] = oldFieldResult.Data ? oldFieldResult.Data.Name : null;\n                debugLog[\'★SelectApi_oldData_TableId\'] = oldFieldResult.Data ? oldFieldResult.Data.TableId : null;\n            }\n\n            if (isZombieRecord) {\n                // 僵尸记录：用直接 SQL 全量覆盖所有字段\n                // 使用 sqle()/sqln() 转义，0个SQL参数，彻底绕过 Jint 的 params object[] 限制\n                var sqle = function(s) { return s == null ? \'NULL\' : \"\'\" + String(s).replace(/\'/g, \"\'\'\") + \"\'\"; };\n                var sqln = function(n) { return n == null ? \'NULL\' : Number(n); };\n                try {\n                    var rawSql = \"UPDATE diy_field SET \" +\n                        \"TableId=\" + sqle(fieldCopy.TableId) + \",\" +\n                        \"TableName=\" + sqle(fieldCopy.TableName) + \",\" +\n                        \"Name=\" + sqle(fieldCopy.Name) + \",\" +\n                        \"Label=\" + sqle(fieldCopy.Label) + \",\" +\n                        \"Type=\" + sqle(fieldCopy.Type) + \",\" +\n                        \"Component=\" + sqle(fieldCopy.Component) + \",\" +\n                        \"Sort=\" + sqln(fieldCopy.Sort) + \",\" +\n                        \"Visible=\" + sqln(fieldCopy.Visible) + \",\" +\n                        \"Readonly=\" + sqln(fieldCopy.Readonly) + \",\" +\n                        \"NotEmpty=\" + sqln(fieldCopy.NotEmpty) + \",\" +\n                        \"Tab=\" + sqle(fieldCopy.Tab) + \",\" +\n                        \"FormWidth=\" + sqln(fieldCopy.FormWidth) + \",\" +\n                        \"TableWidth=\" + sqln(fieldCopy.TableWidth) + \",\" +\n                        \"Config=\" + sqle(fieldCopy.Config) + \",\" +\n                        \"Data=\" + sqle(fieldCopy.Data) + \",\" +\n                        \"`Unique`=\" + sqln(fieldCopy.Unique) + \",\" +\n                        \"Placeholder=\" + sqle(fieldCopy.Placeholder) + \",\" +\n                        \"BindRole=\" + sqle(fieldCopy.BindRole) + \",\" +\n                        \"InTableEdit=\" + sqln(fieldCopy.InTableEdit) + \",\" +\n                        \"IsLockField=\" + sqln(fieldCopy.IsLockField) + \",\" +\n                        \"Encrypt=\" + sqln(fieldCopy.Encrypt) + \",\" +\n                        \"AppVisible=\" + sqln(fieldCopy.AppVisible) + \",\" +\n                        \"NameConfirm=1,\" +\n                        \"OsClient=\" + sqle(V8.OsClient) + \",\" +\n                        \"IsDeleted=0,\" +\n                        \"UpdateTime=NOW() \" +\n                        \"WHERE Id=\'\" + field.Id + \"\'\";\n                    var zombieRawCount = V8.Db.FromSql(rawSql).ExecuteNonQuery();\n                    if (isSelectApi) {\n                        debugLog[\'★SelectApi_zombieRawCount\'] = zombieRawCount;\n                    }\n                    if (zombieRawCount > 0) {\n                        stats.FieldUpdated++;\n                    } else {\n                        // 影响0行，说明记录根本不存在，改为新增\n                        var addFallback2 = V8.FormEngine.AddFormData(\'diy_field\', fieldCopy);\n                        if (addFallback2.Code == 1) {\n                            stats.FieldInserted++;\n                        } else {\n                            debugLog[\'field_zombie_add_error_\' + field.Id] = addFallback2.Msg;\n                        }\n                    }\n                } catch(zombieRawErr) {\n                    debugLog[\'field_zombie_raw_error_\' + field.Id] = zombieRawErr.message;\n                }\n            } else {\n                // 正常记录：使用 FormEngine 更新（默认不触发V8事件）\n                var uptResult = V8.FormEngine.UptFormData(\'diy_field\', fieldCopy);\n                if (isSelectApi) {\n                    debugLog[\'★SelectApi_uptResult_Code\'] = uptResult.Code;\n                    debugLog[\'★SelectApi_uptResult_Msg\'] = uptResult.Msg || \'\';\n                }\n                if (uptResult.Code == 1) {\n                    stats.FieldUpdated++;\n                } else {\n                    // 更新失败：可能被软删(IsDeleted=1)，先修复再重试\n                    try {\n                        V8.Db.FromSql(\"UPDATE diy_field SET IsDeleted=0, OsClient=\'\" + V8.OsClient + \"\' WHERE Id=\'\" + field.Id + \"\'\").ExecuteNonQuery();\n                    } catch(fixErr) {\n                        debugLog[\'field_fix_isdeleted_error_\' + field.Id] = fixErr.message;\n                    }\n                    var uptRetryResult = V8.FormEngine.UptFormData(\'diy_field\', fieldCopy);\n                    if (uptRetryResult.Code == 1) {\n                        stats.FieldUpdated++;\n                    } else {\n                        var addFallback = V8.FormEngine.AddFormData(\'diy_field\', fieldCopy);\n                        if (addFallback.Code == 1) {\n                            stats.FieldInserted++;\n                        } else {\n                            debugLog[\'field_upt_error_\' + field.Id] = uptRetryResult.Msg + \' | addFallback:\' + addFallback.Msg;\n                        }\n                    }\n                }\n            }\n        } else {\n            var fieldCopy = {};\n            for (var key in field) {\n                fieldCopy[key] = field[key];\n            }\n            fieldCopy.OsClient = V8.OsClient;\n            fieldCopy.Id = field.Id;\n            // 不存在则新增\n            var addResult = V8.FormEngine.AddFormData(\'diy_field\', fieldCopy);\n            if (isSelectApi) {\n                debugLog[\'★SelectApi_action\'] = \'AddFormData\';\n                debugLog[\'★SelectApi_addResult_Code\'] = addResult.Code;\n                debugLog[\'★SelectApi_addResult_Msg\'] = addResult.Msg || \'\';\n                debugLog[\'★SelectApi_fieldCopy_keys\'] = Object.keys(fieldCopy).join(\',\');\n                debugLog[\'★SelectApi_fieldCopy_Name\'] = fieldCopy.Name;\n            }\n            if (addResult.Code == 1) {\n                stats.FieldInserted++;\n            } else {\n                debugLog[\'field_add_error_\' + field.Id] = addResult.Msg;\n            }\n\n        }\n    }\n\n    for (var i = 0; i < diyTables.length; i++) {\n        var table = diyTables[i];\n\n        if (!table.Id) {\n            debugLog[\'table_no_id_\' + i] = \'跳过无Id的表数据\';\n            continue;\n        }\n        //清除缓存\n        V8.Cache.Remove(`Microi:${V8.OsClient}:FormData:diy_table_field_list:${table.Id}`);\n        V8.Cache.Remove(`Microi:${V8.OsClient}:FormData:diy_table_field_list:${table.Name.toLowerCase()}`);\n    }\n\n    debugLog.step2Result = \'字段数据处理完成：新增\' + stats.FieldInserted + \'，修改\' + stats.FieldUpdated + \'，检测到\' + fieldChanges.length + \'个字段变化\';\n\n    // SelectApi 执行后验证\n    try {\n        var verifySelectApi = V8.FormEngine.GetFormData(\'diy_field\', {\n            OsClient: V8.OsClient,\n            _Where: [\n                [\'TableId\', \'=\', \'1d28e502-70ea-4a2b-9793-699b3f42234e\'],\n                [\'Name\', \'=\', \'SelectApi\']\n            ]\n        });\n        debugLog[\'★SelectApi_verify_Code\'] = verifySelectApi.Code;\n        if (verifySelectApi.Code == 1 && verifySelectApi.Data) {\n            debugLog[\'★SelectApi_verify\'] = \'✅ 存在于diy_field，Id=\' + verifySelectApi.Data.Id + \', Name=\' + verifySelectApi.Data.Name;\n        } else {\n            // 再按Id查一次\n            var verifyById = V8.FormEngine.GetFormData(\'diy_field\', {\n                OsClient: V8.OsClient,\n                Id: \'01KGE0ZVAK801D2F3K1MWRMNTV\'\n            });\n            if (verifyById.Code == 1 && verifyById.Data) {\n                debugLog[\'★SelectApi_verify\'] = \'⚠️ Id存在但Name不匹配，当前Name=\' + verifyById.Data.Name + \', Type=\' + verifyById.Data.Type + \', TableId=\' + verifyById.Data.TableId;\n            } else {\n                debugLog[\'★SelectApi_verify\'] = \'❌ diy_field中不存在（按Name和Id均未找到）\';\n                debugLog[\'★SelectApi_verifyById_Code\'] = verifyById.Code;\n                debugLog[\'★SelectApi_verifyById_Msg\'] = verifyById.Msg || \'\';\n            }\n        }\n    } catch (verifyError) {\n        debugLog[\'★SelectApi_verify_error\'] = verifyError.message;\n    }\n\n    // ==================== 步骤2.5：同步物理表字段（补充所有表的缺失字段） ====================\n\n    debugLog.step2_5 = \'开始同步物理表字段\';\n\n    var physicalFieldsAdded = 0;\n    var physicalFieldsRenamed = 0;\n    var physicalFieldsModified = 0;\n    var diyTables = Package.DiyTables || [];\n    var diyFields = Package.DiyFields || [];\n\n    // 辅助函数：判断字段Type是否为虚拟字段\n    var isVirtualFieldType = function (fieldType) {\n        return !fieldType || fieldType === \'\' || fieldType === \'1\' || fieldType === 1;\n    };\n\n    // 阶段0：执行字段变更（重命名、修改类型/注释）\n    debugLog.step2_5_phase0 = \'开始处理字段变更\';\n    for (var i = 0; i < fieldChanges.length; i++) {\n        var change = fieldChanges[i];\n        if (!change.TableName || !change.OldName || !change.NewName) continue;\n\n        // 如果新Type或旧Type是虚拟字段，跳过物理表变更\n        // 新Type是虚拟：不需要修改物理列\n        // 旧Type是虚拟：物理列本就不存在，无法修改（缺失的物理字段由phase1/2处理添加）\n        if (isVirtualFieldType(change.NewType) || isVirtualFieldType(change.OldType)) {\n            debugLog[\'change_skip_virtual_\' + change.TableName + \'_\' + change.NewName] = \'虚拟字段(OldType=\' + change.OldType + \', NewType=\' + change.NewType + \')，跳过物理表变更\';\n            continue;\n        }\n\n        var tableName = change.TableName;\n        var oldName = change.OldName;\n        var newName = change.NewName;\n        var newType = mapToMySQLType(change.NewType);\n        var newLabel = change.NewLabel;\n\n        try {\n            // 如果字段名发生变化，执行重命名\n            if (oldName != newName) {\n                // MySQL 重命名字段语法：ALTER TABLE table CHANGE COLUMN old_name new_name type\n                var renameSQL = \'ALTER TABLE `\' + tableName + \'` CHANGE COLUMN `\' + oldName + \'` `\' + newName + \'` \' + newType;\n\n                if (newName == \'Id\') {\n                    renameSQL += \' NOT NULL PRIMARY KEY\';\n                } else {\n                    renameSQL += \' NULL\';\n                }\n\n                if (newLabel && newLabel !== newName) {\n                    var comment = newLabel.replace(/\'/g, \"\'\'\");\n                    renameSQL += \" COMMENT \'\" + comment + \"\'\";\n                }\n\n                try {\n                    V8.Db.FromSql(renameSQL).ExecuteNonQuery();\n                    physicalFieldsRenamed++;\n                    debugLog[\'rename_\' + tableName + \'_\' + oldName] = \'重命名为 \' + newName;\n                } catch (renameError) {\n                    debugLog[\'rename_error_\' + tableName + \'_\' + oldName] = renameError.message;\n                }\n            }\n            // 如果只是类型或注释变化，执行修改\n            else if (change.OldType != change.NewType || change.OldLabel != change.NewLabel) {\n                // MySQL 修改字段类型/注释：ALTER TABLE table MODIFY COLUMN field_name type\n                var modifySQL = \'ALTER TABLE `\' + tableName + \'` MODIFY COLUMN `\' + newName + \'` \' + newType;\n\n                if (newName == \'Id\') {\n                    modifySQL += \' NOT NULL PRIMARY KEY\';\n                } else {\n                    modifySQL += \' NULL\';\n                }\n\n                if (newLabel && newLabel !== newName) {\n                    var comment = newLabel.replace(/\'/g, \"\'\'\");\n                    modifySQL += \" COMMENT \'\" + comment + \"\'\";\n                }\n\n                try {\n                    V8.Db.FromSql(modifySQL).ExecuteNonQuery();\n                    physicalFieldsModified++;\n                    debugLog[\'modify_\' + tableName + \'_\' + newName] = \'类型/注释已修改\';\n                } catch (modifyError) {\n                    debugLog[\'modify_error_\' + tableName + \'_\' + newName] = modifyError.message;\n                }\n            }\n        } catch (changeError) {\n            debugLog[\'change_error_\' + tableName + \'_\' + oldName] = changeError.message;\n        }\n    }\n\n    // 阶段1：按TableId分组字段\n    var fieldsByTable = {};\n    for (var i = 0; i < diyFields.length; i++) {\n        var field = diyFields[i];\n        if (field.TableId && field.Name) {\n            if (!fieldsByTable[field.TableId]) {\n                fieldsByTable[field.TableId] = [];\n            }\n            fieldsByTable[field.TableId].push(field);\n        }\n    }\n\n    // 阶段2：遍历所有表，添加缺失字段\n    debugLog.step2_5_phase1 = \'开始添加缺失字段\';\n    for (var i = 0; i < diyTables.length; i++) {\n        var table = diyTables[i];\n        if (!table.Name || !table.Id) continue;\n\n        // 使用原始表名（保持大小写）\n        var tableName = table.Name;\n        var tableFields = fieldsByTable[table.Id] || [];\n\n        if (tableFields.length == 0) {\n            debugLog[\'sync_skip_\' + tableName] = \'无字段定义，跳过\';\n            continue;\n        }\n\n        try {\n            // 查询物理表的所有字段（不区分大小写），同时获取实际表名\n            var checkColumnsSQL = \"SELECT TABLE_NAME, COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND LOWER(TABLE_NAME) = LOWER(\'\" + tableName + \"\')\";\n            var columnsData = V8.Db.FromSql(checkColumnsSQL).ToArray();\n\n            if (!columnsData || columnsData.length == 0) {\n                debugLog[\'sync_table_not_exist_\' + tableName] = \'表不存在，跳过字段同步\';\n                continue;\n            }\n\n            // 获取实际的物理表名（安全转换）\n            var actualTableName = tableName;\n            try {\n                if (columnsData[0] && columnsData[0].TABLE_NAME) {\n                    actualTableName = String(columnsData[0].TABLE_NAME);\n                }\n            } catch (e) {\n                debugLog[\'sync_tablename_error_\' + tableName] = e.message;\n            }\n\n            // 构建已存在的字段Map（小写key）\n            var existingColumns = {};\n            var columnsCount = 0;\n            try {\n                columnsCount = Number(columnsData.length) || 0;\n            } catch (e) {\n                debugLog[\'sync_count_error_\' + tableName] = e.message;\n                continue;\n            }\n\n            for (var c = 0; c < columnsCount; c++) {\n                try {\n                    if (!columnsData[c]) continue;\n                    var colName = columnsData[c].COLUMN_NAME;\n                    if (colName != null && colName !== undefined) {\n                        // 使用最安全的方式转换\n                        var colNameStr = String(colName);\n                        var colNameLower = String.prototype.toLowerCase.call(colNameStr);\n                        existingColumns[colNameLower] = true;\n                    }\n                } catch (e) {\n                    debugLog[\'sync_parse_error_\' + tableName + \'_\' + c] = e.message;\n                }\n            }\n\n            // 检查并添加缺失的字段\n            var fieldsAddedForTable = 0;\n            for (var f = 0; f < tableFields.length; f++) {\n                try {\n                    var field = tableFields[f];\n                    if (!field) continue;\n\n                    var fieldName = field.Name;\n                    if (!fieldName) continue;\n\n                    // Type为空、null或\"1\"表示虚拟字段，不应存在于物理表\n                    var fieldType = field.Type;\n                    if (!fieldType || fieldType === \'\' || fieldType === \'1\' || fieldType === 1) {\n                        debugLog[\'sync_virtual_\' + tableName + \'_\' + fieldName] = \'虚拟字段(Type=\' + fieldType + \')，跳过物理表同步\';\n                        continue;\n                    }\n\n                    // 安全转换字段名\n                    var fieldNameStr = \'\';\n                    try {\n                        fieldNameStr = String(fieldName);\n                    } catch (e) {\n                        debugLog[\'sync_fieldname_convert_error_\' + tableName + \'_\' + f] = e.message;\n                        continue;\n                    }\n\n                    // MySQL字段名长度限制（安全检查）\n                    var fieldNameLength = 0;\n                    try {\n                        fieldNameLength = Number(fieldNameStr.length) || 0;\n                    } catch (e) {\n                        debugLog[\'sync_length_error_\' + tableName + \'_\' + f] = e.message;\n                        continue;\n                    }\n\n                    if (fieldNameLength > 64) {\n                        try {\n                            var shortName = String.prototype.substring.call(fieldNameStr, 0, 30);\n                            debugLog[\'sync_name_too_long_\' + tableName + \'_\' + shortName] = \'字段名过长：\' + fieldNameLength;\n                        } catch (e) {\n                            debugLog[\'sync_name_too_long_\' + tableName + \'_\' + f] = \'字段名过长：\' + fieldNameLength;\n                        }\n                        continue;\n                    }\n\n                    // 字段已存在，跳过（忽略大小写比较）\n                    var fieldNameLower = \'\';\n                    try {\n                        fieldNameLower = String.prototype.toLowerCase.call(fieldNameStr);\n                    } catch (e) {\n                        debugLog[\'sync_lowercase_error_\' + tableName + \'_\' + f] = e.message;\n                        continue;\n                    }\n\n                    if (existingColumns[fieldNameLower]) {\n                        continue;\n                    }\n                } catch (outerError) {\n                    debugLog[\'sync_field_loop_error_\' + tableName + \'_\' + f] = outerError.message;\n                    continue;\n                }\n\n                // 字段不存在，需要添加（使用实际的物理表名）\n                try {\n                    var fieldType = mapToMySQLType(field.Type);\n                    var alterSQL = \'ALTER TABLE `\' + actualTableName + \'` ADD COLUMN `\' + fieldNameStr + \'` \' + fieldType;\n\n                    // Id字段特殊处理\n                    if (fieldNameStr == \'Id\') {\n                        alterSQL += \' NOT NULL PRIMARY KEY\';\n                    } else {\n                        alterSQL += \' NULL\';\n                    }\n\n                    // 添加字段说明\n                    if (field.Label && field.Label !== fieldNameStr) {\n                        try {\n                            var comment = String(field.Label).replace(/\'/g, \"\'\'\");\n                            alterSQL += \" COMMENT \'\" + comment + \"\'\";\n                        } catch (e) {\n                            debugLog[\'sync_comment_error_\' + tableName + \'_\' + fieldNameStr] = e.message;\n                        }\n                    }\n\n                    try {\n                        V8.Db.FromSql(alterSQL).ExecuteNonQuery();\n                        physicalFieldsAdded++;\n                        fieldsAddedForTable++;\n                        debugLog[\'sync_added_\' + tableName + \'_\' + fieldNameStr] = \'字段已添加\';\n                    } catch (alterError) {\n                        debugLog[\'sync_add_error_\' + tableName + \'_\' + fieldNameStr] = alterError.message;\n                    }\n                } catch (buildSqlError) {\n                    debugLog[\'sync_buildsql_error_\' + tableName + \'_\' + f] = buildSqlError.message;\n                }\n            }\n\n            if (fieldsAddedForTable > 0) {\n                debugLog[\'sync_table_\' + tableName] = \'添加了\' + fieldsAddedForTable + \'个字段\';\n            }\n\n        } catch (checkError) {\n            debugLog[\'sync_error_\' + tableName] = checkError.message;\n        }\n    }\n\n    stats.PhysicalFieldsAdded = physicalFieldsAdded;\n    stats.PhysicalFieldsRenamed = physicalFieldsRenamed;\n    stats.PhysicalFieldsModified = physicalFieldsModified;\n    debugLog.step2_5Result = \'物理表字段同步完成：重命名\' + physicalFieldsRenamed + \'，修改\' + physicalFieldsModified + \'，新增\' + physicalFieldsAdded;\n\n    // ==================== 步骤3：处理sys_menu数据 ====================\n\n    debugLog.step3 = \'开始处理sys_menu数据\';\n\n    var sysMenus = Package.SysMenus || [];\n\n    // 按ParentId排序，确保父菜单先导入\n    var sortedMenus = [];\n    var menuMap = {};\n\n    for (var i = 0; i < sysMenus.length; i++) {\n        menuMap[sysMenus[i].Id] = sysMenus[i];\n    }\n\n    // 先导入没有ParentId的根菜单\n    for (var i = 0; i < sysMenus.length; i++) {\n        if (!sysMenus[i].ParentId || sysMenus[i].ParentId == null) {\n            sortedMenus.push(sysMenus[i]);\n        }\n    }\n\n    // 再导入有ParentId的子菜单\n    for (var i = 0; i < sysMenus.length; i++) {\n        if (sysMenus[i].ParentId && sysMenus[i].ParentId !== null) {\n            sortedMenus.push(sysMenus[i]);\n        }\n    }\n\n    for (var i = 0; i < sortedMenus.length; i++) {\n        var menu = sortedMenus[i];\n\n        if (!menu.Id) {\n            debugLog[\'menu_no_id_\' + i] = \'跳过无Id的菜单数据\';\n            continue;\n        }\n\n        var exists = checkExists(\'sys_menu\', menu.Id);\n\n        //如果传入了 InstallParentSysMenuId，并且当前菜单的ParentId并不存在于待导入的菜单中\n        if (InstallParentSysMenuId && sysMenus.findIndex(m => m.Id === menu.ParentId) === -1) {\n            //并且当前菜单的ParentId等于InstallParentSysMenuId，则将ParentId修改为新导入应用的根菜单Id\n            menu.ParentId = InstallParentSysMenuId;\n        }\n        //如果当前菜单的ParentId并不存在于待导入的菜单中，并且当前菜单的Id不存在于sys_menu表中，则置为顶级\n        else if (menu.ParentId\n            && menu.ParentId != \'00000000000000000000000000\'\n            && menu.ParentId != \'00000000-0000-0000-0000-000000000000\'\n            && sysMenus.findIndex(m => m.Id === menu.ParentId) === -1) {\n            var existsParent = checkExists(\'sys_menu\', menu.ParentId);\n            if (!existsParent) {\n                menu.ParentId = \'00000000000000000000000000\';\n            }\n        }\n        var modelCopy = {};\n        for (var key in menu) {\n            modelCopy[key] = menu[key];\n        }\n        modelCopy.OsClient = V8.OsClient;\n        modelCopy.Id = menu.Id;\n        if (exists) {\n            // 存在则修改\n            var uptResult = V8.FormEngine.UptFormData(\'sys_menu\', modelCopy);\n            if (uptResult.Code == 1) {\n                stats.MenuUpdated++;\n            } else {\n                debugLog[\'menu_upt_error_\' + menu.Id] = uptResult.Msg;\n            }\n        } else {\n            // 不存在则新增\n            var addResult = V8.FormEngine.AddFormData(\'sys_menu\', modelCopy);\n            if (addResult.Code == 1) {\n                stats.MenuInserted++;\n            } else if (addResult.Msg && addResult.Msg.indexOf(\'[Url]已存在唯一值\') > -1 && modelCopy.Url) {\n                // Url重复，自动追加后缀重试\n                var originalUrl = modelCopy.Url;\n                var urlCount = V8.Db.FromSql(\"SELECT COUNT(Id) FROM sys_menu WHERE Url=\'\" + originalUrl.replace(/\'/g, \"\'\'\") + \"\'\").ToScalar();\n                var newUrl = originalUrl + \'-\' + (Number(urlCount) + 1);\n                modelCopy.Url = newUrl;\n                debugLog[\'menu_url_retry_\' + menu.Id] = originalUrl + \' → \' + newUrl;\n                var retryResult = V8.FormEngine.AddFormData(\'sys_menu\', modelCopy);\n                if (retryResult.Code == 1) {\n                    stats.MenuInserted++;\n                } else {\n                    debugLog[\'menu_add_error_\' + menu.Id] = retryResult.Msg;\n                }\n            } else {\n                debugLog[\'menu_add_error_\' + menu.Id] = addResult.Msg;\n            }\n        }\n\n        //清除缓存\n        V8.Cache.Remove(`Microi:${V8.OsClient}:FormData:sys_menu:${menu.Id.toLowerCase()}`);\n        if (menu.ModuleEngineKey) {\n            V8.Cache.Remove(`Microi:${V8.OsClient}:FormData:sys_menu:${menu.ModuleEngineKey.toLowerCase()}`);\n        }\n    }\n\n    debugLog.step3Result = \'菜单数据处理完成：新增\' + stats.MenuInserted + \'，修改\' + stats.MenuUpdated;\n\n    // ==================== 步骤4：处理wf_flowdesign数据（可选） ====================\n\n    if (Package.WfFlowDesigns && Package.WfFlowDesigns.length > 0) {\n        debugLog.step4 = \'开始处理wf_flowdesign数据\';\n\n        var wfFlows = Package.WfFlowDesigns;\n\n        for (var i = 0; i < wfFlows.length; i++) {\n            var flow = wfFlows[i];\n\n            if (!flow.Id) {\n                debugLog[\'flow_no_id_\' + i] = \'跳过无Id的工作流数据\';\n                continue;\n            }\n\n            var exists = checkExists(\'wf_flowdesign\', flow.Id);\n            var modelCopy = {};\n            for (var key in flow) {\n                modelCopy[key] = flow[key];\n            }\n            modelCopy.OsClient = V8.OsClient;\n            modelCopy.Id = flow.Id;\n            if (exists) {\n                var uptResult = V8.FormEngine.UptFormData(\'wf_flowdesign\', modelCopy);\n                if (uptResult.Code == 1) {\n                    stats.FlowUpdated++;\n                } else {\n                    debugLog[\'flow_upt_error_\' + flow.Id] = uptResult.Msg;\n                }\n            } else {\n                // 不存在则新增\n                var addResult = V8.FormEngine.AddFormData(\'wf_flowdesign\', modelCopy);\n                if (addResult.Code == 1) {\n                    stats.FlowInserted++;\n                } else {\n                    debugLog[\'flow_add_error_\' + flow.Id] = addResult.Msg;\n                }\n            }\n        }\n\n        debugLog.step4Result = \'工作流数据处理完成：新增\' + stats.FlowInserted + \'，修改\' + stats.FlowUpdated;\n    }\n\n    // ==================== 步骤5：处理wf_node数据（可选） ====================\n\n    if (Package.WfNodes && Package.WfNodes.length > 0) {\n        debugLog.step5 = \'开始处理wf_node数据\';\n\n        var wfNodes = Package.WfNodes;\n\n        for (var i = 0; i < wfNodes.length; i++) {\n            var node = wfNodes[i];\n\n            if (!node.Id) {\n                debugLog[\'node_no_id_\' + i] = \'跳过无Id的节点数据\';\n                continue;\n            }\n\n            var exists = checkExists(\'wf_node\', node.Id);\n            var modelCopy = {};\n            for (var key in node) {\n                modelCopy[key] = node[key];\n            }\n            modelCopy.OsClient = V8.OsClient;\n            modelCopy.Id = node.Id;\n            if (exists) {\n                var uptResult = V8.FormEngine.UptFormData(\'wf_node\', modelCopy);\n                if (uptResult.Code == 1) {\n                    stats.NodeUpdated++;\n                } else {\n                    debugLog[\'node_upt_error_\' + node.Id] = uptResult.Msg;\n                }\n            } else {\n                // 不存在则新增\n                var addResult = V8.FormEngine.AddFormData(\'wf_node\', modelCopy);\n                if (addResult.Code == 1) {\n                    stats.NodeInserted++;\n                } else {\n                    debugLog[\'node_add_error_\' + node.Id] = addResult.Msg;\n                }\n            }\n        }\n\n        debugLog.step5Result = \'节点数据处理完成：新增\' + stats.NodeInserted + \'，修改\' + stats.NodeUpdated;\n    }\n\n    // ==================== 步骤6：处理wf_line数据（可选） ====================\n\n    if (Package.WfLines && Package.WfLines.length > 0) {\n        debugLog.step6 = \'开始处理wf_line数据\';\n\n        var wfLines = Package.WfLines;\n\n        for (var i = 0; i < wfLines.length; i++) {\n            var line = wfLines[i];\n\n            if (!line.Id) {\n                debugLog[\'line_no_id_\' + i] = \'跳过无Id的连线数据\';\n                continue;\n            }\n\n            var exists = checkExists(\'wf_line\', line.Id);\n            var modelCopy = {};\n            for (var key in line) {\n                modelCopy[key] = line[key];\n            }\n            modelCopy.OsClient = V8.OsClient;\n            modelCopy.Id = line.Id;\n            if (exists) {\n                // 存在则修改\n                var uptResult = V8.FormEngine.UptFormData(\'wf_line\', modelCopy);\n                if (uptResult.Code == 1) {\n                    stats.LineUpdated++;\n                } else {\n                    debugLog[\'line_upt_error_\' + line.Id] = uptResult.Msg;\n                }\n            } else {\n                // 不存在则新增\n                var addResult = V8.FormEngine.AddFormData(\'wf_line\', modelCopy);\n                if (addResult.Code == 1) {\n                    stats.LineInserted++;\n                } else {\n                    debugLog[\'line_add_error_\' + line.Id] = addResult.Msg;\n                }\n            }\n        }\n\n        debugLog.step6Result = \'连线数据处理完成：新增\' + stats.LineInserted + \'，修改\' + stats.LineUpdated;\n    }\n\n    // ==================== 步骤7：处理sys_apiengine数据（可选） ====================\n\n    if (Package.SysApiEngines && Package.SysApiEngines.length > 0) {\n        debugLog.step7 = \'开始处理sys_apiengine数据\';\n\n        var sysApiEngines = Package.SysApiEngines;\n\n        for (var i = 0; i < sysApiEngines.length; i++) {\n            var apiEngine = sysApiEngines[i];\n\n            if (!apiEngine.Id && !apiEngine.ApiEngineKey) {\n                debugLog[\'apiengine_no_id_key_\' + i] = \'跳过无Id和ApiEngineKey的接口引擎数据\';\n                continue;\n            }\n\n            // 根据Id或ApiEngineKey判断是否存在\n            var existsById = false;\n            var existsByKey = false;\n            var existingId = null;\n\n            if (apiEngine.Id) {\n                existsById = checkExists(\'sys_apiengine\', apiEngine.Id);\n                if (existsById) {\n                    existingId = apiEngine.Id;\n                }\n            }\n\n            if (!existsById && apiEngine.ApiEngineKey) {\n                var checkByKeyResult = V8.FormEngine.GetFormData(\'sys_apiengine\', {\n                    OsClient: V8.OsClient,\n                    _Where: [[\'ApiEngineKey\', \'=\', apiEngine.ApiEngineKey]],\n                    _PageSize: 1\n                });\n                existsByKey = checkByKeyResult.Code == 1 && checkByKeyResult.Data;\n                //如果存在ApiEngineKey，但不存在Id，将此ApiEngineKey的Id修改为应用商城的sys_apiengine的Id\n                if (existsByKey) {\n                    try {\n                        V8.Db.FromSql(\"UPDATE sys_apiengine SET Id = \'\" + apiEngine.Id + \"\' WHERE ApiEngineKey = \'\" + apiEngine.ApiEngineKey + \"\' and IsDeleted<>1\")\n                            .ExecuteNonQuery();\n                    } catch (error) {\n\n                    }\n\n                    //清除缓存\n                    V8.Cache.Remove(`Microi:${V8.OsClient}:FormData:sys_apiengine:${checkByKeyResult.Data.Id.toLowerCase()}`);\n                    V8.Cache.Remove(`Microi:${V8.OsClient}:FormData:sys_apiengine:${checkByKeyResult.Data.ApiEngineKey.toLowerCase()}`);\n                    existingId = apiEngine.Id;\n                }\n            }\n\n            var exists = existsById || existsByKey;\n            var modelCopy = {};\n            for (var key in apiEngine) {\n                modelCopy[key] = apiEngine[key];\n            }\n            modelCopy.OsClient = V8.OsClient;\n            modelCopy.Id = apiEngine.Id;\n            if (exists) {\n                var uptResult = V8.FormEngine.UptFormData(\'sys_apiengine\', modelCopy);\n                if (uptResult.Code == 1) {\n                    stats.ApiEngineUpdated++;\n                } else {\n                    debugLog[\'apiengine_upt_error_\' + existingId] = uptResult.Msg;\n                }\n            } else {\n                // 不存在则新增\n                var addResult = V8.FormEngine.AddFormData(\'sys_apiengine\', modelCopy);\n                if (addResult.Code == 1) {\n                    stats.ApiEngineInserted++;\n                } else {\n                    debugLog[\'apiengine_add_error_\' + (apiEngine.Id || apiEngine.ApiEngineKey)] = addResult.Msg;\n                }\n            }\n        }\n\n        debugLog.step7Result = \'接口引擎数据处理完成：新增\' + stats.ApiEngineInserted + \'，修改\' + stats.ApiEngineUpdated;\n    }\n\n    debugLog.endTime = new Date().toISOString();\n\n    // ==================== 构建中文执行日志 ====================\n\n    var errors = [];\n    for (var key in debugLog) {\n        if (key.indexOf(\'_error_\') > -1) {\n            errors.push({ 标识: key, 详情: debugLog[key] });\n        }\n    }\n\n    var urlRetries = [];\n    for (var key in debugLog) {\n        if (key.indexOf(\'_url_retry_\') > -1) {\n            urlRetries.push(debugLog[key]);\n        }\n    }\n\n    var pkgInfo = Package.PackageInfo || {};\n    var startTime = debugLog.startTime || \'\';\n    var endTime = debugLog.endTime || \'\';\n\n    var resultData = {\n        应用包信息: {\n            名称: pkgInfo.Name || \'未命名\',\n            版本: pkgInfo.Version || \'\',\n            来源租户: pkgInfo.OsClient || \'\',\n            创建人: pkgInfo.CreateUser || \'\',\n            创建时间: pkgInfo.CreateTime || \'\',\n            导入开始: startTime,\n            导入结束: endTime\n        },\n        执行概览: {\n            DDL建表: \'执行\' + (stats.DDLExecuted || 0) + \'条，跳过\' + (stats.DDLSkipped || 0) + \'条，补充物理字段\' + (stats.FieldsAdded || 0) + \'个\',\n            表结构: \'新增\' + stats.TableInserted + \'条，修改\' + stats.TableUpdated + \'条\',\n            字段定义: \'新增\' + stats.FieldInserted + \'条，修改\' + stats.FieldUpdated + \'条\',\n            物理字段同步: \'重命名\' + (stats.PhysicalFieldsRenamed || 0) + \'个，修改\' + (stats.PhysicalFieldsModified || 0) + \'个，新增\' + (stats.PhysicalFieldsAdded || 0) + \'个\',\n            菜单: \'新增\' + stats.MenuInserted + \'条，修改\' + stats.MenuUpdated + \'条\',\n            工作流: \'新增\' + stats.FlowInserted + \'条，修改\' + stats.FlowUpdated + \'条\',\n            工作流节点: \'新增\' + stats.NodeInserted + \'条，修改\' + stats.NodeUpdated + \'条\',\n            工作流连线: \'新增\' + stats.LineInserted + \'条，修改\' + stats.LineUpdated + \'条\',\n            接口引擎: \'新增\' + stats.ApiEngineInserted + \'条，修改\' + stats.ApiEngineUpdated + \'条\'\n        }\n    };\n\n    if (urlRetries.length > 0) {\n        resultData[\'菜单Url自动重命名\'] = urlRetries;\n    }\n\n    if (errors.length > 0) {\n        resultData[\'失败详情（共\' + errors.length + \'条）\'] = errors;\n    }\n\n    // ==================== 返回结果 ====================\n    // 注意：平台会根据返回Code自动管理事务\n    // Code=1 时自动提交事务，Code=0 时自动回滚事务\n\n    var hasErrors = errors.length > 0;\n    return {\n        Code: 1,\n        Data: resultData,\n        Msg: hasErrors ? \'导入完成，但有\' + errors.length + \'条异常，请查看失败详情\' : \'导入成功\'\n    };\n\n} catch (error) {\n    // ==================== 异常处理 ====================\n    // 注意：返回Code=0时，平台会自动回滚事务\n\n    return {\n        Code: 0,\n        Msg: \'导入失败：\' + error.message,\n        Data: {\n            错误信息: error.message,\n            错误堆栈: error.stack\n        }\n    };\n}\n', b'1', '', '', '', '', '/apiengine/import-microi-store-package', b'0', '[]', 0, '系统', 0, 0, '', '', 600, 100000000, 2048, 10000);
INSERT INTO `sys_apiengine` VALUES ('01KH08B7375RBYXK45X1W1E4DS', '2026-02-09 11:51:01', '2026-03-21 03:20:16', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '[系统]首页界面引擎数据源', 'platform-dashboard', b'1', '[]', '/**\n * Microi吾码 - 平台首页数据接口引擎（完整版-已修复）\n * \n * 使用说明：\n * 1. 在Microi吾码平台的【接口引擎】中创建一个新接口\n * 2. 将此代码粘贴到接口引擎的V8代码编辑器中\n * 3. 配置接口引擎Key为：platform_dashboard\n * 4. 配置自定义接口地址为：/apiengine/platform-dashboard\n * 5. 配置是否允许匿名调用（建议不允许，需要登录）\n * \n * 调用方式：\n * GET/POST: {ApiBase}/apiengine/platform-dashboard?type=xxx\n * \n * 支持的type参数：\n * - todo: 我的待办\n * - workflow: 我的流程发起\n * - notice: 通知公告\n * - modules: 常用模块\n * - systeminfo: 系统信息（操作系统、版本号等）\n * - performance: 性能指标（CPU/内存/硬盘）\n * - statistics: 数据统计（表单数/模块数等）\n * - loginlogs: 最近登录用户\n * - apirank: 接口调用频率排行\n * - datarank: 表单数据量排行\n * - network: 网络流量\n * - memo: 个人备忘录\n * - all: 获取所有数据\n */\n\ntry {\n    // 获取请求参数\n    var type = V8.Param.type || \'statistics\';\n\n    // 初始化返回数据\n    var resultData = {};\n\n    // 根据type参数返回相应数据\n    switch (type.toLowerCase()) {\n        case \'todo\':\n            resultData = getTodoData();\n            break;\n        case \'workflow\':\n            resultData = getWorkflowData();\n            break;\n        case \'notice\':\n            resultData = getNoticeData();\n            break;\n        case \'modules\':\n            resultData = getModulesData();\n            break;\n        case \'systeminfo\':\n            resultData = getSystemInfo();\n            break;\n        case \'performance\':\n            resultData = getPerformanceData();\n            break;\n        case \'statistics\':\n            resultData = getStatisticsData();\n            break;\n        case \'loginlogs\':\n            resultData = getLoginLogsData();\n            break;\n        case \'apirank\':\n            resultData = getApiRankData();\n            break;\n        case \'datarank\':\n            resultData = getDataRankData();\n            break;\n        case \'network\':\n            resultData = getNetworkData();\n            break;\n        case \'memo\':\n            resultData = getMemoData();\n            break;\n        case \'all\':\n            resultData = getAllData();\n            break;\n        default:\n            // 默认只返回统计数据，避免超时\n            resultData = getStatisticsData();\n            break;\n    }\n\n    return {\n        Code: 1,\n        Data: resultData,\n        Msg: \'获取成功\'\n    };\n\n} catch (ex) {\n    return {\n        Code: 0,\n        Data: null,\n        Msg: \'获取失败：\' + ex.message\n    };\n}\n\n// ============ 数据获取函数 ============\n\n/**\n * 获取我的待办\n */\nfunction getTodoData() {\n    try {\n        var currentUserId = V8.CurrentUserId;\n\n        // 查询待办事项\n        var todoResult = V8.FormEngine.GetTableData(\'diy_workflow_todo\', {\n            _Where: [\n                [\'UserId\', \'=\', currentUserId],\n                [\'Status\', \'=\', \'待处理\']\n            ],\n            _PageSize: 10,\n            _OrderBy: \'CreateTime\',\n            _OrderByType: \'DESC\'\n        });\n\n        return {\n            total: todoResult.Code === 1 ? (todoResult.DataCount || 0) : 0,\n            list: todoResult.Code === 1 ? (todoResult.Data || []) : []\n        };\n    } catch (ex) {\n        return {\n            total: 0,\n            list: [],\n            error: ex.message\n        };\n    }\n}\n\n/**\n * 获取我的流程发起\n */\nfunction getWorkflowData() {\n    try {\n        var currentUserId = V8.CurrentUserId;\n\n        var workflowResult = V8.FormEngine.GetTableData(\'diy_workflow\', {\n            _Where: [\n                [\'CreateUserId\', \'=\', currentUserId]\n            ],\n            _PageSize: 10,\n            _OrderBy: \'CreateTime\',\n            _OrderByType: \'DESC\'\n        });\n\n        return {\n            total: workflowResult.Code === 1 ? (workflowResult.DataCount || 0) : 0,\n            list: workflowResult.Code === 1 ? (workflowResult.Data || []) : []\n        };\n    } catch (ex) {\n        return {\n            total: 0,\n            list: [],\n            error: ex.message\n        };\n    }\n}\n\n/**\n * 获取通知公告\n */\nfunction getNoticeData() {\n    try {\n        var noticeResult = V8.FormEngine.GetTableData(\'diy_notice\', {\n            _Where: [\n                [\'Status\', \'=\', \'已发布\']\n            ],\n            _PageSize: 5,\n            _OrderBy: \'PublishTime\',\n            _OrderByType: \'DESC\'\n        });\n\n        return {\n            total: noticeResult.Code === 1 ? (noticeResult.DataCount || 0) : 0,\n            list: noticeResult.Code === 1 ? (noticeResult.Data || []) : []\n        };\n    } catch (ex) {\n        return {\n            total: 0,\n            list: [],\n            error: ex.message\n        };\n    }\n}\n\n/**\n * 获取常用模块\n */\nfunction getModulesData() {\n    try {\n        var currentUserId = V8.CurrentUserId;\n\n        var modulesResult = V8.FormEngine.GetTableData(\'diy_user_favorite\', {\n            _Where: [\n                [\'UserId\', \'=\', currentUserId],\n                [\'Type\', \'=\', \'模块\']\n            ],\n            _PageSize: 8,\n            _OrderBy: \'UseCount\',\n            _OrderByType: \'DESC\'\n        });\n\n        return {\n            list: modulesResult.Code === 1 ? (modulesResult.Data || []) : []\n        };\n    } catch (ex) {\n        return {\n            list: [],\n            error: ex.message\n        };\n    }\n}\n\n/**\n * 获取系统信息\n */\nfunction getSystemInfo() {\n    var osInfo = {\n        Platform: \'Unknown\',\n        OSVersion: \'Unknown\',\n        MachineName: \'Unknown\',\n        ProcessorCount: 0\n    };\n\n    var versionInfo = {\n        frontendVersion: \'3.0.0\',\n        backendVersion: \'3.0.2\',\n        edition: \'开源版\'\n    };\n\n    // 尝试获取OS信息\n    try {\n        var systemInfo = new V8.System.SystemInfo();\n        var sysInfo = systemInfo.GetOSInfo();\n        if (sysInfo && sysInfo.Success !== false) {\n            osInfo = sysInfo;\n        }\n    } catch (e) {\n        // 如果V8.System不可用，尝试使用System\n        try {\n            osInfo.Platform = System.Environment.OSVersion.Platform.ToString();\n            osInfo.OSVersion = System.Environment.OSVersion.VersionString;\n            osInfo.MachineName = System.Environment.MachineName;\n            osInfo.ProcessorCount = System.Environment.ProcessorCount;\n        } catch (e2) {\n            // 使用默认值\n        }\n    }\n\n    // 获取版本信息\n    try {\n        var versionResult = V8.FormEngine.GetFormData(\'diy_system_config\', {\n            _Where: [[\'ConfigKey\', \'=\', \'SystemVersion\']]\n        });\n        if (versionResult.Code === 1 && versionResult.Data) {\n            var configValue = JSON.parse(versionResult.Data.ConfigValue || \'{}\');\n            versionInfo.frontendVersion = configValue.FrontendVersion || versionInfo.frontendVersion;\n            versionInfo.backendVersion = configValue.BackendVersion || versionInfo.backendVersion;\n            versionInfo.edition = configValue.Edition || versionInfo.edition;\n        }\n    } catch (e) {\n        // 使用默认值\n    }\n\n    return {\n        os: osInfo,\n        version: versionInfo\n    };\n}\n\n/**\n * 获取性能数据\n */\nfunction getPerformanceData() {\n    var cpu = 0;\n    var memory = 0;\n    var disk = 0; // 改为单个数值，与界面引擎匹配\n\n    try {\n        var systemInfo = new V8.System.SystemInfo();\n\n        // 获取CPU和内存信息\n        try {\n            var cpuMemInfo = systemInfo.GetCpuMemoryInfo();\n            if (cpuMemInfo && cpuMemInfo.Success !== false) {\n                cpu = cpuMemInfo.CpuUsagePercent || 0;\n                memory = cpuMemInfo.MemoryUsagePercent || 0;\n            }\n        } catch (e) {\n            // 忽略错误\n        }\n\n        // 获取磁盘信息 - 只返回第一个磁盘的使用率\n        try {\n            var diskInfo = systemInfo.GetDiskInfo();\n            if (diskInfo && diskInfo.Success !== false && diskInfo.Disks && diskInfo.Disks.length > 0) {\n                disk = diskInfo.Disks[0].UsagePercent || 0;\n            }\n        } catch (e) {\n            // 忽略错误\n        }\n    } catch (e) {\n        // V8.System不可用\n    }\n\n    return {\n        cpu: cpu,\n        memory: memory,\n        disk: disk\n    };\n}\n\n/**\n * 获取统计数据\n */\nfunction getStatisticsData() {\n    var formCount = 0;\n    var moduleCount = 0;\n    var apiEngineCount = 0;\n    var userCount = 0;\n\n    // 表单数\n    try {\n        var formCountResult = V8.FormEngine.GetTableData(\'diy_table\', { _PageSize: 1 });\n        formCount = formCountResult.Code === 1 ? (formCountResult.DataCount || 0) : 0;\n    } catch (e) { }\n\n    // 模块数\n    try {\n        var moduleCountResult = V8.FormEngine.GetTableData(\'sys_menu\', { _PageSize: 1 });\n        moduleCount = moduleCountResult.Code === 1 ? (moduleCountResult.DataCount || 0) : 0;\n    } catch (e) { }\n\n    // 接口引擎数\n    try {\n        var apiCountResult = V8.FormEngine.GetTableData(\'diy_apiengine\', { _PageSize: 1 });\n        apiEngineCount = apiCountResult.Code === 1 ? (apiCountResult.DataCount || 0) : 0;\n    } catch (e) { }\n\n    // 用户数\n    try {\n        var userCountResult = V8.FormEngine.GetTableData(\'sys_user\', { _PageSize: 1 });\n        userCount = userCountResult.Code === 1 ? (userCountResult.DataCount || 0) : 0;\n    } catch (e) { }\n\n    return {\n        formCount: formCount,\n        moduleCount: moduleCount,\n        apiEngineCount: apiEngineCount,\n        userCount: userCount\n    };\n}\n\n/**\n * 获取最近登录用户\n */\nfunction getLoginLogsData() {\n    try {\n        var loginLogsResult = V8.FormEngine.GetTableData(\'sys_login_log\', {\n            _PageSize: 10,\n            _OrderBy: \'LoginTime\',\n            _OrderByType: \'DESC\'\n        });\n\n        return {\n            list: loginLogsResult.Code === 1 ? (loginLogsResult.Data || []) : []\n        };\n    } catch (ex) {\n        return {\n            list: [],\n            error: ex.message\n        };\n    }\n}\n\n/**\n * 获取接口调用频率排行（优化版）\n */\nfunction getApiRankData() {\n    try {\n        // 只查询最近500条记录\n        var apiRankResult = V8.FormEngine.GetTableData(\'diy_api_request_log\', {\n            _PageSize: 500,\n            _OrderBy: \'CreateTime\',\n            _OrderByType: \'DESC\'\n        });\n\n        if (apiRankResult.Code !== 1) {\n            return { list: [] };\n        }\n\n        // 统计每个接口的调用次数\n        var apiCallCount = {};\n        var logs = apiRankResult.Data || [];\n\n        for (var i = 0; i < logs.length; i++) {\n            var apiKey = logs[i].ApiKey || logs[i].ApiUrl || \'Unknown\';\n            if (!apiCallCount[apiKey]) {\n                apiCallCount[apiKey] = {\n                    apiKey: apiKey,\n                    apiName: logs[i].ApiName || apiKey,\n                    count: 0\n                };\n            }\n            apiCallCount[apiKey].count++;\n        }\n\n        // 转换为数组并排序\n        var rankList = [];\n        for (var key in apiCallCount) {\n            rankList.push(apiCallCount[key]);\n        }\n        rankList.sort(function (a, b) {\n            return b.count - a.count;\n        });\n\n        return {\n            list: rankList.slice(0, 10)\n        };\n    } catch (ex) {\n        return {\n            list: [],\n            error: ex.message\n        };\n    }\n}\n\n/**\n * 获取表单数据量排行（优化版）\n */\nfunction getDataRankData() {\n    try {\n        // 只获取前20个表\n        var tablesResult = V8.FormEngine.GetTableData(\'diy_table\', {\n            _PageSize: 20,\n            _OrderBy: \'CreateTime\',\n            _OrderByType: \'DESC\'\n        });\n\n        if (tablesResult.Code !== 1) {\n            return { list: [] };\n        }\n\n        var dataRankList = [];\n        var tables = tablesResult.Data || [];\n\n        // 只统计前10个表\n        for (var i = 0; i < Math.min(tables.length, 10); i++) {\n            try {\n                var tableName = tables[i].Name;\n                var tableDesc = tables[i].Description || tableName;\n                var countResult = V8.FormEngine.GetTableData(tableName, {\n                    _PageSize: 1\n                });\n                if (countResult.Code === 1) {\n                    dataRankList.push({\n                        tableName: tableName,\n                        tableDesc: tableDesc,\n                        count: countResult.DataCount || 0\n                    });\n                }\n            } catch (e) {\n                // 忽略单个表的错误\n            }\n        }\n\n        // 排序\n        dataRankList.sort(function (a, b) {\n            return b.count - a.count;\n        });\n\n        return {\n            list: dataRankList\n        };\n    } catch (ex) {\n        return {\n            list: [],\n            error: ex.message\n        };\n    }\n}\n\n/**\n * 获取所有数据（轻量版，移除耗时操作）\n */\nfunction getAllData() {\n    return {\n        todo: getTodoData(),\n        workflow: getWorkflowData(),\n        notice: getNoticeData(),\n        modules: getModulesData(),\n        systemInfo: getSystemInfo(),\n        performance: getPerformanceData(),\n        statistics: getStatisticsData(),\n        loginLogs: getLoginLogsData()\n        // 移除耗时的排行查询，需要时单独调用\n        // apiRank: getApiRankData(),\n        // dataRank: getDataRankData()\n    };\n}\n\n/**\n * 获取网络流量数据\n */\nfunction getNetworkData() {\n    try {\n        var systemInfo = new V8.System.SystemInfo();\n        var networkInfo = systemInfo.GetNetworkTraffic();\n\n        if (networkInfo && networkInfo.Success !== false) {\n            return {\n                upload: networkInfo.BytesSent || 0,\n                download: networkInfo.BytesReceived || 0,\n                uploadSpeed: networkInfo.SendSpeed || 0,\n                downloadSpeed: networkInfo.ReceiveSpeed || 0\n            };\n        }\n    } catch (e) {\n        // 忽略错误\n    }\n\n    return {\n        upload: 0,\n        download: 0,\n        uploadSpeed: 0,\n        downloadSpeed: 0\n    };\n}\n\n/**\n * 获取个人备忘录\n */\nfunction getMemoData() {\n    try {\n        var currentUserId = V8.CurrentUserId;\n\n        var memoResult = V8.FormEngine.GetTableData(\'diy_user_memo\', {\n            _Where: [\n                [\'UserId\', \'=\', currentUserId]\n            ],\n            _PageSize: 10,\n            _OrderBy: \'CreateTime\',\n            _OrderByType: \'DESC\'\n        });\n\n        return {\n            list: memoResult.Code === 1 ? (memoResult.Data || []) : []\n        };\n    } catch (ex) {\n        return {\n            list: [],\n            error: ex.message\n        };\n    }\n}\n', b'0', '', '', '{ \"type\" : \"all\" }', '[2026-02-09 14:51:25]执行结果：{\"Code\":1,\"Data\":{\"todo\":{\"total\":0,\"list\":[]},\"workflow\":{\"total\":0,\"list\":[]},\"notice\":{\"total\":0,\"list\":[]},\"modules\":{\"list\":[]},\"systemInfo\":{\"os\":{\"Platform\":\"Unknown\",\"OSVersion\":\"Unknown\",\"MachineName\":\"Unknown\",\"ProcessorCount\":0},\"version\":{\"frontendVersion\":\"3.0.0\",\"backendVersion\":\"3.0.2\",\"edition\":\"开源版\"}},\"performance\":{\"cpu\":0,\"memory\":0,\"disk\":0},\"statistics\":{\"formCount\":182,\"moduleCount\":204,\"apiEngineCount\":0,\"userCount\":84},\"loginLogs\":{\"list\":[]}},\"Msg\":\"获取成功\"}', '/apiengine/platform-dashboard', b'0', '[]', 0, '系统', 0, 0, '', '', 600, 100000000, 2048, 10000);
INSERT INTO `sys_apiengine` VALUES ('01KM3MF1FVMBYF8RHKW4BQTBDV', '2026-03-20 02:07:40', '2026-03-21 03:20:16', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '获取数据库结构', 'get_db', b'1', '[]', '/**\r\n * 获取数据库结构接口引擎\r\n * \r\n * 功能：获取【吾码】数据库的表结构、字段信息、菜单结构数据\r\n * \r\n * 业务逻辑：\r\n * 1. 查询diy_table表获取所有表及说明（Id、Name、Description）\r\n * 2. 查询diy_field表获取所有字段及说明\r\n *    - 基础字段：Id、Name、Label、Description、Type、Component、TableId\r\n *    - 解析Config字段，提取TableChildTableId、TableChildSysMenuId\r\n * 3. 查询sys_menu表获取系统菜单树形结构\r\n *    - 基础字段：Id、Name、ParentId、DiyTableId\r\n * 4. 组装数据：\r\n *    - Tables: 将字段信息嵌套到对应的表中（_Fields属性）\r\n *    - Menus: 将子菜单嵌套到父菜单中（_Child属性）\r\n * \r\n * 接口配置：\r\n * - ApiEngineKey: get_db\r\n * - ApiAddress: /apiengine/get-db\r\n * - 允许匿名调用: 否\r\n * - 分布式锁: 否\r\n * \r\n * 前端调用示例：\r\n * V8.ApiEngine.Run(\'get_db\', {})\r\n * \r\n * 返回格式：\r\n * {\r\n *   Code: 1,\r\n *   Data: {\r\n *     Tables: [{\r\n *       Id: \"01KEMDAT9ARD75943VSCB7B4J6\",\r\n *       Name: \"table1\",\r\n *       Description: \"表1\",\r\n *       _Fields: [{\r\n *         Id: \"01KEMDAVG6H7HSN6WWVRYK2NPR\",\r\n *         Name: \"CreateTime\",\r\n *         Label: \"创建时间\",\r\n *         Description: null,\r\n *         Type: \"datetime\",\r\n *         Component: \"DateTime\",\r\n *         TableChildTableId: null,\r\n *         TableChildSysMenuId: null\r\n *       }]\r\n *     }],\r\n *     Menus: [{\r\n *       Id: \"01KEMDAT9ARD75943VSCB7B4J6\",\r\n *       Name: \"菜单名称\",\r\n *       ParentId: \"ParentId\",\r\n *       DiyTableId: \"DiyTableId\",\r\n *       _Child: [{\r\n *         Id: \"01KEMDAT9ARD75943VSCB7B4J6\",\r\n *         Name: \"子菜单名称\",\r\n *         ParentId: \"上级菜单Id\",\r\n *         DiyTableId: \"DiyTableId\"\r\n *       }]\r\n *     }]\r\n *   },\r\n *   Msg: \'获取成功\'\r\n * }\r\n */\r\n\r\n// ==================== 参数接收与校验 ====================\r\n\r\n// 定义调试模式\r\nvar isDebug = true;\r\nvar debugLog = {};\r\n\r\ntry {\r\n  debugLog.startTime = new Date().toISOString();\r\n\r\n  // ==================== 步骤1：查询diy_table表数据 ====================\r\n\r\n  var tableResult = V8.FormEngine.GetTableData(\'diy_table\', {\r\n    _SelectFields: [\'Id\', \'Name\', \'Description\'],\r\n    _PageSize: 10000, // 获取所有数据\r\n    _OrderBy: \'Name\',\r\n    _OrderByType: \'ASC\'\r\n  });\r\n\r\n  if (tableResult.Code !== 1) {\r\n    return {\r\n      Code: 0,\r\n      Msg: \'查询diy_table表失败：\' + tableResult.Msg\r\n    };\r\n  }\r\n\r\n  var tables = tableResult.Data || [];\r\n  debugLog.tableCount = tables.length;\r\n\r\n  // ==================== 步骤2：查询diy_field表数据 ====================\r\n\r\n  var fieldResult = V8.FormEngine.GetTableData(\'diy_field\', {\r\n    _SelectFields: [\'Id\', \'Name\', \'Label\', \'Description\', \'Type\', \'Component\', \'TableId\', \'Config\'],\r\n    _PageSize: 50000, // 获取所有数据\r\n    _OrderBy: \'TableId\',\r\n    _OrderByType: \'ASC\'\r\n  });\r\n\r\n  if (fieldResult.Code !== 1) {\r\n    return {\r\n      Code: 0,\r\n      Msg: \'查询diy_field表失败：\' + fieldResult.Msg\r\n    };\r\n  }\r\n\r\n  var fields = fieldResult.Data || [];\r\n  debugLog.fieldCount = fields.length;\r\n\r\n  // ==================== 步骤3：处理字段数据，解析Config字段 ====================\r\n\r\n  var processedFields = [];\r\n  for (var i = 0; i < fields.length; i++) {\r\n    var field = fields[i];\r\n    var processedField = {\r\n      Id: field.Id,\r\n      Name: field.Name,\r\n      Label: field.Label,\r\n      Description: field.Description,\r\n      Type: field.Type,\r\n      Component: field.Component,\r\n      TableId: field.TableId,\r\n      TableChildTableId: null,\r\n      TableChildSysMenuId: null\r\n    };\r\n\r\n    // 解析Config字段，提取TableChildTableId和TableChildSysMenuId\r\n    if (field.Config) {\r\n      try {\r\n        var configObj = typeof field.Config === \'string\' ? JSON.parse(field.Config) : field.Config;\r\n        if (configObj) {\r\n          processedField.TableChildTableId = configObj.TableChildTableId || null;\r\n          processedField.TableChildSysMenuId = configObj.TableChildSysMenuId || null;\r\n        }\r\n      } catch (e) {\r\n        // 解析失败时，保持为null\r\n        if (isDebug) {\r\n          debugLog[\'configParseError_\' + field.Id] = e.message;\r\n        }\r\n      }\r\n    }\r\n\r\n    processedFields.push(processedField);\r\n  }\r\n\r\n  // ==================== 步骤4：将字段信息嵌套到对应的表中 ====================\r\n\r\n  // 创建TableId到字段列表的映射\r\n  var tableFieldsMap = {};\r\n  for (var i = 0; i < processedFields.length; i++) {\r\n    var field = processedFields[i];\r\n    var tableId = field.TableId;\r\n\r\n    if (!tableFieldsMap[tableId]) {\r\n      tableFieldsMap[tableId] = [];\r\n    }\r\n\r\n    // 创建字段对象（不包含TableId，因为已经在表层级了）\r\n    var fieldObj = {\r\n      Id: field.Id,\r\n      Name: field.Name,\r\n      Label: field.Label,\r\n      Description: field.Description,\r\n      Type: field.Type,\r\n      Component: field.Component,\r\n      TableChildTableId: field.TableChildTableId,\r\n      TableChildSysMenuId: field.TableChildSysMenuId\r\n    };\r\n\r\n    tableFieldsMap[tableId].push(fieldObj);\r\n  }\r\n\r\n  // 为每个表添加_Fields属性\r\n  var processedTables = [];\r\n  for (var i = 0; i < tables.length; i++) {\r\n    var table = tables[i];\r\n    processedTables.push({\r\n      Id: table.Id,\r\n      Name: table.Name,\r\n      Description: table.Description,\r\n      _Fields: tableFieldsMap[table.Id] || []\r\n    });\r\n  }\r\n\r\n  // ==================== 步骤5：查询sys_menu表数据 ====================\r\n\r\n  var menuResult = V8.FormEngine.GetTableData(\'sys_menu\', {\r\n    _SelectFields: [\'Id\', \'Name\', \'ParentId\', \'DiyTableId\'],\r\n    _PageSize: 10000, // 获取所有数据\r\n    _OrderBy: \'Id\',\r\n    _OrderByType: \'ASC\'\r\n  });\r\n\r\n  if (menuResult.Code !== 1) {\r\n    return {\r\n      Code: 0,\r\n      Msg: \'查询sys_menu表失败：\' + menuResult.Msg\r\n    };\r\n  }\r\n\r\n  var menus = menuResult.Data || [];\r\n  debugLog.menuCount = menus.length;\r\n\r\n  // ==================== 步骤6：构建菜单树形结构 ====================\r\n\r\n  // 创建菜单ID到菜单对象的映射\r\n  var menuMap = {};\r\n  for (var i = 0; i < menus.length; i++) {\r\n    var menu = menus[i];\r\n    menuMap[menu.Id] = {\r\n      Id: menu.Id,\r\n      Name: menu.Name,\r\n      ParentId: menu.ParentId,\r\n      DiyTableId: menu.DiyTableId,\r\n      _Child: []\r\n    };\r\n  }\r\n\r\n  // 构建树形结构\r\n  var rootMenus = [];\r\n  for (var menuId in menuMap) {\r\n    var menu = menuMap[menuId];\r\n    if (menu.ParentId && menuMap[menu.ParentId]) {\r\n      // 有父级菜单，添加到父级的_Child数组中\r\n      menuMap[menu.ParentId]._Child.push(menu);\r\n    } else {\r\n      // 没有父级菜单或父级不存在，作为根菜单\r\n      rootMenus.push(menu);\r\n    }\r\n  }\r\n\r\n  // ==================== 步骤7：组装返回数据 ====================\r\n\r\n  var result = {\r\n    Tables: processedTables,\r\n    Menus: rootMenus\r\n  };\r\n\r\n  debugLog.endTime = new Date().toISOString();\r\n  debugLog.resultSummary = {\r\n    tableCount: processedTables.length,\r\n    totalFieldCount: processedFields.length,\r\n    menuCount: rootMenus.length\r\n  };\r\n\r\n  // ==================== 返回结果 ====================\r\n\r\n  return {\r\n    Code: 1,\r\n    Data: result,\r\n    Msg: \'获取数据库结构成功\',\r\n    Debug: isDebug ? debugLog : undefined\r\n  };\r\n\r\n} catch (error) {\r\n  // ==================== 异常处理 ====================\r\n\r\n  debugLog.error = {\r\n    message: error.message,\r\n    stack: error.stack,\r\n    endTime: new Date().toISOString()\r\n  };\r\n\r\n  return {\r\n    Code: 0,\r\n    Msg: \'获取数据库结构失败：\' + error.message,\r\n    Debug: isDebug ? debugLog : undefined\r\n  };\r\n}\r\n', b'0', '', '获取【吾码】数据库的表结构、字段信息、菜单结构数据', '', '', '/apiengine/get-db', b'0', '[]', 0, '', 0, 0, '', '', 600, 100000000, 2048, 10000);
INSERT INTO `sys_apiengine` VALUES ('01KMDXFA8PH37RVMCMEGTPQH6X', '2026-03-24 01:56:51', '2026-03-24 12:49:01', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', 'MCP查询用户表数量', 'mcp-query-user-count', b'1', '[]', '// 查找导航菜单相关表（通过iTdos本地数据库查询表结构）\nvar tables = V8.Db.FromSql(\"SHOW TABLES LIKE \'%nav%\'\").ToArray();\nvar tables2 = V8.Db.FromSql(\"SHOW TABLES LIKE \'%module%\'\").ToArray();\nvar tables3 = V8.Db.FromSql(\"SHOW TABLES LIKE \'%menu%\'\").ToArray();\nreturn { Code: 1, Data: { nav: tables, module: tables2, menu: tables3 } };', b'0', NULL, '', NULL, NULL, '', b'0', '[]', NULL, 'MCP临时', 0, 0, NULL, NULL, 600, 100000000, 2048, 10000);
INSERT INTO `sys_apiengine` VALUES ('01KMSGB6G1G4SQHEQT1TKH25DJ', '2026-03-28 13:58:18', NULL, 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '[日历]日程统计', 'calendar-stats', b'1', '[]', '// 日历日程统计接口：返回今日、本周、本月的日程数量\nvar now = new Date();\nvar year = now.getFullYear();\nvar month = now.getMonth();\nvar day = now.getDate();\nvar dayOfWeek = now.getDay() || 7; // 周日=7\n\n// 今日范围\nvar todayStart = DateFormat(new Date(year, month, day), \'yyyy-MM-dd\') + \' 00:00:00\';\nvar todayEnd = DateFormat(new Date(year, month, day), \'yyyy-MM-dd\') + \' 23:59:59\';\n\n// 本周范围（周一到周日）\nvar weekStart = DateFormat(new Date(year, month, day - dayOfWeek + 1), \'yyyy-MM-dd\') + \' 00:00:00\';\nvar weekEnd = DateFormat(new Date(year, month, day - dayOfWeek + 7), \'yyyy-MM-dd\') + \' 23:59:59\';\n\n// 本月范围\nvar monthStart = DateFormat(new Date(year, month, 1), \'yyyy-MM-dd\') + \' 00:00:00\';\nvar monthEnd = DateFormat(new Date(year, month + 1, 0), \'yyyy-MM-dd\') + \' 23:59:59\';\n\n// 并行查询三个统计\nvar todayResult = V8.FormEngine.GetTableDataCount(\'microi_calendar\', {\n    _Where: [\n        [\'StartTime\', \'<=\', todayEnd],\n        [\'AND\', \'EndTime\', \'>=\', todayStart]\n    ]\n});\n\nvar weekResult = V8.FormEngine.GetTableDataCount(\'microi_calendar\', {\n    _Where: [\n        [\'StartTime\', \'<=\', weekEnd],\n        [\'AND\', \'EndTime\', \'>=\', weekStart]\n    ]\n});\n\nvar monthResult = V8.FormEngine.GetTableDataCount(\'microi_calendar\', {\n    _Where: [\n        [\'StartTime\', \'<=\', monthEnd],\n        [\'AND\', \'EndTime\', \'>=\', monthStart]\n    ]\n});\n\n// 未完成总数\nvar pendingResult = V8.FormEngine.GetTableDataCount(\'microi_calendar\', {\n    _Where: [[\'State\', \'=\', \'未完成\']]\n});\n\nreturn {\n    Code: 1,\n    Data: {\n        Today: todayResult.Code === 1 ? todayResult.DataCount : 0,\n        Week: weekResult.Code === 1 ? weekResult.DataCount : 0,\n        Month: monthResult.Code === 1 ? monthResult.DataCount : 0,\n        Pending: pendingResult.Code === 1 ? pendingResult.DataCount : 0\n    }\n};', b'0', NULL, '', NULL, NULL, '', b'0', '[]', NULL, '系统', 0, 0, NULL, NULL, 600, 100000000, 2048, 10000);
INSERT INTO `sys_apiengine` VALUES ('01KMW1NX2EV9SSASY7DYAXFWTH', '2026-03-29 13:39:43', '2026-03-29 13:40:12', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'1', 'aaaa', 'aaaa', b'1', '[]', '1111111111', b'0', NULL, 'aaaaa', NULL, NULL, 'aaaa', b'0', '[]', NULL, 'aaa', 0, 0, NULL, NULL, 600, 100000000, 2048, 10000);
INSERT INTO `sys_apiengine` VALUES ('1262d41d-3f73-4baa-a1cf-04fab89adc3a', '2026-01-06 04:00:49', '2026-03-21 03:20:17', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '[微信]微信支付退款回调接口', 'wxpay_refund_notify', b'1', '[]', '//实不实现，钱都会到用户那里去，因此暂未实现这里的业务逻辑。', b'0', '', '', '', '', '/apiengine/wxpay-refund-notify', b'1', '[]', 0, '微信', 0, 0, '', '', NULL, NULL, NULL, NULL);
INSERT INTO `sys_apiengine` VALUES ('127d8f10-b211-4bb9-92c3-2752c7ec963b', '2024-04-18 13:58:34', '2026-03-21 03:20:16', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '[飞书]根据飞书code拿到低代码平台token', 'get_userinfo_by_feishu_code', b'1', '[]', '\nvar apiUrl = \'https://open.feishu.cn/open-apis/authen/v1/oidc/access_token\';\n//获取 app_access_token （优先从缓存中获取）\n//注意：【get_feishu_app_access_token】接口引擎并不允许匿名访问，因此这里需要虚拟一个帐号\nvar tokenResult = V8.ApiEngine.Run(\'get_feishu_app_access_token\', {\n  AppKey : \'MicroiH5\',// V8.Param.AppKey, // \'app1\',\n  OsClient : V8.Param.OsClient,\n  _CurrentUser : {\n    Id : 1,\n    Name : \'虚拟用户\'\n  }\n});\nif(tokenResult.Code != 1){\n  V8.Result = { Code : 0, Msg : \'获取app_access_token失败：\' + tokenResult.Msg }; return;\n}\nvar app_access_token = tokenResult.Data.app_access_token;\n//根据 code 获取 user_access_token \nvar getUser_access_tokenResult = V8.Http.Post({\n  Url : apiUrl,\n  Headers : {\n    Authorization : \'Bearer \' + app_access_token\n  },\n  PostParam : {\n    grant_type : \'authorization_code\',\n    code : V8.Param.code\n  }\n});\nvar getUser_access_tokenObj = JSON.parse(getUser_access_tokenResult);\nif(getUser_access_tokenObj.code != 0){\n  V8.Result = { Code : 0, Data : getUser_access_tokenObj }; return;\n}\nvar user_access_token = getUser_access_tokenObj.data.access_token;\n//根据 user_access_token 获取用户信息\nvar getUserInfoApiUrl = \'https://open.feishu.cn/open-apis/authen/v1/user_info\';\nvar getUserInfoResult = V8.Http.Get({\n  Url : getUserInfoApiUrl,\n  Headers : {\n    Authorization : \'Bearer \' + user_access_token\n  },\n  PostParam : {\n  }\n});\nvar getUserInfoObj = JSON.parse(getUserInfoResult);\nif(getUserInfoObj.code != 0){\n  V8.Result = { Code : 0, Data: getUserInfoObj, Msg : \'获取用户信息失败！\' }; return;\n}\nvar user_id = getUserInfoObj.data.user_id;\nvar union_id = getUserInfoObj.data.union_id\nif(!user_id){\n  V8.Result = { Code : 0, Data: getUserInfoObj, Msg : \'获取user_id失败！\' }; return;\n}\n\n//根据user_id【 FeishuUserId 】查询到用户，拿到token用于前端自动登录\nvar userResult = V8.FormEngine.GetFormData({\n  FormEngineKey : \'sys_user\',\n  OsClient : V8.Param.OsClient,\n  _Where: [{ Name : \'FeishuUserId\', Value : union_id, Type : \'=\' }, \n            { AndOr : \'OR\', Name : \'Account\', Value : user_id, Type : \'=\' }\n            ]\n});\nif(userResult.Code != 1){\n  V8.Result = { Code : 0, Msg : \'根据飞书user_id获取用户失败：\' + userResult.Msg }; return;\n}\nvar userInfo = userResult.Data;\nuserInfo = V8.Method.SetSysUserRoleInfo(userInfo, V8.OsClient);\n//获取用户的token\nvar getAccessTokenResult = V8.Method.GetAccessToken({\n  OsClient : V8.OsClient,\n  CurrentUser : userInfo\n});\nif(getAccessTokenResult.Code != 1){\n  V8.Result = { Code : 0, Msg : \'根据用户token失败：\' + getAccessTokenResult.Msg }; return;\n}\nV8.Result = {\n  Code : 1,\n  Data : {},\n  RedirectUrl : V8.Param.RedirectUrl ? (decodeURIComponent(V8.Param.RedirectUrl) + \'&token=\' + getAccessTokenResult.Data.Token) : \'\';\n};', b'0', '', '文档：\n必传code\n获取code：https://open.feishu.cn/document/common-capabilities/sso/api/obtain-oauth-code\n根据code获取token：https://open.feishu.cn/document/uAjLw4CM/ukTMukTMukTM/reference/authen-v1/oidc-access_token/create?appId=cli_a577884fdfeed00d\n根据token获取用户信息：https://open.feishu.cn/document/server-docs/authentication-management/login-state-management/get?appId=cli_a577884fdfeed00d', '', '[2024-04-18 16:09:43]执行结果：{\"Code\":0,\"Data\":{\"code\":20003,\"message\":\"invalid request with code\"}}', '/apiengine/get-userinfo-by-feishu-code', b'1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `sys_apiengine` VALUES ('176863d6-6718-4444-b3fb-cd84f247f370', '2024-12-30 15:17:03', '2026-03-21 03:20:16', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '[微信]绑定微信公众号OpenId', 'bind-wechat', b'1', '[]', 'if(!V8.Param.Account || !V8.Param.Pwd || !V8.Param.OsClient || !V8.Param.WxKey){\n  return { Code : 0, Msg : \'参数错误！\' };\n}\nvar wxKey = V8.Param.WxKey;\n//判断是否开启了验证码\nif(V8.SysConfig.EnableCaptcha){\n  if(!V8.Param._CaptchaId || V8.Param._CaptchaValue == null || V8.Param._CaptchaValue == \'\' || V8.Param._CaptchaValue == undefined){\n    return { Code : 0, Msg : \'请输入验证码！\' };\n  }\n  //注意：默认RedisKey有一个【Microi:】前缀，并且验证码redis值存储在在Hash里面的data字段\n  var captchaValue = V8.Cache.HashGet(`Microi:${V8.Param.OsClient}:${V8.Param._CaptchaId}`, \'data\');\n  if(captchaValue != V8.Param._CaptchaValue){\n    return { Code : 0, Msg : \'验证码错误！\', DataAppend : {\n      CaptchaValue : captchaValue,\n      _CaptchaValue : V8.Param._CaptchaValue,\n    } };\n  }\n}\n//判断帐号密码是否正确\nvar userResult = V8.FormEngine.GetFormData(\'sys_user\', {\n  _Where : [{ Name : \'Account\', Value : V8.Param.Account, Type : \'=\' }]\n});\nif(userResult.Code != 1){\n  return { Code : 0, Msg : \'帐号或密码错误！\' };\n}\nvar userInfo = userResult.Data;\nif(userInfo.Pwd != V8.EncryptHelper.DESEncode(V8.Param.Pwd)){\n  return { Code : 0, Msg : \'帐号或密码错误！\' };\n}\n//根据WxKey获取相关信息\nvar cacheKey = `Microi:${V8.Param.OsClient}:FormData:wx_mp:${wxKey}`;\nvar wxMpResult = V8.Cache.Get(cacheKey);\nif(!wxMpResult){\n  var appInfoResult = V8.FormEngine.GetFormData({\n    FormEngineKey : \'wx_mp\',\n    _Where: [{ Name : \'Key\', Value : wxKey, Type : \'=\' }]\n  });\n  if(appInfoResult.Code != 1){\n    return appInfoResult;\n  }\n  wxMpResult = appInfoResult.Data;\n  V8.Cache.Set(cacheKey, JSON.stringify(wxMpResult));\n}else{\n  wxMpResult = JSON.parse(wxMpResult);\n}\nvar apiBase = \'https://api.itdos.com\';//V8.SysConfig.ApiBase\nvar bindRedirectRri = encodeURIComponent(`${apiBase}/apiengine/bind-wechat-callback?OsClient=${V8.Param.OsClient}&UserId=${userInfo.Id}&WxKey=${V8.Param.WxKey}`);\n//前端需要跳转到 RedirectUrl 这个地址\nvar redirectUrl = `https://open.weixin.qq.com/connect/oauth2/authorize?appid=${wxMpResult.AppId}&redirect_uri=${bindRedirectRri}&response_type=code&scope=snsapi_base&state=${V8.Param.OsClient}#wechat_redirect`;\nreturn {\n  Code : 1,\n  Data : {\n    RedirectUrl : redirectUrl\n  }\n};', b'0', '', '必传：Account、Pwd、OsClient、WxKey（如果开启了验证码，还需传入_CaptchaId、_CaptchaValue）\n官方文档：https://developers.weixin.qq.com/doc/offiaccount/OA_Web_Apps/Wechat_webpage_authorization.html', '', '', '/apiengine/bind-wechat', b'1', '[]', 0, '微信', 0, 0, '', '', NULL, NULL, NULL, NULL);
INSERT INTO `sys_apiengine` VALUES ('1ab5f947-6bce-4f6c-ac2d-3ed98073dcf4', '2024-10-22 13:12:54', '2026-03-21 03:20:16', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '【界面引擎】设计模板数据', 'jiemian_yinqing', b'1', '[]', 'var data = {\r\n  labelLine: {\r\n    show: false,\r\n  },\r\n  data: [	{\r\n    value: 1111,\r\n    name: \'张三\'\r\n  },\r\n  {\r\n    value: 222,\r\n    name: \'李四\'\r\n   }\r\n  ],\r\n};\r\nV8.Result = {Code: 1, Data: data};\r\nreturn;', b'0', '', '', '', '[2024-10-22 13:25:38]执行结果：{\"Code\":1,\"Data\":[]}', '/api/jiemianyinqing', b'0', '[]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `sys_apiengine` VALUES ('1f5402db-a7da-475b-a562-11ff5be57653', '2025-01-03 15:12:17', '2026-03-21 03:20:16', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '[微信]创建菜单', 'wechat_create_menu', b'1', '[]', 'if(!V8.Param.MenuJsonString){\n  return { Code : 0, Msg : \'参数错误！\' };\n}\n//获取access_token\nvar tokenResult = V8.ApiEngine.Run(\'get_weixin_access_token\', { WxKey : V8.Param.WxKey });\nif(tokenResult.Code != 1){\n  return tokenResult;\n}\nvar token = tokenResult.Data.access_token;\nvar url = `https://api.weixin.qq.com/cgi-bin/menu/create?access_token=${token}`;\nvar result = V8.Http.Post({\n  Url : url,\n  ParamType : \'json\',\n  PostParamString : V8.Param.MenuJsonString\n});\nvar resultObj = JSON.parse(result);\nif(resultObj.errcode == 0){\n  return { Code : 1 };\n}\nreturn { Code : 0, Data : resultObj, Msg : resultObj.errmsg };', b'0', '', '必传：MenuJsonString、WxKey\n官方文档：https://developers.weixin.qq.com/doc/offiaccount/Custom_Menus/Creating_Custom-Defined_Menu.html\n设置安全域名：https://mp.weixin.qq.com/cgi-bin/settingpage?t=setting/function&action=function&token=27313488&lang=zh_CN\n', '', '', '/apiengine/wechat-create-menu', b'0', '[]', 0, '', 0, 0, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `sys_apiengine` VALUES ('215ce2e7-1661-4334-91ca-4d4b0a7fe676', '2024-10-26 14:38:00', '2026-03-21 03:20:16', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '[系统]上传接口', 'hdfs-upload', b'1', '[]', 'var filesByteBase64 = V8.FilesByteBase64;\nif(!filesByteBase64){\n  V8.Result = {\n    \"errno\": 1, // 只要不等于 0 就行\n    \"message\": \"未发现文件！\"\n  }; return;\n}\nif(Object.values(filesByteBase64).length == 0){\n  V8.Result = {\n    \"errno\": 1, // 只要不等于 0 就行\n    \"message\": \"未发现文件！\"\n  }; return;\n}\nvar result = V8.Method.Upload({\n  FilesByteBase64 : filesByteBase64,\n  //Multiple : true,//editor上传多张图片这个接口会调用多次，每次都是单图\n  OsClient : V8.OsClient\n});\nif(result.Code != 1){\n  V8.Result = {\n    \"errno\": 1, // 只要不等于 0 就行\n    \"message\": result.Msg\n  }; return;\n}\nvar editorResult = {\n  \"errno\": 0, // 注意：值是数字，不能是字符串\n  \"data\": {\n      \"url\": V8.SysConfig.FileServer + result.Data.Path, // 图片 src ，必须\n      \"alt\": result.Data.Name, // 图片描述文字，非必须\n      \"href\": \"\" // 图片的链接，非必须\n  }\n};\nV8.Result = editorResult;', b'0', '', '恭喜', '', '[2024-10-26 15:23:03]执行结果：{\"errno\":1,\"message\":\"未发现文件！\"}', '/apiengine/hdfs/upload', b'0', '[]', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `sys_apiengine` VALUES ('242c4ad1-03e6-41b3-ad01-c19188d5b03d', '2024-12-31 14:53:32', '2026-03-21 03:20:16', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '[微信]绑定微信公众号OpenId回调', 'bind-wechat-callback', b'1', '[]', 'if(!V8.Param.OsClient || !V8.Param.UserId || !V8.Param.code || !V8.Param.WxKey){\n  return { Code : 0, Msg : \'参数错误！\' };\n}\n//获取公众号相关信息\nvar wxKey = V8.Param.WxKey;\n//根据WxKey获取相关信息\nvar cacheKey = `Microi:${V8.Param.OsClient}:FormData:wx_mp:${wxKey}`;\nvar wxMpResult = V8.Cache.Get(cacheKey);\nif(!wxMpResult){\n  var appInfoResult = V8.FormEngine.GetFormData({\n    FormEngineKey : \'wx_mp\',\n    _Where: [{ Name : \'Key\', Value : wxKey, Type : \'=\' }]\n  });\n  if(appInfoResult.Code != 1){\n    return appInfoResult;\n  }\n  wxMpResult = appInfoResult.Data;\n  V8.Cache.Set(cacheKey, JSON.stringify(wxMpResult));\n}else{\n  wxMpResult = JSON.parse(wxMpResult);\n}\n\n//通过code换取网页授权access_token和openid\n//这里通过code换取的是一个特殊的网页授权access_token,与基础支持中的access_token（该access_token用于调用其他接口）不同。公众号可通过下述接口来获取网页授权access_token。如果网页授权的作用域为snsapi_base，则本步骤中获取到网页授权access_token的同时，也获取到了openid，snsapi_base式的网页授权流程即到此为止。\nvar url = `https://api.weixin.qq.com/sns/oauth2/access_token?appid=${wxMpResult.AppId}&secret=${wxMpResult.AppSecret}&code=${V8.Param.code}&grant_type=authorization_code`;\nvar webTokenResult = V8.Http.Get(url);\nvar webTokenResultObj = JSON.parse(webTokenResult);\nif(!webTokenResultObj.access_token){\n  return { Code : 0, Data : webTokenResultObj, Msg : webTokenResult };\n}\nvar openId = webTokenResultObj.openid;\nif(!openId){\n  return { Code : 0, Data : webTokenResultObj, Msg : \'未获取到openid！\' };\n}\n//绑定openid\nvar uptResult = V8.FormEngine.UptFormData(\'sys_user\', {\n  Id : V8.Param.UserId,\n  WxOpenId : openId\n});\nif(uptResult.Code == 1){\n  return \'绑定成功！\';\n}\nreturn \'绑定失败：\' + uptResult.Msg;', b'0', '', '必传：OsClient、UserId、WxKey\n官方文档：https://developers.weixin.qq.com/doc/offiaccount/OA_Web_Apps/Wechat_webpage_authorization.html', '', '', '/apiengine/bind-wechat-callback', b'1', '[]', 0, '微信', 0, 0, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `sys_apiengine` VALUES ('294b1d95-187a-42e4-b10a-4c3d3f32d3f1', '2024-11-25 11:34:55', '2026-03-21 03:20:16', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '[系统]用户找回密码', 'userRetrievePassword', b'1', '[]', '\nif(!V8.Param.Account || !V8.Param.Pwd){\n  V8.Result = { Code : 0, Msg : \'Account、Pwd必填！\' };\n  return;\n}\n\n//-------图形/短信验证码相关验证 START\n//注册一定要判断是否获取了短信验证码，若短信验证码通道出现了问题，也会有一个[SmsCaptcha:Phone=Allow的标记(表示图形验证码已通过)]，因此这里无需再次判断图形验证码。\n//需要在[判断是否存在用户]逻辑之前，防止匿名查询是否存在此帐号。\n\nvar smsCode = V8.Cache.Get(\'SmsCaptcha:\' + V8.Param.Account);\n\nif(!smsCode){\n  V8.Result = { Code : 0, Msg : \'未获取短信验证码！\'};\n  return;\n}\n\nif(smsCode != \'Allow\' && smsCode != V8.Param._SmsCaptchaValue){\n  V8.Result = { Code : 0, Msg : \'短信验证码错误！\'};// + `输入${V8.Param._SmsCaptchaValue}实际${smsCode}`\n  return;\n}\n  \n  //-------图形/短信验证码相关验证 END\n  var sysUserModelResult = V8.FormEngine.GetFormData({\n    FormEngineKey : \'Sys_User\',\n    _Where : [{ Name : \'Account\', Value : V8.Param.Account, Type : \'=\' }]\n  });\n  \n  if(sysUserModelResult.Code == 1){\n    var uptSysUserModelResult = V8.FormEngine.UptFormData({\n        FormEngineKey : \'Sys_User\',\n        Id : sysUserModelResult.Data.Id,//必传\n        _RowModel : {\n            Pwd : V8.EncryptHelper.DESEncode(V8.Param.Pwd)//要修改的字段，注意字段值不能是{}或[]，需要序列化\n        }\n    });\n    //销毁验证码缓存\n    if(uptSysUserModelResult.Code == 1){\n      V8.Cache.Remove(\'SmsCaptcha:\' + V8.Param.Account);\n    }\n    V8.Result = { Code : 1, Msg : \'找回密码成功\'};\n  } else{\n    V8.Result = { Code : 0, Msg : \'当前用户不存在\'};\n    return;\n  }\n  ', b'1', '', '必传：Account、Pwd\n可选：_SmsCaptchaValue（短信验证码，之所以为可选是因为短信通道可能出错，此时只要图形验证码通过即可注册。而图形验证码通过时会往缓存里存一个[SmsCaptcha:Phone=Allow]，因此注册接口无需再次验证图形码）', '', '', '/api/SysUser/retPwd', b'0', '[]', 0, '系统', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `sys_apiengine` VALUES ('2a78d645-18c2-46f4-979a-b909399f3730', '2024-08-18 01:31:13', '2026-03-21 03:20:16', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '[系统]平台初始化接口', 'microi-init', b'1', '[]', '//根据域名获取OsClient值：https://api-china.itdos.com/api/Os/GetOsClientByDomain\nvar osClient = V8.Param.OsClient; \nvar debug = {};\n//Token以旧换新，返回用户身份信息和权限：https://api-china.itdos.com/api/SysUser/getCurrentUser\nvar currentUser = {};\nvar token = \'\';\nif(V8.Param.Token){\n  var tokenResult = V8.Method.GetCurrentToken(V8.Param.Token, osClient);\n  if(tokenResult){\n    var refreshResult = V8.Method.RefreshLoginUser(tokenResult.CurrentUser.Id, osClient);\n    currentUser = refreshResult.Data;\n    if(currentUser && currentUser._RoleLimits && currentUser._RoleLimits.length == 0){\n      debug[\'SetSysUserRoleInfo\'] = true;\n      delete currentUser._IsAdmin;\n      delete currentUser._RoleLimits;\n      delete currentUser._Roles;\n      currentUser = V8.Method.SetSysUserRoleInfo(currentUser, osClient);\n    }\n    var getCurrentToken = V8.Method.GetCurrentToken();\n    if(getCurrentToken && getCurrentToken.Token){\n      token = V8.Method.GetCurrentToken().Token;\n    }\n  }\n}\nif(V8.Param.Domain){\n  var osClientResult = V8.FormEngine.GetFormData({\n    FormEngineKey : \'Sys_OsClients\',\n    _Where:[{ GroupStart : true, Name : \'DomainName\', Value : V8.Param.Domain, Type : \'=\' },\n            { AndOr : \'OR\', Name : \'DomainName\', Value : V8.Param.Domain, Type : \'Like\', GroupEnd : true},\n            { Name : \'IsEnable\', Value : \'1\', Type : \'=\' }],\n    OsClient : osClient,\n  });\n  if(osClientResult.Code == 1){\n    osClient = osClientResult.Data.OsClient;\n  }else{\n    debug[\'GetSysOsClientsError\'] = osClientResult.Msg;\n  }\n  //如果是microi.net，并且未传入token，则自动登录demo帐号\n  if(!V8.Param.Token\n    && !V8.Param.UserSelfLogout\n    && (V8.Param.Domain.toLowerCase() == \'webos.microi.net\' \n        || V8.Param.Domain.toLowerCase() == \'web.microi.net\' \n    )){\n    // currentUser = V8.FormEngine.GetFormData(\'sys_user\', {\n    //   _Where: [{ Name: \'account\', Value: \'demo\', Type: \'=\'}]\n    // }).Data;\n    // currentUser = V8.Method.SetSysUserRoleInfo(currentUser, osClient);\n    // //获取用户的token\n    // var getAccessTokenResult = V8.Method.GetAccessToken({\n    //   OsClient : osClient,\n    //   CurrentUser : currentUser\n    // });\n    // if(getAccessTokenResult.Code != 1){\n    //   V8.Result = { Code : 0, Msg : \'根据用户token失败：\' + getAccessTokenResult.Msg }; return;\n    // }\n    // token = getAccessTokenResult.Data.Token\n  }\n}\n//获取系统设置：https://api-china.itdos.com/api/DiyTable/getSysConfig\nvar sysConfigModel = V8.Cache.Get(`SysConfig:${osClient}`);\nif(!sysConfigModel){\n  var sysConfigResult = V8.FormEngine.GetFormData({\n    FormEngineKey : \'Sys_Config\',\n    _Where:[{ Name : \'IsEnable\', Value : \'1\', Type : \'=\' }],\n    OsClient : osClient,\n  });\n  if(sysConfigResult.Code == 1){\n    sysConfigModel = sysConfigResult.Data;\n  }else{\n    debug[\'GetSysConfigError\'] = sysConfigResult.Msg;\n  }\n}else{\n  sysConfigModel = JSON.parse(sysConfigModel);\n}\nif(sysConfigModel.LoginBgImgRandom){\n  //后期会让V8.FormEngine也支持传入【ORDER BY RAND() 】\n  var bizhiResult = V8.Db.FromSql(\'SELECT ImgUrl FROM diy_wallpaper where IsDeleted=0 AND IsEnable = 1 ORDER BY RAND() LIMIT 1\').ToScalar();\n  debug[\'bizhiResult\'] = bizhiResult;\n  if(bizhiResult){\n    sysConfigModel.LoginBgImg = bizhiResult;\n  }\n}\nif(sysConfigModel.DesktopBgImgRandom){\n  //后期会让V8.FormEngine也支持传入【ORDER BY RAND() 】\n  var bizhiResult = V8.Db.FromSql(\'SELECT ImgUrl FROM diy_wallpaper where IsDeleted=0 AND IsEnable = 1 ORDER BY RAND() LIMIT 1\').ToScalar();\n  debug[\'bizhiResult2\'] = bizhiResult;\n  if(bizhiResult){\n    sysConfigModel.DesktopBgImg = bizhiResult;\n  }\n}\n\n//返回服务器当前时间：https://api-china.itdos.com/api/os/getDateTimeNow\nvar nowTime = V8.Action.GetDateTimeNow();\n//获取菜单\nvar ModuleList = [];\nif(token){\n  var menuResult = V8.ApiEngine.Run(\'get-sys-menu-tree\', {\n    _CurrentUser : currentUser,\n    DesktopType : V8.Param.DesktopType,\n    AppDisplay : V8.Param.AppDisplay\n  });\n  if(menuResult.Code == 1){\n    ModuleList = menuResult.Data;\n    if(menuResult.DataAppend){\n      debug[\'GetSysMenuTreeDataAppend\'] = menuResult.DataAppend;\n    }\n  }else{\n    debug[\'GetSysMenuTreeError\'] = menuResult.Msg;\n  }\n}\n//获取桌面任务栏默认菜单\nvar DesktopDockMenu = [];\nif(token && currentUser.Id){\n  var dockResult = V8.ApiEngine.Run(\'get-desktop-dock\', {\n    _CurrentUser : currentUser,\n    _SysConfig : sysConfigModel,\n  });\n  if(dockResult.Code == 1){\n    DesktopDockMenu = dockResult.Data;\n  }else{\n    debug[\'GetDesktopDockError\'] = dockResult.Msg;\n  }\n}\n\nV8.Result = {\n  Code : 1,\n  Data : {\n    OsClient : osClient,\n    SysConfig : sysConfigModel,\n    DateTimeNow : nowTime,\n    CurrentUser : currentUser,\n    Token : token,\n    ModuleList : ModuleList,\n    DesktopDockMenu : DesktopDockMenu\n  },\n  Debug : debug\n};', b'0', '', '可选参数：Domain、Token\n', '', '', '/apiengine/microi-init', b'1', '[]', 0, '', 0, 0, '', '', NULL, NULL, NULL, NULL);
INSERT INTO `sys_apiengine` VALUES ('2c1a3a3d-ab3a-443a-afeb-a01af040ec12', '2024-09-05 13:38:00', '2026-03-21 03:20:17', 'a0bc4cf2-f0f2-4b60-9474-44febe304e9c', '崔思敏', b'0', '[飞书]发送卡片消息', 'feishu_send_Cardmsg', b'1', '[]', 'if(!V8.Param.AppKey || !V8.Param.Receiver || !V8.Param.MsgType){\r\n  V8.Result = { Code : 0, Msg : \'参数错误！\' }; return;\r\n}\r\n//拿到 tenant_access_token （优先从缓存中获取）\r\n\r\nvar tokenResult = V8.ApiEngine.Run(\'get_feishu_app_access_token\', {\r\n  AppKey : V8.Param.AppKey\r\n});\r\n\r\nif(tokenResult.Code != 1){\r\n  V8.Result = tokenResult; return;\r\n}\r\nvar tenant_access_token = tokenResult.Data.tenant_access_token;\r\n//获取用户的UnionID【 FeishuUnionId 】\r\nvar userResult = V8.FormEngine.GetFormData({\r\n  FormEngineKey : \'sys_user\',\r\n  _Where : [{ Name : \'Id\', Value : V8.Param.Receiver, Type : \'=\' }, \r\n            { AndOr : \'OR\', Name : \'Account\', Value : V8.Param.Receiver, Type : \'=\' }]\r\n});\r\nif(userResult.Code != 1){\r\n  V8.Result = userResult; return;\r\n}\r\nvar userInfo = userResult.Data;\r\n/*\r\nif(!userInfo.Phone || userInfo.Phone.length != 11){\r\n  V8.Result = { Code : 0, Msg : \'用户的手机号为空或格式不正确！\' }; return;\r\n}\r\n*/\r\nvar feishuUnionId = userInfo.FeishuUnionId;\r\n\r\n//如果用户未绑定 FeishuUnionId ，需从飞书绑定\r\nvar getUnionIdResult;\r\nif(!feishuUnionId){//!feishuUnionId\r\n  var getUnionIdUrl = \'https://open.feishu.cn/open-apis/contact/v3/users/batch_get_id?user_id_type=union_id\';\r\n  var postParam = {\r\n    mobiles: [\r\n      userInfo.Phone\r\n    ],\r\n    include_resigned: true\r\n  };\r\n  getUnionIdResult = V8.Http.Post({\r\n    Url : getUnionIdUrl,\r\n    Headers : {\r\n      Authorization : \'Bearer \' + tenant_access_token\r\n    },\r\n    /*\r\n    PostParam : postParam\r\n    */\r\n    //由于接口引擎暂时不支持参数传入数组，所以临时使用 PostParamString 方式\r\n    PostParamString : JSON.stringify(postParam),\r\n	  ParamType : \'JSON\'//这里的\'json\'不区分大小写\r\n  });\r\n   \r\n  var getUnionIdObj = JSON.parse(getUnionIdResult);\r\n  if(getUnionIdObj.code != 0){\r\n    V8.Result = { Code : 0, Data : getUnionIdObj, Msg : \'获取UnionId失败！\' };\r\n    return;\r\n  }\r\n\r\n  feishuUnionId = getUnionIdObj.data.user_list[0].user_id;\r\n  //V8.Result = feishuUnionId; return;\r\n  //给用户更新UnionId\r\n  V8.FormEngine.UptFormData({\r\n    FormEngineKey : \'sys_user\',\r\n    Id : userInfo.Id,\r\n    _RowModel:{\r\n      FeishuUnionId : feishuUnionId\r\n    }\r\n  });\r\n}\r\n//发送消息\r\nvar apiUrl = \'https://open.feishu.cn/open-apis/im/v1/messages?receive_id_type=user_id\';//union_id。user_id\r\nvar content = \"\";\r\n/*\r\nif(V8.Param.MsgType == \'text\' || V8.Param.MsgType == \'interactive\'){\r\n  content = JSON.stringify({ text : V8.Param.Content });\r\n}else{\r\n  V8.Result = { Code : 0, Msg : \'不支持的消息类型！\' };\r\n}*/\r\nvar result = V8.Http.Post({\r\n  Url : apiUrl,\r\n  Headers : {\r\n    Authorization : \'Bearer \' + tenant_access_token,\r\n    //Content-Type : \'application/json\'\r\n  },\r\n  PostParam : {\r\n    receive_id : userInfo.Account, // userInfo.Account,//feishuUnionId,\r\n    msg_type : \'interactive\',//息类型 包括：text、post、image、file、audio、media、sticker、interactive、share_chat、share_user等\r\n    content : V8.Param.Content,\r\n   // uuid : System.Guid.NewGuid(),\r\n    \r\n  },\r\n});\r\nV8.Result = result\r\nreturn\r\n/*var resultObj = JSON.parse(result);\r\nif(resultObj.code == 0){\r\n  V8.Result = { Code : 1, DataAppend : {\r\n    getUnionIdResult : getUnionIdResult\r\n  } };\r\n}else{\r\n  V8.Result = { Code : 0, Data : resultObj, Msg : resultObj.msg };\r\n}*/', b'0', '', '必传参数：AppKey（要发送消息的应用key）、Receiver（接收消息的用户Id或用户账号[指低代码台]）、\nMsgType（消息类型：text、post、image、file、audio、media、sticker、interactive、share_chat、share_user等）\n文档：https://open.feishu.cn/document/server-docs/im-v1/message/create?appId=cli_a577884fdfeed00d\n', '{ \"AppKey\" : \"MicroiH5\",  \"Receiver\" : \"jiangtao\",  \"MsgType\" : \"interactive\", \"Content\" : {\"type\":\"template\",\"data\":{\"template_id\":\"AAqCKBeZPzLd6\",\"template_version_name\":\"1.0.4\",\"template_variable\":{\"Title1\":\"整改任务提醒\",\"Title2\":\"尊敬的徐豪捷\",\"text\":\"尊敬的徐豪捷1\",\"Lianjie\":\"https://www.nbsizhi.com/microi/?OsClient=loctek#/pages/workbench/work-list/index?MenuId=feff39f6-3940-41ed-bad1-d770f0e4d547&MenuName=%E6%95%B4%E6%94%B9%E4%BB%BB%E5%8A%A1%E6%8F%90%E6%8A%A5\"}}}}', '[2024-09-05 13:38:05]执行结果：{\"Code\":0,\"Data\":null,\"DataAppend\":null,\"Msg\":\"执行服务器端V8代码出现错误：Line 84: Unexpected token - --> \",\"DataCount\":null}', '/apiengine/feishu_send_Cardmsg', b'0', '[]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `sys_apiengine` VALUES ('30b6df91-38c4-4538-bf88-36ba99f28bb1', '2024-10-10 15:56:59', '2026-03-21 03:20:17', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '[系统]新增字段', 'add-diyfield', b'1', '[]', 'V8.Result = V8.FormEngine.GetTableData(\'sys_user\', {\n  _OrderBys: { \n    \'Account\' : \'asc\', \n    \'Phone\' : \'desc\' \n  }\n});', b'0', '', '', '', '[2024-11-14 16:02:23]执行结果：{\"Code\":1,\"Data\":[{\"Id\":\"6e262c5e-825d-4f1c-8b8b-5383bdaab5d8\",\"No\":null,\"Account\":\"17606556559\",\"Pwd\":\"JdZe5gWKjZo=\",\"Name\":\"唐小明\",\"DeptId\":\"6c390d32-7fe5-42cd-865b-120294385c12\",\"DeptName\":\"总经办\",\"DeptCode\":\"1-1-\",\"DeptIds\":\"[[\\\"933da282-adf7-4b1d-90f9-bfad70dae3a5\\\",\\\"704c0d3c-92ba-4c62-a539-d173e8766011\\\"]]\",\"RoleIds\":\"[{\\\"Id\\\":\\\"4f79c46a-ee33-4bf4-a715-13b05e315622\\\",\\\"Name\\\":\\\"DIY管理员\\\",\\\"Level\\\":1},{\\\"Id\\\":\\\"5db47859-35a3-411a-a1f7-99482e057d24\\\",\\\"Name\\\":\\\"超级管理员\\\",\\\"Level\\\":999}]\",\"CreateTime\":\"2024-11-06 15:12:56\",\"UpdateTime\":\"2024-11-06 15:13:11\",\"Phone\":\"17606556559\",\"State\":1,\"Remark\":null,\"Avatar\":null,\"Sex\":\"男\",\"Email\":null,\"IsDeleted\":0,\"Level\":999,\"ParentId\":null,\"UserId\":\"c74d669c-a3d4-11e5-b60d-b870f43edd03\",\"UserName\":\"管理员\",\"PwdEncode\":null,\"TenantId\":null,\"TenantName\":null,\"FeishuUnionId\":null,\"UserType\":null,\"MiniProgramOpenId\":null,\"Lang\":null,\"DesktopType\":null,\"DesktopBg\":null,\"PageHistory\":null,\"OpenTreeMenu\":null,\"DesktopDockMenu\":null,\"RandomDesktopBg\":null},{\"Id\":\"5220e9dd-601d-4195-b398-dca2b98913bb\",\"No\":null,\"Account\":\"sunyudan\",\"Pwd\":\"JdZe5gWKjZo=\",\"Name\":\"孙玉丹\",\"DeptId\":\"b4612bd0-f318-40f3-a620-547fa3e9cbc2\",\"DeptName\":\"研发部\",\"DeptCode\":\"1-4-\",\"DeptIds\":\"[]\",\"RoleIds\":\"[{\\\"Id\\\":\\\"573b89e0-dc93-42d7-bd18-af160e3b72b8\\\",\\\"Name\\\":\\\"普通用户\\\",\\\"Level\\\":1}]\",\"CreateTime\":\"2024-09-22 09:05:47\",\"UpdateTime\":null,\"Phone\":null,\"State\":1,\