e\":null,\"MiniProgramOpenId\":\"\",\"Lang\":\"en\",\"DesktopType\":\"\",\"DesktopBg\":\"/itdos/img/20241101/desktop-bg.jpg\",\"PageHistory\":\"[[\\\"3dd0c0b8-0866-44b7-90b7-15f3dcfc07a9\\\"],[\\\"44ab649f-a2f9-4c0f-b3b6-677b2dd4c541\\\",\\\"c6468241-f16c-4abb-aa54-bd59fd4b7cc4\\\"]]\",\"OpenTreeMenu\":0,\"DesktopDockMenu\":\"[[\\\"cdc0844b-7249-4d64-a9c3-563a15c9cd20\\\"],[\\\"adc8487f-9a58-4354-acbd-e97ce182ec7b\\\"],[\\\"96e11071-12e5-4ccc-b79e-84ecdfcd43f6\\\",\\\"bb62e86e-e8dc-438e-8a5e-916d63687b28\\\"]]\",\"RandomDesktopBg\":null}],\"DataAppend\":{\"ServerRunSql\":\" SELECT A.* FROM `Sys_User` A   WHERE 1=1  AND A.IsDeleted = 0  ORDER BY  A.`CreateTime` desc, A.`Id` asc \",\"ServerRunCountSql\":\" SELECT COUNT(A.Id) FROM `Sys_User` A   WHERE 1=1  AND A.IsDeleted = 0 \"},\"Msg\":null,\"DataCount\":67}', '/apiengine/add-diyfield', b'1', '[]', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `sys_apiengine` VALUES ('39d6ca1f-bab5-4ff7-95e2-fadeacd37003', '2024-11-25 11:33:55', '2026-04-01 10:22:20', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '[系统]用户注册', 'sysuser_reg', b'1', '[]', '// [系统]用户手机号登录/自动注册 - 用于 microi.doc 官网\n// 前端调用: POST /api/SysUser/SmsLogin { Phone, _SmsCaptchaValue, OsClient }\n// 此接口引擎仅作为参考逻辑，实际登录逻辑已移至后端 C# SysUserController.SmsLogin 方法\n\nvar phone = V8.Param.Phone || V8.Param.Account;\nvar smsCode = V8.Param._SmsCaptchaValue;\n\nif (!phone || phone.length != 11) {\n  return { Code: 0, Msg: \'手机号错误！\' };\n}\nif (!smsCode) {\n  return { Code: 0, Msg: \'请输入短信验证码！\' };\n}\n\n// 验证短信验证码\nvar cachedCode = V8.Cache.Get(\'Microi:\' + V8.OsClient + \':SmsCaptcha:\' + phone);\nif (!cachedCode) {\n  return { Code: 0, Msg: \'未获取短信验证码或验证码已过期！\' };\n}\nif (cachedCode != \'Allow\' && cachedCode != smsCode) {\n  return { Code: 0, Msg: \'短信验证码错误！\' };\n}\n\n// 查询用户是否已存在\nvar userResult = V8.FormEngine.GetFormData(\'Sys_User\', {\n  _Where: [[\'Phone\', \'=\', phone]],\n  _SelectFields: [\'Id\', \'Account\', \'Name\', \'Phone\', \'State\']\n});\n\nvar userId = \'\';\n\nif (userResult.Code == 2 || (userResult.Code == 1 && !userResult.Data)) {\n  // 用户不存在，自动注册\n  var addResult = V8.FormEngine.AddFormData(\'Sys_User\', {\n    No: \'\',\n    Account: phone,\n    Phone: phone,\n    Pwd: V8.EncryptHelper.DESEncode(phone.substring(phone.length - 6)),  // 默认密码为手机号后6位\n    Name: phone,\n    DeptId: \'\',\n    DeptName: \'\',\n    DeptCode: \'\',\n    RoleIds: \'[]\',\n    Level: 1,\n    State: 1\n  });\n\n  if (addResult.Code != 1) {\n    return { Code: 0, Msg: \'注册失败：\' + addResult.Msg };\n  }\n  userId = addResult.Data;\n} else if (userResult.Code == 1) {\n  // 用户已存在\n  if (userResult.Data.State != 1) {\n    return { Code: 0, Msg: \'账号已被禁用！\' };\n  }\n  userId = userResult.Data.Id;\n} else {\n  return { Code: 0, Msg: \'查询用户失败：\' + userResult.Msg };\n}\n\n// 销毁验证码缓存\nV8.Cache.Remove(\'Microi:\' + V8.OsClient + \':SmsCaptcha:\' + phone);\n\n// 获取登录用户完整信息\nvar loginUserResult = V8.FormEngine.GetFormData(\'Sys_User\', {\n  _Where: [[\'Id\', \'=\', userId]],\n  _SelectFields: [\'Id\', \'Account\', \'Name\', \'Phone\', \'HeadImgUrl\', \'RoleIds\', \'Level\', \'DeptId\', \'DeptName\']\n});\n\nif (loginUserResult.Code != 1) {\n  return { Code: 0, Msg: \'获取用户信息失败！\' };\n}\n\nreturn { Code: 1, Data: loginUserResult.Data, Msg: \'登录成功\' };', b'1', 'sys_user', '必传：Account、Pwd、\n可选：_SmsCaptchaValue（短信验证码，之所以为可选是因为短信通道可能出错，此时只要图形验证码通过即可注册。而图形验证码通过时会往缓存里存一个[SmsCaptcha:Phone=Allow]，因此注册接口无需再次验证图形码）', '', '', '/api/SysUser/reg', b'0', '[]', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `sys_apiengine` VALUES ('3afb1835-2f49-43fe-9be5-4d1358bbfad5', '2024-08-08 13:15:16', '2026-03-21 03:20:16', 'a0bc4cf2-f0f2-4b60-9474-44febe304e9c', '崔思敏', b'0', '[飞书]授权登录获取Token自动登录', 'feishu_login', b'1', '[]', 'var code = V8.Param.code\n// 获取飞书应用\nvar feishuApp = V8.FormEngine.GetFormData({\n    FormEngineKey : \'diy_feishu_app\',\n    OsClient: \"iTdos\",\n     _Where : [\n        { Name : \'AppKey\', Value : V8.Param.appKey, Type : \'=\' }, \n    ]\n})\nif(feishuApp.Code && feishuApp.Code != 1){\n  V8.Result = {Code: 0, Msg: \"获取app失败\"}\n  return;\n}\n//获取飞书自建应用token\nvar apiUrl = \'https://open.feishu.cn/open-apis/auth/v3/app_access_token/internal\';\nvar app_id = feishuApp.Data.AppId;\nvar app_secret = feishuApp.Data.AppSecret;\nvar result = V8.Http.Post({\n  Url : apiUrl,\n  PostParam : {\n    app_id : app_id,\n    app_secret : app_secret,\n  }\n});\nvar appObj = JSON.parse(result);\nif(appObj.code != 0){\n  V8.Result = { Code : 0, Data : appObj, Msg : \'获取飞书access_token失败：\' + appObj.msg }; return;\n}\n//获取用户预授权token\nvar appUrl_user_pre = \'https://open.feishu.cn/open-apis/authen/v1/oidc/access_token\'\nvar getUserPreToken = V8.Http.Post({\n    Url : appUrl_user_pre,\n    Headers : {\n        \'Authorization\' : \'Bearer \' + appObj.app_access_token\n    },\n    PostParam : {\n        grant_type : \'authorization_code\',\n        code : code\n    }\n});\nlet codeToken = JSON.parse(getUserPreToken)\nif(codeToken.code != 0){\n  V8.Result = { Code : 0, Data : codeToken, Msg : \'获取用户预授权token失败：\' + codeToken.msg }; return;\n}\nvar user_access_token = codeToken.data.access_token\n//获取用户信息\nvar getUserInfoApiUrl = \'https://open.feishu.cn/open-apis/authen/v1/user_info\';\nvar getUserInfoResult = V8.Http.Get({\n  Url : getUserInfoApiUrl,\n  Headers : {\n    Authorization : \'Bearer \' + user_access_token\n  },\n  PostParam : {\n  }\n});\nvar getUserInfoObj = JSON.parse(getUserInfoResult);\nif(getUserInfoObj.code != 0){\n  V8.Result = { Code : 0, Data: getUserInfoObj, Msg : \'获取用户信息失败！\' }; return;\n}\nvar user_id = getUserInfoObj.data.user_id;\nvar union_id = getUserInfoObj.data.union_id\nvar user_name = getUserInfoObj.data.en_name\nif(!user_id){\n  V8.Result = { Code : 0, Data: getUserInfoObj, Msg : \'获取user_id失败！\' }; return;\n}\n//根据user_id【 FeishuUserId 】查询到用户，拿到token用于前端自动登录\nvar userResult = V8.FormEngine.GetFormData({\n  FormEngineKey : \'sys_user\',\n  _Where: [{ Name : \'FeishuUserId\', Value : user_id, Type : \'=\' }, \n            { AndOr : \'OR\', Name : \'Account\', Value : user_id, Type : \'=\' }]\n});\nif(userResult.Code != 1){\n  V8.Result = { Code : 0, Msg : \'根据飞书user_id获取用户失败：\' + userResult.Msg }; return;\n}\nvar userInfo = userResult.Data;\nuserInfo = V8.Method.SetSysUserRoleInfo(userInfo, V8.OsClient);\n//获取用户的token\nvar getAccessTokenResult = V8.Method.GetAccessToken({\n  OsClient : V8.OsClient,\n  CurrentUser : userInfo\n});\nif(getAccessTokenResult.Code != 1){\n  V8.Result = { Code : 0, Msg : \'根据用户token失败：\' + getAccessTokenResult.Msg }; return;\n}\nV8.Result = {\n  Code : 1,\n  Data : getAccessTokenResult.Data,\n};', b'0', '', 'code: 飞书登录成功后返回预授权码\nAppKey： 飞书应用key', '{\n\"code\": \"0fo4JdTPTwqpOiNG42bsTdQDeaiO6gez\",\n\"appKey\":\"MicroiH5\"\n}', '[2024-08-14 12:50:14]执行结果：{\"Code\":0,\"Data\":{\"code\":20003,\"message\":\"The code passed is invalid. Please note that the code could only be used once.\"},\"Msg\":\"获取用户预授权token失败：undefined\"}', '/apiengine/feishu_login', b'1', '[]', 0, '飞书', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `sys_apiengine` VALUES ('41032587-c43d-4c60-852b-0f620d9d1cbc', '2024-09-03 17:06:50', '2026-03-21 03:20:16', 'a0bc4cf2-f0f2-4b60-9474-44febe304e9c', '崔思敏', b'0', '企微发送消息', 'qiWei_SendMsg', b'1', '[]', '// 获取应用数据\nvar res = V8.FormEngine.GetFormData({\n  FormEngineKey: \'diy_qiwei_app\',\n  _Where : [\n    { Name : \'YingyongKEY\', Value : \'microi\', Type : \'Like\'}\n  ]\n})\nvar corpid = res.Data.QiyeCORPID\nvar corpsecret = res.Data.AppSecret\nvar Agentid = res.Data.Agentid\n// 获取access_token\nvar accessRes = V8.Http.Post({\n  Url : `https://qyapi.weixin.qq.com/cgi-bin/gettoken?corpid=${corpid}&corpsecret=${corpsecret}`\n})\nvar objAccessRes = JSON.parse(accessRes)\nvar content = {\n   \"content\" : \"123123213\"\n}\n// 发送消息\nvar data = {\n  \"touser\" : \"CuiSiMin\", // 成员ID列表（消息接收者，多个接收者用‘|’分隔，最多支持1000个）。特殊情况：指定为@all，则向关注该企业应用的全部成员发送\n   \"toparty\" : \"\", // 部门ID列表，多个接收者用‘|’分隔，最多支持100个。当touser为@all时忽略本参数\n   \"totag\" : \"\", // 标签ID列表，多个接收者用‘|’分隔，最多支持100个。当touser为@all时忽略本参数\n   \"msgtype\" : \"textcard\",  // 消息类型 \"text\" :文本，textcard： 卡片\n   \"agentid\" : Agentid, // 企业应用的id，整型。可在应用的设置页面查看\n  //  \"text\" : content, \n   \"textcard\" : {\n      \"title\" : \"领奖通知\",\n      \"description\" : \"<div class=\\\"gray\\\">2016年9月26日</div> <div class=\\\"normal\\\">恭喜你抽中iPhone 7一台，领奖码：xxxx</div><div class=\\\"highlight\\\">请于2016年10月10日前联系行政同事领取</div>\",\n      \"url\" : \"https://wuma-m.nbweixin.cn\",\n      \"btntxt\":\"更多\"\n   },\n   \"safe\":0, // 表示是否是保密消息，0表示否，1表示是，默认0\n   \"enable_id_trans\": 0, // 表示是否开启id转译，0表示否，1表示是，默认0\n   \"enable_duplicate_check\": 0, // 表示是否开启重复消息检查，0表示否，1表示是，默认0\n   \"duplicate_check_interval\": 1800 // 表示是否重复消息检查的时间间隔，默认1800s\n}\nvar sendRes = V8.Http.Post({\n  Url : `https://qyapi.weixin.qq.com/cgi-bin/message/send?access_token=${objAccessRes.access_token}`,\n  PostParamstring : JSON.stringify(data),\n  ParamType : \'json\',\n  Headers : {\n    \"content-Type\":\"application/json\",\n  }\n})\nV8.Result = sendRes', b'0', '', '', '', '[2024-12-13 09:51:42]执行结果：{\"errcode\":0,\"errmsg\":\"ok\",\"msgid\":\"mrVtVXE39it1tWVvd57npKvi-TsHXGc_nZSSiVGoGhaJ6l5QKxUACh2ZvKAkkEkT2j9yh9chQwhveVqsSt8b1Q\"}', '', b'0', '[]', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `sys_apiengine` VALUES ('42492b7c-1348-4470-b3c3-a8c99590c663', '2025-01-06 02:10:57', '2026-03-21 03:20:16', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '[系统]翻译引擎', 'translate-engine', b'1', '[]', '//每个函数最后一个V8.OsClient如果不传就默认使用主库的配置，传入对应saas就是使用对应saas库的数据或配置\n//通过阿里云接口翻译\nvar a1 = V8.TranslateEngine.Translate(\'张三\', \'en\');//将【张三】翻译成【英语】\nvar a2 = V8.TranslateEngine.Translate(\'love\', \'cn\', \'en\', V8.OsClient);//将【love】翻译成【中文】，并且设置源文字的语种为【en】\n//从diy_lang表缓存中提取翻译\nvar a3 = V8.TranslateEngine.GetLang(\'NoAuth\');\nvar a4 = V8.TranslateEngine.GetLang(\'NoLogin\', \'cn\');\nvar a5 = V8.TranslateEngine.GetLang(\'ParamError\', \'cn\', V8.OsClient);\nvar a6 = V8.TranslateEngine.GetLangCode(\'NoLogin\');\nvar a7 = V8.TranslateEngine.GetLangCode(\'NoLogin\', V8.OsClient);\nvar a8 = V8.TranslateEngine.GetLangData(\'NoLogin\', V8.OsClient);\nvar a9 = V8.TranslateEngine.GetLang(\'NO0001\', \'en\');\n\nreturn {\n  a1 : a1,\n  a2 : a2,\n  a3 : a3,\n  a4 : a4,\n  a5 : a5,\n  a6 : a6,\n  a7 : a7,\n  a8 : a8,\n  a9 : a9\n};', b'1', '', '必传：Lang、SourceText、OsClient 可选：FromLang \n官方文档：https://next.api.aliyun.com/api/alimt/2018-10-12/TranslateGeneral?tab=DOC&lang=CSHARP', '', '[2025-01-08 14:56:43]执行结果：{\"Code\":0,\"Data\":null,\"DataAppend\":null,\"Msg\":\"执行服务器端V8代码出现错误：NO0001 is not defined -->    at <anonymous>:1:1\",\"DataCount\":null}', '/apiengine/translate-engine', b'0', '[]', 0, '', 1, 0, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `sys_apiengine` VALUES ('431a19a1-44ab-4dbf-bf58-898165087c5f', '2026-01-06 04:08:36', '2026-03-21 03:20:17', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '[微信]微信支付回调接口', 'wxpay-notify', b'1', '[]', '//写回调日志\nvar v8Param = {\n  \"id\": V8.Param.id,\n  \"create_time\": V8.Param.create_time,\n  \"resource_type\": V8.Param.resource_type,\n  \"event_type\": V8.Param.event_type,\n  \"summary\": V8.Param.summary,\n  \"resource\": {\n      \"original_type\": V8.Param.resource && V8.Param.resource.original_type,\n      \"algorithm\": V8.Param.resource && V8.Param.resource.algorithm,\n      \"ciphertext\": V8.Param.resource && V8.Param.resource.ciphertext,\n      \"associated_data\": V8.Param.resource && V8.Param.resource.associated_data,\n      \"nonce\": V8.Param.resource && V8.Param.resource.nonce,\n  }\n};\nV8.FormEngine.AddFormData(\'diy_important_log\', {\n  RizhiMC : \'会员订单支付回调参数\',\n  RizhiLB : \'支付回调\',\n  RizhiNR : JSON.stringify(v8Param)\n});\nvar APIv3SecretKey = V8.OsClientModel.APIv3SecretKey;\n//参数校验\nif(!APIv3SecretKey){\n  V8.FormEngine.AddFormData({\n    FormEngineKey : \'diy_important_log\',\n    _RowModel : {\n      RizhiMC : \'会员订单支付回调错误\',\n      RizhiLB : \'支付回调\',\n      RizhiNR : \'支付配置有误！\',\n      //GuanlianID : orderNo\n    }\n  });\n  return { Code : 0, Msg : \'支付配置有误！\' };\n}\nvar wxParam = V8.Param;\nif(wxParam.event_type != \'TRANSACTION.SUCCESS\'){\n  V8.FormEngine.AddFormData({\n    FormEngineKey : \'diy_important_log\',\n    _RowModel : {\n      RizhiMC : \'会员订单支付回调错误\',\n      RizhiLB : \'支付回调\',\n      RizhiNR : JSON.stringify({ \"code\": \"FAIL\", \"message\": \"失败\" }),\n      //GuanlianID : orderNo\n    }\n  });\n  return { Code : 0, Msg : \'wxParam.event_type != \\\'TRANSACTION.SUCCESS\\\'\' };\n}\n//解密微信发过来的数据\nvar wxOrderParamStr = V8.Method.AesGcmDecrypt(\n  wxParam.resource.associated_data, \n  wxParam.resource.nonce, \n  wxParam.resource.ciphertext,\n  APIv3SecretKey\n);\nvar wxOrderParam = JSON.parse(wxOrderParamStr);\n//商户自有订单号\nvar orderNo = wxOrderParam.out_trade_no;\n//写回调日志\nV8.FormEngine.AddFormData({\n  FormEngineKey : \'diy_important_log\',\n  _RowModel : {\n    RizhiMC : \'会员订单支付回调解密参数\',\n    RizhiLB : \'支付回调\',\n    RizhiNR : wxOrderParamStr,\n    GuanlianID : orderNo\n  }\n});\nif(wxOrderParam.trade_state != \'SUCCESS\'){\n  V8.FormEngine.AddFormData({\n    FormEngineKey : \'diy_important_log\',\n    _RowModel : {\n      RizhiMC : \'会员订单支付回调错误\',\n      RizhiLB : \'支付回调\',\n      RizhiNR : JSON.stringify({ \"code\": \"FAIL\", \"message\": \"失败\" }),\n      GuanlianID : orderNo\n    }\n  });\n  V8.Result = { Code : 0, Msg : \'wxOrderParam.trade_state != \\\'SUCCESS\\\'\' }; return;\n}\n//获取订单信息\nvar orderModelResult = V8.FormEngine.GetFormData({\n  FormEngineKey : \'diy_order\',\n  _Where : [{ Name : \'DingdanBH\', Value : orderNo, Type : \'=\' }]\n});\nif(orderModelResult.Code != 1){\n  //写回调日志\n  V8.FormEngine.AddFormData({\n    FormEngineKey : \'diy_important_log\',\n    _RowModel : {\n      RizhiMC : \'会员订单支付回调异常\',\n      RizhiLB : \'支付回调\',\n      RizhiNR : \'获取订单信息失败：\' + JSON.stringify(orderModelResult),\n      GuanlianID : orderNo\n    }\n  });\n  V8.Result = \'获取订单信息失败：\' + JSON.stringify(orderModelResult); return;\n}\nvar orderModel = orderModelResult.Data;\nif(orderModel.DingdanZT != \'待支付\'){\n  //写回调日志\n  V8.FormEngine.AddFormData({\n    FormEngineKey : \'diy_important_log\',\n    _RowModel : {\n      RizhiMC : \'该订单状态不为【待支付】，无需重复回调\',\n      RizhiLB : \'支付回调\',\n      RizhiNR : \'获取订单信息失败：\' + JSON.stringify(orderModelResult),\n      GuanlianID : orderNo\n    }\n  });\n  V8.Result = \'success\'; return;//SUCCESS，订单已支付，无需再次回调，即使平台重复回调也返回成功。\n}\n\n//根据订单信息获取会员级别信息\n/*\nvar vipLevelModelResult = V8.FormEngine.GetFormData({\n  FormEngineKey : \'diy_vip_level\',\n  Id : orderModel.ShangpinID\n});\nif(vipLevelModelResult.Code != 1){\n  //写回调日志\n  V8.FormEngine.AddFormData({\n    FormEngineKey : \'diy_important_log\',\n    _RowModel : {\n      RizhiMC : \'会员订单支付回调异常\',\n      RizhiLB : \'支付回调\',\n      RizhiNR : \'获取会员级别信息失败：\' + JSON.stringify(vipLevelModelResult),\n      GuanlianID : orderNo\n    }\n  });\n  V8.Result = { Code : 0, Msg : \'获取会员级别信息失败：\' + JSON.stringify(vipLevelModelResult) }; return;\n}\nvar vipLevelModel = vipLevelModelResult.Data;\n*/\n\n//回写订单信息\norderModel.ZhifuSJ = V8.Action.GetDateTimeNow();//支付时间\norderModel.DingdanZT = \'待收货\';//是否已支付\norderModel.TongyiXDHTJG = wxOrderParamStr;//统一下单回调结果\norderModel.ShijiZFJE = (wxOrderParam.amount.payer_total / 100).toFixed(2);\n\nvar uptOorderResult = V8.FormEngine.UptFormData({\n  FormEngineKey : \'diy_order\',\n  Id : orderModel.Id,\n  _RowModel : orderModel\n});\nif(uptOorderResult.Code != 1){\n  //写回调日志\n  V8.FormEngine.AddFormData({\n    FormEngineKey : \'diy_important_log\',\n    _RowModel : {\n      RizhiMC : \'会员订单支付回调异常\',\n      RizhiLB : \'支付回调\',\n      RizhiNR : \'回写订单信息失败：\' + JSON.stringify(uptOorderResult),\n      GuanlianID : orderNo\n    }\n  });\n  return { Code : 0, Msg : \'回写订单信息失败：\' + JSON.stringify(uptOorderResult) };\n}\n\n//用户增加积分、抵用券\n//获取分佣明细\nvar diy_brokerage_log = V8.FormEngine.GetTableData(\'diy_brokerage_log\', {\n  _Where:[{ Name : \'DingdanID\', Value : orderModel.Id, Type : \'=\' }]\n});\nif(diy_brokerage_log.Code != 1){\n  V8.DbTrans.Rollback();\n  return diy_brokerage_log;\n}\nfor(var i = 0; i < diy_brokerage_log.Data.length; i++){\n  var item = diy_brokerage_log.Data[i];\n  //查询当前用户的积分余额、抵用券余额\n  var userResult = V8.FormEngine.GetFormData(\'sys_user\', {\n    Id : item.FenyongRID\n  });\n  if(userResult.Code == 1){\n    var uptUser = V8.FormEngine.UptFormData(\'sys_user\', {\n      Id : item.FenyongRID,\n      _RowModel : {\n        JifenYE : (userResult.Data.JifenYE || 0) + item.FenyongJF,\n        // DiyongQYE : (userResult.Data.DiyongQYE || 0) + item.FenyongDYQ\n        ShangchengQYE : (userResult.Data.ShangchengQYE || 0) + item.FenyongSCQ\n      }\n    }, V8.DbTrans);\n    if(uptUser.Code != 1){\n      V8.DbTrans.Rollback();\n      return uptUser;\n    }\n    //新增收支记录\n    if(item.FenyongJF){\n      var addYeLogResult = V8.FormEngine.AddFormData(\'diy_user_money_log\', {\n        ShouzhiSM : `订单[${orderModel.DingdanBH}]付款获得积分`,\n        HuiyuanMC : item.FenyongR,\n        HuiyuanID : item.FenyongRID,\n        YueLB : \'积分\',\n        ShouzhiLB : \'收入\',\n        ShouzhiSJ : DateNow(\'yyyy-MM-dd HH:mm:ss\'),\n        ShouzhiJE : item.FenyongJF,//收支金额\n        ShouzhiQYE : userResult.Data.DiyongQYE,//收支前余额\n        ShouzhiHYE : userResult.Data.DiyongQYE + item.FenyongJF,//收支后余额\n        GuanlianID : orderModel.Id,\n        _CurrentUser : {\n          Name : \'系统\',\n          Id : System.Guid.Empty\n        }\n      }, V8.DbTrans);\n      if(addYeLogResult.Code != 1){\n        V8.DbTrans.Rollback();\n        return addYeLogResult;\n      }\n    }\n    if(item.FenyongSCQ){\n      //新增收支记录2\n      var addYeLogResult2 = V8.FormEngine.AddFormData(\'diy_user_money_log\', {\n        ShouzhiSM : `订单[${orderModel.DingdanBH}]付款获得商城券`,\n        HuiyuanMC : item.FenyongR,\n        HuiyuanID : item.FenyongRID,\n        YueLB : \'商城券\',\n        ShouzhiLB : \'收入\',\n        ShouzhiSJ : DateNow(\'yyyy-MM-dd HH:mm:ss\'),\n        ShouzhiJE : item.FenyongSCQ,//收支金额\n        ShouzhiQYE : userResult.Data.ShangchengQYE,//收支前余额\n        ShouzhiHYE : userResult.Data.ShangchengQYE + item.FenyongSCQ,//收支后余额\n        GuanlianID : orderModel.Id,\n        _CurrentSysUser : {\n          Name : \'系统\',\n          Id : System.Guid.Empty\n        }\n      }, V8.DbTrans);\n      if(addYeLogResult2.Code != 1){\n        V8.DbTrans.Rollback();\n        return addYeLogResult2;\n      }\n    }\n    //修改分佣状态\n    var uptFenyong = V8.FormEngine.UptFormData(\'diy_brokerage_log\', {\n      Id : item.Id,\n      _RowModel : {\n        FenyongZT : \'已分佣\'\n      }\n    }, V8.DbTrans);\n    if(uptFenyong.Code != 1){\n      V8.DbTrans.Rollback();\n      return uptFenyong;\n    }\n  }else{\n    V8.DbTrans.Rollback();\n    return userResult;\n  }\n}\nV8.DbTrans.Commit();\n//一定要在这里之前提交事务\ndiy_brokerage_log.Data.forEach(item => {\n  V8.Method.RefreshLoginUser(item.FenyongRID, V8.OsClient)\n});\n\n\n//获取订单商品\nvar orderProductResult = V8.FormEngine.GetTableData(\'diy_order_product\', {\n  _Where: [{ Name : \'DingdanID\', Value : orderModel.Id, Type : \'=\' }]\n});\nif(orderProductResult.Code == 1){\n  var productIds = orderProductResult.Data.map(item => { return item.ShangpinID });\n  var productResult = V8.FormEngine.GetTableData(\'diy_product\', {\n    _Where: [{ Name : \'Id\', Value : JSON.stringify(productIds), Type : \'In\' }]\n  });\n  productResult.Data.forEach(productModel => {\n    //如果有升级为会员级别【 ShengjiWHYJB 】\n    if(productModel.ShengjiWHYJB && productModel.ShengjiWHYJB != \'无\'){\n      var uptUserResult = V8.FormEngine.UptFormData(\'sys_user\', {\n        Id : orderModel.XiadanRID,\n        _RowModel : {\n          VipLevel : productModel.ShengjiWHYJB\n        }\n      });\n      if(uptUserResult.Code != 1){\n        //写回调日志\n        V8.FormEngine.AddFormData({\n          FormEngineKey : \'diy_important_log\',\n          _RowModel : {\n            RizhiMC : \'会员订单支付回调回写会员级别失败\',\n            RizhiLB : \'支付回调\',\n            RizhiNR : \'回写会员级别失败：\' + JSON.stringify(uptUserResult),\n            GuanlianID : orderNo\n          }\n        });\n      }else{\n        V8.Method.RefreshLoginUser(orderModel.XiadanRID, V8.OsClient);\n      }\n    }\n  })\n}\nreturn \'success\';\n//会员设置级别\n/*\nvar sysUserModelResult = V8.FormEngine.GetFormData({\n  FormEngineKey : \'Sys_User\',\n  Id : orderModel.UserId\n});\nif(sysUserModelResult.Code != 1){\n  //写回调日志\n  V8.FormEngine.AddFormData({\n    FormEngineKey : \'diy_important_log\',\n    _RowModel : {\n      RizhiMC : \'会员订单支付回调异常\',\n      RizhiLB : \'支付回调\',\n      RizhiNR : \'获取会员信息失败：\' + JSON.stringify(sysUserModelResult),\n      GuanlianID :orderNo\n    }\n  });\n  V8.Result = { Code : 0, Msg : \'获取会员信息失败：\' + sysUserModelResult }; return;\n}\ntry{\n  var sysUserModel = sysUserModelResult.Data;\n  sysUserModel.HuiyuanJB = vipLevelModel.Mingcheng;\n  sysUserModel.HuiyuanJBID = vipLevelModel.Id;\n  //增加时长----START\n  if(!sysUserModel.HuiyuanDQSJ){\n    sysUserModel.HuiyuanDQSJ = new Date();\n  }else{\n    sysUserModel.HuiyuanDQSJ = new Date(sysUserModel.HuiyuanDQSJ);\n  }\n  //以下3个参数是全局函数V8.Action.AddDateTime()需要的\n  V8.Param.OldTime = sysUserModel.HuiyuanDQSJ \n  V8.Param.Number = vipLevelModel.YouxiaoQ;\n  V8.Param.Type = \'d\';\n  //以下1个参数是全局函数V8.Action.GetDateTimeNow()需要的\n  V8.Param.NowTime = V8.Action.AddDateTime();//计算出增加天数后的时间\n  sysUserModel.HuiyuanDQSJ = V8.Action.GetDateTimeNow();\n  //增加时长----END\n  var uptSysUserResult = V8.FormEngine.UptFormData({\n    FormEngineKey : \'Sys_User\',\n    Id : sysUserModel.Id,\n    _RowModel : sysUserModel\n  });\n  if(uptSysUserResult.Code != 1){\n    V8.Result = \'修改会员有效期时长失败：\' + uptSysUserResult;\n    //写回调日志\n    V8.FormEngine.AddFormData({\n      FormEngineKey : \'diy_important_log\',\n      _RowModel : {\n        RizhiMC : \'会员订单支付回调异常\',\n        RizhiLB : \'支付回调\',\n        RizhiNR : \'修改会员有效期时长失败：\' + JSON.stringify(uptSysUserResult),\n        GuanlianID : orderNo\n      }\n    });\n    return;\n  }\n  //刷新会员登陆信息\n  V8.Method.RefreshLoginUser(sysUserModel.Id, V8.OsClient);\n  //写回调日志\n  V8.FormEngine.AddFormData({\n    FormEngineKey : \'diy_important_log\',\n    _RowModel : {\n      RizhiMC : \'会员订单支付回调成功\',\n      RizhiLB : \'支付回调\',\n      RizhiNR : \'success\',\n      GuanlianID :orderNo\n    }\n  });\n  V8.Result = \'success\';//SUCCESS\n}catch(e){\n  //写回调日志\n  V8.FormEngine.AddFormData({\n    FormEngineKey : \'diy_important_log\',\n    _RowModel : {\n      RizhiMC : \'会员订单支付回调异常\',\n      RizhiLB : \'支付回调\',\n      RizhiNR : e.message,\n      GuanlianID :orderNo\n    }\n  });\n  return { Code : 0, Msg : e.message };\n}\n*/\n', b'0', 'Id', 'https://pay.weixin.qq.com/wiki/doc/apiv3/apis/chapter3_5_5.shtml', '', '', '/apiengine/wxpay-notify', b'1', '[]', 0, '', 0, 0, '', '', 600, 100000000, 2048, 10000);
INSERT INTO `sys_apiengine` VALUES ('44f1609a-6920-4b5c-9184-18b61240909d', '2024-08-09 13:54:34', '2026-03-21 03:20:16', 'a0bc4cf2-f0f2-4b60-9474-44febe304e9c', '崔思敏', b'0', '获取服务器配置地址', 'get_apibase', b'1', '[]', 'var res = V8.FormEngine.GetFormData({\n  FormEngineKey: \'diy_project_seting\',\n  _Where: [\n  { Name:\'Client\', Value: V8.Param.Client, Type:\'=\' }\n  ]\n})\nV8.Result = res', b'0', '', 'Client', '{\"Client\":\"crm\"}', '[2024-08-09 14:10:02]执行结果：{\"Code\":1,\"Data\":{\"Id\":\"f3091f80-53ae-400c-972a-b2ed10e001be\",\"CreateTime\":\"2024-08-08 17:03:28\",\"UpdateTime\":null,\"UserId\":\"a0bc4cf2-f0f2-4b60-9474-44febe304e9c\",\"UserName\":\"崔思敏\",\"IsDeleted\":0,\"XiangmuMC\":\"iTdos\",\"Client\":\"iTdos\",\"ApiBase\":\"https://api-china.itdos.com\"},\"DataAppend\":{\"ServerRunSql\":\" SELECT * FROM `diy_project_seting` A  WHERE  A.`Client` = \'iTdos\'  AND  A.IsDeleted <> 1  ORDER BY A.`CreateTime` DESC,A.Id asc \"},\"Msg\":\"\"}', '/api/get_apibase', b'1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `sys_apiengine` VALUES ('4617671b-ac06-40c0-b26f-06e73d87187b', '2024-09-02 11:20:56', '2026-03-21 03:20:16', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', b'0', '[系统]获取系统菜单数据', 'get-sys-menu-tree', b'1', '[]', 'var dataAppend = {};\nvar _menuWhere = [];\nif(V8.Param.DesktopType == \'macos\'){\n  _menuWhere = [{ Name : \'DisplayMac\', Value : 1, Type : \'=\' }];\n}else{\n  _menuWhere = [{ Name : \'DisplayWin\', Value : 1, Type : \'=\' }];\n}\nif(V8.Param.AppDisplay != undefined){\n  _menuWhere.push({ Name : \'AppDisplay\', Value : V8.Param.AppDisplay ? 1 : 0, Type : \'=\' });\n}\n/*\ndataAppend[\'GetSysMenuTree_CurrentUser\'] = {\n  CurrentUser: V8.CurrentUser,\n  _CurrentUser: V8.Param._CurrentUser,\n};\n*/\n//如果不是超级管理员，判断权限\nif(V8.Param._CurrentUser && V8.Param._CurrentUser.Id && (!V8.CurrentUser || !V8.CurrentUser.Id)){\n  V8.CurrentUser = V8.Param._CurrentUser;\n}\nif(V8.CurrentUser && V8.CurrentUser.Id && V8.CurrentUser.Level < 999 && V8.CurrentUser.Account != \'admin\'){\n  var roleIds = [];\n  var userRoles = JSON.parse(V8.CurrentUser.RoleIds);\n  //dataAppend[\'GetSysMenuTree_RoleIds\'] = userRoles;\n  userRoles.forEach(item => {\n    if(typeof(item) == \'string\'){\n      roleIds.push(item);\n    }else {\n      roleIds.push(item.Id);\n    }\n  })\n  var limitListResult = V8.FormEngine.GetTableData(\'Sys_RoleLimit\', {\n    _Where: [{ Name : \'Type\', Value : \'Menu\', Type : \'=\' }, \n            { Name : \'RoleId\', Value : JSON.stringify(roleIds), Type : \'In\' }]\n  });\n  var menuIds = [];\n  //dataAppend[\'GetSysMenuTree_limitListResult\'] = limitListResult;\n  if(limitListResult.Code == 1){\n    menuIds = limitListResult.Data.map(item => item.FkId);\n    //dataAppend[\'GetSysMenuTree_menuIds\'] = menuIds;\n    _menuWhere.push({ Name : \'Id\', Value : JSON.stringify(menuIds), Type : \'In\' });\n  }else{\n    dataAppend[\'GetSysMenuTree_SysRoleLimit_Error\'] = limitListResult.Msg;\n  }\n}\nvar result = V8.FormEngine.GetTableDataTree({\n  FormEngineKey : \'sys_menu\',\n  _TreeLazy : 0,\n  _Where: _menuWhere,\n  _OrderBy : \'Sort\',\n  _OrderByType : \'ASC\',\n  _SelectFields : [\'Id\', \'Name\', \'Icon\', \'IconClass\', \'Display\', \'AppDisplay\', \'IsMicroiService\', \n    \'OpenType\', \'ComponentName\', \'ComponentPath\', \'PageTemplate\', \'Url\',\n    \'DiyTableId\', \'ParentId\', \'Sort\', \n    \'MacScreenIndex\', \'SizeWidthMac\', \'SizeHeightMac\', \n    \'SecondMenuWidth\', \'SecondMenuHeight\', \'SecondMenuLineCount\', \'IconComponent\', \'SecondMenuColumn\', \'SecondMenuRow\']\n});\n//dataAppend[\'GetSysMenuTree_Where\'] = _menuWhere;\nif(result.Code != 1){\n  V8.Result = result; return;\n}\n//分屏数据\nvar ModuleList = [];\nif(V8.SysConfig.MacScreenCount){\n  for(var i = 1; i <= V8.SysConfig.MacScreenCount; i++){\n    var arr = [];\n    if(i == 1){\n      arr = result.Data.filter(item => item.MacScreenIndex == 1 || !item.MacScreenIndex);\n    }else{\n      arr = result.Data.filter(item => item.MacScreenIndex == i);\n    }\n    ModuleList.push({\n      ScreenId : i,\n      ScreenName : \'\',\n      List: arr\n    });\n  }\n}else{\n  ModuleList.push({\n    ScreenId : 1,\n    ScreenName : \'\',\n    List: result.Data\n  });\n}\n//dataAppend[\'DataAppend\'] = dataAppend.DataAppend;\nV8.Result = { Code : 1, Data : ModuleList, DataAppend : dataAppend };', b'0', '', '', '', '[2024-10-12 15:39:20]执行结果：{\"Code\":1,\"Data\":[{\"ScreenId\":1,\"ScreenName\":\"\",\"List\":[{\"Id\":\"a109bc95-8ddd-49e4-8bb7-5102efd201f0\",\"Name\":\"首页\",\"Icon\":\"/itdos/sysmenu/20240928/home.png\",\"IconClass\":\"fas fa-home\",\"Display\":1,\"AppDisplay\":1,\"IsMicroiService\":0,\"OpenType\":\"Component\",\"ComponentName\":\"\",\"ComponentPath\":\"/diy-home\",\"PageTemplate\":\"\",\"Url\":\"/\",\"DiyTableId\":\"\",\"ParentId\":\"00000000-0000-0000-0000-000000000000\",\"Sort\":-999},{\"Id\":\"3f6fca15-d3ce-453c-9dc1-d4dc161644f1\",\"Name\":\"我的工作\",\"Icon\":\"\",\"IconClass\":\"fas fa-tasks\",\"Display\":1,\"AppDisplay\"