{\"Id\":\"4848633b-4845-4494-9aad-7843857b9a5a\",\"Name\":\"测试iframe\",\"Icon\":\"\",\"IconClass\":\"\",\"Display\":1,\"AppDisplay\":1,\"IsMicroiService\":0,\"OpenType\":\"Iframe\",\"ComponentName\":\"\",\"ComponentPath\":\"\",\"PageTemplate\":\"\",\"Url\":\"/iframe/https://microi.net?diyToken=$V8.CurrentToken$\",\"DiyTableId\":\"\",\"ParentId\":\"44ab649f-a2f9-4c0f-b3b6-677b2dd4c541\",\"Sort\":0},{\"Id\":\"632ce1f9-6e3d-41ee-a34c-c02d134f3aa2\",\"Name\":\"测试打开百度\",\"Icon\":\"\",\"IconClass\":\"\",\"Display\":1,\"AppDisplay\":1,\"IsMicroiService\":0,\"OpenType\":\"SecondMenu\",\"ComponentName\":\"\",\"ComponentPath\":\"\",\"PageTemplate\":\"\",\"Url\":\"https://www.baidu.com\",\"DiyTableId\":\"\",\"ParentId\":\"44ab649f-a2f9-4c0f-b3b6-677b2dd4c541\",\"Sort\":0},{\"Id\":\"c6468241-f16c-4abb-aa54-bd59fd4b7cc4\",\"Name\":\"博文测试\",\"Icon\":\"\",\"IconClass\":\"\",\"Display\":1,\"AppDisplay\":1,\"IsMicroiService\":0,\"OpenType\":\"Diy\",\"ComponentName\":\"\",\"ComponentPath\":\"/diy/diy-table-rowlist\",\"PageTemplate\":\"\",\"Url\":\"/bowenceshi\",\"DiyTableId\":\"7508d9e6-3cfa-4027-aee1-782b4ecf908b\",\"ParentId\":\"44ab649f-a2f9-4c0f-b3b6-677b2dd4c541\",\"Sort\":0},{\"Id\":\"643d2478-284c-4b3d-8d2b-8e37f6230740\",\"Name\":\"报表子表用户访问记录\",\"Icon\":null,\"IconClass\":null,\"Display\":1,\"AppDisplay\":1,\"IsMicroiService\":0,\"OpenType\":\"Diy\",\"ComponentName\":null,\"ComponentPath\":\"/diy/diy-table-rowlist\",\"PageTemplate\":null,\"Url\":\"/baobiaozibiaoyhfwjl\",\"DiyTableId\":\"f9582b52-faba-490a-9b72-df032c5d8827\",\"ParentId\":\"44ab649f-a2f9-4c0f-b3b6-677b2dd4c541\",\"Sort\":1},{\"Id\":\"7fd79e47-52fd-4b94-a98a-b26617002b65\",\"Name\":\"测试vue3\",\"Icon\":\"\",\"IconClass\":\"fas fa-address-card\",\"Display\":1,\"AppDisplay\":1,\"IsMicroiService\":0,\"OpenType\":\"Diy\",\"ComponentName\":\"\",\"ComponentPath\":\"/diy/diy-table-rowlist\",\"PageTemplate\":\"\",\"Url\":\"/ceshivue3\",\"DiyTableId\":\"44833819-2651-48b6-9e16-6d4abb9321fa\",\"ParentId\":\"44ab649f-a2f9-