INSERT INTO `sys_config` VALUES ('a5fabe90-995f-45a0-adb4-606cdb98cdcd', '', '2021-08-23 15:33:28', '2026-04-22 01:16:20', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '管理员', 0, 'Microi吾码 - 空库', 'Microi吾码', '小吾科技', '{\"Id\":\"legacy_1772681504737\",\"Name\":\"microi-red-256-1768377694.png\",\"Size\":\"\",\"CreateTime\":\"\",\"Path\":\"https://static.itdos.com/itdosimg/20260114/microi-red-256-1768377694.png\",\"State\":1}', '默认配置', 1, '{\"Id\":\"legacy_1772681504737\",\"Name\":\"desktop-bg-1768377708.jpg\",\"Size\":\"\",\"CreateTime\":\"\",\"Path\":\"https://static.itdos.com/itdosimg/20260114/desktop-bg-1768377708.jpg\",\"State\":1}', '', 0, '', '{\"Id\":\"legacy_1772681504737\",\"Name\":\"favicon-1768377697.ico\",\"Size\":\"\",\"CreateTime\":\"\",\"Path\":\"https://static.itdos.com/itdosimg/20260114/favicon-1768377697.ico\",\"State\":1}', '文字图形', '50', '/', NULL, '', NULL, NULL, '', 'V8.Extend.GetDateTimeNow = function(format){\n  var time = new Date();\n  if (!format) {\n    var year = time.getFullYear();\n    var month = time.getMonth() + 1;\n    var day = time.getDate();\n    var hh = time.getHours();\n    var mm = time.getMinutes();\n    var ss = time.getSeconds();\n    return year + \'-\' \n            + (month > 9 ? month : \'0\' + month) + \'-\' \n            + (day > 9 ? day : \'0\' + day) + \' \' \n            + (hh > 9 ? hh : \'0\' + hh) + \':\' \n            + (mm > 9 ? mm : \'0\' + mm) + \':\' \n            + (ss > 9 ? ss : \'0\' + ss);\n  }\n  var o = {\n    \'M+\': time.getMonth() + 1, // month\n    \'d+\': time.getDate(), // day\n    \'h+\': time.getHours(), // hour\n    \'H+\': time.getHours(), // hour\n    \'m+\': time.getMinutes(), // minute\n    \'s+\': time.getSeconds(), // second\n    \'q+\': Math.floor((time.getMonth() + 3) / 3), // quarter\n    \'S\': time.getMilliseconds() // millisecond\n  }\n  if (/(y+)/.test(format)) {\n    format = format.replace(RegExp.$1,\n      (time.getFullYear() + \'\').substr(4 - RegExp.$1.length))\n  }\n  for (var k in o) {\n    if (new RegExp(\'(\' + k + \')\').test(format)) {\n      format = format.replace(RegExp.$1,\n        RegExp.$1.length == 1 ? o[k]\n          : (\'00\' + o[k]).substr((\'\' + o[k]).length))\n    }\n  }\n  return format\n}\n\n//定义加载关联表单的函数，可以在进入表单事件，也可以在任何触发事件\nV8.Extend.LoadJoinForm = function(tableNameOrId, joinFormFieldName, joinId, formMode, v8obj){\n    //仅仅测试下传过来的v8obj对象与V8对象是否是同一个对象，若此函数使用window.LoadJoinForm来定义，建议此处v8对象由其它V8事件传过来\n    //var v8 = v8obj ? v8obj : V8;\n    var v8 = V8;\n    if(!tableNameOrId || !joinFormFieldName || !joinId || !formMode){\n      v8.Tips(\'关联表单参数错误！\', false);\n      return;\n    }\n    var joinFormConfig = {\n        //如果是36位，那一定是Id，否则就是TableName\n        TableName: tableNameOrId.length == 36 ? \'\' : tableNameOrId,\n        TableId: tableNameOrId.length == 36 ? tableNameOrId : \'\',\n        FormMode: formMode//关联表单与主表同步状态，也可以手动传入\'Add/Edit/View\'\n    };\n    joinFormConfig.Id = joinId;//关联表的Id值，可以与主表Id(V8.Form.Id)一致，也可以生成一个全新的，跟主表的某个值关联\n    v8.Field[joinFormFieldName].Config.JoinForm = joinFormConfig;// 关联表单field字段属性-赋值\n    v8.FieldSet(joinFormFieldName, \'Config\', v8.Field[joinFormFieldName].Config);// 关联表单field字段属性-赋值\n    v8.ReloadJoinForm(v8.Field[joinFormFieldName]);// 刷新关联表单\n}', 'https://static.itdos.com', 'https://static.itdos.com', 0, '', '', '', '<div class=\"col-md-12\">\n      {{ OsVersion }}\n</div>\n<div class=\"col-md-12\">\n      Copyright © 2009 - 2026\n</div>', 'Style1', '', '', '<div>\n@$SysShortTitle$ - ©$CompanyName$ - $OsVersion$ - Copyright © 2009-2024 - <a target=\"_blank\" href=\"https://qm.qq.com/cgi-bin/qm/qr?k=V9zkmFPZtp3kEuVOxWq81Q5SvckhPa1n&jump_from=webapi&authKey=LC364mgylbapiK9DbLaKN5NueHgh4mbuIqqsc3YdiDX6QiPYyFkYooECyTWHNSOj\">QQ群60831381</a> - 浙ICP备20023076号-2 [动态配置]\n</div>', 0, 0, 0, 0, 0, 0, 0, '\nfunction calc(operation, ...numbers) {\n    const multipliers = numbers.map(num => {\n        const decimal = num.toString().split(\'.\')[1];\n        return decimal ? Math.pow(10, decimal.length) : 1;\n    });\n    \n    const maxMultiplier = Math.max(...multipliers);\n    const results = numbers.map(num => num * maxMultiplier);\n    \n    let result;\n    switch(operation) {\n        case \'+\': result = results.reduce((sum, curr) => sum + curr, 0); break;\n        case \'-\': result = results.reduce((diff, curr, i) => i === 0 ? curr : diff - curr); break;\n        case \'*\': result = results.reduce((product, curr) => product * curr, 1); break;\n        case \'/\': result = results.reduce((quotient, curr, i) => i === 0 ? curr : quotient / curr); break;\n        default: throw new Error(\'Unsupported operation\');\n    }\n    \n    return result / (operation === \'*\' ? Math.pow(maxMultiplier, numbers.length) : \n                 operation === \'/\' ? Math.pow(maxMultiplier, numbers.length - 1) : maxMultiplier);\n}\nfunction DateNow(format) {\n  var time = new Date();\n  if (!format) {\n    var year = time.getFullYear();\n    var month = time.getMonth() + 1;\n    var day = time.getDate();\n    var hh = time.getHours();\n    var mm = time.getMinutes();\n    var ss = time.getSeconds();\n    return year + \'-\' \n            + (month > 9 ? month : \'0\' + month) + \'-\' \n            + (day > 9 ? day : \'0\' + day) + \' \' \n            + (hh > 9 ? hh : \'0\' + hh) + \':\' \n            + (mm > 9 ? mm : \'0\' + mm) + \':\' \n            + (ss > 9 ? ss : \'0\' + ss);\n  }\n  \n  var year = time.getFullYear();\n  var month = (\'0\' + (time.getMonth() + 1)).slice(-2);\n  var day = (\'0\' + time.getDate()).slice(-2);\n  var hours = (\'0\' + time.getHours()).slice(-2);\n  var minutes = (\'0\' + time.getMinutes()).slice(-2);\n  var seconds = (\'0\' + time.getSeconds()).slice(-2);\n\n  var formattedDate = format;\n\n  formattedDate = formattedDate.replace(\'yyyy\', year);\n  formattedDate = formattedDate.replace(\'MM\', month);\n  formattedDate = formattedDate.replace(\'dd\', day);\n  formattedDate = formattedDate.replace(\'HH\', hours);\n  formattedDate = formattedDate.replace(\'mm\', minutes);\n  formattedDate = formattedDate.replace(\'ss\', seconds);\n\n  return formattedDate;\n}\n//传入日期或字符串类型的time\nfunction DateFormat(time, format) {\n  if (!time) {\n    return null;\n  }\n  if (typeof time === \'string\') {\n    time = new Date(time);\n  }\n  if (!format) {\n    format = \'yyyy-MM-dd HH:mm:ss\';\n  }\n\n  var year = time.getFullYear();\n  var month = (\'0\' + (time.getMonth() + 1)).slice(-2);\n  var day = (\'0\' + time.getDate()).slice(-2);\n  var hours = (\'0\' + time.getHours()).slice(-2);\n  var minutes = (\'0\' + time.getMinutes()).slice(-2);\n  var seconds = (\'0\' + time.getSeconds()).slice(-2);\n\n  format = format.replace(\'yyyy\', year);\n  format = format.replace(\'MM\', month);\n  format = format.replace(\'dd\', day);\n  format = format.replace(\'HH\', hours);\n  format = format.replace(\'mm\', minutes);\n  format = format.replace(\'ss\', seconds);\n\n  return format;\n}\nfunction DateAdd(startTime, strInterval, number, format) {\n  var dtTmp = new Date(startTime);\n  var realFormat = format || \'yyyy-MM-dd HH:mm:ss\';\n\n  if (typeof number === \'string\') {\n      number = parseInt(number, 10);\n  }\n\n  var result = new Date(dtTmp);\n  switch (strInterval) {\n      case \'s\': //秒\n          result.setSeconds(result.getSeconds() + number);\n          break;\n      case \'n\': //分（这里\'n\'和\'m\'重复了，我保留\'n\'作为分钟，但通常使用\'m\'）\n      case \'m\': //分\n          result.setMinutes(result.getMinutes() + number);\n          break;\n      case \'h\': //小时\n      case \'H\': //小时（\'H\'通常用于24小时制，但这里我们不做区分）\n          result.setHours(result.getHours() + number);\n          break;\n      case \'d\': //天\n          result.setDate(result.getDate() + number);\n          break;\n      case \'w\': //周\n          result.setDate(result.getDate() + number * 7);\n          break;\n      case \'q\': //季\n          result.setMonth(result.getMonth() + number * 3);\n          break;\n      case \'M\': //月\n          var month = result.getMonth() + number;\n          var year = result.getFullYear();\n          var day = result.getDate();\n          result.setMonth(month);\n          // 如果日期溢出，则设置为该月的最后一天\n          if (result.getDate() !== day) {\n              result.setDate(0); // 设置为上个月的最后一天，然后加1天得到本月的最后一天\n          }\n          // 如果年份变了（比如从12月增加到下一年1月前的情况），则调整年份\n          if (result.getMonth() === month - number && result.getMonth() !== 11) {\n              result.setFullYear(year + 1);\n          }\n          break;\n      case \'y\': //年\n          result.setFullYear(result.getFullYear() + number);\n          break;\n  }\n\n  // 处理闰年2月29日增加月份或天数后变为3月1日或类似情况\n  if (dtTmp.getMonth() === 1 && dtTmp.getDate() === 29 && (result.getMonth() !== 1 || result.getDate() !== 29)) {\n      // 如果原日期是2月29日，且结果不是2月29日，则调整为2月的最后一天（平年是28天）\n      result.setDate(28);\n  }\n\n  return DateFormat(result, realFormat);\n}\n/*\n全局通用INSERT插入函数。若物理表加载为DIY表后，可直接使用V8.FormEngine\n必传参数：\nV8.Param.DbContext（数据库访问对象，可传入V8.Db或V8.Dbs.***） \nV8.Param.TableName（表名）：如：\'remain\'\nV8.Param.Fields（字段名数组）：如：[\'name\', \'age\']\nV8.Param.FieldValues（字段值数组）：如：[\'张三\', 18]\nV1版本采用纯拼接方式，更灵活，但需要额外手动处理sql注入、参数化、单引号符号等问题。\n*/\nV8.Action.DbInsert = function(){\n    if(!V8.Param.DbContext || !V8.Param.TableName || !V8.Param.Fields || !V8.Param.FieldValues){\n      return { Code : 0, Msg : \'参数错误！\' };\n    }\n    if(V8.Param.Fields.length == 0 || V8.Param.FieldValues.length == 0 || V8.Param.FieldValues.length != V8.Param.Fields.length){\n      return { Code : 0, Msg : \'字段或字段值参数错误！\' };\n    }\n    var fields = V8.Param.Fields.join(\',\');\n    var sql = ` INSERT INTO \\`${V8.Param.TableName}\\`(${fields}) VALUES(`;\n    var valuesStr = \'\';\n    for(var i = 0; i < V8.Param.FieldValues.length; i++){\n      var fieldValue = V8.Param.FieldValues[i];\n      var endStr = (i == V8.Param.FieldValues.length - 1 ? \'\' : \',\');\n      var fieldType = typeof(fieldValue);\n      if(fieldType == \'number\'){\n        valuesStr += fieldValue + endStr;\n      }else if(fieldType == \'string\'){\n        valuesStr += `\'${fieldValue}\'${endStr}`;\n      }else{\n        return { Code : 0, Msg : `字段[$V8.Param.Fields[i]}]的值[${fieldValue}]的数据类型[${fieldType}]暂不支持！` }; \n      }\n    }\n    valuesStr += \') \';\n    sql += valuesStr;\n    var count = V8.Param.DbContext.FromSql(sql).ExecuteNonQuery();\n    if(count <= 0){\n      V8.Result = { Code : 0, Msg : \'数据库受影响行数为0！\', DataAppend : {\n        ServerRunSql : V8.SysConfig.PrintSqlToPage ? sql : \'\'\n      } }\n    }else{\n      V8.Result = { Code : 1, DataAppend : {\n        ServerRunSql : V8.SysConfig.PrintSqlToPage ? sql : \'\'\n      }}\n    }\n}\n//V2版本采用sql参数化方式\nV8.Action.DbInsertV2 = function(){\n    if(!V8.Param.DbContext || !V8.Param.TableName || !V8.Param.Fields || !V8.Param.FieldValues){\n      return { Code : 0, Msg : \'参数错误！\' };\n    }\n    if(V8.Param.Fields.length == 0 || V8.Param.FieldValues.length == 0 || V8.Param.FieldValues.length != V8.Param.Fields.length){\n      return { Code : 0, Msg : \'字段或字段值参数错误！\' };\n    }\n    var fields = V8.Param.Fields.join(\',\');\n    var sql = ` INSERT INTO \\`${V8.Param.TableName}\\`(${fields}) VALUES(`;\n    var valuesStr = \'\';\n    var sqlParams = [];\n    for(var i = 0; i < V8.Param.FieldValues.length; i++){\n      var fieldValue = V8.Param.FieldValues[i];\n      var endStr = (i == V8.Param.FieldValues.length - 1 ? \'\' : \',\');\n      valuesStr += `@${V8.Param.Fields[i]}${endStr}`;\n      var sqlParam = V8.Param.DbContext.Db.DbProviderFactory.CreateParameter();\n      sqlParam.ParameterName = V8.Param.Fields[i];\n      //sqlParam.DbType = System.Data.DbType.String;\n      sqlParam.Value = fieldValue;\n      sqlParams.push(sqlParam);\n    }\n    valuesStr += \') \';\n    sql += valuesStr;\n    \n    var count = V8.Param.DbContext.FromSql(sql)\n                  .AddParameter(sqlParams)\n                  .ExecuteNonQuery();\n    if(count <= 0){\n      return { Code : 0, Msg : \'数据库受影响行数为0！\', DataAppend : {\n        ServerRunSql : V8.SysConfig.PrintSqlToPage ? sql : \'\'\n      } }\n    }else{\n      return { Code : 1, DataAppend : {\n        ServerRunSql : V8.SysConfig.PrintSqlToPage ? sql : \'\'\n      }}\n    }\n}\n\n\nV8.Action.GetDateTimeNow = function(){\n  var time = new Date();\n  var format = V8.Param.DateFormat;\n  var year = time.getFullYear();\n  var month = time.getMonth() + 1;\n  var day = time.getDate();\n  var hh = time.getHours();\n  var mm = time.getMinutes();\n  var ss = time.getSeconds();\n  return year + \'-\' \n          + (month > 9 ? month : \'0\' + month) + \'-\' \n          + (day > 9 ? day : \'0\' + day) + \' \' \n          + (hh > 9 ? hh : \'0\' + hh) + \':\' \n          + (mm > 9 ? mm : \'0\' + mm) + \':\' \n          + (ss > 9 ? ss : \'0\' + ss);\n}\n//yyy-MM-dd\nV8.Action.GetDateTimeNowYYYYMMdd = function(){\n  var time = new Date();\n  var format = V8.Param.DateFormat;\n  var year = time.getFullYear();\n  var month = time.getMonth() + 1;\n  var day = time.getDate();\n  var hh = time.getHours();\n  var mm = time.getMinutes();\n  var ss = time.getSeconds();\n  return year + \'-\' \n          + (month > 9 ? month : \'0\' + month) + \'-\' \n          + (day > 9 ? day : \'0\' + day) \n          ;\n}\n\n\n//增加一个自定义变量TestParam1\nV8.Param.TestParam1 = \"abc\";\n//增加一个自定义方法TestAction1\nV8.Action.TestTuomin = function(){\n    var listData = [];\n    //如果是第一行数据、或是表单数据，从数据库中获取数据 \n    if(V8.RowIndex == 0 || V8.RowIndex == null){\n    	listData = V8.Db.FromSql(\"select * from Sys_User\").ToDataTable();\n	    //将数据缓存起来，第二行还要用到，没必要再从数据库取一次。\n	    V8.CacheData = listData;\n    }else{\n	    listData = V8.CacheData;\n    }\n    if(V8.Form[V8.Param.TuominField] != null)\n    {\n        //V8.CurrentUser == null ? \"\":\n        var account = V8.CurrentUser.Account;\n        V8.Form[V8.Param.TuominField] = \n        V8.Form[V8.Param.TuominField].substring(0,1) \n        + \"*\" + account\n 	    + \"*\" + listData.Rows[(V8.RowIndex == null ? 0 : V8.RowIndex)][\"Account\"];\n         V8.NotSaveField = [V8.Param.TuominField];\n    }\n    \n};\n\n//demo演示账户数据脱敏\n/*\nif(V8.EventName == \'DataFilter\' && V8.CurrentUser \n  && (V8.CurrentUser.Account == \'demo\' || V8.CurrentUser.RoleIds.indexOf(\'949b2e88-cfa1-44cd-b234-85f043785ece\') > -1)\n  ){\n  var notFilterTable = [\n    \'sys_menu\', \'sys_servernode\',\n    \'diy_table\', \'rpt_report\',\n    \'diy_field\', \'diy_wallpaper\',\n    \'rpt_type\', \'sys_microistore\',\n    \'diy_component\', \'diy_test\',\n    \'sys_apiengine\', \'diy_microi_price\',\n    \'sys_datasource\',\n    \'diy_lang\',\'sys_config\',\'mic_day_word\',\'mic_memo\',\'diy_news\', \n    \'wf_flowdesign\',\'wf_node\',\'wf_flow\',\'wf_nodelist\',\'wf_history\',\'wf_work\', \'wf_line\',\n    \'diy_schedule_job\', \'diy_queue_receive\', \'diy_sso\', \'diy_schedule_job_log\', \'sys_basedata\',\'microi_icon\',\n    \'mic_order\'\n  ];\n  if(V8.TableModel && V8.TableModel.Name && notFilterTable.indexOf(V8.TableModel.Name.toLowerCase()) > -1){\n    return;\n  }\n  var subStringIndex = 2;\n  if(V8.TableData && V8.TableData.length > 0){\n    V8.TableData.forEach(item => {\n      for(let key in item){\n        if(key != \'Id\' && item[key]){\n          if(typeof(item[key]) == \'number\'){\n            item[key] = -1;\n          }\n          else if(item[key].length > subStringIndex){\n            item[key] = item[key].substring(0, subStringIndex) + \'***\';\n          }\n        }\n      }\n    })\n  }\n  if(V8.Form){\n    for(let key in V8.Form){\n      var item = V8.Form;\n      if(key != \'Id\' && item[key]){\n        if(typeof(item[key]) == \'number\'){\n          item[key] = -1;\n        }\n        else if(item[key].length > subStringIndex){\n          item[key] = item[key].substring(0, subStringIndex) + \'***\';\n        }\n      }\n    }\n  }\n}\n*/', 'DES', '吾码IM', '', '//必传参数：\n//V8.Param.PwdType（可能的值：Encode、Decode）\n//V8.Param.Account（用户登陆时传入的账号）\n//V8.Param.Pwd（用户登陆时传入的密码 或 修改密码时传入的新密码或旧密码，一般是明文）\nif(!V8.Param.PwdType || !V8.Param.Account || !V8.Param.Pwd){\n  return;\n}\n//如果是加密\nif(V8.Param.PwdType == \'Encode\'){\n  //默认DES方式\n  //V8.Result = V8.EncryptHelper.DESEncode(param.Pwd);\n\n  //新的方式：\n  //第一步：密钥 + 工号 + （密码是明文的SHA256加密，再转大写）\n  //CRCLDAP（密钥）+CRP_DENGQ281X（登录账号）\n  //+7BFDE614AA574DD6540D58A92F31DB981790D30E560A824F6E833D4BA906BDBD（密文）\n  //第二步：再进行SHA256加密，再转大写\n\n  //获取密钥，可以在这里写死，也可以从系统设置中获取\n  var miyao =\'123456\';// V8.SysConfig.Miyao || \n  //获取工号，可能是前端传入？也可能是根据前端传入的帐号去获取对应的工号？也可能登陆帐号就是工号？\n  var gonghao = V8.Param.Account.toUpperCase();\n  return V8.EncryptHelper.SHA256(miyao + gonghao + V8.EncryptHelper.SHA256(V8.Param.Pwd).toUpperCase()).toUpperCase();\n}\n//如果是解密\nelse if(V8.Param.PwdType == \'Decode\'){\n  //DES才能解密，SHA256不支持。\n  return V8.EncryptHelper.DESDecode(V8.Param.Pwd);\n}', 'Aliyun', 3, '{\"Id\":\"legacy_1772681504737\",\"Name\":\"desktop-bg-1768377711.jpg\",\"Size\":\"\",\"CreateTime\":\"\",\"Path\":\"/itdosimg/20260114/desktop-bg-1768377711.jpg\",\"State\":1}', 1, '/* \n前后端通信相关的配置,注释只允许使用多行方式 \n*/\n{\n  /* 上传图片配置项 */\n  \"imageActionName\": \"uploadimage\", /* 执行上传图片的action名称 */\n  \"imageFieldName\": \"upfile\", /* 提交的图片表单名称*/\n  \"imageMaxSize\": 20971520, /* 上传大小限制，单位B   默认20M*/\n  \"imageAllowFiles\": [ \".png\", \".jpg\", \".jpeg\", \".gif\", \".bmp\" ], /* 上传图片格式显示 */\n  \"imageCompressEnable\": false, /* 是否压缩图片,默认是true，这里是前端压缩，一张4M图片前端压成了110KB左右。 */\n  \"imageCompressBorder\": 780, /* 图片压缩最长边限制 */\n  \"imageInsertAlign\": \"none\", /* 插入的图片浮动方式 */\n  \"imageUrlPrefix\": \"https://static-ali-img.itdos.com\", /* 图片访问路径前缀 */\n  \"imagePathFormat\": \"editor/image/{yyyy}{mm}/{time}{rand:6}\", /* 上传保存路径,可以自定义保存路径和文件名格式 */\n  /* {filename} 会替换成原文件名,配置这项需要注意中文乱码问题 */\n  /* {rand:6} 会替换成随机数,后面的数字是随机数的位数 */\n  /* {time} 会替换成时间戳 */\n  /* {yyyy} 会替换成四位年份 */\n  /* {yy} 会替换成两位年份 */\n  /* {mm} 会替换成两位月份 */\n  /* {dd} 会替换成两位日期 */\n  /* {hh} 会替换成两位小时 */\n  /* {ii} 会替换成两位分钟 */\n  /* {ss} 会替换成两位秒 */\n  /* 非法字符 \\ : * ? \" < > | */\n  /* 具请体看线上文档: fex.baidu.com/ueditor/#use-format_upload_filename */\n\n  /* 涂鸦图片上传配置项 */\n  \"scrawlActionName\": \"uploadscrawl\", /* 执行上传涂鸦的action名称 */\n  \"scrawlFieldName\": \"upfile\", /* 提交的图片表单名称 */\n  \"scrawlPathFormat\": \"editor/image/{yyyy}{mm}/{time}{rand:6}\", /* 上传保存路径,可以自定义保存路径和文件名格式 */\n  \"scrawlMaxSize\": 10485760, /* 上传大小限制，单位B */\n  \"scrawlUrlPrefix\": \"https://static-ali-img.itdos.com\", /* 图片访问路径前缀 */\n  \"scrawlInsertAlign\": \"none\",\n\n  /* 截图工具上传 */\n  \"snapscreenActionName\": \"uploadimage\", /* 执行上传截图的action名称 */\n  \"snapscreenPathFormat\": \"editor/image/{yyyy}{mm}/{time}{rand:6}\", /* 上传保存路径,可以自定义保存路径和文件名格式 */\n  \"snapscreenUrlPrefix\": \"https://static-ali-img.itdos.com\", /* 图片访问路径前缀 */\n  \"snapscreenInsertAlign\": \"none\", /* 插入的图片浮动方式 */\n\n  /* 抓取远程图片配置 */\n  \"catcherLocalDomain\": [ \"127.0.0.1\", \"localhost\", \"img.baidu.com\" ],\n  \"catcherActionName\": \"catchimage\", /* 执行抓取远程图片的action名称 */\n  \"catcherFieldName\": \"source\", /* 提交的图片列表表单名称 */\n  \"catcherPathFormat\": \"editor/image/{yyyy}{mm}/{time}{rand:6}\", /* 上传保存路径,可以自定义保存路径和文件名格式 */\n  \"catcherUrlPrefix\": \"https://static-ali-img.itdos.com\", /* 图片访问路径前缀 */\n  \"catcherMaxSize\": 10485760, /* 上传大小限制，单位B */\n  \"catcherAllowFiles\": [ \".png\", \".jpg\", \".jpeg\", \".gif\", \".bmp\" ], /* 抓取图片格式显示 */\n\n  /* 上传视频配置 */\n  \"videoActionName\": \"uploadvideo\", /* 执行上传视频的action名称 */\n  \"videoFieldName\": \"upfile\", /* 提交的视频表单名称 */\n  \"videoPathFormat\": \"editor/video/{yyyy}{mm}/{time}{rand:6}\", /* 上传保存路径,可以自定义保存路径和文件名格式 */\n  \"videoUrlPrefix\": \"https://static-ali-img.itdos.com\", /* 视频访问路径前缀 */\n  \"videoMaxSize\": 209715200, /* 上传大小限制，单位B，默认200MB */\n  \"videoAllowFiles\": [\n    \".flv\",\n    \".swf\",\n    \".mkv\",\n    \".avi\",\n    \".rm\",\n    \".rmvb\",\n    \".mpeg\",\n    \".mpg\",\n    \".ogg\",\n    \".ogv\",\n    \".mov\",\n    \".wmv\",\n    \".mp4\",\n    \".webm\",\n    \".mp3\",\n    \".wav\",\n    \".mid\"\n  ], /* 上传视频格式显示 */\n\n  /* 上传文件配置 */\n  \"fileActionName\": \"uploadfile\", /* controller里,执行上传视频的action名称 */\n  \"fileFieldName\": \"upfile\", /* 提交的文件表单名称 */\n  \"filePathFormat\": \"editor/file/{yyyy}{mm}/{time}{rand:6}\", /* 上传保存路径,可以自定义保存路径和文件名格式 */\n  \"fileUrlPrefix\": \"https://static-ali-img.itdos.com\", /* 文件访问路径前缀 */\n  \"fileMaxSize\": 209715200, /* 上传大小限制，单位B，默认200MB */\n  \"fileAllowFiles\": [\n    \".png\",\n    \".jpg\",\n    \".jpeg\",\n    \".gif\",\n    \".bmp\",\n    \".flv\",\n    \".swf\",\n    \".mkv\",\n    \".avi\",\n    \".rm\",\n    \".rmvb\",\n    \".mpeg\",\n    \".mpg\",\n    \".ogg\",\n    \".ogv\",\n    \".mov\",\n    \".wmv\",\n    \".mp4\",\n    \".webm\",\n    \".mp3\",\n    \".wav\",\n    \".mid\",\n    \".rar\",\n    \".zip\",\n    \".tar\",\n    \".gz\",\n    \".7z\",\n    \".bz2\",\n    \".cab\",\n    \".iso\",\n    \".doc\",\n    \".docx\",\n    \".xls\",\n    \".xlsx\",\n    \".ppt\",\n    \".pptx\",\n    \".pdf\",\n    \".txt\",\n    \".md\",\n    \".xml\"\n  ], /* 上传文件格式显示 */\n\n  /* 列出指定目录下的图片 */\n  \"imageManagerActionName\": \"listimage\", /* 执行图片管理的action名称 */\n  \"imageManagerListPath\": \"editor/image\", /* 指定要列出图片的目录 */\n  \"imageManagerListSize\": 20, /* 每次列出文件数量 */\n  \"imageManagerUrlPrefix\": \"https://static-ali-img.itdos.com\", /* 图片访问路径前缀 */\n  \"imageManagerInsertAlign\": \"none\", /* 插入的图片浮动方式 */\n  \"imageManagerAllowFiles\": [ \".png\", \".jpg\", \".jpeg\", \".gif\", \".bmp\" ], /* 列出的文件类型 */\n\n  /* 列出指定目录下的文件 */\n  \"fileManagerActionName\": \"listfile\", /* 执行文件管理的action名称 */\n  \"fileManagerListPath\": \"editor/file\", /* 指定要列出文件的目录 */\n  \"fileManagerUrlPrefix\": \"https://static-ali-img.itdos.com\", /* 文件访问路径前缀 */\n  \"fileManagerListSize\": 20, /* 每次列出文件数量 */\n  \"fileManagerAllowFiles\": [\n    \".png\",\n    \".jpg\",\n    \".jpeg\",\n    \".gif\",\n    \".bmp\",\n    \".flv\",\n    \".swf\",\n    \".mkv\",\n    \".avi\",\n    \".rm\",\n    \".rmvb\",\n    \".mpeg\",\n    \".mpg\",\n    \".ogg\",\n    \".ogv\",\n    \".mov\",\n    \".wmv\",\n    \".mp4\",\n    \".webm\",\n    \".mp3\",\n    \".wav\",\n    \".mid\",\n    \".rar\",\n    \".zip\",\n    \".tar\",\n    \".gz\",\n    \".7z\",\n    \".bz2\",\n    \".cab\",\n    \".iso\",\n    \".doc\",\n    \".docx\",\n    \".xls\",\n    \".xlsx\",\n    \".ppt\",\n    \".pptx\",\n    \".pdf\",\n    \".txt\",\n    \".md\",\n    \".xml\"\n  ] /* 列出的文件类型 */\n\n}\n', '{\n  \"CaptchaType\": 11, // 验证码类型，值为0-11，具体效果见平台文档\n  \"CodeLength\": 1, // 验证码长度, 要放在CaptchaType设置后。当类型为算术表达式时（CaptchaType=10-11），长度代表操作的个数, 建议1。当CaptchaType=0-9时建议填4。\n  \"ExpirySeconds\": 300, // 验证码过期秒数\n  \"IgnoreCase\": true, // 比较时是否忽略大小写\n  //\"StoreageKeyPrefix\": \"\", // 存储键前缀\n  \"ImageOption\": {\n    \"Animation\": true, // 是否启用动画\n    \"FontSize\": 32, // 字体大小\n    \"Width\": 150, // 验证码宽度\n    \"Height\": 50, // 验证码高度\n    \"BubbleMinRadius\": 5, // 气泡最小半径\n    \"BubbleMaxRadius\": 10, // 气泡最大半径\n    \"BubbleCount\": 1, // 气泡数量\n    \"BubbleThickness\": 1.0, // 气泡边沿厚度\n    \"InterferenceLineCount\": 1, // 干扰线数量\n    //\"FontFamily\": \"kaiti\", //【暂不支持】 包含actionj,epilog,fresnel,headache,lexo,prefix,progbot,ransom,robot,scandal,kaiti\n    \"FrameDelay\": 300, // 每帧延迟,Animation=true时有效, 默认30，建议300左右\n    //\"BackgroundColor\": \"#ffffff\", //【暂不支持】  格式: rgb, rgba, rrggbb, or rrggbbaa format to match web syntax, 默认#fff\n    \"ForegroundColors\": \"\", //  颜色格式同BackgroundColor,多个颜色逗号分割，随机选取。不填，空值，则使用默认颜色集\n    \"Quality\": 100, // 图片质量（质量越高图片越大，gif调整无效可能会更大）\n    \"TextBold\": false // 粗体\n  }\n}', '[{\"Id\":1700034574306,\"State\":1,\"Name\":\"WechatIMG66.jpeg\",\"Size\":205650,\"Path\":\"/itdos/img/20231115/WechatIMG66.jpeg\",\"CreateTime\":\"2023-11-15 15:49:34\"}]', '', '[{\"Id\":1700035377766,\"State\":1,\"Name\":\"73aa60dc3f3450cc23920008a960cb95.jpeg\",\"Size\":837006,\"Path\":\"/itdos/img/20231115/73aa60dc3f3450cc23920008a960cb95.jpeg\",\"CreateTime\":\"2023-11-15 16:02:58\"}]', 1, 'https://api-china.itdos.com', 1, '<div>\r\n©$CompanyName$ $OsV