\":0,\"Name\":\"复制\",\"V8Code\":\"V8.OpenAnyForm({\\n  TableName : \'Sys_OsClients\',\\n  DialogType : \'Dialog\',\\n  FormMode : \'Add\',\\n  SelectFields: [\'OsClient\', \'OsClientType\', \'OsClientNetwork\'],//只查询、显示哪些字段\\n  DataAppend: {\\n    //传入自定义附加数据，DataAppend为固定参数名称。可在指定的打开表单V8事件中使用V8.DataAppend访问。\\n    OsClient: V8.Form.OsClient,\\n    OsClientType: V8.Form.OsClientType,\\n    OsClientNetwork: V8.Form.OsClientNetwork,\\n  },\\n  Width : \'765px\',\\n  EventReplace : {//替换掉提交事件\\n    //这3个参数一定会接收到，必须执行callback(DosResult)\\n    Submit : async function(v8, param, callback){\\n      V8.ConfirmTips(`确认复制${v8.Form.OsClient}？`, async function(){\\n        //必传：Id、OsClient、OsClientType、OsClientNetwork\\n        V8.ApiEngine.Run(\'copy-saas-engine\', {\\n          Id : V8.Form.Id,\\n          OsClientValue : v8.Form.OsClient,\\n          OsClientType : v8.Form.OsClientType,\\n          OsClientNetwork : v8.Form.OsClientNetwork,\\n        }, function(result){\\n          if(result.Code == 1){\\n            V8.Tips(\'复制成功！\');\\n            V8.RefreshTable();\\n          }else{\\n            V8.Tips(\'复制失败：\' + result.Msg);\\n          }\\n        });\\n      });\\n    }\\n  }\\n});\\n\\n\",\"V8CodeShow\":\"\",\"Icon\":\"fas fa-copy\",\"Url\":\"\",\"BtnStyle\":\"primary\",\"ShowRow\":true,\"IsVisible\":true}]', '', '', '[]', '', '[]', '[]', '[]', 0, '[\"d0fcf7be-768c-4b89-ab55-59f708ec5d5e\"]', '[]', 0, '2026-03-28 16:02:39', NULL, '[]', '[{\"Id\":\"71baaa8c-b765-4cc7-b87e-6ce1166dbcfc\",\"AsName\":\"\",\"Name\":\"OsClient\",\"Label\":\"OsClient\",\"TableId\":\"6fc136be-9346-4508-af0d-988b25987d51\",\"TableName\":\"Sys_OsClients\",\"TableDescription\":\"OsClients\",\"IsVisible\":true},{\"Id\":\"8cbb612e-4ee2-432b-aef9-a530564a9c71\",\"AsName\":\"\",\"Name\":\"DomainName\",\"Label\":\"域名\",\"TableId\":\"6fc136be-9346-4508-af0d-988b25987d51\",\"TableName\":\"Sys_OsClients\",\"TableDescription\":\"OsClients\",\"IsVisible\":true},{\"Id\":\"d0fcf7be-768c-4b89-ab55-59f7