INSERT INTO `sys_menu` VALUES ('61b7faee-35b2-4571-add2-5231a355f368', '应用商城', '', '', '', '', '/microi-store', '', 'cdc0844b-7249-4d64-a9c3-563a15c9cd20', 1, '{\"Id\":\"legacy_1770831109742\",\"Name\":\"appstore.png\",\"Size\":\"\",\"CreateTime\":\"\",\"Path\":\"/itdos/img/20241021/appstore.png\",\"State\":1}', 'fab fa-app-store', '2022-08-08 21:50:12', 'Diy', '搜索+卡片', '/diy/diy-table-rowlist', '', 0, 1, '', 'c74d669c-a3d4-11e5-b60d-b870f43edd03', '', '6cf254f1-edd0-4f04-96bc-c9ad08b5a2c1', '[]', '', '[]', '{\"HiddenIndex\":0,\"GeneralSeaarch\":0}', '[]', '', '', '[]', b'0', '', '[]', '', '', '[{\"Id\":\"01KKG1YJ44M5FDZ0BGK1PC9SGV\",\"Name\":\"安装\",\"Icon\":\"Cloudy\",\"BtnStyle\":\"primary\",\"V8Code\":\"debugger;\\nV8.ConfirmTips(\'确认以覆盖的形式安装此应用？应用商城为刚上线新功能，安装前请备份好数据库！\', function () {\\n  //获取数据包\\n  V8.Post(\\\"https://api.itdos.com/apiengine/get-microi-store-model?OsClient=iTdos\\\", {\\n    Id: V8.Form.Id\\n  }, function(result) {\\n    if(result.Code != 1) {\\n      V8.Tips(\\\"获取数据包失败：\\\" + result.Msg, false);\\n      return;\\n    }\\n    if (!result.Data.AppPakcet || !result.Data.AppPakcet.trim()) { \\n      V8.Tips(\\\"数据包中不存在数据，无法安装！\\\", false);\\n      return;\\n    }\\n    //开始安装\\n    V8.ApiEngine.Run(\\\"import-microi-store-package\\\", {\\n      Package: JSON.parse(result.Data.AppPakcet)\\n    }, function (result2) {\\n      if (result2.Code != 1) {\\n        V8.Tips(\\\"安装失败：\\\" + result2.Msg, false)\\n        return;\\n      }\\n      V8.Tips(\\\"安装成功，请刷新系统，新模块可能需要在[角色权限]模块配置权限！\\\")\\n    })\\n  })\\n});\",\"V8CodeShow\":\"\",\"ShowRow\":1}]', '', '', '[]', '', '[]', '[]', '[{\"Id\":\"01KKG20H4Z0PH9SRCPEKE037PN\",\"Name\":\"官方应用\",\"Icon\":\"MostlyCloudy\",\"V8Code\":\"\",\"V8CodeShow\":\"\"},{\"Id\":\"01KKG20H4Z9D0PSZPYSAY0DP8Z\",\"Name\":\"社区应用\",\"Icon\":\"User\",\"V8Code\":\"\",\"V8CodeShow\":\"\"}]', 0, '[]', '[]', 0, '2026-04-07 01:10:33', '管理员', '[]', '[{\"Id\":\"01KKBDGX8YK03VW8BB1G5K5XM7\",\"Label\":\"应用名称\",\"Name\":\"AppName\",\"As