\',\\n  `EditCodeShowV8` mediumtext NULL COMMENT \'[编辑]按钮显示条件\',\\n  `AddCodeShowV8` mediumtext NULL COMMENT \'[新增]按钮显示条件\',\\n  `IsChildSystem` int NULL COMMENT \'是否子系统\',\\n  `ModuleEngineKey` varchar(50) NULL COMMENT \'模块引擎Key\',\\n  `TableCardImgStyle` varchar(500) NULL COMMENT \'卡片图片样式\',\\n  `TableCardImgField` varchar(50) NULL COMMENT \'卡片图片字段\',\\n  `TableCardCol` int NULL COMMENT \'卡片每行几列\',\\n  `SecondMenuRow` int NULL COMMENT \'二级目录缩略行\',\\n  `SecondMenuColumn` int NULL COMMENT \'二级目录缩略列\',\\n  `IconComponent` varchar(50) NULL COMMENT \'图标组件\',\\n  `DefaultPageSize` int NULL COMMENT \'默认每页数量\',\\n  `SecondMenuLineCount` int NULL COMMENT \'二级目录每行几个\',\\n  `SecondMenuHeight` varchar(50) NULL COMMENT \'二级目录高度\',\\n  `SecondMenuWidth` varchar(50) NULL COMMENT \'二级目录宽度\',\\n  `MacScreenIndex` int NULL COMMENT \'所属mac第几屏幕\',\\n  `HasChild` int NULL COMMENT \'是否有子集\',\\n  `SizeHeightMac` varchar(50) NULL COMMENT \'图标高（mac）\',\\n  `SizeWidthMac` varchar(50) NULL COMMENT \'图标宽（mac）\',\\n  `DisplayMac` int NULL COMMENT \'显示[mac]\',\\n  `AppDisplay` int NULL COMMENT \'移动端是否显示\',\\n  `ReportId` varchar(36) NULL,\\n  `ReportName` varchar(100) NULL COMMENT \'选择报表\',\\n  `OpenType` varchar(500) NULL COMMENT \'打开方式\',\\n  `ImportV8` mediumtext NULL,\\n  `Icon` varchar(500) NULL COMMENT \'菜单图片\',\\n  `TableDiyFieldIds` mediumtext NULL COMMENT \'查询列[废弃]\',\\n  `PageTemplate` varchar(255) NULL COMMENT \'界面模板\',\\n  `PageBtns` mediumtext NULL COMMENT \'[页面]更多按钮\',\\n  `DiyTableId` varchar(36) NULL COMMENT \'选择表单\',\\n  `NotShowFields` mediumtext NULL COMMENT \'不显示列\',\\n  `SqlWhere` mediumtext NULL COMMENT \'Where条件\',\\n  `StatisticsFields` mediumtext NULL COMMENT \'统计列\',\\n  `IsMicroiService` int NULL COMMENT \'微服务\',\\n  `ImportTemplateName` varchar(255) NULL COMMENT \'导入模板名称\',\\n  `EnName` varchar(500) NULL,\\n  `MultRun` int NULL,\\n  `Code` varchar(500) NULL,\\n  `TableHeaders` mediumtext NULL COMMENT \'多级表头数据\',\\n  `JquerySelector` varchar(500) NULL,\\n  `ExportV8` mediumtext NULL,\\n  `DefaultOrderBy` varchar(255) NULL COMMENT \'默认排序字段\',\\n  `Sort` int(11) NULL COMMENT \'排序\',\\n  `InTableEdit` int NULL COMMENT \'开启表内编辑\',\\n  `Class` varchar(500) NULL COMMENT \'就是Customer\',\\n  `SearchFieldIds` mediumtext NULL COMMENT \'可搜索的字段\',\\n  `ComponentPath` varchar(500) NULL COMMENT \'组件路径\',\\n  `Description` varchar(500) NULL COMMENT \'菜单描述\',\\n  `ExportMoreBtns` mediumtext NULL COMMENT \'[导出]更多按钮\',\\n  `IconClass` varchar(500) NULL COMMENT \'图标\',\\n  `Url` varchar(500) NULL COMMENT \'Url地址\',\\n  `DiyConfig` mediumtext NULL COMMENT \'模块配置\',\\n  `SortFieldIds` mediumtext NULL COMMENT \'可排序字段\',\\n  `Link` varchar(500) NULL,\\n  `SqlJoin` mediumtext NULL COMMENT \'Join关联\',\\n  `BatchSelectMoreBtns` mediumtext NULL COMMENT \'[批量选择]更多按钮\',\\n  `StoreId` varchar(36) NULL,\\n  `ImportTemplate` varchar(255) NULL COMMENT \'导入模板\',\\n  `Name` varchar(500) NULL COMMENT \'名称\',\\n  `EnDescription` varchar(500) NULL,\\n  `MoreBtns` mediumtext NULL COMMENT \'[行]更多按钮\',\\n  `ComponentName` varchar(500) NULL COMMENT \'界面模板\',\\n  `PageTabs` mediumtext NULL COMMENT \'页面多Tab\',\\n  `InTableEditFields` mediumtext NULL COMMENT \'表内可编辑字段\',\\n  `Display` int NULL COMMENT \'是否显示\',\\n  `DetailPageV8` mediumtext NULL COMMENT \'详情按钮V8\',\\n  `RoleGroup` mediumtext NULL,\\n  `SelectFields` mediumtext NULL COMMENT \'查询列\',\\n  `FormBtns` mediumtext NULL COMMENT \'[表单]更多按钮\',\\n  `JoinTables` mediumtext NULL COMMENT \'关联表\',\\n  `DisplayWin` int NULL COMMENT \'显示[win]\',\\n  `ParentId` varchar(50) NULL COMMENT \'上级\',\\n  `ParentIds` mediumtext NULL\\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;\"}],\"SysMenus\":[{\"HiddenIndex\":0,\"GeneralSeaarch\":0,\"FixedFields\":\"[]\",\"IsChildSystem\":0,\"TableCardCol\":0,\"SecondMenuRow\":0,\"SecondMenuColumn\":0,\"DefaultPageSize\":0,\"SecondMenuLineCount\":0,\"MacScreenIndex\":0,\"HasChild\":0,\"SizeHeightMac\":\"1\",\"SizeWidthMac\":\"1\",\"DisplayMac\":1,\"AppDisplay\":1,\"OpenType\":\"Diy\",\"Icon\":\"{\