 COMMENT \'表单分组\',\\n  `ApiReplace` mediumtext NULL COMMENT \'接口替换\',\\n  `IsAnonymousRead` int NULL COMMENT \'允许匿名读取\',\\n  `FieldBorder` varchar(255) NULL,\\n  `Description` mediumtext NULL COMMENT \'表说明\',\\n  `Tabs` mediumtext NULL COMMENT \'表单分组\',\\n  `BindRole` mediumtext NULL COMMENT \'访问权限\',\\n  `TableTabsPosition` varchar(255) NULL,\\n  `TabsPosition` varchar(255) NULL COMMENT \'分组标签位置\',\\n  `Name` varchar(255) NULL COMMENT \'表名\',\\n  `TreeParentFields` mediumtext NULL COMMENT \'完整父级列\',\\n  `TreeHasChildren` varchar(50) NULL COMMENT \'是否有子级列\',\\n  `ServerDataV8` mediumtext NULL COMMENT \'后端数据处理V8事件\',\\n  `IsTree` int NULL COMMENT \'树形结构\',\\n  `FormOpenWidth` varchar(255) NULL COMMENT \'弹窗/抽屉宽度\',\\n  `TableArticle` mediumtext NULL,\\n  `DataEncryptTransfer` int NULL,\\n  `InFormV8` mediumtext NULL COMMENT \'前端表单进入V8事件\',\\n  `TreeParentField` varchar(50) NULL COMMENT \'父级列\',\\n  `TreeLazy` int NULL COMMENT \'树形懒加载\',\\n  `FormArticle` mediumtext NULL,\\n  `EnableCache` int NULL,\\n  `IsAnonymousAdd` int NULL COMMENT \'允许匿名新增\',\\n  `CacheParentKey` varchar(255) NULL,\\n  `FormOpenType` varchar(255) NULL COMMENT \'表单打开方式\',\\n  `SubmitFormV8` mediumtext NULL COMMENT \'前端表单提交前V8事件\',\\n  `FormLabelPosition` varchar(255) NULL COMMENT \'标签对齐方式\'\\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;\"},{\"TableName\":\"diy_component\",\"TableId\":\"73a92e3d-8cd9-4a1f-bfc1-83fbc8e493d5\",\"DDL\":\"CREATE TABLE IF NOT EXISTS `diy_component` (\\n  `Id` varchar(36) NOT NULL PRIMARY KEY,\\n  `CreateTime` datetime NULL COMMENT \'创建时间\',\\n  `UpdateTime` datetime NULL COMMENT \'修改时间\',\\n  `UserId` varchar(36) NULL COMMENT \'创建人Id\',\\n  `UserName` varchar(255) NULL COMMENT \'创建人\',\\n  `IsDeleted` int NULL COMMENT \'是否已删除\',\\n  `Disable` varchar(255) NULL COMMENT \'是否禁用\',\\n  `Description` mediumtext NULL COMMENT \'描述\',\\n  `Readonly` varchar(255) NULL COMMENT \'默认只读\',\\n  `Sort` int NULL COMMENT \'排序\',\\n  `IsNew` varchar(255) NULL COMMENT \'是否新组件\',\\n  `Path` va