ULL COMMENT \'登陆背景图\',\\n  `AppIndexSlideshow` mediumtext NULL COMMENT \'首页轮播图\',\\n  `CaptchaConfig` mediumtext NULL COMMENT \'验证码配置\',\\n  `UEditorConfig` mediumtext NULL COMMENT \'富文本配置\',\\n  `DesktopBgImg` varchar(255) NULL COMMENT \'桌面默认背景图\',\\n  `MacScreenCount` int NULL COMMENT \'mac桌面屏幕数量\',\\n  `EnableCaptcha` int NULL COMMENT \'开启验证码\',\\n  `HDFS` varchar(50) NULL,\\n  `PwdV8` mediumtext NULL COMMENT \'密码V8加解密\',\\n  `DefaultIndexUrl` varchar(500) NULL COMMENT \'默认首页路由\',\\n  `EnableChat` varchar(25) NULL COMMENT \'微聊系统\',\\n  `PwdEncode` varchar(50) NULL COMMENT \'密码存储形式\',\\n  `GlobalServerV8Code` mediumtext NULL COMMENT \'服务器端全局V8引擎\',\\n  `PwdAllowMultiLogin` int NULL COMMENT \'允许多处登陆\',\\n  `PwdErrorLockTime` int NULL COMMENT \'封锁时间\',\\n  `PwdAllowErrorCount` int NULL COMMENT \'允许错误次数\',\\n  `PwdContainUpperLower` int NULL COMMENT \'包含混合大小写\',\\n  `PwdContainSpecial` int NULL COMMENT \'包含特殊字符\',\\n  `PwdContainNumber` int NULL COMMENT \'包含数字\',\\n  `PwdShortestLength` int NULL COMMENT \'最短密码长度\',\\n  `PageBottomTpl` mediumtext NULL COMMENT \'页面底部信息\',\\n  `MenuWordColor` varchar(25) NULL COMMENT \'文字颜色\',\\n  `MenuBackgroundColor` varchar(25) NULL COMMENT \'背景颜色\',\\n  `MenuBg` varchar(50) NULL COMMENT \'模块背景\',\\n  `MenuBottomContent` mediumtext NULL COMMENT \'模块底部信息\',\\n  `MenuWidth` varchar(50) NULL COMMENT \'菜单宽度\',\\n  `ActiveMenuColor` varchar(50) NULL COMMENT \'选中文字 \',\\n  `SysTitleColor` varchar(50) NULL COMMENT \'系统标题颜色\',\\n  `TopWidthFull` int NULL COMMENT \'顶部宽度铺满\',\\n  `MediaServer` varchar(50) NULL,\\n  `FileServer` varchar(50) NULL COMMENT \'文件服务器\',\\n  `GlobalV8Code` mediumtext NULL COMMENT \'前端全局V8引擎\',\\n  `ActiveMenuBg` varchar(50) NULL COMMENT \'选中背景\',\\n  `SysLogoLink` varchar(50) NULL COMMENT \'Logo超链接\',\\n  `SysLogoHeight` varchar(50) NULL COMMENT \'Logo高度\',\\n  `SysLogoType` varchar(50) NULL COMMENT \'Logo形式\',\\n  `ThemeColor` varchar(25) NULL COMMENT \'主题色\',\\n  `IsAeroLogin` int NULL COMMENT \'登陆背景虚化\',\\n  `SysLa