LL,\\n  `Readonly` int NULL COMMENT \'是否只读\',\\n  `TableId` varchar(36) NULL COMMENT \'所属表Id\',\\n  `Config` mediumtext NULL COMMENT \'配置\',\\n  `TableWidth` int(11) NULL COMMENT \'表格占宽\',\\n  `NameConfirm` int NULL COMMENT \'已确认字段名\',\\n  `Code` varchar(255) NULL,\\n  `V8TmpEngineTable` mediumtext NULL COMMENT \'模板V8引擎（表格）\',\\n  `Unique` int NULL COMMENT \'是否唯一\',\\n  `InTableEdit` int NULL COMMENT \'开启表内编辑\',\\n  `Name` varchar(255) NULL COMMENT \'字段名\',\\n  `OsClient` varchar(255) NULL,\\n  `Type` varchar(255) NULL COMMENT \'字段类型\',\\n  `Tab` varchar(255) NULL COMMENT \'所属表单分组\',\\n  `FormWidth` int(11) NULL COMMENT \'表单占宽\',\\n  `Remark` mediumtext NULL COMMENT \'备注\'\\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;\"},{\"TableName\":\"Rpt_Report\",\"TableId\":\"3c55fc03-e9d6-4b3e-953d-494e6e5ffcf3\",\"DDL\":\"CREATE TABLE IF NOT EXISTS `Rpt_Report` (\\n  `Id` varchar(36) NOT NULL PRIMARY KEY,\\n  `CreateTime` datetime NULL COMMENT \'创建时间\',\\n  `UpdateTime` datetime NULL COMMENT \'修改时间\',\\n  `UserId` varchar(36) NULL COMMENT \'创建人Id\',\\n  `UserName` varchar(255) NULL COMMENT \'创建人\',\\n  `IsDeleted` int NULL COMMENT \'是否已删除\',\\n  `Preview` mediumtext NULL COMMENT \'预览图\',\\n  `FkTableId` varchar(36) NULL COMMENT \'关联TableId\',\\n  `IsEnable` int NULL COMMENT \'是否启用\',\\n  `JiazaiXZZD` varchar(255) NULL COMMENT \'添加选择的字段\',\\n  `RptSelectFieldList` mediumtext NULL COMMENT \'选择字段\',\\n  `RptLoadTableField` varchar(255) NULL COMMENT \'添加表的所有字段\',\\n  `RptSelectTable` varchar(100) NULL COMMENT \'选择表\',\\n  `RptFieldList` varchar(255) NULL COMMENT \'字段配置\',\\n  `DataSourceId` varchar(36) NULL COMMENT \'数据源Id\',\\n  `DataSourceForm` varchar(255) NULL COMMENT \'关联表单\',\\n  `XinzengSJY` varchar(255) NULL COMMENT \'新增数据源\',\\n  `DataSource` varchar(100) NULL COMMENT \'数据源\',\\n  `RtpType` varchar(50) NULL COMMENT \'报表类型\',\\n  `RptKey` varchar(50) NULL COMMENT \'报表Key（虚拟表名）\',\\n  `RptName` varchar(50) NULL COMMENT \'报表名称\'\\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;\"}],\